INSERT INTO #PVC VALUES (9154, N'81034352', N'81055552', N'Implantação de letreiro de LED para comunicação operacional da Balança Rodoviária', NULL, N'Others/Outros', N'Antes da implantação, os motoristas não tinham visibilidade dos status das balança (Operacional, manutenção, calibração ou parada), o que gerava filas, problemas no transito e retrabalho a terem que se deslocar para a outra balança.', N'Melhorar comunicação com os motoristas, reduzindo filas e tempo de espera na balança, além de aumentar a eficiência operacional.', N'10233', N'01 - Imagens/01 - Antes/9154.jpeg', N'Antes da implantação do letreiro de LED, não havia um meio visual eficiente para comunicar aos motoristas o status da balança rodoviária. As informações eram repassadas apenas verbalmente ou após o motorista já se direcionar até a pista, o que gerava filas desnecessárias, retrabalho e perda de tempo.
INSERT INTO #PVC VALUES (9155, N'81050431', N'81009658', N'restauração dos coletores', NULL, N'Others/Outros', N'os coletores estavam se deteriorando', N'economia', N'10139', N'01 - Imagens/01 - Antes/9155.jpeg', N'os carros coletores de óleo estavam precisando de uma restauração ', N'01 - Imagens/02 - Depois/9155.jpeg', N'foi restaurado', NULL, N'melhoria', N'melhoria', 5000, 1, N'melhor resultado em preventiva', '2026-03-22T00:00:00.000', '2026-04-02T13:50:46.000', N'81050431', NULL, NULL);
INSERT INTO #PVC VALUES (9156, N'81044674', N'81038855', N'Substituição da Válvula Pinch CF-2057-33', NULL, N'No Replication/Sem replicação', N'A válvula pinch da linha CF-2057-33 apresentava falhas recorrentes, com rompimento frequente do mangote, além de oxidação dos componentes.
INSERT INTO #PVC VALUES (9157, N'81050431', N'81058947', N'RECUPERAÇÃO DE ESCADA', NULL, N'Others/Outros', N'ESACADA ESTAVA SEM ALGUNS DEGRAUS  IRIA PARA DESCASTE', N'ECONOMIA', N'10139', N'01 - Imagens/01 - Antes/9157.jpeg', N'ESCADA SEM DEGRAUS ', N'01 - Imagens/02 - Depois/9157.jpeg', N'REPOSICIONADO DEGRAUS  APROVEITADO A ESCADA', NULL, N'ECONOMIA', N'ECONOMIA', 4000, 1, N'The CRT uses the sample information to adjust targets, etc. this is important to make sure numbers are accurate.', '2026-03-22T00:00:00.000', '2026-04-02T14:11:53.000', N'81050431', NULL, NULL);
INSERT INTO #PVC VALUES (9158, N'81050431', N'81058947', N'RECUPERAÇÃO DE ESCADA', NULL, N'Others/Outros', N'ANTES A ESCADA NÃO TINHA UMA BOA  ERGONOMIA ', N'ECONIMIA', N'10139', N'01 - Imagens/01 - Antes/9158.jpeg', N'ANTES A ESCADA NÃO TINHA UMA BOA ERGONOMIA ', N'01 - Imagens/02 - Depois/9158.jpeg', N'FOI CONFECCIONADA UM ESCADA COM MELHOR ERGONOMIA', NULL, N'MELHORIA', N'ECONOMIA', 3000, 1, N'5S', '2026-03-21T00:00:00.000', '2026-04-02T14:21:17.000', N'81050431', NULL, NULL);
INSERT INTO #PVC VALUES (9159, N'81044674', N'498974', N'Adequação da Portinhola da CX-2017-32', NULL, N'No Replication/Sem replicação', N'Durante atividade de manutenção na CX-2017-32, foi identificado que a portinhola de acesso apresentava elevado nível de desgaste e avarias.
INSERT INTO #PVC VALUES (9160, N'81003351', N'81003675', N'Avaliação de Reação - Treinamentos ', NULL, N'Others/Outros', N'Apesar da existência da avaliação de reação nos treinamentos, observava-se baixa aderência dos participantes, o que limitava a obtenção de indicadores consistentes.', N'Melhorar a visibilidade dos treinamentos através do olhar dos colaboradores ', N'10332', N'01 - Imagens/01 - Antes/9160.jpeg', N'Apesar da existência da avaliação de reação nos treinamentos, observava-se baixa aderência dos participantes, o que limitava a obtenção de indicadores consistentes.', N'01 - Imagens/02 - Depois/9160.jpeg', N'Foi implementado um token para avaliação de reação, onde os empregados de forma individual consegue acessar e responder a pesquisa logo após o treinamento.', NULL, N'Sim, foi resolvido.
INSERT INTO #PVC VALUES (9161, N'81044674', N'543216', N'Redução de Risco no Acionamento', NULL, N'No Replication/Sem replicação', N'Durante inspeção de segurança, foi identificado que o executante permanecia exposto abaixo do moitão do guindaste durante atividades de manutenção.
INSERT INTO #PVC VALUES (9162, N'81044674', N'81046993', N'Montagem da Proteção das Correias da BP-2057-12', NULL, N'No Replication/Sem replicação', N'Foi identificado que a proteção das correias da BP-2057-12 encontrava-se em condições inadequadas , apresentando desgaste acentuado e comprometendo sua função de proteção.
INSERT INTO #PVC VALUES (9163, N'81044674', N'81058364', N'Instalação de Válvulas para Água de Selagem – BP-2057-34', NULL, N'No Replication/Sem replicação', N'A linha de água de selagem da BP-2057-34 apresentava vazamentos e dificuldade no controle de fluxo, devido a falhas nas válvulas existentes.
INSERT INTO #PVC VALUES (9164, N'81044674', N'81030439', N'Adequação e Substituição da Válvula Guilhotina', NULL, N'No Replication/Sem replicação', N'O equipamento não possuía proteção na região da lâmina da válvula guilhotina, deixando partes cortantes expostas e oferecendo risco de acidentes aos colaboradores.
INSERT INTO #PVC VALUES (9165, N'81044674', N'472918', N'Adequação da Portinhola da CX-2017-32', NULL, N'No Replication/Sem replicação', N'Durante inspeção de manutenção na CX-2017-32, foi identificado que a portinhola de acesso apresentava elevado nível de desgaste e avarias.
INSERT INTO #PVC VALUES (9166, N'81034166', N'81055026', N'limitador do vidro da porta do operador', NULL, N'No Replication/Sem replicação', N'Em virtude da falha ocorrida no vidro da porta do CA 19 que veio a desencaixar do trilho.
INSERT INTO #PVC VALUES (9167, N'499365', N'499365', N'Ferramenta de Solicitação de Dotação Orçamentária', NULL, N'Projects/Projetos', N'Antes o processo de dotação era feito por e-mail e muitas das vezes se perdia, não tinha rastreabilidade, difícil dar devolutiva, demora nas aprovações. ', N'Dar transparencia ao processo, maior controle e rastreabalidade', N'10000', N'01 - Imagens/01 - Antes/9167.jpeg', N'Antes o processo de dotação era feito por e-mail e muitas das vezes se perdia, não tinha rastreabilidade, difícil dar devolutiva, demora nas aprovações, dificuldade de controle. Não havia possibilidade de identificar onde estava o processo, não tinha como dar o report em tempo hábil. Não tinha um ponto focal de aprovação. ', N'01 - Imagens/02 - Depois/9167.jpeg', N'Funcionamento Pleno e eficiente da Ferramenta de gestão de controle do processo de avaliação e aprovação de dotação orçamentaria dos projetos Capex, com etapas de validação entre os stakeholders com aprovação da gerência geral.  ', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/86fed373-9554-403a-9f21-bca15024f16f?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&hint=3db019a3-126d-4e92-a494-e402c071f738&sourcetime=1747767315333&source=portal', N'Com a implantação da ferramenta foi possível identificar gargalhos na demora das aprovações resultando em dificuldade de controle e gestão. Com a ferramenta foi possível acompanhar o status de cada processo, onde estaria pendente, data e responsável, ficando mais eficiente nas aprovações.', N'Com a implantação da ferramenta foi possível identificar gargalhos na demora das aprovações resultando em dificuldade de controle e gestão. Com a ferramenta foi possível acompanhar o status de cada processo, onde estaria pendente, data e responsável, ficando mais eficiente nas aprovações.', 0, NULL, N'Eliminação das falhas de conectores e chicotes no sistema de vidros elétricos do 797FAumento da disponibilidade do equipamento. Redução dos custos de manutenção relacionados a falhas de vidros elétricos. Melhoria na confiabilidade e eficiência operacional do equipamento.', '2026-01-30T00:00:00.000', '2026-04-02T17:08:46.000', N'499365', NULL, NULL);
INSERT INTO #PVC VALUES (9168, N'81034166', N'506216', N'JANELA DE VISITA DO TANK DE EXPANSÃO', NULL, N'No Replication/Sem replicação', N'IMPOSSIBILITAVA VER A MANGUEIRA E SABER AS CONDIÇÕES DAS MANGUEIRAS.', N'MELHORIA COTINUA ', N'10140', N'01 - Imagens/01 - Antes/9168.jpeg', N'Não tínhamos acesso a mangueiras do tanque de expansão, e ver as condições certas, já que o tanque é fixo e impossibilita retirar do lugar para ver as mangueiras. ', N'01 - Imagens/02 - Depois/9168.jpeg', N'Aberto uma janela de visita, assim possibilitou a verificação das mangueiras e melhorando a confiabilidade das mangueiras, possibilitando realizar trocas bem mais acertivas.', NULL, N'sim, pois consigo realizar trocas das mangueiras mais rápidas e mais confortáveis.', N'melhoria contínua e trabalho em equipe  ', 0, NULL, N'Com essa melhoria aplicada o risco de executar essa atividade foi eliminado.', '2026-04-01T00:00:00.000', '2026-04-02T17:47:29.000', N'81034166', NULL, NULL);
INSERT INTO #PVC VALUES (9169, N'1008370', N'1008370', N'Updating DCS Logic for LRT Feed Pumps', NULL, N'Others/Outros', N'Unable to open any of the 4 discharge XV''s on the LRT Feed Pumps. Would require a DCS bypass to open the valves and drain down lines during outages. ', N'Improve daily tasks, time saving during outages, remove need for DCS bypass', N'0', N'01 - Imagens/01 - Antes/9169.jpeg', N'Unable to stroke any of the 4 LRT Feed Pump discharge XV''s in 221 without a bypass. We stroke these valves for line priming, line draining and troubleshooting', N'01 - Imagens/02 - Depois/9169.jpeg', N'Worked with DCS team to update logic. SCR was completed to allow CRT to stroke discharge XV''s of LRT Feed Pumps if all 4 pumps are offline. This will remove the need to apply a bypass when priming or draining the feed line, which can minimize downtime and reduce the total number of bypasses', NULL, N'Yes problem has been solved', N'Review DCS logic more often for improvements', 0, NULL, N'Redução da perda de canetas;
INSERT INTO #PVC VALUES (9170, N'81036747', N'81036747', N'Importance of cooling samples for hydrometer use', NULL, N'Refining/Refino', N'Sample results differing across shifts possibly due to incorrect sample temperatures', N'correct sampling across shifts', N'0', N'01 - Imagens/01 - Antes/9170.jpeg', N'It was noticed across shifts that thickener overflow sample solution specific gravities had discrepancies. There was a possibilty that not all technicians new/were cooling their samples or new the importance of cooling the sample.', N'01 - Imagens/02 - Depois/9170.jpeg', N'The hydrometer temperature range was found to be 15 Celsius which is much cooler than the LRT and CCD samples. They need to be cooled in order for the hydrometer to give an accurate reading. A sheet was done up explaining the importance of cooling the samples and where to find a thermometer. ', NULL, N'yes, all ppts should know the proper procedure now.', N'SOPS and sampling', 0, NULL, N'Hopefully new techs find it less stressful try to determine which sample point to use.', '2026-04-02T00:00:00.000', '2026-04-03T01:51:10.000', N'81036747', NULL, NULL);
INSERT INTO #PVC VALUES (9171, N'81052056', N'81052056', N'Red chain storage', NULL, N'Others/Outros', N'Red chain left on the floor in a location that it is frequently used in.', N'Area organization ', N'0', N'01 - Imagens/01 - Antes/9171.jpeg', N'Red chain left on the floor.', N'01 - Imagens/02 - Depois/9171.jpeg', N'Made storage for red chain and labeled. This will also help with having red chain available when needing it to remove plates rather then having to look for it each time. ', NULL, N'The problem was solved by organizing the area.', N'5S', 0, NULL, NULL, '2026-03-24T00:00:00.000', '2026-04-03T04:35:34.000', N'81052056', NULL, NULL);
INSERT INTO #PVC VALUES (9172, N'81034443', N'81034443', N'Implementação de Registro em Propulsora Pneumatica para Melhoria de Controle e Segurança', NULL, N'Others/Outros', N'A propulsora pneumática não tinha um registro para controle de ar, dificultando o controle de operação e aumentando o risco de falhas e acidentes.', N'Instalar um registro na propulsora pneumática para melhorar o controle de ar, aumentar a segurança operacional e reduzir o risco de falhas e acidentes.', N'10140', N'01 - Imagens/01 - Antes/9172.jpeg', N'A propulsora pneumática não tinha um registro para controle de ar, dificultando o controle de operação e aumentando o risco de falhas e acidentes.', N'01 - Imagens/02 - Depois/9172.jpeg', N' Instalar um registro na propulsora pneumática para melhorar o controle de ar e aumentar a segurança operacional.', NULL, N'Meta: Instalar um registro na propulsora pneumática para melhorar o controle de ar e aumentar a segurança.
INSERT INTO #PVC VALUES (9173, N'81035620', N'81047890', N'Aquisição de pórtico giratório com linha de vida ', NULL, N'Open Pit/Poço aberto', N'Atualmente para execução da atividade em altura em escavadeira hidráulica PC5500; 	para drenar e abastecer  os fluídos dos PTO´S tendo a necessidade de montagem de andaime ou escada plataforma risco de queda de  nível diferente. 
INSERT INTO #PVC VALUES (9174, N'81035620', N'486790', N'Injetores de lubrificação do boom da PC5500', NULL, N'Concentration/Concentração', N'Atualmente para execução da atividade em altura  para teste ou substituição dos injetores de lubrificação do boom   e dos cilindros do boom para realizar as atividade sempre é necessário a montagem de andaime. risco de queda de nível diferente
INSERT INTO #PVC VALUES (9175, N'81050299', N'81050299', N'Otimização Duradoura: Proteção para  Caixa de Fusíveis do 797F', NULL, N'Others/Outros', N'
INSERT INTO #PVC VALUES (9176, N'81035620', N'81047890', N' Injetores de lubrificação do stick   ', NULL, N'Projects/Projetos', N'Atualmente para execução da atividade em altura  para teste ou substituição dos injetores de lubrificação do stick   e dos cilindros do stick para realizar as atividade sempre é necessário a montagem de andaime ou uso de plataforma risco de queda de nível diferente pois o mesmo ficam em altura de 4 metros.
INSERT INTO #PVC VALUES (9177, N'81035620', N'536605', N'valvulas lubrifil pra proteção da linha de ar da propulsora móvel do box ', NULL, N'Projects/Projetos', N'muita água na linha de ar causando a quebra antecipada da propulsora ', N'segurança, produtividade ,aumento da vida útil da propulsora de graxa', N'10324', N'01 - Imagens/01 - Antes/9177.jpeg', N'muita água na linha de ar causando a quebra antecipada da propulsora', N'01 - Imagens/02 - Depois/9177.jpeg', N' Redução  da troca prematura da propulsora aumentando a vida útil.', NULL, N' Ganhos agilidade, segurança e produtividade.
INSERT INTO #PVC VALUES (9178, N'538711', N'538711', N'Portão de acesso da TR-0950-01 à área de granulação', NULL, N'Others/Outros', N'Ausência de portão no acesso da TR-0950-01 para a granulação, possibilitando a entrada indevida de pessoas não autorizadas, aumentando o risco de acidentes e descumprimento dos requisitos de segurança da área.', N'Implantar portão no acesso da TR-0950-01 à área de granulação', N'10233', N'01 - Imagens/01 - Antes/9178.jpeg', N'Anteriormente, o acesso da TR-0950-01 à área de granulação encontrava-se sem portão ou qualquer outro meio de bloqueio físico, permitindo a circulação livre de pessoas. Essa condição possibilita o acesso direto à área operacional, que possui equipamentos em funcionamento contínuo e riscos inerentes ao processo.', N'01 - Imagens/02 - Depois/9178.jpeg', N'Foi realizada a instalação de um portão físico no acesso da TR-0950-01 à área de granulação, com sistema de fechamento adequado com cadeado e controle de acesso restrito. A solução incluiu também a implantação de sinalização de área restrita, indicando claramente a necessidade de autorização para entrada.
INSERT INTO #PVC VALUES (9179, N'538711', N'538711', N'Portão para controle de acesso de pessoas.', NULL, N'Others/Outros', N'Existia ausência de portão ou barreira física para limitar o acesso de pessoas ao raio de manobra da empilhadeira na área da balança de finos, permitindo a circulação de pedestres em uma área destinada à operação de equipamento móvel. Essa condição possibilita o acesso indevido de pessoas não autorizadas, aumentando significativamente o risco de atropelamentos, colisões e acidentes graves.', N'Implantar portão para limitar o acesso de pessoas no raio de manobra da empilhadeira', N'10233', N'01 - Imagens/01 - Antes/9179.jpeg', N'A área operacional apresentava livre circulação de pessoas no raio de manobra da empilhadeira, sem a existência de portão, barreira física ou qualquer outro meio de controle de acesso. Não havia segregação adequada entre a área destinada para armazenamento do palete de bags e movimentação da empilhadeira, expondo pessoas aos riscos inerentes às manobras e movimentação de cargas.', N'01 - Imagens/02 - Depois/9179.jpeg', N'Foi realizada a implantação de um portão com controle de acesso limitado ao raio de manobra da empilhadeira, promovendo a segregação física entre a área de circulação de pedestres e a área de operação do equipamento móvel.
INSERT INTO #PVC VALUES (9180, N'81050299', N'81050299', N'Redução de quebra de conectores ', NULL, N'Others/Outros', N'"Conectores e chicotes do sistema de vidros elétricos do equipamento 797F estão quebrando frequentemente devido ao atrito e exposição ao abrir e fechar das portas da cabine, causando paradas não programadas e aumento de custos de manutenção."', N'Objetivo Geral: Eliminar falhas de conectores e chicotes no sistema de vidros elétricos do equipamento 797F causadas por atrito e exposição. /Metas Específicas:Reduzir em 100% as falhas de conectores e chicotes no sistema de vidros elétricos do 797F nos próximos 12 meses', N'10140', N'01 - Imagens/01 - Antes/9180.jpeg', N'Antes da melhoria, os conectores e chicotes do sistema de vidros elétricos do equipamento 797F estavam expostos ao atrito constante do abrir e fechar das portas da cabine. Isso causava falhas frequentes, resultando em: Paradas não programadas do equipamento. Aumento dos custos de manutenção. Redução da disponibilidade do equipamento. A falta de proteção adequada levava a quebras constantes, impactando a produtividade e eficiência operacional.', N'01 - Imagens/02 - Depois/9180.jpeg', N'Com a melhoria implementada, os conectores e chicotes do sistema de vidros elétricos do equipamento 797F agora estão protegidos contra o atrito e exposição. Isso resultou em: Eliminação das falhas frequentes de conectores e chicotes. Redução significativa das paradas não programadas. Aumento da disponibilidade e confiabilidade do equipamento. Redução dos custos de manutenção. A proteção adequada permitiu uma operação mais estável e eficiente do sistema de vidros elétricos.', NULL, N'Declaração do Problema:
INSERT INTO #PVC VALUES (9181, N'81034922', N'516988', N'Melhoria no conector do sensor de nível do óleo hidráulico na frota 830E', NULL, N'No Replication/Sem replicação', N'O conector do sensor de nível do óleo hidráulico tem um travamento ineficiente, isso gera muitas falhas de baixo nível de óleo hidráulico na frota Komatsu 830E.', N'Eliminar essa falha pelo conector do sensor', N'10140', N'01 - Imagens/01 - Antes/9181.jpeg', N'Devido a vibração do equipamento em operação e a baixa eficiência do travamento do conector do sensor era comum gerar a falha de baixo nível do óleo hidráulico ocasionando uma parada em corretiva, diminuindo os resultados de MTBF  e DF da frota.', N'01 - Imagens/02 - Depois/9181.jpeg', N'Foi soldado o terminal no sensor e instalado um conector com um travamento mais eficiente, com isso foi eliminado a falha por desconexão do chicote.', NULL, N'sim, com a aplicação da melhoria em toda frota vamos eliminar essa falha.', N'Temos oportunidades de melhora o nosso processo a cada dia.', 0, NULL, N'Resposta rápida e eficaz em caso de princípio de incêndio.
INSERT INTO #PVC VALUES (9182, N'81057418', N'81008816', N'Suporte para caneta na prancheta ', NULL, N'Open Pit/Poço aberto', N'Canetas se perdendo com facilidade causando perda de tempo e consumo maior do material ', N'Reduzir a perda de canetas e o tempo gasto na procura desse material', N'10256', N'01 - Imagens/01 - Antes/9182.jpeg', N'As canetas utilizadas na área se perdiam com facilidade sendo frequentemente perdidas ou esquecidas, gerando perda de tempo e desorganização.', N'01 - Imagens/02 - Depois/9182.jpeg', N'As pranchetas passaram a utilizar canetas com suporte, eliminando perdas e melhorando a organização e agilidade nas atividades.', NULL, N'Menos preocupação com canetas, mais agilidade nas atividades ', N'Foi possível observar que melhorias simples, como a fixação da caneta na prancheta, reduzem perdas de material, aumentam a agilidade nas atividades', 0, NULL, N'Atendimento pleno às exigências de SSMA.
INSERT INTO #PVC VALUES (9183, N'81053928', N'81053928', N'LRT sample point location', NULL, N'Refining/Refino', N'Sample points not labeled.', N'Make it easier to locate ', N'10283', N'01 - Imagens/01 - Antes/9183.jpeg', N'Hoses not labeled at sample point', N'01 - Imagens/02 - Depois/9183.jpeg', N'Hoses labeled, now we know which sample point to use.', NULL, N'yes because now a new tech will find it easier to locate.', N'Made it easier to locate', 0, NULL, N'Maior disponibilidade do EC09.
INSERT INTO #PVC VALUES (9184, N'81046149', N'540176', N'Dispositivo de trocar calço ', NULL, N'Others/Outros', N'Durante a montagem do calço da embreagem do equipamento bolas, foram identificado algumas dificuldades que impactam diretamente  a execução da atividade.', N'Dispositivo de trocar de calço para embreagem dos bolas ', N'10362', N'01 - Imagens/01 - Antes/9184.jpeg', N'Durante a montagem do calço da embreagem do equipamento bolas, foram identificado algumas dificuldades que impactam diretamente  a execução da atividade.
INSERT INTO #PVC VALUES (9185, N'607148', N'607939', N'Relocation of Press Cloth Storage Rack to Facilitate Additional Space for Items Requiring Storage Under Fire Suppression ', NULL, N'Refining/Refino', N'Items like IX Resin had to be stacked, or stored outside Fire Suppression area due to lack of space ', N'5S', N'10275', N'01 - Imagens/01 - Antes/9185.jpeg', N'Items like IX Resin had to be stacked, or stored outside Fire Suppression area.  Photo demonstrates Press Cloths being stored in valuable Fire Suppression space due to lack of space. ', N'01 - Imagens/02 - Depois/9185.jpeg', N'Press Cloths were relocated to a nearby area which was essentially “dead space”. Lines were painted and labelled creating additional space for items requiring storage under Fire Suppression.   Photo demonstrates the new Press Cloth Storage Rack location and the newly created Fire Suppression area.', NULL, N'Photo demonstrates the new Press Cloth Storage Rack location and the newly created Fire Suppression area.', N'5S importance', 0, NULL, N'Identificação padronizada da área.', '2026-04-01T00:00:00.000', '2026-04-05T08:04:27.000', N'607148', NULL, NULL);
INSERT INTO #PVC VALUES (9186, N'607148', N'607306', N'Acid Empty Bottle Management', NULL, N'Refining/Refino', N'Spent acid bottles placed in an area with no instructions what to do with them.', N'5S', N'10275', N'01 - Imagens/01 - Antes/9186.jpeg', N'OLD instructions didn''t make sense as there were no instructions what to do with the bottles.', N'01 - Imagens/02 - Depois/9186.jpeg', N'New instructions show what to do with the bottles.', NULL, N'New signage with proper direction', N'5S and proper instruction importance', 0, NULL, N'Acesso permanentemente livre e seguro.
INSERT INTO #PVC VALUES (9187, N'607148', N'81024727', N'Re-purposing weigh scale for CHP Ops from Instrumentation', NULL, N'Refining/Refino', N'Instrumentation Supervisor reached out to Operations to see if a newly discarded weigh scale could be re-purposed for Ops use/CHP did not have a weigh scale in-house.', N'5S, Productivity', N'10275', N'01 - Imagens/01 - Antes/9187.jpeg', N'Instrumentation Supervisor reached out to Operations to see if a newly discarded weigh scale could be re-purposed for Ops use/CHP did not have a weigh scale in-house.', N'01 - Imagens/02 - Depois/9187.jpeg', N'When troubleshooting Precipitation circuit issues (cook times/particle size), testing the density of Sodium Hypochlorite by way of weight is required to eliminate reagent as source of the problem. Prior to the implementation of the scale, it was required to grab samples from the Bleach tanks and walk it over to the ECR Gas lab to use their scale. Now, CHP has a weigh scale at the Leaching Test Bench that can be used to weigh various items if required. ', NULL, N'When troubleshooting Precipitation circuit issues (cook times/particle size), testing the density of Sodium Hypochlorite by way of weight is required to eliminate reagent as source of the problem. Prior to the implementation of the scale, it was required to grab samples from the Bleach tanks and walk it over to the ECR Gas lab to use their scale. Now, CHP has a weigh scale at the Leaching Test Bench that can be used to weigh various items if required. ', N'5s, Productivity Importance', 0, NULL, N'Redução da exposição a riscos de tráfego.
INSERT INTO #PVC VALUES (9188, N'607148', N'81006968', N'Spare chemical storage', NULL, N'Refining/Refino', N'ETP operations would need to travel to another building for chemicals for ETP and boiler test benches. Made keeping track of inventory difficult as well', N'5s, Productivity', N'10275', N'01 - Imagens/01 - Antes/9188.jpeg', N'ETP operations would need to travel to another building for chemicals for ETP and boiler test benches. Made keeping track of inventory difficult as well', N'01 - Imagens/02 - Depois/9188.jpeg', N'Modified shelf unit in ETP to chemical storage area.', NULL, N'Reagents now close to where needed.', N'5s, Productivity', 0, NULL, N'Operação segura, sem interferência visual.
INSERT INTO #PVC VALUES (9189, N'494528', N'494528', N'Dispositivo de scanner do Britador', NULL, N'Crusher/Britadeira', N'Dificuldade em posicionar com eficiência e segurança o  aparelho durante scanner no Britador.', N'Garantir mais segurança para o aparelho e para os operadores durante atividade', N'10044', N'01 - Imagens/01 - Antes/9189.jpeg', N'Durante a atividade de scanner no Britador Primário o posicionamento do aparelho era feito de forma totalmente manual, com exposição de pelo menos duas pessoas à beira da moega do Britador.', N'01 - Imagens/02 - Depois/9189.jpeg', N'Foi desenvolvido dispositivo movimentado por uma ponte rolante, guiado por apenas uma pessoa através de cordas guias.', NULL, N'Menos exposição de pessoas ao lado da moega do britador, risco de queda, menor risco de queda do aparelho de scanner.', N'Diminuição de riscos', 0, NULL, N'Aumento da visibilidade operacional.
INSERT INTO #PVC VALUES (9190, N'997932', N'997932', N'Otimização do controle de ar nas células de flotação.', NULL, N'No Replication/Sem replicação', N'Alto tempo operacional e risco de erro de controle manual das válvulas durante a partida dos sopradores.', N'Eliminar trabalho manual nas controladoras de ar na flotação.', N'10054', N'01 - Imagens/01 - Antes/9190.jpeg', N'Situação Anterior (Antes da Melhoria):
INSERT INTO #PVC VALUES (9191, N'81060882', N'81060882', N'Raspador em "V"', NULL, N'Others/Outros', N'Grande acúmulo de materiais vindo no retorno da correia , acumulando no tambor traseiro e também no retorno da correia.', N'Realizar a remoção dos materiais no retorno da correia.', N'10362', N'01 - Imagens/01 - Antes/9191.jpeg', N'Grande acúmulo de material no transportador, devido não conter um raspador no local para realizar o direcionamento para o local adequado afim de eliminar essa anormalidade.', N'01 - Imagens/02 - Depois/9191.jpeg', N'Realizada a montagem de um raspador em V no retorno da correia para realizar a limpeza no retorno e também para realizar o direcionamento do fluxo do material para facilitar a limpeza operacional.', NULL, N'Raspador vai evitar o acúmulo de material e eliminar a contaminação no tambor traseiro e seus componentes.', N'Limpeza no retorno do transportador.', 0, NULL, N'100% de disponibilidade de extintores manuais.
INSERT INTO #PVC VALUES (9192, N'81060882', N'81060882', N'Adequação dos planos de inspeção Bombas Rejeito.', NULL, N'Others/Outros', N'Durante as manutenções nos componentes internos das bombas de rejeito o inspetor não tinha condições de realizar a inspeção em conjunto com a equipe preventiva devido seu plano de inspeção não constar para o respectivo equipamento naquele dia da preventiva, não sendo necessário a verificação dos componentes internos pelo inspetor.', N'Realizar a inspeção nos componentes internos e verificações dos dimensionais dos componentes. ', N'10362', N'01 - Imagens/01 - Antes/9192.jpeg', N'Durante manutenção preventiva no acoplamento de alta rotação da bomba de rejeito foi identificado a ausência de lubrificação, causando o desgaste prematuro dos componentes internos e também do cubo.', N'01 - Imagens/02 - Depois/9192.jpeg', N'Foi solicitado a revisão do plano de inspeção para cruzar as tarefas dos planos preventivos e sensitivos para dar condições do inspetor realizar as verificações dos componentes internos e mensurar os níveis de desgaste, folgas e espessuras.
INSERT INTO #PVC VALUES (9193, N'36805', N'81039148', N'Identificação das áreas com Equipamentos Teleoperados', NULL, N'Others/Outros', N'Equipamentos operando ou estacionados em áreas sem sinalização específica, sem alerta formal de teleoperação e sem isolamento físico, gerando risco de aproximação indevida de pessoas e veículos e potencial para acidentes graves.', N'Eliminar o risco de acesso indevido a equipamentos operando ou estacionados por meio da padronização da sinalização, isolamento da área e formalização do processo, garantindo 100% de conformidade em SSMA.', N'10090', N'01 - Imagens/01 - Antes/9193.jpeg', N'Falta de isolamento físico na área de operação teleopeda, veículos circulando próximo ao equipamento.', N'01 - Imagens/02 - Depois/9193.jpeg', N'Área delimitada com sinalização padronizada e visível, com barreira física.', NULL, N'Risco alto e não conformidade (antes) → risco controlado e conformidade (depois).', N'A ausência de padrão gera variações e exposição ao risco.', 0, NULL, N'Drenagem controlada e sustentável.
INSERT INTO #PVC VALUES (9194, N'36805', N'81005436', N'Reposicionamento do Extintor de Incêndio do TT89', NULL, N'Others/Outros', N'O extintor de incêndio do TT89 encontrava-se mal posicionado, com baixa visibilidade e difícil acesso, podendo comprometer a resposta em situação de emergência.', N'Garantir que o extintor esteja corretamente posicionado, visível e acessível, atendendo aos requisitos de SSMA e combate a incêndio.', N'10090', N'01 - Imagens/01 - Antes/9194.jpeg', N'Extintor em local sem visibilidade; dificuldade de acesso em emergência.', N'01 - Imagens/02 - Depois/9194.jpeg', N'Extintor reposicionado em local adequado, visível e de fácil acesso', NULL, N'Antes: acesso difícil e risco elevado.
INSERT INTO #PVC VALUES (9195, N'36805', N'81035400', N'Proibição de Retirada do Extintor Kidde – Auditório da Infraestrutura de Mina', NULL, N'Others/Outros', N'O extintor Kidde instalado no auditório da infraestrutura de mina estava sujeito à retirada indevida, comprometendo a prontidão de resposta em caso de emergência.', N'Garantir a permanência obrigatória do extintor no auditório, assegurando disponibilidade contínua e conformidade com os requisitos de SSMA e combate a incêndio.', N'10090', N'01 - Imagens/01 - Antes/9195.jpeg', N'Possibilidade de retirada do extintor para uso em outras áreas.
INSERT INTO #PVC VALUES (9196, N'36805', N'536238', N'Instalação de Tomada para Carregamento do Joystick – Equipamento EC09', NULL, N'Others/Outros', N'O joystick do equipamento EC09 não possuía ponto dedicado para carregamento de bateria, gerando improvisações, risco de falha operacional e indisponibilidade do equipamento.', N'Disponibilizar tomada fixa, segura e adequada para carregamento da bateria do joystick do EC09, garantindo confiabilidade operacional e atendimento aos requisitos de SSMA.', N'10090', N'01 - Imagens/01 - Antes/9196.jpeg', N'Ausência de tomada específica para carregamento com uso de pontos improvisados ou deslocamento do equipamento.', N'01 - Imagens/02 - Depois/9196.jpeg', N'Tomada instalada em local definido e seguro para carregamento do joystick.', NULL, N'Antes: improviso, risco e indisponibilidade.
INSERT INTO #PVC VALUES (9197, N'36805', N'536238', N'Autonomia Operacional para Execução de Atividade sem Dependência da Redel', NULL, N'Others/Outros', N'A execução da atividade dependia exclusivamente da equipe da Redel, gerando tempo de espera, atrasos no início das operações após a mobilização e baixa agilidade na locomoção entre frentes de trabalho.', N'Eliminar a dependência da Redel, garantindo autonomia operacional, redução do tempo de espera e maior fluidez no início das atividades.', N'10090', N'01 - Imagens/01 - Antes/9197.jpeg', N'Necessidade de aguardar a chegada da equipe Redel para instalar o sistema de aterramento da escavadeira teleoperada, acarretava no atraso no início das atividades após mobilização.', N'01 - Imagens/02 - Depois/9197.jpeg', N'Mudança do método de aterramento, realizado com a equipe própria. Maior agilidade e eficiência operacional.', NULL, N'Antes: dependência externa e atrasos recorrentes.
INSERT INTO #PVC VALUES (9198, N'81020702', N'486351', N'Suporte placas de identificação', NULL, N'Others/Outros', N'As placas eram colocadas de formas desordenadas', N'Desenvolver suporte para padronizar', N'10140', N'01 - Imagens/01 - Antes/9198.jpeg', N'As placas era aplicadas nos cerquites do box de manutenção, porém não ficava padronizado.', N'01 - Imagens/02 - Depois/9198.jpeg', N'Foi desenvolvido um suporte para cada ferramenta no box, e identificado todos de forma padronizada, melhorando o nosso cenário e contribuindo com o 5s da área.', NULL, N'Sim', N'Padronização', 0, NULL, N'Zero acidentes por queda de nível no canteiro.
INSERT INTO #PVC VALUES (9199, N'36805', N'505288', N'Ordenação do Estacionamento no Acesso Leve – Curva CA01', NULL, N'Others/Outros', N'Veículos de revezamento estacionados no acesso de veículos leves do estacionamento, na curva CA01, obstruindo o tráfego, devido à estreitamento da via, gerando riscos de incidentes entre veículos e pessoas.', N'Eliminar a obstrução do acesso leve, garantindo tráfego seguro, fluido e conforme, reduzindo o risco de incidentes.', N'10090', N'01 - Imagens/01 - Antes/9199.jpeg', N'Veículos parados em local indevido, acesso estreito sem margem para manobras seguras com risco de colisões e atropelamentos.', N'01 - Imagens/02 - Depois/9199.jpeg', N'Retirado estreitamento, tráfego seguro e contínuo, proibição de estacionamento no acesso leve da curva CA01.', NULL, N'Antes: acesso obstruído e risco elevado.
INSERT INTO #PVC VALUES (9200, N'36805', N'505288', N'Adequação de Acesso para Veículos de Apoio – Drenagem 300 Sul / Curva CA01', NULL, N'Others/Outros', N'A implantação do estacionamento pesado na curva CA01 inviabilizou o acesso seguro pela via habitual, obrigando os veículos de apoio das obras periféricas a trafegarem por dentro do pátio de tubos da Drenagem 300 Sul para acessar as gaiolas de placas, gerando risco operacional e de tráfego.', N'Restabelecer um acesso seguro, segregado e adequado para os veículos de apoio, eliminando a circulação indevida pelo pátio de tubos.', N'10090', N'01 - Imagens/01 - Antes/9200.jpeg', N'Acesso original bloqueado pelo estacionamento pesado.
INSERT INTO #PVC VALUES (9201, N'36805', N'505288', N'Correção do Ofuscamento de Operadores por Antena de LED na Cabine', NULL, N'Others/Outros', N'A antena de LED instalada atrás da cabine do equipamento está causando ofuscamento visual dos operadores, reduzindo a visibilidade e aumentando o risco de acidentes durante a operação.', N'Eliminar o ofuscamento visual, garantindo conforto, visibilidade adequada e operação segura do equipamento.', N'10090', N'01 - Imagens/01 - Antes/9201.jpeg', N'LED posicionado atrás da cabine, incômodo visual e prejuízo à visibilidade do operador com aumento do risco operacional, especialmente em operações noturnas.', N'01 - Imagens/02 - Depois/9201.jpeg', N'Antena de LED reposicionada, protegida ou ajustada, eliminação do ofuscamento e melhoria do conforto visual do operador.', NULL, N'Antes: ofuscamento e risco operacional.
INSERT INTO #PVC VALUES (9202, N'36805', N'536138', N'Instalação de Suporte com Espelho Retrovisor Ajustável na Bica', NULL, N'Others/Outros', N'A ausência de espelho retrovisor ajustável na bica limita a visibilidade do operador, aumentando o risco de colisões, contatos indevidos com estruturas e falhas durante a operação.
INSERT INTO #PVC VALUES (9203, N'36805', N'536138', N'Otimização do Abastecimento de Pipas de Grande Porte – Bica 07 (SAT)', NULL, N'Others/Outros', N'A Bica 07 na SAT gera atrasos no abastecimento de pipas de grande porte, especialmente durante períodos de treinamento, impactando diretamente a eficiência da umectação de particulados.', N'Reduzir o tempo de abastecimento dos pipas de grande porte, garantindo continuidade da operação e efetividade da umectação de particulados, mesmo em períodos de treinamento.', N'10090', N'01 - Imagens/01 - Antes/9203.jpeg', N'Baixa vazão/capacidade da Bica 07 para pipas grandes, filas e atrasos durante treinamentos, redução da frequência de umectação.', N'01 - Imagens/02 - Depois/9203.jpeg', N'Processo de abastecimento mais ágil.
INSERT INTO #PVC VALUES (9204, N'36805', N'536138', N'Controle de Recarga e Estoque de Extintores – Prédio Castanheira', NULL, N'Others/Outros', N'Não havia registro formal de controle de recarga e estoque de extintores de incêndio manuais na gaiola de extintores do prédio Castanheira, ocasionando desabastecimento e risco à prontidão em emergências.', N'Implantar controle sistemático de estoque e recarga de extintores, assegurando disponibilidade contínua e conformidade com requisitos de SSMA e combate a incêndio.', N'10090', N'01 - Imagens/01 - Antes/9204.jpeg', N'Ausência de registro de controle, fesabastecimento recorrente da gaiola com tisco de indisponibilidade em emergência.', N'01 - Imagens/02 - Depois/9204.jpeg', N'Implantação de registro de controle de estoque e recarga.
INSERT INTO #PVC VALUES (9205, N'36805', N'532422', N'Direcionamento na saída do Estacionamento do Espaço Jequitibá', NULL, N'Others/Outros', N'Risco de incidentes e colisões entre veículos na entrada e saída do estacionamento do Espaço  Jequitibá, devido à falta de direcionamento na via, comprometendo a segurança de motoristas e pedestres.', N'Implantar direcionamento viário claro e padronizado, garantindo fluxo seguro, organizado e sem conflitos na entrada e saída do estacionamento.', N'10090', N'01 - Imagens/01 - Antes/9205.jpeg', N'Ausência de sinalização de entrada e saída, conflitos no fluxo de saída dos espaço jequiti e castanheiras, risco elevado de colisões e quase-acidentes.', N'01 - Imagens/02 - Depois/9205.jpeg', N'Direcionamento definido (entrada/saída), instalado de sinalização adequada e organizada. Melhoria do fluxo e da segurança dos acessos.', NULL, N'Antes: conflito de fluxo e risco elevado.
INSERT INTO #PVC VALUES (9206, N'36805', N'532422', N'Implantação de Condutor para Escoamento de Água', NULL, N'Others/Outros', N'A ausência de condutor adequado para escoamento de água provoca carreamento descontrolado, erosões, poças e impactos na segurança viária, operacional e ambiental.', N'Implantar condutor de escoamento de água eficiente, direcionando corretamente a drenagem e reduzindo riscos operacionais, ergonômicos e ambientais.', N'10090', N'01 - Imagens/01 - Antes/9206.jpeg', N'Água escoando de forma irregular, formação de erosões, lama e poças com impacto na trafegabilidade e segurança das pessoas e veículos.
INSERT INTO #PVC VALUES (9207, N'36805', N'81003238', N'Plataforma Segura de Acesso ao Sump B', NULL, N'Others/Outros', N'O acesso ao Sump B feito de forma inadequada, expondo trabalhadores a risco de queda, dificuldade de mobilidade e condições inseguras durante inspeção, limpeza e manutenção.', N'Garantir acesso seguro, estável e ergonômico ao Sump B por meio da implantação de plataforma adequada, atendendo aos requisitos de SSMA.', N'10090', N'01 - Imagens/01 - Antes/9207.jpeg', N'Acesso improvisado feito por cima da leira, risco elevado de queda e escorregamento além da dificuldade de execução das atividades operacionais.', N'01 - Imagens/02 - Depois/9207.jpeg', N'Plataforma de acesso implantada, nivelada e resistente, acesso seguro para inspeção, limpeza e manutenção do Sump B.', NULL, N'Antes: acesso inseguro e risco elevado.
INSERT INTO #PVC VALUES (9208, N'36805', N'81057164', N'Adequação do Suporte do Pluviômetro da Cava', NULL, N'Others/Outros', N'O pluviômetro da cava encontrava-se com suporte inadequado/instável, comprometendo a confiabilidade das medições, a segurança no acesso e a integridade do equipamento.', N'Adequar o suporte do pluviômetro, garantindo estabilidade, segurança, correto posicionamento e leituras confiáveis.', N'10090', N'01 - Imagens/01 - Antes/9208.jpeg', N'Suporte improvisado ou inadequado.
INSERT INTO #PVC VALUES (9209, N'36805', N'81030756', N'Segregação Segura de Tráfego no Acesso Leve – Mitigação de Ponto Cego', NULL, N'Others/Outros', N'Veículos leves estavam acessando o acesso leve de frente ao lado de ponto cego dos caminhões fora de estrada, configurando condição crítica de risco para colisões e atropelamentos.', N'Eliminar a exposição dos veículos leves ao ponto cego de equipamentos fora de estrada, garantindo segregação segura de fluxos e melhoria da segurança das vias', N'10090', N'01 - Imagens/01 - Antes/9209.jpeg', N'Veículos leves trafegando no sentido oposto ao campo visual dos caminhões, alto risco de colisões e incidentes graves.
INSERT INTO #PVC VALUES (9210, N'36805', N'81030756', N'Otimização do Estacionamento nas Praças de Carga', NULL, N'Others/Outros', N'Caminhões estavam estacionando de ré nas baias próximas às praças de carga, ocasionando perda de tempo com manobras e aumento do risco de colisões durante aproximação, estacionamento e saída.', N'Reduzir o tempo de manobra e eliminar o risco de colisões, garantindo fluxo mais ágil e estacionamento seguro nas praças de carga.', N'10090', N'01 - Imagens/01 - Antes/9210.jpeg', N'Estacionamento de ré com manobras repetitivas e demoradas.
INSERT INTO #PVC VALUES (9211, N'36805', N'2149', N'Implantação de Guarda‑Corpo no Canteiro da Supressão Vegetal', NULL, N'Others/Outros', N'Existe falta de guarda‑corpo na área do canteiro, expondo trabalhadores a risco de queda em desnível, com potencial para acidentes graves.', N'Eliminar o risco de queda por meio da implantação de guarda‑corpo adequado, garantindo acesso e permanência seguros na área.', N'10090', N'01 - Imagens/01 - Antes/9211.jpeg', N'Área com desnível sem proteção, risco elevado de queda de pessoas, pessoas sentadas na leira.', N'01 - Imagens/02 - Depois/9211.jpeg', N'Guarda‑corpo instalado e conforme norma deixando a área protegida e segura para circulação e atividades.', NULL, N'Antes: área sem proteção e risco elevado.
INSERT INTO #PVC VALUES (9212, N'36805', N'2149', N'Suporte de Madeira para Organização de Mangueira', NULL, N'Others/Outros', N'A mangueira de higienização era mantida diretamente no solo, sem organização adequada, não atendendo aos princípios de 5S e apresentando condição ergonomicamente inadequada.', N'Organizar a mangueira por meio da implantação de suporte de madeira, garantindo ergonomia, segurança e conformidade com o 5S.', N'10090', N'01 - Imagens/01 - Antes/9212.jpeg', N'Mangueira apoiada no chão, risco de tropeço e desgaste do material, uso desconfortável e esforço físico desnecessário.', N'01 - Imagens/02 - Depois/9212.jpeg', N'Mangueira organizada em suporte de madeira, feita com madeira reaproveitada da Supressão. Área limpa, padronizada e ergonomicamente adequada.', NULL, N'Antes: mangueira no solo, desorganização e risco ergonômico.
INSERT INTO #PVC VALUES (9213, N'36805', N'2149', N'Espaço Adequado para Assinatura e Café dos Colaboradores', NULL, N'Others/Outros', N'Falta de local adequado para os colaboradores realizarem assinaturas de documentos e pausa para café, resultando em improvisações, desconforto e falta de organização no ambiente de trabalho.', N'Disponibilizar área apropriada, organizada e segura para assinatura de documentos e consumo de café, promovendo conforto, ergonomia e organização.', N'10090', N'01 - Imagens/01 - Antes/9213.jpeg', N'Ausência de espaço definido para assinatura e café, desconforto e desorganização no ambiente.', N'01 - Imagens/02 - Depois/9213.jpeg', N'Espaço definido com mesa, cadeiras e ponto para café.
INSERT INTO #PVC VALUES (9214, N'36805', N'2149', N'Correção de Drenagem no Pátio de Madeiras', NULL, N'Others/Outros', N'Dreno aberto direcionado para o pátio de madeiras, ocasionando acúmulo de água no interior do pátio e consequente deterioração das madeiras, além de impactos operacionais e de organização.', N'Redirecionar e adequar o sistema de drenagem, eliminando o acúmulo de água no pátio e preservando a integridade das madeiras.', N'10090', N'01 - Imagens/01 - Antes/9214.jpeg', N'Dreno aberto descarregando diretamente no pátio de madeiras, acumulando água e lama, com potencial de apodrecimento de madeiras', N'01 - Imagens/02 - Depois/9214.jpeg', N'Dreno direcionado para local adequado.
INSERT INTO #PVC VALUES (9215, N'36805', N'2149', N'Estacionamento Adequado para Caminhões da Supressão', NULL, N'Others/Outros', N'Dalta de estacionamento adequado para os caminhões da Supressão, resultando em estacionamento improvisado, interferência em acessos, risco de incidentes e baixa organização operacional.', N'Disponibilizar estacionamento específico, sinalizado e dimensionado para os caminhões da Supressão, garantindo segurança, organização e fluidez operacional.', N'10090', N'01 - Imagens/01 - Antes/9215.jpeg', N'Caminhões estacionados em locais improvisados.
INSERT INTO #PVC VALUES (9216, N'36805', N'533881', N'Correção de Depressão no acesso em Frente ao Estacionamento do Posto de Combustíveis', NULL, N'Others/Outros', N'Depressões no solo e formação de poças de lama em frente ao estacionamento do posto de combustíveis, comprometendo a segurança viária, a trafegabilidade e as condições operacionais da área.', N'Eliminar as depressões e o acúmulo de lama, garantindo acesso seguro, piso estável e drenagem adequada no entorno do estacionamento.', N'10090', N'01 - Imagens/01 - Antes/9216.jpeg', N'Piso irregular com depressões; lama e poças de água.
INSERT INTO #PVC VALUES (9217, N'36805', N'81038547', N'Confecção de Suporte Metálico para Lavadora de alta pressão', NULL, N'Others/Outros', N'A lavadora utilizada nas atividades de limpeza não possuía suporte adequado, sendo armazenada de forma desorganizada, com baixa visibilidade da área, risco de pequenos acidentes e não conformidade com o 5S.', N'Confeccionar e instalar suporte metálico adequado para a lavadora, garantindo organização, segurança, ergonomia e melhor aproveitamento do espaço.', N'10090', N'01 - Imagens/01 - Antes/9217.jpeg', N'Lavadora apoiada diretamente no solo ou em local improvisado.
INSERT INTO #PVC VALUES (9218, N'36805', N'81038547', N'Implantação de Gabarito para Esquadrejamento de Chapas de Acrílico', NULL, N'Others/Outros', N'Falta de gabarito para posicionamento das chapas de acrílico, fazendo com que o esquadrejamento fosse realizado manualmente, tornando o processo mais demorado e suscetível a variações dimensionais.', N'Implantar gabarito de posicionamento padronizado, garantindo agilidade, precisão e repetibilidade no esquadrejamento das chapas de acrílico.', N'10090', N'01 - Imagens/01 - Antes/9218.jpeg', N'Posicionamento manual das chapas, maior tempo de ajuste e esquadro, variações dimensionais e risco de retrabalho.', N'01 - Imagens/02 - Depois/9218.jpeg', N'Gabarito implantado para posicionamento correto das chapas.
INSERT INTO #PVC VALUES (9219, N'36805', N'527377', N' Melhoria na Proteção do Suporte para Corte de Tubos', NULL, N'Others/Outros', N'O suporte para corte de tubos apresentava proteção inadequada ou inexistente, expondo operadores a risco de contato com partes metálicas, impactos e danos aos materiais durante o apoio e o corte.', N'Aprimorar a proteção do suporte de corte, garantindo segurança, ergonomia e melhor apoio dos tubos durante a atividade.', N'10090', N'01 - Imagens/01 - Antes/9219.jpeg', N'Pontos metálicos expostos no suporte, risco de cortes, impactos e danos aos tubos com condição inadequada para apoio seguro.', N'01 - Imagens/02 - Depois/9219.jpeg', N'Proteção feita de tubos no suporte, apoio seguro e estável para os tubos, atividade mais segura e padronizada.', NULL, N'Antes: suporte com risco e proteção insuficiente.
INSERT INTO #PVC VALUES (9220, N'36805', N'81038609', N'Melhoria Ergonômica no Transporte de Estacas', NULL, N'Others/Outros', N'O transporte de estacas era realizado de forma inadequada para os empregados, impactando negativamente a ergonomia, com aumento do esforço físico e risco à saúde ocupacional.', N'Adequar o transporte de estacas, garantindo melhores condições ergonômicas, redução do esforço físico e maior segurança aos empregados.', N'10090', N'01 - Imagens/01 - Antes/9220.jpeg', N'Transporte manual inadequado, posturas incorretas e esforço excessivo e Risco de fadiga, lesões e desconforto físico.', N'01 - Imagens/02 - Depois/9220.jpeg', N'Construído um suporte para transporte de forma adequada e/ou com apoio, melhoria das condições ergonômicas da atividade.', NULL, N'Antes: transporte inadequado e alto esforço físico.
INSERT INTO #PVC VALUES (9221, N'36805', N'521907', N' Totem Carregador de Celular', NULL, N'Others/Outros', N'Havia ausência de pontos adequados para carregamento de celulares, fazendo com que pessoas utilizassem tomadas escondidas, ficassem sentadas no chão e deixassem cabos espalhados, gerando riscos de segurança, ergonomia inadequada e desorganização do ambiente.', N'Disponibilizar totem carregador de celulares em local acessível, garantindo segurança, ergonomia', N'10090', N'01 - Imagens/01 - Antes/9221.jpeg', N'Falta de pontos adequados de carregamento, pessoas sentadas no chão próximo às tomadas e Cabos espalhados, risco de tropeços e choques elétricos.', N'01 - Imagens/02 - Depois/9221.jpeg', N'Feito um Totem com carregador instalado em local apropriado.
INSERT INTO #PVC VALUES (9222, N'36805', N'81035634', N'Identificação da Voltagem da Impressora', NULL, N'Others/Outros', N'A impressora não possuía identificação visível de voltagem, gerando dúvidas no momento da conexão, risco de ligação em tensão incorreta, danos ao equipamento e condição insegura de uso.', N'Identificar de forma clara e permanente a voltagem correta da impressora, garantindo segurança elétrica, confiabilidade do equipamento e padronização.', N'10090', N'01 - Imagens/01 - Antes/9222.jpeg', N'Ausência de identificação de voltagem, risco de ligação incorreta na tomada com possibilidade de dano ao equipamento e choque elétrico.', N'01 - Imagens/02 - Depois/9222.jpeg', N'Impressora identificada com etiqueta de voltagem correta, para uso seguro e padronizado do equipamento.', NULL, N'Antes: ausência de identificação e risco elétrico.
INSERT INTO #PVC VALUES (9223, N'503436', N'503436', N'INSTALAÇÃO DE GATEWAY PARA COLETAS ONLINE', NULL, N'Others/Outros', N'ANTERIORMENTE AS COLETAS ERAM FEITAS OFFLINE NAS INFORMAÇÕES DE VIBRAÇÃO DO CAMINHÃO KOMATSU 830 E TAG CA08 NUMA DISTÂNCIA DE 2 MÊTRIOS O COLABORADOR TINHA QUE SE APROXIMAR E MANTER O CAMINHÃO EM 1930 RPM.', N'COLETAR VIBRAÇÃO ONLINE', N'10015', N'01 - Imagens/01 - Antes/9223.jpeg', N'COLETA DE VIBRAÇÃO ERAM FEITAS OFFLINE PROXIMAS DO CAMINHÃO E DO PONTO ESPECIFICADO NA PLATAFORMA, UMA DISTÂNICA DE 2 MÊTROS DO COMPONENTE, INICIAVA-SE A COLETA EM ALTA ROTAÇÃO.', N'01 - Imagens/02 - Depois/9223.jpeg', N'A INSTALAÇÃO DE UMA GATEWAY OU PAINEL DE RECOLHIMENTO DE DADOS DE VIBRAÇÃO FICARÁ ONLINE PARA COLETAR AS INFORMAÇÕES DOS PONTOS MONITORADOS, CUBO DE HÉLICE , ALTERNADOR PRINCIPAL, BOMBA DE ELEVAÇÃO E DIREÇÃO E FREIO. ACADA 10 MINUTOS UM DISPARO DE SINAL É ENVIADO AOS SENSORES FIXADOS NO EQUIPAMENTO FAZENDO UMA COLETA DE VIBRAÇÃO REMOTA E SEGURA.', NULL, N'EM TESTES PARA TODA A FROTA KOMATSU 830 E & 930 E INICIAREMOS OS TESTES DOS TRIGGERS PARA COLETAS DURANTE A ELEVAÇÃO DA BASCULA EM ALTA ROTAÇÃO 1930 RPM.', N'SEGURANÇA E MAIOR AGILIDADE DE DADOS', 10, 1, N'Melhoria contínua da qualidade e confiabilidade do processo de corte.', '2026-04-01T00:00:00.000', '2026-04-06T00:19:50.000', N'503436', NULL, NULL);
INSERT INTO #PVC VALUES (9224, N'503436', N'503436', N'MONITORAMENTO ONLINE DO MOTOR ELÉTRICO E BOMBA DO LAVADOR', NULL, N'Others/Outros', N'O MONITORAMENTO DO MOTOR DO LAVADOR E BOMBA IMBIL ERAM REALIZADOS ATRAVÉS DE COLETAS OFFLINE E PRESENCIAL NO COMPONENTE LEVANDO MAIS DE UMA HORA PARA LIBERAÇÃO DE DOCUMENTAÇÃO E ATRASOS, MUITAS VEZES GERANDO QUEBRAS DE ROLAMENTO DO MOTOR ELÉTRICO.', N'COLETAR ONLINE E ANALISAR EM TEMPO ÁGIL ', N'10015', N'01 - Imagens/01 - Antes/9224.jpeg', N'COLETAS OFFLINE E MUITOS EVENTOS DE ALTA TEMPERATURA DO ROLAMENTO DO MOTOR ELÉTRICO, QUEBRAS EM HORAS INESPERADAS DO TURNO. DEMORA PARA ASSINATURA DE DOCUMENTOS E DESLOCAMENTOS ATÉ O LOCAL DO ATIVO.', N'01 - Imagens/02 - Depois/9224.jpeg', N'COM A INSTALAÇÃO DE UMA GATEWAY LTE NA FRENTE DO MOTOR E BOMBA DO LAVADOR DE EQUIPAMENTOS, CONSEGUIMOS ATIVAR AS COLETAS DE VIBRAÇÃO ONLINE E COM DISPAROS DE DADOS A CADA 10 MINUTOS EM DIFERENTES TURNOS, MANTENDO ASSIM UMA TENDÊNCIA DE MONITORAMENTO DO ATIVO, MAIOR DISPONIBILIDADE PARA MONITORARMOS ESSES COMPONENTES.', NULL, N'A META INICIAL E MONITORARMOS O MOTOR ELÉTRICO E A BOMBA DE MULTI ESTÁGIO EVITANDO QUEBRAS INESPERADAS E UMA MAIOR AGILIDADE DE DADOS DE VIBRAÇÃO ONLINE PARA NOSSO CMA DA MINA.', N'MAIOR AGILIDADE NO MONITORAMENTO E LAUDOS', 5970, 1, N'Confiabilidade nos monitoramento 
INSERT INTO #PVC VALUES (9225, N'81054419', N'81054419', N'Metodologia de dimensionamento de Estoque para materiais estratégicos', NULL, N'Others/Outros', N'O dimensionamento do parque reserva era realizado de forma empírica, sem metodologia estatística estruturada e com baixa integração entre as áreas. Esse cenário gerava falta de padronização, excesso ou ausência de itens, alto capital imobilizado, riscos de indisponibilidade operacional e baixa previsibilidade de custos.', N'Implantar metodologia estatística e probabilística para dimensionamento do parque reserva', N'10015', N'01 - Imagens/01 - Antes/9225.jpeg', N'O dimensionamento era feito com base em histórico, sem uso estruturado de dados estatísticos, não havia definição clara de nível de serviço ou risco aceitável, resultando em estoques subdimensionados ou sobre dimensionados', N'01 - Imagens/02 - Depois/9225.jpeg', N'Foi implementada metodologia estatística estruturada, utilizando Monte Carlo para itens com histórico robusto e Poisson para eventos raros. Passou-se a considerar confiabilidade, mantenabilidade, lead time e horizonte de até cinco anos, com definição explícita de nível de serviço e risco, integração entre áreas e apoio de software especialista em confiabilidade', NULL, N'A meta estabelecida era dimensionar o park reserva com base estatística, garantindo alto nível de serviço e redução de custos. O resultado alcançado atendeu plenamente ao objetivo, proporcionando decisões tecnicamente sustentadas, redução de riscos operacionais e criação de uma metodologia replicável, alinhada às melhores práticas de gestão de ativos', N' O uso de métodos estatísticos aumenta significativamente a assertividade no dimensionamento de estoques. A escolha do método deve considerar a maturidade dos dados, e a definição clara de risco e nível de serviço é fundamental. A integração entre áreas e a padronização do processo são fatores-chave para sustentabilidade e escalabilidade da solução', 4000000, 1, N'Eliminar riscos de acidentes na remoção da lona, melhorar a ergonomia do ASG, padronizar a atividade, evitar improvisos e tornar o processo mais seguro, eficiente e confiável.', '2026-03-25T00:00:00.000', '2026-04-06T09:16:22.000', N'81054419', NULL, NULL);
INSERT INTO #PVC VALUES (9226, N'81019448', N'81019448', N'Estruturação da Gestão do Material Rodante considerando Longo Lead Time', NULL, N'Others/Outros', N'A gestão do material rodante era reativa, com lead time de cerca de 12 meses entre solicitação, fabricação e fornecimento. Resultando em compras emergenciais, fretes aéreos, aumento de custos logísticos e riscos operacionais, financeiros e de segurança, devido à falta de um processo integrado entre as áreas de inspeção, engenharia, planejamento e suprimentos', N'Implantar um modelo preventivo e integrado de gestão do material rodante, capaz de antecipar a necessidade de substituição dos componentes críticos, alinhando vida útil, criticidade e lead time, de forma a:  1.Eliminar compras emergenciais e fretes aéreos 2.Aumentar a previsibilidade da tomada de decisão técnica 3.Reduzir riscos de paradas não planejadas 4.Mitigar impactos operacionais, financeiros e de segurança 5.Sustentar a disponibilidade física dos equipamentos críticos.', N'10015', N'01 - Imagens/01 - Antes/9226.jpeg', N'A gestão do material rodante era reativa, com identificação tardia da necessidade, sem considerar o lead time crítico. Havia falta de integração entre áreas, compras emergenciais, fretes aéreos, altos custos e elevada exposição a riscos.
INSERT INTO #PVC VALUES (9227, N'81043741', N'81043741', N'Mapa de Ativos Integrado para Planejamento, Projetos e Eficiência Operacional', NULL, N'Others/Outros', N'A operação apresentava falhas devido à falta de centralização e padronização das informações dos ativos da mina, gerando imprecisão no levantamento de materiais e custos. A limitação de dados dificultava o planejamento detalhado e o dimensionamento antecipado, resultando em retrabalhos, ajustes tardios e paradas não planejadas.', N'Centralizar e integrar planejamento e informações dos ativos em um mapa único', N'10355', N'01 - Imagens/01 - Antes/9227.jpeg', N'Informações dos ativos eram descentralizadas e sem padronização, gerando incertezas de localização, imprecisão no levantamento de materiais e custos e falta de dados para um planejamento detalhado.', N'01 - Imagens/02 - Depois/9227.jpeg', N'Os ativos passaram a ser visualizados em um mapa único e integrado com precisão de localização, materiais e custos, permitindo planejamento detalhado, antecipação e redução de retrabalhos e paradas.', NULL, N'A meta inicial era centralizar e integrar as informações dos ativos para melhorar o planejamento, os projetos e a precisão no dimensionamento de materiais e custos. Os problemas identificados incluíam dados descentralizados, imprecisão de informações, dificuldade de planejamento detalhado e confusão na localização dos ativos.
INSERT INTO #PVC VALUES (9228, N'201675', N'201675', N'Remote Desktop Licensing Standarization', NULL, N'Others/Outros', N'~15 servers identified with inconsistent licensing configuration and over provisioned licenses - resulting in increased cost and operational complexity.  ', N'Standardize Remote Desktop License Type and Right-Size license investment', N'0', N'01 - Imagens/01 - Antes/9228.jpeg', N'1)Inconsistent Remote Desktop license configuration on Windows servers (per user vs per device)
INSERT INTO #PVC VALUES (9229, N'520046', N'520046', N'Ponto de resgate contra afogamento - lavador', NULL, N'Others/Outros', N'Problema detectado devido Risco de afogamento sem local estruturado para resgate.
INSERT INTO #PVC VALUES (9230, N'514353', N'514353', N'Melhoria no Processo de Corte de Cerâmica', NULL, N'Others/Outros', N'O corte de cerâmicas era feito no chão com cortador manual, exigindo posturas inadequadas como curvar-se ou ajoelhar-se, gerando desconforto, risco ergonômico, menor produtividade e falta de padronização.', N'Melhor ergonomia e conforto para o colaborador', N'10017', N'01 - Imagens/01 - Antes/9230.jpeg', N'O corte de cerâmicas era feito no chão com cortador manual exigindo posturas inadequadas como curvar-se ou ajoelhar-se, gerando desconforto, risco ergonômico menor produtividade e falta de padronização.', N'01 - Imagens/02 - Depois/9230.jpeg', N'Foi implementada mesa para corte de cerâmica com madeira reaproveitada. A estrutura ergonômica melhora a postura, reduz esforço físico e diminui riscos de lesões ao colaborador.', NULL, N'Melhor ergonomia e conforto para o colaborador; Redução de riscos ocupacionais; Maior precisão no corte das peças.', N'ergonomia', 0, NULL, N'Work orders can be completed as scheduled - minimizing unnecessary escalations', '2026-04-01T00:00:00.000', '2026-04-06T12:02:59.000', N'514353', NULL, NULL);
INSERT INTO #PVC VALUES (9231, N'460389', N'1010712', N'SAP reporting for Materials in KIT and Work Complete', NULL, N'Others/Outros', N'Complicated process for returning materials from kit to the warehouse in SAP.  ', N'Simplify and report Kit Materials to be actioned', N'0', N'01 - Imagens/01 - Antes/9231.jpeg', N'Materials for work scopes that have been completed were sitting on the KIT stores area of the warehouse and would need manual intervention (email, teams, phone calls and or visits) with follow up to determine what materials could be put back in stock.  This is also needed so the work order will go TECO (technically complete) 90 days later to CLOSED (where no more costing is allowed to settle to the work order).', N'01 - Imagens/02 - Depois/9231.jpeg', N'End users apply a KIT_TECO status on the work order.  The warehouse can then run a report on what materials to action and return to stock.  When the warehouse runs their report and updates it to complete the end users can then TECO the work order.', NULL, N'No verbal communication or follow up required.', N'SAP functionality ', 0, NULL, N'Expected cost savings over a year due to reducing delays to operations.', '2026-03-02T00:00:00.000', '2026-04-06T12:55:52.000', N'460389', NULL, NULL);
INSERT INTO #PVC VALUES (9232, N'1009270', N'1009270', N'Photo Booth for Open House', NULL, N'Others/Outros', N'For community events, we would normally bring in a vendor who would set up and run a Photo Booth for us. Each time we did this, it would cost $650', N'Reduce Cost', N'0', N'01 - Imagens/01 - Antes/9232.jpeg', N'For community events, we typically relied on a third-party vendor to supply and operate a photo booth. Each engagement incurred a cost of approximately $650 per event.', N'01 - Imagens/02 - Depois/9232.jpeg', N'In 2025, four events were planned that would have required renting a photo booth, at an estimated cost of approximately $2,600. Instead, we elected to invest in in-house equipment, purchasing a printer and photo paper for $492 and props for an additional $100. This one-time investment enables us to support 10 or more events annually. As a result, this approach is projected to deliver ongoing cost avoidance of approximately $5,850 per year while increasing flexibility and reuse across future engagement initiatives.', NULL, N'Yes, problem solved', N'positive business case for purchasing over contracting', 5850, 3, N'Alcançamos o resultado esperado, conseguimos trazer segurança e organização da nossa área.', '2025-11-10T00:00:00.000', '2026-04-06T13:12:55.000', N'1009270', NULL, NULL);
INSERT INTO #PVC VALUES (9233, N'1009270', N'201966', N'Signage & Branding Capabilities', NULL, N'Others/Outros', N'To have a small, vinyl sticker created to put on the door of our new multi faith room, it cost $180. ', N'Reduce cost associated with branding, sigage and communications', N'0', N'01 - Imagens/01 - Antes/9233.jpeg', N'we have been investing in branding and standardization of signage across the Business Unit. When we started looking hard at the prices being charged by some signage companies for a small vinyl sticker, we realized that there is a better way that can save some money. For example, the sign for our new multi-Faith room cost $180', N'01 - Imagens/02 - Depois/9233.jpeg', N'We decided to invest in a Cricut, with supplies, that will allow us to design and print our own signs, shirts, cups and other material, saving us thousands. For example, we are about to open our new Asset Monitoring Station, where we will print vinyl''s to go on the glass to show where the station is located. The stickers for this alone would have cost $900. We estimate that we can save ~$2000/year just from the use of this product', NULL, N'yes', N'paying for service we can do in house', 2000, 3, N'Melhorar a confiabilidade operacional do sistema, reduzir falhas humanas e garantir que a válvula de água de make‑up automática seja corretamente identificada e utilizada.', '2026-04-06T00:00:00.000', '2026-04-06T13:54:13.000', N'1009270', NULL, NULL);
INSERT INTO #PVC VALUES (9234, N'81046576', N'81038913', N'Implementação do Sistema de Lubrificação automática (olhais  do cilindro da mesa do ripper) -PT6013', NULL, N'Others/Outros', N'A lubrificação manual do conjunto de fixação do cilindro da mesa do ripper apresentava variabilidade, risco operacional e impacto na confiabilidade do equipamento, devido à falta de padronização e controle do processo.', N'Lubricar de forma automática o conjunto de fixação do cilindro da mesa do RIpper ', N'10144', N'01 - Imagens/01 - Antes/9234.jpeg', N'Antes da melhoria, o conjunto de fixação do cilindro da mesa do ripper era lubrificado de forma manual, com aplicação direta de graxa nos pontos de lubrificação.
INSERT INTO #PVC VALUES (9235, N'512019', N'512019', N'Fixador adicional do cubo da hélice ', NULL, N'Others/Outros', N'Em decorrência da má instalação ou ausência de manutenção periódica, ocasiona desprendimento da hélice quando equipamento está em operação, vindo a danificar a mesma.', N'Reduzir a possibilidade de desprendimento da hélice ', N'10324', N'01 - Imagens/01 - Antes/9235.jpeg', N'Em decorrência da má instalação ou ausência de manutenção periódica, ocasiona desprendimento da hélice quando equipamento está em operação, vindo a danificar a mesma.', N'01 - Imagens/02 - Depois/9235.jpeg', N'Foi confeccionado rosca UNC de 1/2 POL e adicionado elemento de fixação com uma arruela projetada sobre o cubo da hélice para mitigar a possibilidade de desprendimento.', NULL, N'Sim. 
INSERT INTO #PVC VALUES (9236, N'36805', N'538792', N'Régua de Medição para Cortes de tubos', NULL, N'Others/Outros', N'A ausência de demarcação na régua/suporte de medição para cortes de turbos gerava dúvidas nas medidas corretas, impactando a precisão do processo.', N'Padronizar a medição dos cortes por meio da demarcação clara da régua, eliminando incertezas e erros operacionais.', N'10090', N'01 - Imagens/01 - Antes/9236.jpeg', N'Falta de referências visuais, levando a interpretações diferentes para medição de corte dos tubos ', N'01 - Imagens/02 - Depois/9236.jpeg', N'Implantação de demarcações visuais na régua de medição, orientando corretamente os pontos de corte dos tubos', NULL, N'A meta foi atingida, pois a demarcação da régua eliminou as dúvidas de medição e melhorou o processo.', N'Maior assertividade nas medidas de corte e redução de dúvidas durante a operação.', 0, NULL, NULL, '2026-03-18T00:00:00.000', '2026-04-06T15:45:13.000', N'36805', NULL, NULL);
INSERT INTO #PVC VALUES (9237, N'81027232', N'81027232', N'Utilização de boroscópio nas inspeções dos instrumentos geotecnico', NULL, N'Open Pit/Poço aberto', N'Falta de confiabilidade nas leituras manuais, falta de informações das inconsistência nas leituras manuais. ', N'Melhoria e confiabilidade nas leituras manuais.', N'10141', N'01 - Imagens/01 - Antes/9237.jpeg', N'Durante as obras de adequação do DF‑I, alguns instrumentos passaram pelo alteamento da tubulação existente. Após o alteamento, o instrumento INCLI‑07 apresentou um pico nas leituras, situação que indicava a possível existência de alguma anomalia geotécnica na estrutura. Foram realizadas leituras adicionais a fim de verificar a possibilidade de erro nas leituras manuais; entretanto, não foram identificadas inconsistências, e o problema persistiu.  ', N'01 - Imagens/02 - Depois/9237.jpeg', N'A aquisição de uma câmera boroscópica/endoscópica possibilitou a inspeção interna do instrumento, identificando que a inconsistência nas leituras foi causada por falha na instalação do tubo durante o processo de alteamento.', NULL, N'Sim. O EOR realizou o ajuste das leituras considerando as observações verificadas nas emendas da tubulação.', N'Implementar maior rigor e cuidado no processo de manuseio da tubulação geotécnica, a fim de evitar falhas durante procedimentos de alteamento.', 600, 1, N'Evitar desperdícios de tempo, causados pela repreparação de amostra.', '2026-03-30T00:00:00.000', '2026-04-06T16:04:40.000', N'81027232', NULL, NULL);
INSERT INTO #PVC VALUES (9238, N'520046', N'520046', N'Gancho para remover lona', NULL, N'Others/Outros', N'A remoção da lona da caixa de 3 metros de altura é realizada de forma manual e insegura, exigindo esforço excessivo e, em alguns casos, o uso improvisado de ferramentas ou acesso em altura.
INSERT INTO #PVC VALUES (9239, N'81007314', N'81007314', N'IMPLEMENTAÇÃO DE TOMADA DE TRABALHO', NULL, N'Projects/Projetos', N'Antes no pátio de manutenção de perfuratrizes não havia tomada disponível na tensão de 220V, o que gerava perca de tempo e produtividade quando precisava-se fazer pequenos reparos com máquina de solda portátil ou equipamentos rotativos, pois era necessário transportar gerador para a realização das atividades.', N'GANHO DE TEMPO E PRODUTIVIDADE DURANTE AS MANUTENÇÕES NO PATIO DE PERFURAÇÃO', N'10166', N'01 - Imagens/01 - Antes/9239.jpeg', N'Antes no pátio de manutenção de perfuratrizes não havia tomada disponível na tensão de 220V, o que gerava perca de tempo e produtividade quando precisava-se fazer pequenos reparos com máquina de solda portátil ou equipamentos rotativos, pois era necessário transportar gerador para a realização das atividades.', N'01 - Imagens/02 - Depois/9239.jpeg', N'Depois, com a implantação de uma tomada 220V terá um ganho de tempo, produtividade, deslocamento de empilhadeira e tempo de gerador ligado em nossa praça de manutenção.', NULL, N'SIM , om a implantação de uma tomada 220V terá um ganho de tempo, produtividade, deslocamento de empilhadeira e tempo de gerador ligado em nossa praça de manutenção.', N'OTIMIZAÇÃO DO PROCESSO DE MANUTENÇÃO EM PEQUENOS REPAROS', 1257, 1, N'Ganho em confiabilidade nas indicações operacionais das válvulas associadas as bomba. ', '2026-04-05T00:00:00.000', '2026-04-06T16:52:26.000', N'81007314', NULL, NULL);
INSERT INTO #PVC VALUES (9240, N'388278', N'388278', N'SLAM sign off sheets', NULL, N'Concentration/Concentração', N'Area to keep SLAM sign off sheets not available. Had to print sheets and waste time looking for the cover sheets.', N'Area to keep sheets. Easy and visible access.', N'10282', N'01 - Imagens/01 - Antes/9240.jpeg', N'No central easy location for sheets.', N'01 - Imagens/02 - Depois/9240.jpeg', N'Installed file holder in shift office in central location easy access and visible. Added label.', NULL, N'Yes. Simplified outcome.', N'Simplify', 10, 3, N'A ATIVIDADE PASSOU A SER REALIZADA EM MENOS TEMPO, DEVIDO A COLOCAÇÃO DO SUPORTE PARA O DISPOSITIVO NA PROPRIA CAÇAMBA.', '2026-04-05T00:00:00.000', '2026-04-06T17:59:16.000', N'388278', NULL, NULL);
INSERT INTO #PVC VALUES (9241, N'81058052', N'81058052', N'BASTÃO DE MANOBRA PARA AROS DE PNEUS', NULL, N'Others/Outros', N'A movimentação de pneus era realizada manualmente, exigindo esforço excessivo dos colaboradores, com risco de:
INSERT INTO #PVC VALUES (9242, N'538409', N'538409', N'PORTA CHAVES ', NULL, N'Others/Outros', N'DESORGANIZAÇÃO', N'5S', N'10139', N'01 - Imagens/01 - Antes/9242.jpeg', N'RISCO DE PERDA DAS CHAVES
INSERT INTO #PVC VALUES (9243, N'460389', N'1014623', N'PM Set up to align with Contractor Visit', NULL, N'Others/Outros', N'Critical asset work being performed by a contractor who is on site every 3rd Monday of the month were set up as 30 day PM cycles and due to the misalignment work orders were escalating as they were not completed within the preset SAP time. ', N'Align work orders to be scheduled when contractor is on site', N'0', N'01 - Imagens/01 - Antes/9243.jpeg', N'PM was set up on a 30 day frequency - and is flagged as a Critical Asset.  Contractor has been coming in routinely on the 3rd Monday of the month and supports the work scope needed.  Using 30 days the call dates shifted from the 3rd Monday of the month and could cause escalation', N'01 - Imagens/02 - Depois/9243.jpeg', N'Set the PM up to call the work order for the 3rd Monday of each month - with tolerance to shift the work from that baseline.  Aligns with when the work is required and when the contractor is on site.  Also prevents the work from escalating due to scheduling - any escalation is now reflective of a required action.', NULL, N'Work is now forecasting and created based on the contractor being on site the 3rd Monday of each Month.', N'SAP can be configured to support operational needs', 0, NULL, N'Redução dos riscos de acidentes por uso de celulares', '2026-03-30T00:00:00.000', '2026-04-07T07:01:47.000', N'460389', NULL, NULL);
INSERT INTO #PVC VALUES (9244, N'81023799', N'200661', N'Hollow Core Connectable Bolt Implementation', NULL, N'Underground/Subterrâneo', N'The use of traditional cablebolts in underground mining is a slow and labour intensive process. ', N'Cost Savings and Time Efficiency Improvement', N'10311', N'01 - Imagens/01 - Antes/9244.jpeg', N'Traditional cable bolts can be drilled with either the Maclean or a bolter, but the cable bolts must then be manually inserted and grouted into the hole by employees working on the deck. This process is slow and exposes employees to more hazards. ', N'01 - Imagens/02 - Depois/9244.jpeg', N'Connectable Hollow Core bolts are a suitable alternative to traditional cable bolts and the entire process can be completed with a mechanized bolter. This drastically improves the rate of installation, while also removing the employee from the hazards of traditional cable bolt installation. ', NULL, N'Yes, the process has become more efficient and the workforce is exposed to less hazards during installation. ', N'Process Efficiency', 1000000, 3, N'Fortalecimento da cultura de segurança, com maior conscientização dos colaboradores sobre áreas restritas e riscos químicos.', '2026-04-03T00:00:00.000', '2026-04-07T10:24:21.000', N'81023799', NULL, NULL);
INSERT INTO #PVC VALUES (9245, N'81022599', N'81047914', N'Suporte de Mangueira de Processo', NULL, N'Others/Outros', N'Não havia nenhum tipo de suporte para nossa mangueira de processo, por isso, ela ficava enrolada no chão.', N'Criar um suporte para posicionar a mangueira, evitando que a mesma seja colocada no chão.', N'10064', N'01 - Imagens/01 - Antes/9245.jpeg', N'Não havia suporte para nossa mangueira de água de processo, trazendo desorganização na área e também podendo ocasionar algum acidente, onde, o colaborador ao transitar pela área pode tropeçar na mangueira.', N'01 - Imagens/02 - Depois/9245.jpeg', N'Foi confeccionado um suporte para nossa mangueira de água de processo trazendo organização na área e segurança para o colaborador ao transitar pela área.', NULL, N'A meta inicial foi montar esse suporte, ao montar e posicionar a mangueira, trouxa mais organização e segurança para a área.', N'Mangueiras de processo não podem ficar no chão da área, precisam de suportes.', 0, NULL, N'repairs and change will reduce cost of belt replacement prematurely. avoids cost of belt, and labor and lost production.', '2026-04-06T00:00:00.000', '2026-04-07T11:21:19.000', N'81022599', NULL, NULL);
INSERT INTO #PVC VALUES (9246, N'81055646', N'81054579', N'Identificação da válvula água de make-up automática', NULL, N'No Replication/Sem replicação', N' a válvula de água de make‑up automática não possui uma identificação padronizada e visível em campo, dificultando sua localização, reconhecimento funcional e entendimento durante atividades de operação, manutenção corretiva e preventiva.', N'Padronizar e implementar a identificação clara e permanente da válvula de água de make‑up automática', N'10229', N'01 - Imagens/01 - Antes/9246.jpeg', N'A válvula de água de make‑up automática não possuía identificação padronizada, dificultando sua localização e aumentando o risco de erros operacionais e atrasos nas manutenções.', N'01 - Imagens/02 - Depois/9246.jpeg', N'Com a identificação padronizada e visível, a válvula passou a ser facilmente localizada, reduzindo erros, agilizando a manutenção e aumentando a segurança e confiabilidade do sistema.', NULL, N'Padronização da identificação da válvula
INSERT INTO #PVC VALUES (9247, N'81029873', N'532659', N'Adequação do estacionamento da empilhadeira SF21', NULL, N'Others/Outros', N'O estacionamento da empilhadeira SF21 encontrava-se inadequado, sem padronização e sinalização definida, gerando risco de obstrução, dificuldades de manobra e impacto na segurança operacional.', N'Implementar adequação do estacionamento da empilhadeira SF21', N'10245', N'01 - Imagens/01 - Antes/9247.jpeg', N'O estacionamento da empilhadeira SF21 não possuía local definido nem demarcação adequada, resultando em posicionamento irregular, desorganização da área e riscos à segurança operacional.', N'01 - Imagens/02 - Depois/9247.jpeg', N'O estacionamento da empilhadeira SF21 passou a ter local definido, devidamente demarcado e padronizado, proporcionando melhor organização da área, facilitando as manobras e aumentando a segurança operacional.', NULL, N'Houve melhoria na organização da área, segurança operacional e facilidade de manobra, devido à padronização e demarcação adequada do estacionamento da empilhadeira.
INSERT INTO #PVC VALUES (9248, N'1015684', N'1015684', N'BM Tank Sample Platform', NULL, N'Refining/Refino', N'After installation of a new Ball Mill discharge tank, the platform put in place was too high for workers to comfortably use, posing ergonomic hazard while taking samples or cleaning out tank.', N'Have a platform in place at a proper height for workers', N'0', N'01 - Imagens/01 - Antes/9248.jpeg', N'After installation of a new Ball Mill discharge tank, the platform put in place was too high for workers to comfortably use, posing ergonomic hazard while taking samples or cleaning out tank. Platform height would also cause workers to strike their head while completing tasks.', N'01 - Imagens/02 - Depois/9248.jpeg', N'Had scaffold modified to have platform set up a height that was comfortable and safe for workers to complete tasks from. No longer a risk of hitting head.', NULL, N'Work platform is now setup properly for workers to complete tasks from.', N'Proper work station setup will make for a safer more efficient workspace', 0, NULL, N'Eliminação do risco de derramamentos fora da contenção. ', '2026-04-06T00:00:00.000', '2026-04-07T16:24:06.000', N'1015684', NULL, NULL);
INSERT INTO #PVC VALUES (9249, N'388278', N'388278', N'SLAM sheet holder', NULL, N'Concentration/Concentração', N'Make it easier for employees to have SLAM sheets', N'Easy access to SLAM sheets', N'10282', N'01 - Imagens/01 - Antes/9249.jpeg', N'No easy access for employees to get SLAM sheets. Need to get from supervisor.', N'01 - Imagens/02 - Depois/9249.jpeg', N'Easy access for employees to get daily SLAM sheet.', NULL, N'Problem solved with line up room location', N'Easy access', 10, 3, N'Redução da frequência de acesso dos operadores à parte superior do filtro para realização da limpeza manual dos bicos de lavagem', '2026-04-06T00:00:00.000', '2026-04-07T18:50:13.000', N'388278', NULL, NULL);
INSERT INTO #PVC VALUES (9250, N'923201', N'923201', N'Segregação de vidrarias para análise de Cloro', NULL, N'Smelting/Fundição', N'Perca da rastreabilidade e contaminação, nas etapas de fusão e solubilização de amostra, para determinar cloro.', N'Garantir a rastreabilidade das amostra na fusão de amostras para análise de Cloro', N'10152', N'01 - Imagens/01 - Antes/9250.jpeg', N'No processo de fusão de amostras para determinação de Cl, utilizam-se cadinhos de níquel que requerem identificação para rastreabilidade. Inicialmente, a identificação foi replicada com tinta tipo coloral xadrez. Entretanto, devido ao uso de reagente de caráter fortemente básico, a tinta não apresentou resistência química, sofrendo degradação durante a solubilização. Esse desprendimento gerou sujidade, contaminação da solução da amostra e interferência analítica, ocasionando desvios no teor de cloro determinado.', N'01 - Imagens/02 - Depois/9250.jpeg', N'Considerando que a tinta xadrez não apresentava aderência adequada aos cadinhos, comprometendo a identificação das amostras fundidas, foi adotado o uso de marcador industrial para nova identificação. Com essa ação, eliminou-se a sujidade dos cadinhos durante a solubilização, garantindo a rastreabilidade das amostras, prevenindo trocas e evitando possíveis contaminações decorrentes do desprendimento da tinta.', NULL, N'A substituição por marcador industrial manteve a identificação dos cadinhos, eliminou a sujidade durante a solubilização e garantiu a rastreabilidade das amostras, atendendo plenamente à meta inicial do processo.', N'O uso de soluções adequadas garante rastreabilidade, limpeza do processo e confiabilidade dos resultados.', 0, NULL, N'A eliminação da contaminação dos bicos de lavagem melhorou as condições ergonômicas, pois os colaboradores não precisaram mais se agachar, reduzindo esforços e riscos à coluna.', '2026-03-27T00:00:00.000', '2026-04-07T19:27:40.000', N'923201', NULL, NULL);
INSERT INTO #PVC VALUES (9251, N'923201', N'923201', N'Melhoria na Identificação de Cadinhos Utilizados na Análise de Cl', NULL, N'Smelting/Fundição', N'Perda da rastreabilidade de amostras na fusão para determinação de Cloro. Contaminação de amostras na solubilização para análise de Cloro', N'Garantir a rastreabilidade de amostras no processo de fusão para análise de Cloro e evitar  contaminação ', N'10152', N'01 - Imagens/01 - Antes/9251.jpeg', N'No processo de fusão de amostras para determinação de Cl, utilizam-se cadinhos de níquel que requerem identificação para rastreabilidade. Inicialmente, a identificação foi replicada com tinta tipo coloral xadrez. Entretanto, devido ao uso de reagente de caráter fortemente básico, a tinta não apresentou resistência química, sofrendo degradação durante a solubilização. Esse desprendimento gerou sujidade, contaminação da solução da amostra e interferência analítica, ocasionando desvios no teor de cloro determinado.', N'01 - Imagens/02 - Depois/9251.jpeg', N'Considerando que a tinta xadrez não apresentava aderência adequada aos cadinhos, comprometendo a identificação das amostras fundidas, foi adotado o uso de marcador industrial para nova identificação. Com essa ação, eliminou-se a sujidade dos cadinhos durante a solubilização, garantindo a rastreabilidade das amostras, prevenindo trocas e evitando possíveis contaminações decorrentes do desprendimento da tinta.', NULL, N'A substituição por marcador industrial manteve a identificação dos cadinhos, eliminou a sujidade durante a solubilização e garantiu a rastreabilidade das amostras, atendendo plenamente à meta inicial do processo.', N'A identificação de materiais utilizados em processos químicos deve considerar a compatibilidade com os reagentes empregados. Materiais de identificação sem resistência química podem causar contaminação e desvios analíticos. O uso de soluções adequadas garante rastreabilidade, limpeza do processo e confiabilidade dos resultados.', 0, NULL, N'Propor e implementar melhorias que tornem o fluxo de trabalho mais ágil, seguro ou econômico.', '2026-03-27T00:00:00.000', '2026-04-07T19:52:43.000', N'923201', NULL, NULL);
INSERT INTO #PVC VALUES (9252, N'81016620', N'542814', N'Painel pneumático', NULL, N'Others/Outros', N'Ocorrência recorrente devido projeções de materiais sobre o painel pneumático, ocasionando a paradas  operacional da bomba.', N'eliminar paradas da bomba do ES_2019_01', N'10197', N'01 - Imagens/01 - Antes/9252.jpeg', N'Falha recorrente nas válvulas de transferência e recirculação decorrente da projeções de material sobre o painel pneumático resultando em parada operacional da bomba do ES_2019_01.
INSERT INTO #PVC VALUES (9253, N'543555', N'543555', N'SUPORTE PARA DISPOSITIVO DE ORGANIZAÇÃO DOS FRASCOS.', NULL, N'Others/Outros', N'ANTES NÃO TINHAMOS UM SUPORTE E UM LOCAL ADEQUADO PARA O DISPOSITIVO DE ORGANIZAÇÃO DOS FRASCOS.
INSERT INTO #PVC VALUES (9254, N'1008449', N'1008449', N'HCl offload storage hose', NULL, N'Refining/Refino', N'Offload hose left on the ground after offload', N'Storage', N'0', N'01 - Imagens/01 - Antes/9254.jpeg', N'After completing a tanker offload, the hose was just dragged back and placed on the ground in the bund', N'01 - Imagens/02 - Depois/9254.jpeg', N'Made up a tapped flange and bolted it to the structural steel to allow a connection for the offload hose and keep it off the ground away from potentially being damaged', NULL, N'Yes', N'hose storage', 0, NULL, N'cleaner working area and improvement to working ergonomics', '2026-04-07T00:00:00.000', '2026-04-08T08:26:02.000', N'1008449', NULL, NULL);
INSERT INTO #PVC VALUES (9255, N'1008449', N'1009524', N'Frac tank fittings', NULL, N'Refining/Refino', N'draining frac tank to floor in aisle', N'Proper draining', N'0', N'01 - Imagens/01 - Antes/9255.jpeg', N'No fittings on frac tank that was being used to store Ni feed solution. Would create a mess when draining', N'01 - Imagens/02 - Depois/9255.jpeg', N'Sourced and placed fittings on frac tank to allow 2" chem hose to be attached and run hose to the basement for proper draining', NULL, N'YES', N'Less mess of solution/chemicals', 0, NULL, N'A aplicação bem-sucedida do 5S gera melhoria no clima organizacional, segurança, redução de desperdícios e maior satisfação no trabalho', '2026-03-25T00:00:00.000', '2026-04-08T08:55:20.000', N'1008449', NULL, NULL);
INSERT INTO #PVC VALUES (9256, N'47901', N'47901', N'Orientação Sobre Uso de Celular - Guarde no Porta-luvas e/ou Porta Trecos.', NULL, N'Others/Outros', N'Não havia informação clara dentro dos veículos leves sobre o uso/guarda dos celulares dos condutores.', N'Reduzir riscos de acidentes', N'10020', N'01 - Imagens/01 - Antes/9256.jpeg', N'Não havia informações dentro do veículo sobre uso/guarda dos celulares', N'01 - Imagens/02 - Depois/9256.jpeg', N'Foi criado um adesivo para colar nos painéis dos veículos/equipamentos sobre o uso/guarda de celulares. ', NULL, N'Sim, pois através do adesivo colado no painel o condutor irá lembrar de guardar seu celular no porta-luvas. ', N'Através do adesivo acreditamos que a detecção do uso de celulares através do aparelho de detecção de sonolência reduzirá e/ou será eliminado por completo. ', 0, NULL, N'Ganho na confiabilidade das válvulas de recirculação e transferência do ES_2019_01. ', '2026-04-08T00:00:00.000', '2026-04-08T10:12:45.000', N'47901', NULL, NULL);
INSERT INTO #PVC VALUES (9257, N'81054815', N'81054815', N'Barreira Física para Eliminar acesso de pessoas na lateral do Galpão GI - 06', NULL, N'Refining/Refino', N'Apesar de o Galpão GI‑06 ser totalmente fechado, sua lateral permanecia aberta, permitindo o acesso e circulação de pessoas, que utilizavam o local como rota de passagem. Trata-se de uma área destinada ao armazenamento de produtos químicos, o que representa risco elevado à segurança.
INSERT INTO #PVC VALUES (9258, N'387677', N'498948', N'Remove impact beds on #9 conv.', NULL, N'Underground/Subterrâneo', N'remove worn impact beds that is no longer needed under old chutes, impact beds rubbing unevenly causing side tracking, and premature wear on belt', N'to remove impact beds and correct tracking', N'10058', N'01 - Imagens/01 - Antes/9258.jpeg', N' impact bed is worn, falling apart and rubbing
INSERT INTO #PVC VALUES (9259, N'47901', N'47901', N'Padronização das Orientações sobre Uso e Guarda de Celulares em Veículos Leves e/ou Equipametos', NULL, N'Others/Outros', N'Ausência de sinalização e orientações claras nos veículos leves e/ou equipamentos quanto às regras de uso e guarda de aparelhos celulares pelos condutores.', N'Garantir que 100% dos veículos leves e/ou equipamentos possuam sinalização padronizada e visível com orientações sobre o uso e a guarda de celulares pelos condutores, promovendo maior segurança e conformidade com as normas internas.', N'10213', N'01 - Imagens/01 - Antes/9259.jpeg', N'Antes da implementação, os veículos não possuíam qualquer tipo de informação, sinalização ou orientação visual relacionada ao uso e à guarda de aparelhos celulares. Essa ausência de padronização gerava dúvidas entre os condutores quanto às regras aplicáveis, aumentando o risco de uso inadequado do celular durante a condução e, consequentemente, potencializando situações de insegurança.', N'01 - Imagens/02 - Depois/9259.jpeg', N'Após a implementação, todos os veículos passaram a contar com adesivos informativos padronizados, posicionados de forma visível, contendo orientações claras sobre o uso e a guarda de aparelhos celulares durante a condução de veículos e operação de máquinas/equipamentos.
INSERT INTO #PVC VALUES (9260, N'81046654', N'81046654', N'Relatório Informativo sobre o Aumento do Kit Delivery', NULL, N'Others/Outros', N'Ausência de visibilidade e acompanhamento quanto ao aumento do Kit Delivery aplicado à frota de carga e às operações de carregamento.', N'Redução Kit delivery', N'10234', N'01 - Imagens/01 - Antes/9260.jpeg', N'Ausência de visibilidade e acompanhamento quanto ao aumento do Kit Delivery aplicado à frota de carga e às operações de carregamento.', N'01 - Imagens/02 - Depois/9260.jpeg', N'Foram implementados dashboards para monitorar o Kit Delivery da frota, garantindo maior transparência e suportando análises comparativas.', NULL, N'Maior visibilidade nas informações do kit delivery da frota! ', N'N/A', 0, NULL, N'Better working areas with less hazards and prevention of ergonomic related injury ', '2026-04-02T00:00:00.000', '2026-04-08T11:52:38.000', N'81046654', NULL, NULL);
INSERT INTO #PVC VALUES (9261, N'544612', N'544612', N'Descarregamento seguro', NULL, N'Others/Outros', N'Processo de descarregamento com risco de derramamentos de produtos químicos fora da área de contenção.', N'Gestão de riscos no descarregamento de produtos químicos ', N'10054', N'01 - Imagens/01 - Antes/9261.jpeg', N'O descarregamento de reagentes químicos era realizado fora da área de contenção adequada, aumentando o risco de derramamentos, contaminação ambiental e não conformidade com requisitos de segurança e meio ambiente.', N'01 - Imagens/02 - Depois/9261.jpeg', N'Realizada a mudança do ponto de descarregamento para a posição lateral, dentro da área de contenção.
INSERT INTO #PVC VALUES (9262, N'479248', N'479248', N'Sistema de filtragem de particulado na linha de água de lavagem de tecidos e placas do filtro 21', NULL, N'Open Pit/Poço aberto', N'A obstrução dos bicos de lavagem dos filtros Andritz, causada pela contaminação da água, compromete a eficiência da limpeza dos tecidos e placas filtrantes. Essa ineficiência resulta na redução da vida útil desses componentes, sendo uma causa recorrente de perdas operacionais, frequentemente identificada nos perfis de perdas e discutida nas reuniões de FMDS.', N'Reduzir os contaminantes que obstruem os bicos de lavagens.', N'10293', N'01 - Imagens/01 - Antes/9262.jpeg', N'A linha do sistema de lavagem dos tecidos e placas dos filtros ANDRITZ não possui nenhum dispositivo de filtragem ou tratamento da água antes de sua chegada aos bicos de lavagem. Atualmente, a água utilizada provém diretamente da caixa CX-2020-01, que recebe o overflow do espessador ES-2020-01, apresentando elevada carga de contaminantes e impurezas. Essa condição compromete a eficiência do sistema de lavagem e contribui para o desgaste prematuro dos componentes filtrantes.
INSERT INTO #PVC VALUES (9263, N'479248', N'479248', N'Sistema de filtragem de particulado na linha de água de lavagem de tecidos e placas do filtro 21.', NULL, N'Open Pit/Poço aberto', N'A obstrução dos bicos de lavagem dos filtros Andritz, causada pela contaminação da água, compromete a eficiência da limpeza dos tecidos e placas filtrantes. Essa ineficiência resulta na redução da vida útil desses componentes, sendo uma causa recorrente de perdas operacionais, frequentemente identificada nos perfis de perdas e discutida nas reuniões de FMDS.', N'Reduzir 50% dos contaminantes que obstruem os bicos de lavagens.  Aumento da vida útil dos tecidos em 5%.  Aumento em UF em 3%.  Nosso objetivo é disponibilizar água limpa para lavagens dos tecidos e placas para garantirmos a confiabilidade desse sistema.', N'10293', N'01 - Imagens/01 - Antes/9263.jpeg', N'A linha do sistema de lavagem dos tecidos e placas dos filtros ANDRITZ não possui nenhum dispositivo de filtragem ou tratamento da água antes de sua chegada aos bicos de lavagem. Atualmente, a água utilizada provém diretamente da caixa CX-2020-01, que recebe o overflow do espessador ES-2020-01, apresentando elevada carga de contaminantes e impurezas. Essa condição compromete a eficiência do sistema de lavagem e contribui para o desgaste prematuro dos componentes filtrantes.', N'01 - Imagens/02 - Depois/9263.jpeg', N'Foi desenvolvido um estudo para a instalação de um dispositivo de filtragem na linha de água utilizada na lavagem dos tecidos dos filtros ANDRITZ. Como solução, foi adotado o uso de um filtro cesto do tipo Duplex, Após a implementação no filtro 21, observou-se que o dispositivo reteve eficientemente os contaminantes presentes na água, resultando na mitigação significativa da obstrução dos bicos de lavagem.', NULL, N'Conseguimos reduzir em 100% dos contaminantes que obstruem os bicos de lavagens.
INSERT INTO #PVC VALUES (9264, N'81006670', N'81027100', N'Suporte de bastões', NULL, N'Others/Outros', N'Bastões acomodados em cima de armários', N'Adequação em local seguro', N'10144', N'01 - Imagens/01 - Antes/9264.jpeg', N'Bastões Magnéticos ficavam posicionados sobre as prateleiras, gerando um aspecto de desorganização e riscos de queda, podendo ocasionar acidentes.', N'01 - Imagens/02 - Depois/9264.jpeg', N'Foi criado um suporte adequado para acomodar os três bastões, proporcionando maior organização e segurança.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1727897898112&source=portal', N'Aumentar a participação dos colaboradores na identificação de riscos, como a realização de um número X de relatórios de quase acidentes ou inspeções.', N'O aprendizado só é genuíno se resultar em alterações concretas nos procedimentos e equipamentos, impedindo a repetição do evento.', 0, NULL, N'Agilidade no atendimento', '2026-04-06T00:00:00.000', '2026-04-08T13:45:48.000', N'81006670', NULL, NULL);
INSERT INTO #PVC VALUES (9265, N'388959', N'388959', N'Redução de risco com Içamento de básculas realizando içamento lateral', NULL, N'Others/Outros', N'Para utilização do local de içamento da báscula é necessário acesso do colaborador via escada com carga do pina que pesa cerca de 27 Kg', N'Eliminar o risco de queda em nível diferente portando material com peso de 27Kg', N'10081', N'01 - Imagens/01 - Antes/9265.jpeg', N'Era necessário acessar uma escada plataforma para instalação do pino na báscula.', N'01 - Imagens/02 - Depois/9265.jpeg', N'Com a instalação dos olhais laterais, a amarração da carga passa a ser instalada no mesmo nível do solo', NULL, N'Eliminação do trabalho em altura  portando carga de 27 Kg', N'Redução de risco na amarração de básculas', 0, NULL, NULL, '2026-04-02T00:00:00.000', '2026-04-08T13:49:25.000', N'388959', NULL, NULL);
INSERT INTO #PVC VALUES (9266, N'606854', N'606854', N'Improve Locomotive Cameras', NULL, N'Underground/Subterrâneo', N'the existing Camera & Monitor installed had performance (vibration) and clarity issues ', N'Front & rear mount cameras for line of site visual and recording device', N'0', N'01 - Imagens/01 - Antes/9266.jpeg', N'The existing locomotive camera and monitor was ineffective due to vibration and did not record data into secure storage ', N'01 - Imagens/02 - Depois/9266.jpeg', N'New camera & Display properly rated for rail travel (EN 50155 certified) ', NULL, N'Improved visual and secure recording feature', N'obtain feedback and action continuous improvements ', 0, NULL, N'It is a room that will be utilized overtime', '2026-04-03T00:00:00.000', '2026-04-08T14:23:24.000', N'606854', NULL, NULL);
INSERT INTO #PVC VALUES (9267, N'1009854', N'81009270', N'Effluent Treatment Sampling Table', NULL, N'Concentration/Concentração', N'potential to contaminate water samples', N'Avoid potential contamination when performing water sampling', N'10101', N'01 - Imagens/01 - Antes/9267.jpeg', N'There was nowhere in the reclaim/treated effluent area to lay water quality/sampling equipment, causing potential to contaminate samples/equipment/buckets etc.
INSERT INTO #PVC VALUES (9268, N'81006670', N'81027100', N'Suporte pá/vassoura', NULL, N'Others/Outros', N'Local impróprio para guarde de pás', N'Aspecto correto de 5S', N'10144', N'01 - Imagens/01 - Antes/9268.jpeg', N'Não existia um local definido e adequado para guardar a vassoura e a pá.', N'01 - Imagens/02 - Depois/9268.jpeg', N'Foi criado um local específico para guardar a vassoura e a pá, garantindo melhor organização, segurança e padronização do ambiente.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal#', N's lições aprendidas com a implementação do 5S (Seiri, Seiton, Seiso, Seiketsu, Shitsuke) destacam que a metodologia vai além da limpeza, focando na mudança de cultura e disciplina para aumentar a produtividade. ', N'A organização deve ser funcional, permitindo encontrar ferramentas rapidamente e identificando falhas de fluxo.', 0, NULL, NULL, '2026-04-06T00:00:00.000', '2026-04-08T15:50:47.000', N'81006670', NULL, NULL);
INSERT INTO #PVC VALUES (9269, N'81016620', N'542814', N'Válvula  Pneumática', NULL, N'Others/Outros', N'Ocorrência de falhas recorrente devido acumulo de matérias sobre a válvula ocasionando travamento e comprometendo a parada da bomba operacional. 
INSERT INTO #PVC VALUES (9270, N'81027031', N'81027031', N'Daily Offload Sheet', NULL, N'Others/Outros', N'No FMDS board tracking sheet for visual on tons offloaded per day', N'Have a clear visual of our target amount offloaded versus how much we actually offloaded', N'10271', N'01 - Imagens/01 - Antes/9270.jpeg', N'No visual representation of  offload for day to day target vs actual concentrate offloaded', N'01 - Imagens/02 - Depois/9270.jpeg', N'Clear visual to be filled out to show actual offloaded concentrate vs actual amount offloaded per day', NULL, N'Yes, now have place on the board to show progress of offload', N'Updating board will be required for each offload to ensure it is up to date with proper tonnages and dates', 0, NULL, N'Melhoria na comunicação interna, aumento da eficiência operacional e maior agilidade no atendimento da Ferramentaria.
INSERT INTO #PVC VALUES (9271, N'81035706', N'81035706', N'GESTÃO DE PERTENCES', NULL, N'Others/Outros', N'Pertences pessoais encontrados na ferramentaria sem identificação.
INSERT INTO #PVC VALUES (9272, N'537635', N'537635', N'Conforto e Segurança Visual.', NULL, N'Others/Outros', N'Iluminação insuficiente na área dos bombeiros, ocasionando uma baixa visibilidade e aumentando o risco de acidentes durante as atividades que os bombeiros fazem durantes as suas manutenções e atividades de inspeções.', N'Melhorando as condições inseguras da Área.', N'10245', N'01 - Imagens/01 - Antes/9272.jpeg', N'Durante inspeção realizada em conjunto com a equipe dos bombeiros e a técnica de segurança, foi constatado que a iluminação ao redor do contêiner dos bombeiros era insuficiente. O local, utilizado para armazenamento de materiais de extintores, apresentava baixa visibilidade no período noturno, o que dificultava o acesso e o manuseio dos materiais, além de aumentar os riscos de acidentes e da presença de animais peçonhentos.', N'01 - Imagens/02 - Depois/9272.jpeg', N'Após a identificação do problema, foi realizada uma ação corretiva com a instalação de 5 refletores ao redor do contêiner. Com a melhoria da iluminação, o ambiente passou a oferecer melhores condições de uso, mais segurança no acesso e no armazenamento dos materiais, além de contribuir para a redução dos riscos de acidentes e de aparecimento de animais no local.', NULL, N'Sim, o problema foi resolvido realizamos a montagem de 5 refletores de 100 watts de potencia onde a iluminação ficou eficiente. ', N'Ver e Agir.', 0, NULL, N'Eliminação do uso de ferramentas improvisadas , diminuindo o risco de batidas e prensamentos , melhoria da ergonomia visando a Nr-17, padronização da atividade e redução de tempo para a troca dos discos de ruptura da área 295.', '2026-04-08T00:00:00.000', '2026-04-09T01:31:53.000', N'537635', NULL, NULL);
INSERT INTO #PVC VALUES (9273, N'1010180', N'1010180', N'Hose management ', NULL, N'Others/Outros', N'Hoses on hangers not being properly stored creating trip hazards and poor ergonomic situation when coiling.', N'Improve ergonomics and housekeeping', N'0', N'01 - Imagens/01 - Antes/9273.jpeg', N'Hoses being left on floor due to difficulty in storing. Time and poor ergonomics. This was creating tripping hazards and congested work area.', N'01 - Imagens/02 - Depois/9273.jpeg', N'Installed retractable reel to make it easier to store hose and eliminate ergonomic hazards and mitigate housekeeping issues. ', NULL, N'Yes', N'Make things as easy as possible for best results ', 0, NULL, N'DESPERCIOS DE TEMPO E SOBRE CARGA DE TRABALHO NO PROCESSO DE PLANEJAMENTO DE ORDENS, ENTREGANDO DESEMPENHO EM DIREÇÃO AO NOVO ALVO DE MELHORIA CONTÍNUA.', '2026-04-03T00:00:00.000', '2026-04-09T01:47:32.000', N'1010180', NULL, NULL);
INSERT INTO #PVC VALUES (9274, N'81007243', N'81003514', N'Guarda corpo - Motoniveladora', NULL, N'Others/Outros', N'A ausência de guarda-corpo em áreas com desnível representa um risco grave de acidente, caracterizado como queda em nível diferente. Esse tipo de ocorrência pode resultar em lesões de alta gravidade, incluindo fraturas, traumatismos e até mesmo óbito, dependendo da altura da queda e das condições do ambiente.', N'Redução de queda de nível diferente ', N'10139', N'01 - Imagens/01 - Antes/9274.jpeg', N'A ausência de guarda-corpo em áreas com desnível representa um risco grave de acidente, caracterizado como queda em nível diferente. Esse tipo de ocorrência pode resultar em lesões de alta gravidade, incluindo fraturas, traumatismos e até mesmo óbito, dependendo da altura da queda e das condições do ambiente.', N'01 - Imagens/02 - Depois/9274.jpeg', N'Foi instalado guarda-corpo para proteção coletiva dos operadores e da manutenção esse item é previsto nas normas regulamentadoras de segurança do trabalho, cuja função é impedir que trabalhadores ou terceiros tenham acesso a áreas de risco de queda. ', NULL, N'Sim, redução de risco de queda', N'Redução de risco de queda', 0, NULL, N'open hole was closed off eliminating hazard', '2026-04-05T00:00:00.000', '2026-04-09T02:29:31.000', N'81007243', NULL, NULL);
INSERT INTO #PVC VALUES (9275, N'81007243', N'81003514', N'Grade de proteção Mantas', NULL, N'Others/Outros', N'A falta de mecanismos de controle para a retirada de das mantas gera riscos significativos para a organização. Sem registros ou barreiras adequadas, torna-se impossível garantir a rastreabilidade e a correta utilização dos itens e a reposição correta. A demora na reposição  desse  recurso essencial no momento necessário compromete a continuidade das atividades.', N'Elaborar uma grade para controlar as retiradas das mantas ', N'10139', N'01 - Imagens/01 - Antes/9275.jpeg', N'A falta de mecanismos de controle para a retirada das mantas gera riscos significativos para a organização. Sem registros ou barreiras adequadas, torna-se impossível garantir a rastreabilidade e a correta utilização dos itens e a reposição correta. A demora na reposição  desse  recurso essencial no momento necessário compromete a continuidade das atividades.', N'01 - Imagens/02 - Depois/9275.jpeg', N'A instalação de uma grade de proteção é uma medida eficaz para garantir o controle físico de recursos, evitando retiradas não autorizadas e assegurando maior organização no ambiente de trabalho. Esse dispositivo funciona como uma barreira física que delimita o acesso, permitindo que apenas pessoas autorizadas possam realizar a retirada ou reposição dos materiais.
INSERT INTO #PVC VALUES (9276, N'81007243', N'81018600', N'ANTI IMPACTO DO PORTÃO', NULL, N'Projects/Projetos', N'PORTÃO SEMPRE AO FECHAR TINHA IMPACTO  BATIDA CONTRA .', N'ELIMIMAR BATIDA ', N'10346', N'01 - Imagens/01 - Antes/9276.jpeg', N'O portão de entrada da oficina, local destinado à realização de manutenções, sofre impactos significativos durante sua operação. Considerando que o material do portão é alumínio, esses impactos geram ruído elevado e aumentam o risco de avarias estruturais e danos prematuros ao equipamento.', N'01 - Imagens/02 - Depois/9276.jpeg', N'Foi instalada borracha nas laterais do portão de entrada da oficina, local onde são realizadas as manutenções, com o objetivo de evitar impactos diretos durante a abertura e o fechamento. Essa medida reduziu significativamente os ruídos gerados pela movimentação do portão, além de contribuir para o aumento de sua vida útil e prevenção de possíveis avarias.', NULL, N'o portão de entrada da oficina sofria impactos significativos durante sua operação.
INSERT INTO #PVC VALUES (9277, N'81029922', N'81029847', N'TABELA DE CORES', NULL, N'Others/Outros', N'DIFICULDADES EM IDENTIFICAR AS TONELADAS.', N'FACILITAR IDENTIFICAÇÃO', N'10036', N'01 - Imagens/01 - Antes/9277.jpeg', N'Antes durante a retirada de cintas na sala de içamento , os colaboradores tinham dificuldades em identificar as toneladas das cintas a serem retiradas , dificultando a localização das mesma e tornando o atendimento mais demorado devido ter que verificar na etiqueta de cada uma.', N'01 - Imagens/02 - Depois/9277.jpeg', N'Foi colocado na sala de içamento uma placa com as toneladas em cores, facilitando a identificação das mesmas e tornando o atendimento mais pratico e ágil .', NULL, N'os colaboradores tinham dificuldades em identificar as toneladas das cintas a serem retiradas.
INSERT INTO #PVC VALUES (9278, N'460522', N'81046804', N'Environment Truck ', NULL, N'Others/Outros', N'Cost savings of removing the environment truck from the HSER team and team to share the safety truck.', N'cost savings ', N'10231', N'01 - Imagens/01 - Antes/9278.jpeg', N'In the past the environment team was a separate department and they had their own truck. 
INSERT INTO #PVC VALUES (9279, N'460389', N'201966', N'Multifaith Room ', NULL, N'Others/Outros', N'There was not a defined room or space dedicated to multifaith ', N'To ensure that everyone feels valued and safe at our site', N'0', N'01 - Imagens/01 - Antes/9279.jpeg', N'No dedicated space for prayer or reflection.', N'01 - Imagens/02 - Depois/9279.jpeg', N'A neutral and calm space that embraces the multifaith culture and supports our people.  ', NULL, N'This room is utilized by people on site who have expressed gratitude for the space and consideration of their beliefs while on our site.  ', N'Inclusion impacts everyone.  For those using it we heard stories of gratitude.  Those not using it also commented that it was nice to see the company take initiative to value our people.  ', 0, NULL, N'AUMENTO DA AGILIDADE NA ELABORAÇÃO/REVISÃO DAS ARTs, COM QUALIDADE TÉCNICA, PARAMETRIZAÇÃO DAS INFORMAÇÕES E ASSERTIVIDADE NA IDENTIFICAÇÃO DOS RISCOS, REDUZINDO RETRABALHO E OTIMIZANDO O TEMPO DE MIGRAÇÃO DE REVISÃO E APROVAÇÃO, SEM ABRIR MÃO DA SEGURANÇA OPERACIONAL.', '2026-01-29T00:00:00.000', '2026-04-09T07:36:37.000', N'460389', NULL, NULL);
INSERT INTO #PVC VALUES (9280, N'87000312', N'87000319', N'AMF valves standardization', NULL, N'Refining/Refino', N'Defect', N'Optimize inventory management, shorten delivery times, and reduce costs.', N'0', N'01 - Imagens/01 - Antes/9280.jpeg', N'Both 2RT and 3RT are equipped with raw material supply systems (AMF). The supply lines have valves (DH, DL) that need to be replaced periodically. Even valves of the same type but their appearance differs. And lead time and cos were also differ. It was not in handy.', N'01 - Imagens/02 - Depois/9280.jpeg', N'The valves in the 2AMF was replaced to 3AMF type. - Thanks to the replacement it cost is from 22500 to 13000 yen. To, spare valve cost can be reduced since then.', NULL, N'Yes, we could achieve the target as we thought.', N'Asset ', 9500, NULL, N'Workers now have proper supplies available to clean themselves', '2026-04-08T00:00:00.000', '2026-04-09T07:40:19.000', N'87000312', NULL, NULL);
INSERT INTO #PVC VALUES (9281, N'460522', N'81060745', N'Decommissioning StatueMOC Test environment', NULL, N'Others/Outros', N'decommissioning test StatureMOC environment for VB, VNL and Thompson users. This will not stop any production MOC activity. The test environment was used for troubleshooting and this can be done in the production environment. ', N'cost savings', N'10231', N'01 - Imagens/01 - Antes/9281.jpeg', N'Decommissioning test StatureMOC environment for VB, VNL and Thompson users. This will not stop any production MOC activity. 
INSERT INTO #PVC VALUES (9282, N'460389', N'201966', N'Wellness Room', NULL, N'Others/Outros', N'No dedicated space or tool used to help support people for a commitment for overall health and wellness', N'Provide a space and tool to allow people visibility to their health and well being', N'0', N'01 - Imagens/01 - Antes/9282.jpeg', N'There was a body scanner on site but no visibility on the machine or the purpose of it.', N'01 - Imagens/02 - Depois/9282.jpeg', N'A room was designed at the change house with signage and communication on health and wellness.  This room is equipped with a body scanner, fact sheets on the machine, wellness books, and a space for people to feel comfortable to do a body analysis.  Analysis takes less than 2 minutes and provides detail statistics on your health with respect to diabetes''s, cardiac and oncology to name a few.   ', NULL, N'People are using the body scanner for personal health and wellness.  The body scanner provides a print out or app that details personal statistics on their health.  The room provides a comfortable space to do the scan and review your results. ', N'People will utilize opportunity if aware', 0, NULL, N'Tools are easier to find', '2026-03-06T00:00:00.000', '2026-04-09T08:31:26.000', N'460389', NULL, NULL);
INSERT INTO #PVC VALUES (9283, N'81035706', N'81035706', N'RADIO DE COMUNICAÇÃO NA FERRAMENTARIA', NULL, N'Others/Outros', N'Comunicação feita presencialmente ou por terceiros,
INSERT INTO #PVC VALUES (9284, N'200795', N'607697', N'Garson Cage Conveyance Permanent Hoods', NULL, N'Underground/Subterrâneo', N'We used to have to install and remove inspection hoods for every weekly inspection.  This required time and effort.  Also potential for MSD type injuries and exposure to pinch points for those installing and removing the inspection hoods.', N'Efficiency gains and safety improvement', N'10238', N'01 - Imagens/01 - Antes/9284.jpeg', N'We used to have to install and remove inspection hoods for every weekly inspection.  This required time and effort.  Also potential for MSD type injuries and exposure to pinch points for those installing and removing the inspection hoods.', N'01 - Imagens/02 - Depois/9284.jpeg', N'Installed permanent hoods on the cage conveyance.  This saves time and effort as we no longer need to install and remove the inspection hoods for each weekly inspection.  Reduces exposure to MSD type injuries.  Eliminates open hole condition.  Safety railing is permanent. ', NULL, N'Problem solved', N'Will order a spare', 0, NULL, N'Redução significativa das intervenções de manutenção
INSERT INTO #PVC VALUES (9285, N'81002603', N'81002603', N'EXTENSOR DE FLANGES', NULL, N'Projects/Projetos', N'Foi identificada a necessidade de melhoria no processo de troca de dos discos de ruptura das tubulações da área 295,devido á ausência de padronização na atividade , dificuldades na substituição . Essas condições poderiam e geravam atrasos operacionais , riscos durante a execução da atividade por falta de uma ferramenta específica.', N'PEÇA ESPECÍFICA PARA ATIVIDADE', N'10001', N'01 - Imagens/01 - Antes/9285.jpeg', N'Antes da implementação da melhoria , a atividade de troca dos discos de ruptura das tubulações da área 295,era realizada utilizando alabanca , e ferramentas convencionais como a chave de boca , o que se afirma como improviso de ferramentas por não haver ferramenta específica para a execução da atividade. Para viabilizar a substituição do disco inferior , era necessário realizar a abertura do flange superior e , posteriormente , do conjunto inferior , exigindo a desmontagem de dois discos de flange para permitir acesso e a retirada do componente.
INSERT INTO #PVC VALUES (9286, N'519874', N'519874', N'LISTA DE TAREFA_SISTEMA DE DIREÇÃO SCANIA R450 OU G450', NULL, N'Others/Outros', N'NA FROTA DE CAMINHÓES LEVES SCANIA R450 E G450 NÃO EXISTE LISTA DE TAREFA PARA LAUDO DA CAIXA DE DIREÇÃO', N'ELIMINAR DESPERDÍCIOS DE TEMPO SOBRECARGA DE TRABALHO, IRREGULARIDADES  OU OUTRAS PREOCUPAÇÕES ESPECIFICAS SISTEMÁTICA, ENTREGANDO DESEMPENHO EM DIREÇÃO AO NOVO ALVO DE MELHORIA CONTÍNUA', N'10023', N'01 - Imagens/01 - Antes/9286.jpeg', N'NA FROTA DE CAMINHÓES LEVES SCANIA R450 E G450 NÃO EXISTE LISTA DE TAREFA PARA LAUDO DA CAIXA DE DIREÇÃO', N'01 - Imagens/02 - Depois/9286.jpeg', N'CRIADO LISTA DE TAREFA, ELIMINANDO DESPERCIOS DE TEMPO E SOBRE CARGA DE TRABALHO NO PROCESSO DE PLANEJAMENTO DE ORDENS, ENTREGANDO DESEMPENHO EM DIREÇÃO AO NOVO ALVO DE MELHORIA CONTÍNUA.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal', N'SIM, META ALCANÇADA  ELIMINANDO DESPERDÍCIO DE TEMPO E SOBRECARGA DE TRABALHO', N'ESSE KAIZEM TROXE MELHORIA PARA NOSSO PROCESSO, ONDE QUALQUER COLABORADOR POSSO DESEMPENHO O PLANEJAMENTO DE UMA ORDEM LAUDO DA CAIXA DIREÇÃO SEM DIFICULDADE. A IMPORTÂNCIA DE TERMOS OS NOSSOS PROCESSO PADRONIZADOS SEMPRE BUSCANDO MELHORAR CADA VEZ MAIS.', 0, NULL, N'Maior performance dos ativos elétricos, aumento da disponibilidade física e redução de ocorrências de natureza elétrica e de instrumentação.', '2026-04-08T00:00:00.000', '2026-04-09T11:14:02.000', N'519874', NULL, NULL);
INSERT INTO #PVC VALUES (9287, N'607404', N'607404', N'LH Guarding', NULL, N'Refining/Refino', N'Current conveyor was lacking sufficient guarding', N'Install Guarding', N'10073', N'01 - Imagens/01 - Antes/9287.jpeg', N'Insufficient guarding', N'01 - Imagens/02 - Depois/9287.jpeg', N'Guarding was added to close off the open area', NULL, N'open hole was closed off eliminating hazard', N'guarding required', 0, NULL, N'Implantação de coleta de amostras no processo
INSERT INTO #PVC VALUES (9288, N'81020607', N'81046991', N'Melhoria no engate para abastecimento do caminhão fora de estrada', NULL, N'Others/Outros', N'Dificuldades ao abastecer ', N'Qualidade e melhoria do processo ', N'10139', N'01 - Imagens/01 - Antes/9288.jpeg', N' Engate menor, modelo não compatível, Impossibilitando o abastecimento, reservatório de graxa estava vazio.', N'01 - Imagens/02 - Depois/9288.jpeg', N'Acoplado engate padrão para lubrificação feito pelos comboios, assim foi realizada a transferência de graxa para o reservatório.', NULL, N'Com a melhoria estabelecida, obteve-se ganhos em Performance e Qualidade no processo.', N'Qualidade no processo', 0, NULL, N'Com a implementação da Bomba FOX como recurso de resposta inicial a princípios de incêndio, espera‑se um impacto financeiro positivo indireto e sustentável, por meio da redução de custos evitados (Cost Avoided) e da otimização dos recursos operacionais existentes.', '2026-04-06T00:00:00.000', '2026-04-09T11:20:09.000', N'81020607', NULL, NULL);
INSERT INTO #PVC VALUES (9289, N'502854', N'508380', N'SUPORTE PARA INSTALAÇÃO DE ANEL TRAVA', NULL, N'Others/Outros', N'NA ATIVIDADE DE REMOÇÃO DE ANEL TRAVA, IDENTIFICAMOS O RISCO DE QUEDA DE MATERIAL, PODENDO CAUSAR DANOS MATERIAIS E PESSOAIS', N'EVITAR QUEDA DE COMPONENTES  SOBRE COLABORADOR', N'10140', N'01 - Imagens/01 - Antes/9289.jpeg', N'no momento de realizar a remoção do anel trava da rodas dos caminhões fora de estrada, o executante fica exposto ao risco e queda ou projeção de material.', N'01 - Imagens/02 - Depois/9289.jpeg', N'Foi projetado e confeccionado suporte para reter o componente no momento da atividade, evitando assim a queda de material sobre o colaborador ', NULL, N'foi reduzido o risco de alto para baixo na atividade de remoção de componentes.', N'identificamos o risco na atividade, solucionamos com ideias simples da turma, colocamos a segurança em primeiro lugar.', 0, NULL, N'Redução das falhas operacionais
INSERT INTO #PVC VALUES (9290, N'388959', N'388959', N'Redução do tempo de reforma de báscula com a utilização do Kit de revestimento.', NULL, N'Others/Outros', N'O tempo de reforma de uma báscula estava em torno de 100 dias com a fabricação do revestimento internamente.', N'Redução do tempo de reforma  para 45 dias', N'10081', N'01 - Imagens/01 - Antes/9290.jpeg', N'A reforma executada tinha a fabricação do Kit de revestimento com equipe interna, gerando mobilização de mão de obra e elevação do tempo de reforma .', N'01 - Imagens/02 - Depois/9290.jpeg', N'fizemos o projeto de revestimento para a báscula a ser recuperada e aplicamos no caminhão.', NULL, N'O tempo de reforma foi reduzido de 100 dias de acordo com a ultima reforma da Om 202402302324 para 45 dias de execução.', N'Redução no tempo de reforma', 894, 1, N'Better tracking of ligno offloads. Coach to review daily when completing handover to ensure everything is correct. Less random paperwork should be left on the coach desk', '2026-04-02T00:00:00.000', '2026-04-09T12:09:26.000', N'388959', NULL, NULL);
INSERT INTO #PVC VALUES (9291, N'81054815', N'549542', N'Borracha de Contenção no Vazamento de FeNi da TR 950 - 01', NULL, N'Others/Outros', N'A TR 95001 apresenta vazamento excessivo de FeNi durante a operação, ocasionando acúmulo de material no piso ao redor do equipamento. Essa condição evidencia falha no sistema de contenção/vedação, resultando em perda de material, desorganização da área, aumento da demanda por limpeza, além de riscos à segurança operacional e impactos negativos na eficiência do processo.
INSERT INTO #PVC VALUES (9292, N'81036390', N'81036390', N'MATURIDADE TÉCNICA NA ANÁLISE DE PERIGOS E MEDIDAS DE CONTRLE EM ARTs', NULL, N'Others/Outros', N'A PLANILHA ANTERIOR APRESENTAVA BAIXA ADERÊNCIA OPERACIONAL E DEFICIÊNCIAS ESTRUTURAIS, IMPACTANDO NEGATIVAMENTE A AGILIDADE DE ELABORAÇÃO DAS ARTs, BEM COMO A QUALIDADE TÉCNICA DAS INFORMAÇÕES E A ASSERTIVIDADE NA IDENTIFICAÇÃO DE PERIGOS E DEFINIÇÃO DE MEDIDAS DE CONTROLE E DIFICULDADE EM APROVAÇÃO DAS ARTs PELA EQUIPE DE SEGURADA, O QUE IMPACTA DIRETAMENTE NO TEMPO DE MIGRAÇÃO.', N'ELEVAR O NÍVEL DE MATURIDADE TÉCNICA NA IDENTIFICAÇÃO DE PERIGOS', N'10140', N'01 - Imagens/01 - Antes/9292.jpeg', N'A PLANILHA ANTERIOR APRESENTAVA BAIXA ADERÊNCIA OPERACIONAL E DEFICIÊNCIAS ESTRUTURAIS, IMPACTANDO NEGATIVAMENTE A AGILIDADE NA ELABORAÇÃO DAS ARTs, BEM COMO A QUALIDADE TÉCNICA DAS INFORMAÇÕES E A ASSERTIVIDADE NA IDENTIFICAÇÃO DE PERIGOS E MEDIDAS DE CONTROLE.', N'01 - Imagens/02 - Depois/9292.jpeg', N'A NOVA PLANILHA PROPORCIONA MAIOR PADRONIZAÇÃO, CLAREZA E DIRECIONAMENTO TÉCNICO, OTIMIZANDO A ELABORAÇÃO DAS ARTs COM MAIS AGILIDADE, QUALIDADE E SEGURANÇA NA ANÁLISE DE RISCOS. ABRINDO MENTES', NULL, N'BAIXA ADERÊNCIA E FALTA DE PARAMETRIZAÇÃO DA PLANILHA ANTERIOR, QUE DIFICULTAVA A ELABORAÇÃO/REVISÃO TÉCNICA DAS ARTs, GERAVA RETRABALHO.', N'A IMPORTÂNCIA DA PADRONIZAÇÃO, DA ADERÊNCIA À REALIDADE OPERACIONAL E DO DIRECIONAMENTO TÉCNICO PARA GARANTIR MAIS AGILIDADE, QUALIDADE E ASSERTIVIDADE NA ELABORAÇÃO E APROVAÇÃO DAS ARTs', 0, NULL, N'acompanhamento da performance do trimestre atual e direcionamento de onde queremos chegar para os próximos trimestres e ano, permitindo uma visualização clara e objetiva.', '2026-04-01T00:00:00.000', '2026-04-09T16:31:05.000', N'81036390', NULL, NULL);
INSERT INTO #PVC VALUES (9293, N'1015684', N'1015684', N'Shampoo & Body wash for showers at Port', NULL, N'Refining/Refino', N'There was no shampoo or body wash available for workers at Port.', N'To have shampoo and bodywash available for the workers to be able to clean and decontaminate themselves after the work day,', N'0', N'01 - Imagens/01 - Antes/9293.jpeg', N'There was no shampoo or body wash available at Port for workers to properly clean themselves at the end of the shift, if workers needed to shower they would have to use scrub pads or whatever else they could find.', N'01 - Imagens/02 - Depois/9293.jpeg', N'Order a supply of shampoo and body wash from the catalogue and stocked all the showers at Port. Workers now have the correct supplies to properly clean and decontaminate themselves at the end of their shift.', NULL, N'Yes, problem was solved, workers now have supplies available to them and can reorder from catalogue when needed.', N'Having proper cleaning supplies for workers leads to better decontamination and cleaning at the end of the shift.', 0, NULL, N'Comunicação rápida e eficiente.
INSERT INTO #PVC VALUES (9294, N'81016620', N'542814', N'Coriolis', NULL, N'Others/Outros', N'Ocorrências de falhas recorrentes devido  projeção de óleo sobre o instrumentos FSL/ FSLL ocasionando a parada operacional do moinho.', N'Eliminar paradas do moinho por falhas de vazão de óleo', N'10197', N'01 - Imagens/01 - Antes/9294.jpeg', N'Falhas recorrente na chave de fluxo de óleo FSL/FSLL decorrentes de projeção de óleo sobre o instrumentos gerando falhas ocasionando a parada operacional do MO_2057_01', N'01 - Imagens/02 - Depois/9294.jpeg', N'Substituídos por um modelo coriolis FIT_2057_800A/B e relocado para uma área de melhor acessibilidade, eliminando as  paradas recorrentes do moinho e aumentando a confiabilidade operacional.  MO_2057-01. ', NULL, N'Após a substituições e relocações dos medidores de vazão não foram registradas novas recorrências de falhas nos medidores de vazão coriolis', N'Maior confiabilidades dos medidores coriolis', 0, NULL, N'Redução das obstruções na linha
INSERT INTO #PVC VALUES (9295, N'81005911', N'81005911', N'222 Tool Cabinet', NULL, N'Refining/Refino', N'tools were unorganized and hard to find/ kept going missing', N'to organize and retain tools in 222', N'0', N'01 - Imagens/01 - Antes/9295.jpeg', N'tools were unorganized and hard to find/ kept going missing', N'01 - Imagens/02 - Depois/9295.jpeg', N'Installed tool racks to hold tools frequently used in 222 to help access tools faster and organize them', NULL, N'yes', N'tools need to be organized ', 0, NULL, N' A tubulação apresentava vazamentos de ar devido à corrosão, causando perda de pressão no sistema.
INSERT INTO #PVC VALUES (9296, N'81044674', N'81058364', N'Confeccionar suporte para transporte do cabeçote do redutor do moinho vertical', NULL, N'No Replication/Sem replicação', N'Devido à quebra do eixo do agitador do moinho vertical, a transportadora responsável não aceitou realizar o transporte da peça utilizando pallet, em função do elevado peso.
INSERT INTO #PVC VALUES (9297, N'81044674', N'81038889', N'Substituição do Sistema de Acionamento CF 2017 10', NULL, N'No Replication/Sem replicação', N'O equipamento apresentava alta frequência de falhas, incluindo queima do motor, quebra de correias e necessidade constante de substituição de polias motrizes devido ao desgaste.
INSERT INTO #PVC VALUES (9298, N'81044674', N'527014', N'Fabricação de Guarda-Corpo DI 2057-01', NULL, N'No Replication/Sem replicação', N'Foi identificada a existência de vão aberto na área operacional, representando risco de queda de pessoas em nível diferente.
INSERT INTO #PVC VALUES (9299, N'81031812', N'81031812', N'Painel de Indicadores de Performance Elétrica/Instrumentação', NULL, N'Others/Outros', N'Baixa visibilidade dos impactos em indicadores de produtividade (DF, MTBF, MTTR, HM) e ocorrências de manutenção elétrica e instrumentação.', N'Acompanhar semanalmente indicadores de produtividade para elétrica e instrumentação.', N'10314', N'01 - Imagens/01 - Antes/9299.jpeg', N'Visão geral dos indicadores das Usinas com todos os setores de manutenção, resultando em baixa visibilidade dos impactos de elétrica e instrumentação.', N'01 - Imagens/02 - Depois/9299.jpeg', N'Cálculo dos principais indicadores de produtividade seguindo o padrão da Engenharia com foco em elétrica e instrumentação. Melhor acompanhamento dos desvios e disponibilidade de dados para definição de métricas e tratamento de perdas.', NULL, N'SIM. Atualmente é possível visualizar com clareza paradas e ocorrências de elétrica e instrumentação.', N'A análise de dados eficaz é realizada através da combinação de várias ferramentas.', 0, NULL, N'All items being checked in field now match the check Prsheet.,', '2026-04-09T00:00:00.000', '2026-04-10T11:40:50.000', N'81031812', NULL, NULL);
INSERT INTO #PVC VALUES (9300, N'81044674', N'81054451', N'Adequação de Amostrador de Material', NULL, N'No Replication/Sem replicação', N'Foi identificado que não havia coleta de amostras na tubulação de alívio do processo.
INSERT INTO #PVC VALUES (9301, N'513657', N'513657', N'KAIZEN – Agilidade Operacional e Proteção à Vida na Bomba FOX', NULL, N'Others/Outros', N'Historicamente, todas as ocorrências de incêndio eram tratadas exclusivamente com o apoio do caminhão de bombeiros, independentemente da gravidade, localização ou estágio inicial do evento.
INSERT INTO #PVC VALUES (9302, N'81044674', N'81030439', N'Melhoria na Válvula do CI-2057-01 – Letra G', NULL, N'No Replication/Sem replicação', N'As válvulas instaladas no equipamento CI-2057-01 apresentavam falhas recorrentes, como vazamentos, obstruções frequentes e baixa confiabilidade operacional.
INSERT INTO #PVC VALUES (9303, N'1008370', N'1008370', N'Update Coach handover to better track ligno offloads and paperwork', NULL, N'Others/Outros', N'Ligno offloads were not being tracked properly. Vale forms were not being filled out. Paperwork was not being sent to warehouse', N'Make tracking ligno offloads easier ', N'0', N'01 - Imagens/01 - Antes/9303.jpeg', N'Ligno offloads were not being tracked properly. Vale forms were not being completed. Paperwork was not being sent to warehouse. There would often being confusing when tracking isotainers.', N'01 - Imagens/02 - Depois/9303.jpeg', N'Updated POL coach handover to include a section for ligno. The POL coach will have to review this every day when completing his handover. Ensuring that the coach reviews this every day should result in better management of the ligno offloading/tracking process', NULL, N'Yes', N'Using better tracking methods', 0, NULL, N'Eliminated a possible pinch point and made the back loading connection process easier.', '2026-04-09T00:00:00.000', '2026-04-10T12:32:46.000', N'1008370', NULL, NULL);
INSERT INTO #PVC VALUES (9304, N'81044674', N'81038717', N'Instalação de Válvula Esférica ½” na Tubulação CF-2057-16 (Alimentação do Retrofit)', NULL, N'No Replication/Sem replicação', N'Na condição anterior, a saída da tubulação de 4” que alimentava a mangueira de ¾” era realizada por ligação direta, sem a presença de um dispositivo de bloqueio de fluxo.
INSERT INTO #PVC VALUES (9305, N'33019', N'33019', N'Painel de Desempenho & Performance: Mina e Usina ', NULL, N'Others/Outros', N'A apresentação anterior em dois slides dificultava a comparação e a análise integrada das performances de mina e usina, gerando informações fragmentadas  dificultando a compreensão e o acompanhamento das performances.', N'Melhorar a visualização e o acompanhamento das metas trimestrais e anual e também de performance da mina e usina em um único slide, facilitando a comunicação e o entendimento das informações pela equipe.', N'10270', N'01 - Imagens/01 - Antes/9305.jpeg', N'Fragmentação da apresentação em dois slides, para acompanhamento das performances de mina e usina, com maior detalhamento. Com oportunidade de simplificação e colocar a performance atual do trimestre bem como aonde queremos chegar no ano de forma.', N'01 - Imagens/02 - Depois/9305.jpeg', N' Unificação das informações em um só slide, destacando a performance do trimestre atual e direcionamento de onde queremos chegar para os próximos trimestres e ano, permitindo uma visualização clara e objetiva.  Melhoria na comunicação das performances, com um slide que sintetiza dados essenciais e facilita a tomada de decisões.', NULL, N'Melhoria na comunicação das performances, com um slide que sintetiza dados essenciais e facilita a tomada de decisões.', N'simplificação de informação de performance e desempenho', 0, NULL, N'hoses being left on the floor creates a potential for someone to trip and hurt themselves. properly storing hoses can minimize the potential for incidents', '2026-04-06T00:00:00.000', '2026-04-10T13:56:01.000', N'33019', NULL, NULL);
INSERT INTO #PVC VALUES (9306, N'81035706', N'81035706', N'PADRONIZAÇÃO DA COR DO MÊS', NULL, N'Others/Outros', N'Não havia padronização visual para identificação da cor do mês.
INSERT INTO #PVC VALUES (9307, N'81044674', N'81039011', N'Instalação de válvulas para melhoria do sistema de alimentação', NULL, N'No Replication/Sem replicação', N'O sistema de alimentação apresentava frequentes obstruções nas mangueiras e conexões, impactando diretamente a continuidade da operação. Essas obstruções exigiam intervenções constantes de manutenção, reduzindo a disponibilidade do equipamento. O problema foi identificado por meio do alto número de paradas corretivas no AM 2057-16.', N'Reduzir as obstruções na linha e minimizar trocas emergenciais de componentes, aumentando a confiabilidade do sistema.', N'10031', N'01 - Imagens/01 - Antes/9307.jpeg', N'O sistema de bombas apresentava alta dependência de manutenção para desobstrução frequente da linha do AM 2057-16,', N'01 - Imagens/02 - Depois/9307.jpeg', N'Foram instaladas válvulas na linha de alimentação, proporcionando melhor controle do fluxo e facilitando intervenções operacionais. Com isso, houve redução significativa das obstruções e maior estabilidade no processo produtivo.', NULL, N'Redução das obstruções na linha
INSERT INTO #PVC VALUES (9308, N'81044674', N'550686', N' Instalação de Válvula de Ar Manual', NULL, N'No Replication/Sem replicação', N' A tubulação responsável por conduzir ar até a válvula controladora LV-2057-838B da CF-2057-28 apresentava vazamentos devido à corrosão do material, ocasionando furos na linha.
INSERT INTO #PVC VALUES (9309, N'33019', N'33019', N'Melhoria no Acompanhamento dos Resultados Acumulados no Relatório Diário de Produção (YTD)', NULL, N'Others/Outros', N'No relatório diário de produção, as informações sobre os resultados acumulados (YTD) eram limitadas ao resultado até o final do mês anterior. Essa abordagem dificultava uma visão clara do desempenho atual, pois os colaboradores não tinham acesso a dados atualizados que incluíssem os resultados do mês vigente até a data atual (d-1).', N'Melhorar o acompanhamento dos resultados acumulados (YTD) no Relatório Diário de Produção, proporcionando uma visão mais clara e atualizada do desempenho', N'10270', N'01 - Imagens/01 - Antes/9309.jpeg', N'No relatório diário de produção, as informações sobre os resultados acumulados (YTD) eram limitadas ao resultado até o final do mês anterior. Essa abordagem dificultava uma visão clara do desempenho atual, pois os colaboradores não tinham acesso a dados atualizados que incluíssem os resultados do mês vigente até a data atual (d-1).', N'01 - Imagens/02 - Depois/9309.jpeg', N'A solução adotada consiste na reformulação das colunas de YTD no Relatório Diário de Produção. Agora, os relatórios apresentam não apenas os resultados até o mês anterior, mas também incluem os resultados acumulados do mês vigente até o dia (d-1).  promovendo um maior engajamento das equipes na busca por resultados. acesso a informações mais relevantes e em tempo real, melhorando a visibilidade sobre o desempenho da produção e garantindo um acompanhamento mais eficaz dos indicadores e do cumprimento das metas orçadas', NULL, N'Agora, os relatórios apresentam não apenas os resultados até o mês anterior, mas também incluem os resultados acumulados do mês vigente até o dia (d-1).  promovendo um maior engajamento das equipes na busca por resultados. acesso a informações mais relevantes e em tempo real, melhorando a visibilidade sobre o desempenho da produção e garantindo um acompanhamento mais eficaz dos indicadores e do cumprimento das metas orçadas', N' necessidade de uma visão mais precisa e atualizada da performance de produção', 0, NULL, N'Mais atenção e cuidado com a area que trabalhamos.', '2026-04-08T00:00:00.000', '2026-04-10T14:53:51.000', N'33019', NULL, NULL);
INSERT INTO #PVC VALUES (9310, N'723908', N'723908', N'Substituição dos Engates de Abastecimento de Óleo da Máquina PZ-26', NULL, N'Others/Outros', N'engates originais não permitiam a conexão adequada com os equipamentos dos comboios.', N'Qualidade no processo', N'10139', N'01 - Imagens/01 - Antes/9310.jpeg', N'Engates de fábrica incompatíveis com os comboios.
INSERT INTO #PVC VALUES (9311, N'514353', N'514353', N'Melhoria no Armazenamento de Galões de Água (20L)', NULL, N'Others/Outros', N'Os galões de água de 20L eram armazenados sobre pallets, sem qualquer tipo de proteção física ou controle ambiental.', N'Melhoria na qualidade e conservação da água', N'10017', N'01 - Imagens/01 - Antes/9311.jpeg', N'Os galões de 20L eram armazenados em pallets, sem proteção ou controle ambiental, expostos ao sol, poeira e contaminantes, gerando risco à saúde, perda de qualidade e não conformidade com 5S e SSMA.', N'01 - Imagens/02 - Depois/9311.jpeg', N'Com foco em segurança e qualidade, foi implantado armário exclusivo para galões de 20L. Solução de baixo custo elimina exposição a agentes externos, melhora organização e é replicável.', NULL, N'Aumento do nível de organização (5S)
INSERT INTO #PVC VALUES (9312, N'81045248', N'81045248', N'Wharf Conveyor Valeforms checklist update', NULL, N'Refining/Refino', N'The Valeforms for Wharf Conveyor operational checks needed to be updated, several items being checked and also referenced in the SOP were not captured on the Valeform.', N'To have Valeform capture everything being checked in the field', N'0', N'01 - Imagens/01 - Antes/9312.jpeg', N'The Valeforms for Wharf Conveyor operational checks needed to be updated, several items being checked and also referenced in the SOP were not captured on the Valeform.', N'01 - Imagens/02 - Depois/9312.jpeg', N'Added questions to the check sheet to confirm the oil level in the gearbox''s and to check the counterweight and take-up system on the wharf conveyor.', NULL, N'Yes, problem was solved, check sheet is updated.', N'Procedural reviews found items missing from checkseet.', 0, NULL, N'Garantir operação segura e eficiente da válvula de água de make‑up do by‑pass da Linha 2, reduzindo riscos de falhas, retrabalho e impactos no processo produtivo.', '2026-04-09T00:00:00.000', '2026-04-10T23:18:27.000', N'81045248', NULL, NULL);
INSERT INTO #PVC VALUES (9313, N'201781', N'201781', N'Unsafe Condition Card Holder', NULL, N'No Replication/Sem replicação', N'Not all employees were aware of where the Unsafe Condition cards were stored.', N'To make it easier for Employees to access Unsafe Condition Cards.', N'10236', N'01 - Imagens/01 - Antes/9313.jpeg', N'Employees unaware of where cards were kept.', N'01 - Imagens/02 - Depois/9313.jpeg', N'A file holder was installed in the line-up/lunchroom beside the existing SLAM holder to allow employees constant and easy access to the Unsafe Condition Cards.
INSERT INTO #PVC VALUES (9314, N'81045248', N'81045248', N'Checklists ', NULL, N'No Replication/Sem replicação', N'vale form checklists have not been consistently filled out and submitted. 
INSERT INTO #PVC VALUES (9315, N'496419', N'496419', N'Cartão de Coleta Bujões dos Componentes Infra', NULL, N'Others/Outros', N'As analises de óleo e as respostas são recebidas apenas, após a coleta durante a preventiva, não sendo identificada antes.', N'Conseguir analisar de forma visual se existe alguma anomalia ou desgaste de componente.', N'10115', N'01 - Imagens/01 - Antes/9315.jpeg', N'Durante as preventivas não havia uma forma de coleta e analise visual dos lubrificantes dos componentes, era executado apenas a coleta em frascos e enviado para o laboratório.', N'01 - Imagens/02 - Depois/9315.jpeg', N'Foi incluído nas pastas de preventiva um cartão, com espaços onde podem ser colocadas as amostras do lubrificante de cada componente, quando colocada a amostra sobre o cartão é possível verificar se existe particulado (quando o desgaste esta acentuado), podendo ser realizada intervenção de imediato, esse cartão também é entregue a equipe de preditiva após a termino da manutenção.', NULL, N'Anteriormente não existia uma analise antecipada e nem um complemento das analises, agora temos um cartão onde pode ser colocada as coletas de cada componente', N'Com essa iniciativa, a analise dos lubrificantes se torna mais completa. ', 0, NULL, N' Menor tempo gasto na localização e triagem das amostras', '2026-04-03T00:00:00.000', '2026-04-11T21:46:54.000', N'496419', NULL, NULL);
INSERT INTO #PVC VALUES (9316, N'609342', N'609342', N'Truck Back Loading Hose Pinch Point', NULL, N'Refining/Refino', N'The Truck backloading hose is hard to attach to connection point due to limited space.', N'To remove a possible pinch point', N'10114', N'01 - Imagens/01 - Antes/9316.jpeg', N'The truck back loading hose is hard to connect due to limited space because the mounted high pressure water hose mount is to close in proximity. ', N'01 - Imagens/02 - Depois/9316.jpeg', N'High pressure water hose was relocated to the backside of the column to eliminate the pinch point and allow for easier back loading hose connection.', NULL, N'Yes, the problem was solved by simply relocating the high-pressure water hose.', N'Pinch points can be anywhere ', 0, NULL, N' CONTROLE DE ESTOQUE FACILITADO , COM ACOMPANHAMENTO VISUAL DIÁRIO.', '2026-04-10T00:00:00.000', '2026-04-11T21:57:04.000', N'609342', NULL, NULL);
INSERT INTO #PVC VALUES (9317, N'923110', N'81009651', N'Padronização ponto de água.', NULL, N'Others/Outros', N'Válvula do ponto de água de limpeza do topo das colunas danificada e tubulação fora do padrão/identificação.', N'Padronizar ponto de água de limpeza dos topos das colunas e substituir válvula com defeito. ', N'10054', N'01 - Imagens/01 - Antes/9317.jpeg', N'Válvula do ponto de água de limpeza do topo das colunas danificada e tubulação fora do padrão/identificação.', N'01 - Imagens/02 - Depois/9317.jpeg', N'Foi instalado nova válvula e padronizado tubulação pintando na cor verde que identificar tubulação de água, com isso tivemos um impacto positivo, melhorando qualidade na distribuição de água de arandela das colunas e com melhorando a qualidade do concentrado de cobre. ', NULL, N'Sim, substituição da válvula e padronizado tubulação de água. ', N'Kaizen', 0, NULL, N'Controle facilitado: O sistema de cores avisa quando é hora de repor o produto, evitando faltas ou excessos.', '2026-04-10T00:00:00.000', '2026-04-11T22:57:02.000', N'923110', NULL, NULL);
INSERT INTO #PVC VALUES (9318, N'81045248', N'81045248', N'Hose storage ', NULL, N'No Replication/Sem replicação', N'hoses left on floor next to the tripper - new hose drops were created to help with clean up and hoses can be attached anywhere along the rails. There was not a current storage situation for the new hose attachments', N'housekeeping ', N'0', N'01 - Imagens/01 - Antes/9318.jpeg', N'hose left on the floor next to the tripper ', N'01 - Imagens/02 - Depois/9318.jpeg', N'hose now hanging on the wall neatly - no longer a tripping hazard ', NULL, N'hoses are now neatly stored off the floor', N'reduce tripping hazards ', 0, NULL, N'Saves time.', '2026-04-11T00:00:00.000', '2026-04-12T00:17:47.000', N'81045248', NULL, NULL);
INSERT INTO #PVC VALUES (9319, N'81047450', N'81047017', N'SUPORTE REMOVER E INSTALAR EIXO PIVÔ D10 E D11', NULL, N'Open Pit/Poço aberto', N'DURANTE A REMOÇÃO E INSTALAÇÃO DO EIXO PIVÔ NA FROTA DO TRATOR DE ESTEIRAS D11 E D10 NÃO TINHAMOS UM SUPORTE ADEQUADO PARA CONECTAR O COMPONENTE COM A MAQUINA.', N'REDUZIR RISCO RISCO E PRODUTIVIDADE ', N'10318', N'01 - Imagens/01 - Antes/9319.jpeg', N'DURANTE A REMOÇÃO E INSTALAÇÃO DO EIXO PIVÔ NA FROTA DO TRATOR DE ESTEIRAS D11 E D10 NÃO TINHAMOS UM SUPORTE ADEQUADO PARA CONECTAR O COMPONENTE COM A MAQUINA ERA UTILIZADO UM PALITE DE MADEIRA OFERENCENDO RISCO AOS EXECUTANTES.', N'01 - Imagens/02 - Depois/9319.jpeg', N'FOI CRIADO UM SUPORTE ONDE E CONECTADA A FERRAMENTA COM AUXILIO DE UM EQUIPAMENTO AUXILIAR TORNANDO A ATIVIDADE AGIL E SEGURA PARA EQUIPE DE MANUTENÇÃO.', NULL, N'REDUÇÃO DE RISCO, REDUÇÃO DE TEMPO E ESPAÇO ', N'REDUÇÃO DE RISCO ', 10, 1, N'Acquire faster access of first aid material.', '2026-04-11T00:00:00.000', '2026-04-12T01:48:16.000', N'81047450', NULL, NULL);
INSERT INTO #PVC VALUES (9320, N'81047450', N'81047017', N'SUPORTE PARA ARMARIOS DE FERRAMENTAS ', NULL, N'Open Pit/Poço aberto', N'CARRINHOS DE FERRAMENTAS POSICIONADOS EM NIVEL DE SOLO, OBTENDO CONTATO COM AGUA E OUTROS AGENTES OCASIONANDO FERRUGEM NOS MESMO DIMINUINDO SUA VIDA UTIL.', N'REDUÇÃO DE CUSTO/ PRESERVAR RECURSO ', N'10318', N'01 - Imagens/01 - Antes/9320.jpeg', N'CARRINHOS DE FERRAMENTAS POSICIONADOS EM NIVEL DE SOLO, OBTENDO CONTATO COM AGUA E OUTROS AGENTES OCASIONANDO FERRUGEM NOS MESMO DIMINUINDO SUA VIDA UTIL.', N'01 - Imagens/02 - Depois/9320.jpeg', N'FOI REALIZADA A FABRICAÇÃO DE UM SUPORTE METALICO ELEVANDO O CONJUNTO EM 12.CM ELEMINADO O CONTATO DO CONJUNTO POR AGUA E AGENTES QUIMICOS ELEVANDO SUA VIDA UTIL E FACILITANDO A APLICAÇÃO DO 5S EM SEU INTERIOR.', NULL, N'FOI REALIZADA A FABRICAÇÃO DE UM SUPORTE METALICO ELEVANDO O CONJUNTO EM 12.CM ELEMINADO O CONTATO DO CONJUNTO POR AGUA E AGENTES QUIMICOS ELEVANDO SUA VIDA UTIL E FACILITANDO A APLICAÇÃO DO 5S EM SEU INTERIOR.', N'MELHORIA CONTINUA ', 80, 1, N'Required training SOPs relevancy reviewed.', '2026-04-10T00:00:00.000', '2026-04-12T02:16:26.000', N'81047450', NULL, NULL);
INSERT INTO #PVC VALUES (9321, N'81052183', N'81052183', N'Ajuste do coletor', NULL, N'Projects/Projetos', N'Coletor de amostras moinho de bola apresentava danos onde poderia machucar as laboratoristas que o usava com frequencia nas suas rotinas.', N'Melhorias rotineiras', N'10054', N'01 - Imagens/01 - Antes/9321.jpeg', N'Coletor de amostras do moinho de bolas apresentava perigo exposto onde o fio estava descascado e com risco de quebrar na hora de amostrar.', N'01 - Imagens/02 - Depois/9321.jpeg', N'Fizemos a troca componente onde estava danificado por um novo e mais seguro. Evitando a perca do cletor na hora da amostragem e um acidente de trabalho com as laboratoristas que usam ele rotineiramente.', NULL, N'SIM. Resultados alcançados com sucesso.', N'Atenção e cuidados redobrados / cuidado genuíno.', 0, NULL, N'spend less time gathering tools and bringing them up and down the stairs ', '2026-04-06T00:00:00.000', '2026-04-12T11:16:18.000', N'81052183', NULL, NULL);
INSERT INTO #PVC VALUES (9322, N'81052183', N'81009651', N'SUPORTE DA PIA', NULL, N'Projects/Projetos', N'suporte apresentava desgaste visivel', N'MELHORIA PARA AREA ', N'10054', N'01 - Imagens/01 - Antes/9322.jpeg', N'Suporte de pia estava apresentando muito desgaste.', N'01 - Imagens/02 - Depois/9322.jpeg', N'Trocamos o suporte que estava desgastado para um novo e realizamos a pintura para efeito aparente.', NULL, N'Conforme o esperado.', N'Cuidados com a area.', 0, NULL, N'incentivo para replicação, melhora da vida util do nosso ativo.', '2026-04-05T00:00:00.000', '2026-04-12T11:43:24.000', N'81052183', NULL, NULL);
INSERT INTO #PVC VALUES (9323, N'81055646', N'81054579', N'Identificação da Válvula de Água de Make‑up Automática', NULL, N'Projects/Projetos', N'Atualmente, a válvula de água de make‑up automática não possui uma identificação padronizada e visível em campo, dificultando sua localização, reconhecimento funcional e entendimento durante atividades de operação, manutenção corretiva e preventiva.', N'Padronizar e implementar a identificação clara e permanente da válvula de água de make‑up automática', N'10229', N'01 - Imagens/01 - Antes/9323.jpeg', N'A válvula de água de make‑up automática não possuía identificação padronizada, dificultando sua localização e aumentando o risco de erros operacionais e atrasos nas manutenções.', N'01 - Imagens/02 - Depois/9323.jpeg', N'Com a identificação padronizada e visível, a válvula passou a ser facilmente localizada, reduzindo erros, agilizando a manutenção e aumentando a segurança e confiabilidade do sistema.', NULL, N'A meta inicial foi plenamente atendida, eliminando a falta de identificação da válvula de água de make‑up automática.', N'A identificação padronizada de ativos é fundamental para evitar erros operacionais, reduzir tempo de intervenção e aumentar a confiabilidade do processo.', 0, NULL, N'inspection time cut in half', '2026-03-17T00:00:00.000', '2026-04-12T12:04:21.000', N'81055646', NULL, NULL);
INSERT INTO #PVC VALUES (9324, N'81033756', N'81022593', N'Melhoria em suporte de cordoalha do transportador.', NULL, N'Others/Outros', N'Cordoalha de emergência do transportador de correias TR-2305SA-02, encontrava-se com um longo vão entre as extremidades de suporte, ocasionando assim oscilações e balanço da mesma, e ocorrendo o acionamento da chave involuntariamente. Com o acionamento da chave ocorria a para de todo o circuito de correias da área da moagem e prensagem SLB-3, gerando o corte de alimentação da usina, impactando diretamente na produtividade.', N'Mitigar paradas do circuito de correias ', N'10197', N'01 - Imagens/01 - Antes/9324.jpeg', N'Cordoalha de emergência do transportador de correias TR-2305SA-02, encontrava-se com um longo vão entre as extremidades de suporte, ocasionando assim oscilações e balanço da mesma, e ocorrendo o acionamento da chave involuntariamente. ', N'01 - Imagens/02 - Depois/9324.jpeg', N'Foi realizado a confecção e instalação de novos suportes em pontos estratégicos mitigando a folga e tencionando adequadamente a cordoalha, com isso houve a redução das oscilações e balanço da cordoalha e vitando assim o seu acionamento involuntário.  ', NULL, N'O problema foi sanado com a instalação dos novos suportes em pontos estratégicos, mitigando a folga e tencionando adequadamente a cordoalha, evitando assim as oscilações e balanço da cordoalha, e por sua vez o acionamento involuntário da chave de emergência.', N'Foi constatado que ao deixar um longo vão entre as extremidades de suporte da cordoalha, a mesma fica propícia a oscilações e balanço, e vulnerável ao acionamento involuntário da chave de emergência.', 0, NULL, N'Melhoria com segurança e eliminação de risco.', '2026-04-08T00:00:00.000', '2026-04-12T12:20:59.000', N'81033756', NULL, NULL);
INSERT INTO #PVC VALUES (9325, N'81055646', N'81054579', N'Identificação da Válvula de Água de Make‑up – By‑pass da Linha 2', NULL, N'Projects/Projetos', N'A válvula de água de make‑up do by‑pass da Linha 2 não possuía identificação adequada em campo, dificultando sua correta localização e compreensão da sua função durante operações e intervenções de manutenção', N'Implementar a identificação padronizada da válvula de água de make‑up do by‑pass da Linha 2, garantindo rápida localização, correta operação e maior segurança, reduzindo falhas humanas e tempo de intervenção.', N'10229', N'01 - Imagens/01 - Antes/9325.jpeg', N'A válvula de água de make‑up do by‑pass da Linha 2 operava sem identificação visível, causando dúvidas operacionais, risco de manobras indevidas e atrasos nas atividades de manutenção.', N'01 - Imagens/02 - Depois/9325.jpeg', N'A válvula passou a contar com identificação padronizada e clara, permitindo fácil reconhecimento em campo, melhor entendimento de sua função no sistema e maior agilidade nas atividades.', NULL, N'A meta foi atingida com sucesso, eliminando a falta de identificação da válvula de água de make‑up do by‑pass da Linha 2. O problema inicial foi resolvido por meio da padronização, trazendo ganhos em segurança, operação e manutenção.', N'A correta identificação de válvulas críticas, especialmente em linhas de by‑pass, é essencial para evitar erros operacionais e melhorar a confiabilidade e segurança do sistema.', 0, NULL, N'Confiabilidade, segurança e produção', '2026-03-18T00:00:00.000', '2026-04-12T12:33:16.000', N'81055646', NULL, NULL);
INSERT INTO #PVC VALUES (9326, N'81036747', N'81036747', N'textured paint in fall risk area', NULL, N'Others/Outros', N'When flocculent mixes with water it becomes extremely slippery. The ramp at the west bay door is a high traffic area and a staging area for flocculent lifts into the bund. ', N'reduce the chances of slipping in the area', N'0', N'01 - Imagens/01 - Antes/9326.jpeg', N'Ramp is next to flocculent bund and can become slippery when flocculent spills or becomes wet. A pallet jack is used to move flocculent around in this area on an incline. ', N'01 - Imagens/02 - Depois/9326.jpeg', N'A paint with sand was applied to the ramp in this area to increase traction. This reduces the likelihood of a slip and fall or work place injury resulting in lost time.', NULL, N'the paint provides increased traction in this area while still being with in the approved 5S color scheme', N'na', 0, NULL, N'MELHOROU ACESSO DE FORMA SEGURA.', '2026-04-11T00:00:00.000', '2026-04-12T13:35:31.000', N'81036747', NULL, NULL);
INSERT INTO #PVC VALUES (9327, N'81023633', N'507447', N'Operação Cadeado Fechado:', NULL, N'Others/Outros', N'Risco de abertura não autorizada ou acidental das portinholas de acesso aos alçapões das peneiras', N'Mitigar o risco crítico de acesso não autorizado aos alçapões das peneiras', N'10220', N'01 - Imagens/01 - Antes/9327.jpeg', N'As portinholas de acesso aos alçapões das peneiras possuíam apenas trincos manuais simples. Esse cenário permitia a abertura imediata por qualquer colaborador, sem a necessidade de liberação de chaves, expondo a equipe a riscos de queda de nível durante uma inspeção/manutenção nos equipamentos.', N'01 - Imagens/02 - Depois/9327.jpeg', N'Implementação de barreiras físicas (cadeados) e sinalização de ''Acesso Restrito'' nas portinholas de acesso aos alçapões das peneiras. Esta ação estabelece um obstáculo físico e administrativo, forçando o colaborador a seguir o fluxo oficial via CCB (Centro de Controle de Bloqueio). A medida visa desestimular o acesso inadvertido e sinalizar claramente a proibição.', NULL, N'sim. O acesso imediato foi dificultado. A barreira física restringe a abertura por distração e sinaliza o perigo. Embora não impeça a violação intencional (quebra do cadeado), ela estabelece um padrão de controle via CCB e elimina a desculpa de abertura por engano.
INSERT INTO #PVC VALUES (9328, N'81057538', N'81057538', N'IDENTIFICAÇÃO DE AMOSTRAS BRUTAS', NULL, N'Others/Outros', N'AMOSTRAS QUE CHEGAVAM NO TURNO ANTERIOR E NAO SABIAMOS O QUE REALMENTE ERA PRA SER FEITO.', N'MELHORAR NA IDENTICAÇÃO', N'10129', N'01 - Imagens/01 - Antes/9328.jpeg', N'- Era recebido um grande volume de amostras no turno anterior, mas havia falta de clareza sobre qual era o procedimento correto a ser seguido, gerando incertezas e falhas no processo.
INSERT INTO #PVC VALUES (9329, N'81057520', N'81057520', N'KAIBAN GESTÃO VISUAL', NULL, N'Others/Outros', N'DIFICULDADE NA VISUALIZAÇÃO DE MATERIAL PARA O CONTROLE DE REPOSIÇÃO', N'CONTROLE DE ESTOQUE FACILITADO, COM ACOMPANHAMENTO VISUAL DIÁRIO', N'10129', N'01 - Imagens/01 - Antes/9329.jpeg', N'DIFICULDADE NA VISUALIZAÇÃO DE MATERIAL PARA O CONTROLE DE REPOSIÇÃO', N'01 - Imagens/02 - Depois/9329.jpeg', N'Identificação visual: fixada diretamente na prateleira, além de codificação por cores (verde - amarelo -vermelho) na estrutura , referência rápida para nível de estoque ou tipo de material, conforme o método Kaiban.
INSERT INTO #PVC VALUES (9330, N'81057520', N'81057520', N'IDETIFICAÇÃO VISUAL DE PAPEL DE FILTRO', NULL, N'No Replication/Sem replicação', N'Controle visual: Sem referência de nível de estoque  não era possível verificar rapidamente se o material estava baixo, médio ou alto.', N'GESTÃO VISUAL', N'10129', N'01 - Imagens/01 - Antes/9330.jpeg', N'- Controle visual: Sem referência de nível de estoque não era possível verificar rapidamente se o material estava baixo, médio ou alto.', N'01 - Imagens/02 - Depois/9330.jpeg', N'Clareza total: Qualquer colaborador identifica rapidamente o material e seu nível de estoque.
INSERT INTO #PVC VALUES (9331, N'81062686', N'81062686', N'Oil rag supply container', NULL, N'Others/Outros', N'Could not locate the oil rag for checking pump oil when completing operator rounds.', N'Provide easy access to oil rags', N'10212', N'01 - Imagens/01 - Antes/9331.jpeg', N'Oil rags either missing or contaminated when trying to complete operator rounds. ', N'01 - Imagens/02 - Depois/9331.jpeg', N'Easily accessible oil rag supply located next to the pump.', NULL, N'Yes.', N'N/A', 0, NULL, N'ADEQUAÇÃO PARA MELHORA DO PROCESSO.', '2026-04-11T00:00:00.000', '2026-04-12T20:36:13.000', N'81062686', NULL, NULL);
INSERT INTO #PVC VALUES (9332, N'81045247', N'81045247', N'First Aid Reflectors', NULL, N'Others/Outros', N'Visibility of burn blanket and burn kit was not optimal.', N'Make first aid items more visible.', N'10212', N'01 - Imagens/01 - Antes/9332.jpeg', N'First aid items not visibly obvious, therefore requiring time looking for it.', N'01 - Imagens/02 - Depois/9332.jpeg', N'Reflectors catch the eye and make the items more visible.', NULL, N'First aid items are now more visible in an emergency situation.', N'Time matters in an emergency.', 0, NULL, N'A consulta ao inventário demandava deslocamento até um computador e tempo adicional para localizar a planilha, gerando demora no acesso às informações.', '2026-04-11T00:00:00.000', '2026-04-12T21:35:40.000', N'81045247', NULL, NULL);
INSERT INTO #PVC VALUES (9333, N'81005913', N'81005913', N'POL CRT authorization tracking', NULL, N'Refining/Refino', N'Tracking checklists for control room technicians had no dedicated storage area at POL Control Room panel. This resulted in misplaced progress logs after routine operations, vacations and shift changes.', N'Ease of tracking progress', N'0', N'01 - Imagens/01 - Antes/9333.jpeg', N'Tracking checklists for control room technicians had no dedicated storage area at POL Control Room panel. This resulted in misplaced progress logs after routine operations, vacations and shift changes.', N'01 - Imagens/02 - Depois/9333.jpeg', N'Dedicated CRT checklist binder sorted by shifts added to essential POL Control Room binder shortage area near panel. This ensures technician training progress and supervisor signoffs will not be lost while they are completing the year long process of Control Room training.', NULL, N'Binder implemented successfully and communicated with all shifts.', N'Visual success, Sustain, Checklist culture', 0, NULL, N'Agilidade no acesso aos pontos de monitoramento.', '2026-04-12T00:00:00.000', '2026-04-13T01:24:28.000', N'81005913', NULL, NULL);
INSERT INTO #PVC VALUES (9334, N'81045248', N'81045248', N'offload hilti and storage ', NULL, N'No Replication/Sem replicação', N'each time we need to use a hilti tool on the tripper/wharf conveyor level during offload clean up, we need to carry hilti tool, batteries, and attachments up to the top of the building. 
INSERT INTO #PVC VALUES (9335, N'81034776', N'81034776', N'Cobertura de Proteção Painel', NULL, N'Others/Outros', N'Antes painel ficava exposto podendo e gerando infiltração, acumulando água internamente, gerando falhas no equipamento. ', N'Melhorar segurança e vida util dos nossos ativos', N'10329', N'01 - Imagens/01 - Antes/9335.jpeg', N'material projetado sobre painel sem proteção, ocasionando acúmulo e possibilidade de infiltração.', N'01 - Imagens/02 - Depois/9335.jpeg', N'Com melhoria realizada, material projetado já não se alojará, sobre o painel e a possibilidade de infiltração diminui consideravelmente.', NULL, N'O problema foi resolvido, temos uma condição agora de painel protegido.', N'No decorrer das atividades conseguimos enxergar e atuar para melhoria de nossos processos e proteção de nossos ativos.', 0, NULL, N'Com a ação 
INSERT INTO #PVC VALUES (9336, N'81057902', N'81057902', N'Kiln troubleshooting', NULL, N'Refining/Refino', N'not being able to inspect kiln internals in 24hrs', N'inspect kiln with limited down time ', N'0', N'01 - Imagens/01 - Antes/9336.jpeg', N'to inspect the kiln internal shell it requires 3-4 days to dismantle outer shell and inspect.', N'01 - Imagens/02 - Depois/9336.jpeg', N'by removing only half of the outer shell and inspect the internal shell by rotating it by hand we are able to inspect in half the time.', NULL, N'yes. this is proven to work ', N'optimize ', 0, NULL, N'To reduce the workload and inaccuracies in reporting on the business', '2026-04-08T00:00:00.000', '2026-04-13T09:00:23.000', N'81057902', NULL, NULL);
INSERT INTO #PVC VALUES (9337, N'544566', N'544566', N'Relocação da sirene do transportador TR-2101SA-01 ', NULL, N'Others/Outros', N'Situação oferecia risco de queda altura de 1,8 metros', N'Eliminar risco de queda altura 1,8 metros', N'0', N'01 - Imagens/01 - Antes/9337.jpeg', N'Sirene de partida do transportador TR-2101SA-01 se encontrava em local de difícil acesso . A mesma estava instalada a uma altura acima de 1,8 metros oferecendo risco de queda de nível diferente. ', N'01 - Imagens/02 - Depois/9337.jpeg', N'Foi instalado um poste articulado para fixar a sirene de modo a facilitar a manutenção e principalmente redução de cenário de risco de trabalho em altura. Sirene hoje instalado na escada de acesso ao transportador.
INSERT INTO #PVC VALUES (9338, N'544566', N'544566', N'Adequação de proteção do LIT BR2104SA-02', NULL, N'Others/Outros', N'O instrumento estava sem proteção adequada, sofrendo projeção de material e danificando o mesmo. ', N'Eliminar projeção de material no instrumento', N'0', N'01 - Imagens/01 - Antes/9338.jpeg', N'O instrumento estava sem proteção, dentro do raio de projeção de material, podendo ocasionar falhas e vindo danificar o mesmo.', N'01 - Imagens/02 - Depois/9338.jpeg', N'Foi realizado suporte e aplicado ao instrumento, trazendo segurança e confiabilidade, eliminando o risco de danificar o instrumento por projeção de material.', NULL, N'Sim, foi eliminado o cenário de risco em que o instrumento se encontrava.', N'Segurança, ', 0, NULL, N'melhoria e adequação das lanternas.', '2026-04-08T00:00:00.000', '2026-04-13T10:45:54.000', N'544566', NULL, NULL);
INSERT INTO #PVC VALUES (9339, N'81033365', N'81033365', N'acesso das mangueiras de acoplamento da prancha', NULL, N'Projects/Projetos', N'ausência de acesso as mangueiras de acoplamento da prancha', N'processo de melhoria', N'10139', N'01 - Imagens/01 - Antes/9339.jpeg', N'FOI IDENTIFICADO QUE NÃO HAVIA UM ACESSO SEGURO PARA REALIZAR ACOPLAGEM/DESACOPLAGEM DAS MANGUEIRAS DA PRANCHA, COM ISSO DIFICULTAVA O DESATRELAMENTO NO MOMENTO DAS MANOBRAS NA MINA.', N'01 - Imagens/02 - Depois/9339.jpeg', N'FOI REALIZADO A FABRICAÇÃO  DE ESCADAS PARA ACESSAR DE FORMA SEGURA NO MOMENTO DE DESACOPLAR/ACOPLAR AS MANGUEIRAS DA PRANCHA, COM ISSO FACILITOU A MANOBRA SEGURA PARA DESATRELAR.', NULL, N'MELHOROU ACESSO DE FORMA SEGURA.', N'MELHORIA CONTINUA', 0, NULL, NULL, '2026-04-12T00:00:00.000', '2026-04-13T10:49:54.000', N'81033365', NULL, NULL);
INSERT INTO #PVC VALUES (9340, N'81033365', N'1005614', N'suporte do calço', NULL, N'Others/Outros', N'local inadequado para o suporte do calço', N'processo de melhoria', N'10139', N'01 - Imagens/01 - Antes/9340.jpeg', N'FOI IDENTIFICADO QUE O SUPORTE DOS CALÇOS ESTAVAM NO LOCAL INADEQUADO ATRAPALHANDO O ACESSO DE PESSOAS PELA ESCADA DO EQUIPAMENTO.', N'01 - Imagens/02 - Depois/9340.jpeg', N'FOI REPOSICIONADO O SUPORTE DOS CALÇOS NO LOCAL ADEQUADO E SEGURO, ELIMINADO A CONDIÇÃO INSEGURA NO MOMENTO DE ACESSAR A ESCADA DO EQUIPAMENTO.', NULL, N'reposição do suporte do calço para local seguro.', N'adequação segura', 0, NULL, N'By labeling handle it also helps to ensure tech doesn''t turn wrong valve .', '2026-04-12T00:00:00.000', '2026-04-13T11:07:06.000', N'81033365', NULL, NULL);
INSERT INTO #PVC VALUES (9341, N'81052635', N'81016620', N'Monitoramento online de temperatura dos cilindros hidráulicos das pá carregadeiras WE1850  PC07 E PC06', NULL, N'Others/Outros', N'Foram instalados sensores de temperatura nos cilindros de elevação lado esquerdo e direito, afim de identificar delta T relacionado a fuga interna dos cilindros durante as operações dos equipamentos. obs: só conseguíamos ver essa condição na inspeção sistemática do equipamento a cada 500 horas.', N'Acompamhar delta t dos cilindros durante as operações afim de antecipar falhas inesperadas.', N'10015', N'01 - Imagens/01 - Antes/9341.jpeg', N'Anteriormente só conseguíamos ver as condições dos cilindros de elevação das WE1850 a cada 500 horas em inspeção sistemática.', N'01 - Imagens/02 - Depois/9341.jpeg', N'Foram instalados sensores de temperatura nos cilindros de elevação lado esquerdo e direito das WE1850, afim de identificar delta T relacionado a fuga interna dos cilindros durante as operações dos equipamentos. ', NULL, N'Avanço em monitoramento continuo para analise de dados e antecipação de falhas.', N'Oportunidade de monitorar os outros pontos .', 0, NULL, NULL, '2026-04-10T00:00:00.000', '2026-04-13T11:14:30.000', N'81052635', NULL, NULL);
INSERT INTO #PVC VALUES (9342, N'200538', N'200538', N'3rd Party Time Confirmation & Financial Accuracy', NULL, N'Projects/Projetos', N'Verification of 3rd Party Contractor hours is a manual process that relies on individually reviewing signed timesheets against executed work and submitted invoices. This approach is time‑consuming, prone to delays, and increases the risk of missed discrepancies or incomplete visibility of signed hours. As a result, confirming billed hours and generating month‑end accruals requires significant manual effort and may reduce the accuracy and timeliness of financial reporting.', N'Provide a centralized, up-to-date view of signed hours linked to executed jobs & provide clear visibility on upcoming charges.', N'10345', N'01 - Imagens/01 - Antes/9342.jpeg', N'Verification of 3rd Party Contractor hours is a manual process that relies on individually reviewing signed timesheets against executed work and submitted invoices. This approach is time‑consuming, prone to delays, and increases the risk of missed discrepancies or incomplete visibility of signed hours. As a result, confirming billed hours and generating month‑end accruals requires significant manual effort and may reduce the accuracy and timeliness of financial reporting.', N'01 - Imagens/02 - Depois/9342.jpeg', N'An Excel‑based query has been developed to automatically pull signed timesheets from a shared folder and populate them into a structured Excel table. This solution improves visibility of signed hours tied to executed jobs, and provides a standardized, automated tracking process to efficiently validate invoices and produce accurate month-end accruals.', NULL, N'System has been developed and tested. Reduction in time spent verifying hours and preparing accruals (~30hrs per month), Decrease in invoice discrepancies related to labour hours, Improved timeliness of month‑end close activities.', N'Improved accuracy and confidence in invoice verification. More reliable month‑end accruals based on signed hours, Reduced administrative effort and cycle time, Increased transparency and auditability of labour hour tracking.', 0, NULL, N'Garantir que todos os envolvidos na operação e manutenção tenham acesso rápido, confiável e em tempo real ao status dos equipamentos, apoiando decisões mais ágeis e eficientes.', '2026-04-10T00:00:00.000', '2026-04-13T11:32:18.000', N'200538', NULL, NULL);
INSERT INTO #PVC VALUES (9343, N'81052635', N'81016620', N'Monitoramento de vibração dos mancais da base do gerador das WE1850.', NULL, N'Others/Outros', N'Foram instalados sensores de vibração online nas bases dos geradores com possibilidade de acompanhar a vibração online de cada base de fixação independente usando comparação para identificar folga de fixação e borracha de amortecimento WE1850 PC06 E PC07.
INSERT INTO #PVC VALUES (9344, N'81033365', N'1005614', N'Suporte das mangueiras hidráulicas/cabos elétricos/sistema pneumático', NULL, N'Projects/Projetos', N'ausência de local adequado.', N'processo de melhoria', N'10139', N'01 - Imagens/01 - Antes/9344.jpeg', N'FOI IDENTIFICADO QUE AS MANGUEIRAS HIDRÁULICAS/PNEUMÁTICAS/CABOS ELÉTRICOS FICAVAM ARMAZENADOS NO PISO DO EQUIPAMENTO DE FORMA INADEQUADO PODENDO CAUSAR ACIDENTE NA MANOBRA DE ATRELAMENTO.', N'01 - Imagens/02 - Depois/9344.jpeg', N'FOI REALIZADO UM SUPORTE PARA ARMAZENAR AS MAGUEIRAS/CABOS DE FORMA SEGURA E ELIMINANDO A CONDIÇÃO INSEGURA NO MOMENTO DA MANOBRA.', NULL, N'ADEQUAÇÃO PARA MELHORA DO PROCESSO.', N'ADEQUAR E ELIMINAR CONDIÇÃO INSEGURA', 0, NULL, N'Garantir que o Painel de Performance de Frota esteja sempre atualizado, confiável e disponível para a engenharia e operação, sem dependência de atividades manuais.', '2026-04-12T00:00:00.000', '2026-04-13T12:02:45.000', N'81033365', NULL, NULL);
INSERT INTO #PVC VALUES (9345, N'492707', N'492707', N'Implantação de QR Code para Acesso Rápido ao Inventário do Container', NULL, N'Others/Outros', N'Atualmente, o inventário do container é disponibilizado apenas em formato físico ou em arquivos não acessíveis diretamente no local de uso, o que dificulta a consulta rápida dos materiais disponíveis. Essa situação gera perda de tempo na verificação do inventário, risco de informações desatualizadas, retrabalho durante inspeções e dificuldades em auditorias e atividades operacionais do dia a dia.', N'Otimização da Consulta ao Inventário do Container', N'10139', N'01 - Imagens/01 - Antes/9345.jpeg', N'Para ter acesso ao inventário, era necessário consultar a planilha exclusivamente no computador, o que dificultava o acesso rápido às informações no local de uso', N'01 - Imagens/02 - Depois/9345.jpeg', N'Após a implantação do QR Code na porta do container, o inventário passou a estar disponível de forma rápida, prática e padronizada, permitindo que qualquer colaborador acesse as informações diretamente pelo celular, sem necessidade de computador.
INSERT INTO #PVC VALUES (9346, N'81052635', N'81016620', N'Atalho na plataforma Dynapredict para análise de vibração dos pontos de monitoramento escavação e carregamento.', NULL, N'Others/Outros', N'Foi criado um atalho para encontrar de fácil acesso os pontos para analise de vibração e temperatura dos pontos de monitoramento escavação e carregamento na plataforma Dynapredcit.
INSERT INTO #PVC VALUES (9347, N'81033365', N'81048572', N'proteção da tomada de 220v', NULL, N'Others/Outros', N'acumulo de água da chuva dentro da tomada 220v', N'processo de melhoria', N'10139', N'01 - Imagens/01 - Antes/9347.jpeg', N'Foi identificado acúmulo de água dentro de uma tomada 220V durante chuvas onde trazia uma situação de alto risco choques elétricos fatais, incêndios e danos severos à instalação elétrica.', N'01 - Imagens/02 - Depois/9347.jpeg', N'Foi fabricado uma cobertura de ação imediata para evitar choques elétricos fatais, incêndios e danos severos à instalação elétrica.', NULL, N'adequação de cobertura para evitar danos.', N'melhoria continua', 0, NULL, N'Great team work makes a positive work place ', '2026-04-11T00:00:00.000', '2026-04-13T13:13:27.000', N'81033365', NULL, NULL);
