INSERT INTO #PVC VALUES (9482, N'81058516', N'81058516', N'PLANILHA DE ATIVIDADES MAPEADAS - BENTLEY', NULL, N'Projects/Projetos', N'No desenvolvimento de instalação do HardWare do sistema Bentley pela Testato na EC-03 foram identificadas lições aprendidas, devido o atraso de entrega do hardware fora do prazo da grande parada. ', N'Aderencia a curva S da grande parada .', N'10015', N'01 - Imagens/01 - Antes/9482.jpeg', N'Antes não existia a planilha e as instalações eram por oportunidades.
