INSERT INTO #PVC VALUES (9484, N'1010294', N'1010294', N'Improvement to Labelling of ICP-MS sample location', NULL, N'Others/Outros', N'Previous labeling was hard to read and cumbersome to file samples.  Sample trays always shifting to impede reading of labels.', N'Visual aid for the storage of samples', N'10352', N'01 - Imagens/01 - Antes/9484.jpeg', N'Previous labels were on the shelf top and the trays would shift and cover up the labels, making it hard to read and know where to place the sample.', N'01 - Imagens/02 - Depois/9484.jpeg', N'New labels allow clear visual aid from a distance and quick reference for placing samples.', NULL, N'Yes, results in quicker storage and more accurate placement.', N'signage for storage makes process faster and less room for error', 0, NULL, N'Garantir maior previsibilidade dos gastos com reformas de componentes, apoiando a tomada de decisão gerencial e a priorização das atividades ao longo do ano', '2026-04-20T00:00:00.000', '2026-04-21T16:22:17.000', N'1010294', NULL, NULL);
INSERT INTO #PVC VALUES (9485, N'1010294', N'1010294', N'Posting Kaizan QR Code', NULL, N'Others/Outros', N'Looking for link or QR code when wanting to enter a Kaizen.', N'Easy access to Kaizen entry', N'10352', N'01 - Imagens/01 - Antes/9485.jpeg', N'QR Code was not posted. Made finding the link difficult.', N'01 - Imagens/02 - Depois/9485.jpeg', N'QR Code posted on FMDS board for easy access for all employees to enter Kaizens.', NULL, N'Yes - Kaizen entry is easily accessible for all lab personnel.', N'More inclined to enter Kaizens with quick access to ValeForms.', 0, NULL, NULL, '2026-04-20T00:00:00.000', '2026-04-21T17:00:54.000', N'1010294', NULL, NULL);
