INSERT INTO #PVC VALUES (9487, N'81061537', N'81061537', N'Coletor Manual para Amostras', NULL, N'Others/Outros', N'Coletor muito pesado e posição ergonômicas desconfortável  ao pegar o coletor antigo.', N'Mais precisão, menos esforço e zero desperdício.', N'10054', N'01 - Imagens/01 - Antes/9487.jpeg', N'Na imagem, observa-se uma postura com o braço elevado acima da linha dos ombros e o tronco levemente inclinado, o que caracteriza uma situação de risco ergonômico. Esse tipo de posicionamento, quando frequente, pode causar fadiga muscular, desconforto e até lesões ao longo do tempo, especialmente em regiões como ombros, coluna e pescoço.
INSERT INTO #PVC VALUES (9488, N'81050579', N'81013615', N'ILUMINAÇÃO TRASEIRA DA ES2101 ', NULL, N'Others/Outros', N' equipamento não tinha iluminação traseira, dificultando a visibilidade do operador.', N'MELHORAR A VISIBILIDADE DO OPERADOR ', N'10327', N'01 - Imagens/01 - Antes/9488.jpeg', N'equipamento não tinha iluminação traseira, dificultando a visibilidade do operador.', N'01 - Imagens/02 - Depois/9488.jpeg', N'Foi montado um refletor traseiro para melhor visibilidade na operação com mais segurança.', NULL, N'SIM. Foi montado um refletor traseiro para melhor visibilidade na operação com mais segurança.', N'BOA VISIBILIDADE EM LOCOMOÇÕES EM RÉ, EVITANDO ASSIM RISCO DE BATIDAS CONTRA POR FALTA DE ILUMINAÇÃO ADEQUADA ', 0, NULL, N'Solução: Substituído o tambor por mangueira, evitando a vibração e quebra', '2026-04-11T00:00:00.000', '2026-04-21T20:23:05.000', N'81050579', NULL, NULL);
