INSERT INTO #PVC VALUES (9491, N'123307', N'81043245', N'Acesso Restrito', NULL, N'Others/Outros', N'Área de transição de operadores da ponte rolante, sem isolamento.', N'Eliminar fluxo indevido de pessoas na área do operador de ponte rolante.', N'10054', N'01 - Imagens/01 - Antes/9491.jpeg', N'Área de transição de operadores da ponte rolante, sem isolamento.', N'01 - Imagens/02 - Depois/9491.jpeg', N'Foi instalado portão de acesso restrito para proteger entradas indevidas e fluxos de pessoas durante operação da ponte rolante.', NULL, N'Sim, realizado isolamento de área restrita.', N'VER E AGIR', 0, NULL, N'De 180 dias para 5 dias', '2026-04-21T00:00:00.000', '2026-04-22T03:02:51.000', N'123307', NULL, NULL);
INSERT INTO #PVC VALUES (9492, N'123307', N'81043245', N'Proteção Placa de Estacionamento', NULL, N'Others/Outros', N'Na área da filtragem, no estacionamento tem uma placa proibido estacionar com partes cortantes com risco de batidas contra.', N'Eliminar risco de batidas com cortes.', N'10054', N'01 - Imagens/01 - Antes/9492.jpeg', N'Na área da filtragem, no estacionamento tem uma placa proibido estacionar com partes cortantes com risco de batidas contra.', N'01 - Imagens/02 - Depois/9492.jpeg', N'Instalação de uma proteção de borracha em torno placa, eliminando a condição de batidas com risco de cortes.', NULL, N'Sim, instalado uma proteção de borracha em torno da placa e eliminado a condição de cortes caso aja batidas.', N'VER e AGIR', 0, NULL, N'Havia recorrência de não devolução das chaves das caminhonetes e, em alguns casos, não era possível identificar para quem a chave havia sido entregue, gerando desorganização, atrasos operacionais e risco de uso indevido dos veículos.', '2026-04-03T00:00:00.000', '2026-04-22T03:32:30.000', N'123307', NULL, NULL);
INSERT INTO #PVC VALUES (9493, N'123307', N'81043245', N'CCB FILTRAGEM MATRIZ DE BLOQUEIO', NULL, N'Others/Outros', N'Inexistência matriz de bloqueio impressa para consultar equipamentos e periféricos para bloqueio.', N'Eliminar riscos de erros na etapa de bloqueio dos equipamentos', N'10054', N'01 - Imagens/01 - Antes/9493.jpeg', N'Inexistência matriz de bloqueio (no CCB da filtragem) impressa para consultar equipamentos e periféricos para bloquear em uma determinada atividade.', N'01 - Imagens/02 - Depois/9493.jpeg', N'Foi realizado impressão, plastificação e instalação de uma pasta na parede do CCB de fácil acesso para uso de consultas sobre quais equipamentos bloquear para uma determinada atividade.', NULL, N'Sim, material de consulta elimina possível risco de erros em bloquear determinado equipamento.', N'VER E AGIR', 0, NULL, N'Eliminar risco de choque eletrico e danos no equipamento', '2026-04-20T00:00:00.000', '2026-04-22T03:49:59.000', N'123307', NULL, NULL);
INSERT INTO #PVC VALUES (9494, N'1008636', N'1008636', N'02 Cylinder Dust Caps', NULL, N'No Replication/Sem replicação', N'Receiving 02 cylinders from the warehouse sometimes come with missing dust caps from vendor.  Storage area has high potential for dust which would lodge inside the outlet creating a high potential for contamination. ', N'Prevent dust build up on 02 cylinder outlet', N'10113', N'01 - Imagens/01 - Antes/9494.jpeg', N'Dust would accumulate in/on the outlet', N'01 - Imagens/02 - Depois/9494.jpeg', N'Developed and 3D printed caps to prevent dust build up in/on the outlet', NULL, N'Yes, developed and 3D printed a dust cap that will be used if needed to prevent any future issues with dust getting into the outlet.', N'Attention to detail', 0, NULL, N'Waiting time was reduced.', '2026-04-21T00:00:00.000', '2026-04-22T08:01:48.000', N'1008636', NULL, NULL);
INSERT INTO #PVC VALUES (9495, N'81045248', N'81036736', N'storage cabinet for tools', NULL, N'No Replication/Sem replicação', N'carrying heavy tools up to the tripper level of the 211 storage building for cleaning in the offload circuit can be exhausting before even attempting to carry out any work 
INSERT INTO #PVC VALUES (9496, N'81060533', N'81060533', N'ORGANIZADORES DE SACOS PLÁSTICOS', NULL, N'Others/Outros', N'As sacolas plásticas não tinham um local visual e organizado para ficar a disposição dos colaboradores no refeitório de campo.', N'organizar de forma adequada as sacolas utilizadas na operação', N'10361', N'01 - Imagens/01 - Antes/9496.jpeg', N'O refeitório de campo não possuía um organizador que facilitava a organização das sacolas plásticas para a utilização da operação.', N'01 - Imagens/02 - Depois/9496.jpeg', N'- O suporte proporciona praticidade, resistência e baixo custo de manutenção.
INSERT INTO #PVC VALUES (9497, N'498307', N'498307', N'PAINEL DE PROJEÇÃO USINA', NULL, N'Others/Outros', N'Ausência de controle da projeção anual, mensal e semanal das reformas de componentes da Usina, resultando em uma falta de previsibilidade financeira, dificultando a tomada de decisão gerencial.', N'CONTROLAR E ACOMPANHAR A ADERÊNCIA DAS EXECUÇÕES AO PROJETADO DOS GASTOS COM REFORMAS DE COMPONENTES DA USINA', N'10230', N'01 - Imagens/01 - Antes/9497.jpeg', N'Ausência de um processo estruturado, padronizado e integrado de planejamento e acompanhamento das reformas de componentes, com definição clara de responsáveis, premissas, critérios de projeção e rotinas de atualização mensal, semanal e anual, resultando em falta de previsibilidade financeira e baixa confiabilidade das informações para suporte à tomada de decisão gerencial.', N'01 - Imagens/02 - Depois/9497.jpeg', N'Foi realizada a melhoria do processo e implantado o controle estruturado de projeção das reformas de componentes, com acompanhamento anual, mensal e semanal, fortalecendo a previsibilidade financeira e o suporte à tomada de decisão gerencial.', NULL, N'Sim. Processo implantado na rotina dando maior previsibilidade financeira e auxiliando as tomadas de decisões. ', N'Padronização das premissas; Rituais periódicos de acompanhamento; Visibilidade antecipada', 0, NULL, N'Com Essa melhoria tivemos uma redução e atenção significativa de batidas, movimentações de materiais, uma operação mais segura e uma equipe mais atenta aos riscos.', '2026-04-10T00:00:00.000', '2026-04-22T10:37:01.000', N'498307', NULL, NULL);
INSERT INTO #PVC VALUES (9498, N'81015749', N'81015749', N'Revisão de Item em Plano de Manutenção - Aplicação de Filtros - Tratores de Pneus ', NULL, N'Open Pit/Poço aberto', N'Material adicionado no plano de manutenção sob PN que englobava cabeçote do filtro de óleo também para substituição, não se fazendo necessário a substituição, pois é necessário a troca somente da carcaça do filtro. ', N'Reduzir o custo de manutenção preventiva ajustando materiais aplicados nas atividades programadas. ', N'10015', N'01 - Imagens/01 - Antes/9498.jpeg', N'Filtros inclusos na lista de tarefa contemplando carcaça + cabeçote (PN 1664647) – 2 unidades nos planos dos TU24 e TU25 e 1 unidade no plano do TU23;
INSERT INTO #PVC VALUES (9499, N'81044674', N'544451', N'Substituição de Carretéis e Curvas por Revestimento Cerâmico – CF-2017-19', NULL, N'No Replication/Sem replicação', N'Os carretéis e curvas antigos, fabricados em PU, apresentavam baixa resistência mecânica, sendo frágeis e altamente suscetíveis a desgastes e quebras. Essa condição ocasionava vazamentos frequentes no sistema, impactando diretamente a eficiência operacional e gerando riscos à segurança.
INSERT INTO #PVC VALUES (9500, N'553135', N'81060557', N'CONTENÇÃO PARA TOTBIN', NULL, N'Others/Outros', N'PRODUTOS QUIMICOS DE LIMPEZA EM GERAL FICAM ARMAZENADOS EM TOTBIN''S, ELE NÃO POSSUIAM CONTENÇÃO O QUE PODIA LEVAR A CONTAMINAÇÃO DO SOLO', N'CONTENÇÃO DE DERRAMAMENTO DE PRODUTO QUIMICO', N'10139', N'01 - Imagens/01 - Antes/9500.jpeg', N'PRODUTOS QUIMICOS DE LIMPEZA EM GERAL FICAM ARMAZENADOS EM TOTBIN''S, ELE NÃO POSSUIAM CONTENÇÃO O QUE PODIA LEVAR A CONTAMINAÇÃO DO SOLO', N'01 - Imagens/02 - Depois/9500.jpeg', N'FOI CONFECCIONADA UMA CONTENÇÃO COM MATERIAIS DE REUSO DEIXANDO MAIS SEGURO DE USAR, ELIMINANDO O RISCO VAZAMENTO E CONTAMINAÇÃO DO SOLO', NULL, N'PRODUTOS QUIMICOS DE LIMPEZA EM GERAL FICAM ARMAZENADOS EM TOTBIN''S, ELE NÃO POSSUIAM CONTENÇÃO O QUE PODIA LEVAR A CONTAMINAÇÃO DO SOLO', N'SOLUÇÕES SIMPLES E BARATAS ', 0, NULL, N'Ambiente organizado, seguro e padronizado, com redução de tempo improdutivo e aumento da vida útil das ferramentas.
INSERT INTO #PVC VALUES (9501, N'553135', N'516988', N'Melhoria no bocal de enchimento do tanque diesel da MA85 ', NULL, N'Others/Outros', N'Problema: Bocal apresentando vazamento constante de combustível por conta da vibração', N'EVITAR VIBRAÇÃO', N'10139', N'01 - Imagens/01 - Antes/9501.jpeg', N'Problema: Bocal apresentando vazamento constante de combustível por conta da vibração', N'01 - Imagens/02 - Depois/9501.jpeg', N'Solução: Substituído o tambor por mangueira, evitando a vibração e quebra', NULL, N'Problema: Bocal apresentando vazamento constante de combustível por conta da vibração', N'VERIFICAÇÕES E AJUSTES SÃO SEMPRE NECESSÁRIOS', 0, NULL, N'Redução significativa dos riscos à saúde e segurança dos colaboradores, com a eliminação do trabalho em altura, diminuição da exposição a riscos elétricos e melhoria das condições de acesso para operação e manutenção do painel elétrico do pórtico.', '2026-04-21T00:00:00.000', '2026-04-22T14:23:00.000', N'553135', NULL, NULL);
INSERT INTO #PVC VALUES (9502, N'935171', N'935171', N'LOGISTICA SEGURA ', NULL, N'Others/Outros', N'Esteira sem suporte com risco de  queda e movimentação no momento da coleta ', N'Reduzir o risco na logística ', N'10230', N'01 - Imagens/01 - Antes/9502.jpeg', N'Esteira sem suporte, era coletado com grande dificuldade com a empilhadeira, Sem um suporte estrutural adequado, a esteira pode ceder ou se deslocar inesperadamente.', N'01 - Imagens/02 - Depois/9502.jpeg', N'Feito um suporte padrão com as medidas do garfo da empilhadeira para o carregamento seguro da esteira.', NULL, N'Inicialmente, na área de Salobo, a esteira do trator D11 era carregada sem a utilização de um suporte padrão, o que gerava riscos elevados durante a movimentação, com possibilidade de instabilidade e queda da carga, além de expor os trabalhadores a situações inseguras.', N'USAR AS  FERRAMENTAS DA EMPRENSA ', 0, NULL, N'Atualização do inventário em tempo real, de acordo com as entradas e saídas de materiais.', '2026-04-21T00:00:00.000', '2026-04-22T15:44:19.000', N'935171', NULL, NULL);
INSERT INTO #PVC VALUES (9503, N'81035680', N'81047881', N'MELHORIA DA PASSAGEM DE CABOS NA CASA DE MÁQUINAS DA EC17', NULL, N'Projects/Projetos', N'Devido o alto número de corretivas por causa da queima de cabos devido os tubos de exaustão estarem próximos, foi feito esse projeto
INSERT INTO #PVC VALUES (9504, N'493280', N'493280', N'Redução do Lead Time do Acionamento da Comporta do Filtro Prensa VPA1540-54', NULL, N'Others/Outros', N'Material da comporta atualmente é adquirido através de importação, e com grande lead time de entrega.', N'Redução de lead time e custo em 50%', N'10081', N'01 - Imagens/01 - Antes/9504.jpeg', N'Acionamento da comporta do filtro prensa, modelo VPA1540-54, atualmente é adquirido através de importação, e com grande lead time de entrega.
INSERT INTO #PVC VALUES (9505, N'81035706', N'81035706', N'CONTROLE DAS CHAVES DE CAMINHONETE', NULL, N'Others/Outros', N'Havia recorrência de não devolução das chaves das caminhonetes e, em alguns casos, não era possível identificar para quem a chave havia sido entregue, gerando desorganização, atrasos operacionais e risco de uso indevido dos veículos.', N'Melhoria no controle e responsabilidade pelo uso das caminhonetes', N'10139', N'01 - Imagens/01 - Antes/9505.jpeg', N'Havia recorrência de não devolução das chaves das caminhonetes e, em alguns casos, não era possível identificar para quem a chave havia sido entregue, gerando desorganização, atrasos operacionais e risco de uso indevido dos veículos.', N'01 - Imagens/02 - Depois/9505.jpeg', N'A ação implementada contribui significativamente para o atendimento aos requisitos de controle operacional, segurança patrimonial e conformidade, promovendo maior confiabilidade no gerenciamento das caminhonetes.', NULL, N'Havia recorrência de não devolução das chaves das caminhonetes e, em alguns casos, não era possível identificar para quem a chave havia sido entregue, gerando desorganização, atrasos operacionais e risco de uso indevido dos veículos.', N'Garantia de rastreabilidade dos veículos; Fortalecimento do controle interno;', 0, NULL, N'Consumo de óleo.', '2026-04-21T00:00:00.000', '2026-04-22T16:38:46.000', N'81035706', NULL, NULL);
INSERT INTO #PVC VALUES (9506, N'81049566', N'524849', N'Plataforma Arcondicionado', NULL, N'Crusher/Britadeira', N'Ar Condicionado operando em contato direto no chao, com riscos de choque eletrico ou dano no equipamento.', N'eliminar contato do ar condicionado com o chao', N'10362', N'01 - Imagens/01 - Antes/9506.jpeg', N'Central do Ar condicionado em contato direto com o chão, com risco de choque elétrico. ', N'01 - Imagens/02 - Depois/9506.jpeg', N'Fabricado bancada para Eliminar contato do ar condicionado direto com o solo .', NULL, N'Eliminado risco de choque elétrico e danos no ar condicionado devido contato direto com o chão .', N'eliminado risco de choque eletrico ', 0, NULL, N'To kickstart and provide a complete compilation of reference materials and hand samples of rock types of Voisey''s Bay. A Spreadsheet has been created consisting of the rock types with explanations pertinent to each sample.', '2026-04-21T00:00:00.000', '2026-04-22T18:56:37.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (9507, N'87000312', N'87000373', N'To relocate check valve at the outlet of the No2 collection pump.', NULL, N'Refining/Refino', N'Defect', N'To prevent leaking weak acid in the piping of the outlet of the No2 collection pump in case of power failure. ', N'0', N'01 - Imagens/01 - Antes/9507.jpeg', N'A minimum flow piping (towards No. 1CL-T) is located downstream of the No. 2CL-T pump outlet check valve. When the No. 2CL-T pump stops due to a power outage or other reasons, liquid flows back from the 7F tank into the minimum flow piping, causing the 7F tank level to drop. If the 7F tank is emptied, it will take more than 30 minutes to pump the liquid back to the normal level, during which time the temperature of the CV catalyst layer will drop, and it may not be possible to immediately resume operation.', N'01 - Imagens/02 - Depois/9507.jpeg', N'This prevents leakage weak acid in the piping. 7F tank level when the No. 2CL-T pump stops due to a power outage, etc., eliminating time loss when resuming operations.', NULL, N'Yes, we could achieve the target as we thought.', N'Asset ', 0, NULL, NULL, '2026-04-22T00:00:00.000', '2026-04-23T06:27:40.000', N'87000312', NULL, NULL);
INSERT INTO #PVC VALUES (9508, N'81009995', N'81009995', N'Spent Acid Sign', NULL, N'Others/Outros', N'No spent acid sign add the unloading of sulfuric acid at mandrel prep', N'Add Sign to spent acid bucket', N'10255', N'01 - Imagens/01 - Antes/9508.jpeg', N'No sign on the spent acid bucket', N'01 - Imagens/02 - Depois/9508.jpeg', N'ADd sign to new bucket', NULL, N'Added sign for awareness', N'Buckets being replaced need to be a direct replica of old bucket', 0, NULL, N'Objetivo do Kaizen é que com essa modificação, o sistema seja previamente pressurizado antes da partida, evitando a entrada de ar na linha e proporcionando uma partida mais suave, além de reduzir esforços no sistema de alimentação e aumentar a confiabilidade operacional.
INSERT INTO #PVC VALUES (9509, N'81042207', N'81054975', N'Implantação de Degrau Móvel para Melhoria da Acessibilidade e Segurança no Acesso à Escavadeira Hidráulica', NULL, N'Others/Outros', N'Durante inspeção no galpão de descarga, foi identificado que existe um batente elevado que dá acesso à escada para a escavadeira hidráulica. Devido à baixa estatura da maioria dos colaboradores, foi constatada dificuldade para subir nesse batente, gerando esforço adicional, desconforto e potencial risco de queda ou acidente.
INSERT INTO #PVC VALUES (9510, N'92000588', N'92000588', N'Alarme Sonoro Contra Colisão ( Empilhadeira)', NULL, N'Others/Outros', N'Antes das instalações das sirenes tivemos eventos na operação de colisão entre as ferragens das tendas, tendo o risco de desabamento.', N'Eliminar o Risco de batidas, evitando a Colisão entre As tendas e a torre da empilhadeira.', N'10079', N'01 - Imagens/01 - Antes/9510.jpeg', N'Antes das instalações das sirenes tivemos eventos na operação de colisão entre as ferragens das tendas, tendo o risco de desabamento.', N'01 - Imagens/02 - Depois/9510.jpeg', N'Após a instalação das sirenes tivemos esse meio de alerta rapidamente mediante as movimentações evitando riscos de colisão, reduzindo danos materiais e aumento da segurança da operação.', NULL, N'Antes: Riscos de batidas nas tendas por falta de sinalizações, gerando danos, custos e insegurança.
INSERT INTO #PVC VALUES (9511, N'553135', N'521213', N'CONTROLE DE ESTEIRAS ', NULL, N'Others/Outros', N'ANTES A EQUIPE NÃO POSSUIA NENHUMA FERRAMENTA DE CONTROLE QUE PUDESSEMOS ACOMPANHAR  AS ESTEIRAS DE FORMA EFICAZ. NÃO TINHAMOS A QUANTIDADES CORRETA/PADRÃO DE HORAS PARA TROCA DE ESTEIRAS E NÃO POSSUIA PADRAO DE FORNCEDOR LEVANDO MUITAS VEZES A A PERDER ESTEIRAS.  ', N'EXCELENCIA NO MONITORAMENTO', N'10139', N'01 - Imagens/01 - Antes/9511.jpeg', N'ANTES A EQUIPE NÃO POSSUIA NENHUMA FERRAMENTA DE CONTROLE QUE PUDESSEMOS ACOMPANHAR  AS ESTEIRAS DE FORMA EFICAZ. NÃO TINHAMOS A QUANTIDADES CORRETA/PADRÃO DE HORAS PARA TROCA DE ESTEIRAS E NÃO POSSUIA PADRAO DE FORNCEDOR LEVANDO MUITAS VEZES A A PERDER ESTEIRAS.  ', N'01 - Imagens/02 - Depois/9511.jpeg', N'FOI CRIADO UMA PLANILHA DE ACOMPANHAMENTO, ONDE É POSSÍVEL MONITORAR TODOS OS EQUIPAMENTOS DE ESTEIRA, FORNECEDOR, DATA DE INSTALAÇÃO PERFORMANCE ATUAL EM HORAS. LEVANDO A UM TRABALHO DE EXCELENCIA, EVITANDO CUSTOS E RETRABALHO.', NULL, N'FOI CRIADO UMA PLANILHA DE ACOMPANHAMENTO, ONDE É POSSÍVEL MONITORAR TODOS OS EQUIPAMENTOS DE ESTEIRA, FORNECEDOR, DATA DE INSTALAÇÃO PERFORMANCE ATUAL EM HORAS. LEVANDO A UM TRABALHO DE EXCELENCIA, EVITANDO CUSTOS E RETRABALHO.', N'PRECISAMOS CONTROLAR E MONITORAR', 0, NULL, N'Melhoria da organização visual do posto de trabalho. Redução de riscos relacionados à proliferação de fungos e bactérias. Aumento da vida útil do EPI de couro. Melhoria das condições de higiene e conforto do colaborador. Contribuição para o fortalecimento da cultura de organização e segurança.', '2026-04-22T00:00:00.000', '2026-04-23T11:26:16.000', N'553135', NULL, NULL);
INSERT INTO #PVC VALUES (9512, N'460605', N'460605', N'Reagent Cost Savings for Neutralization ', NULL, N'Refining/Refino', N'Flocculant reagents used within the Neutralization process costs between $5.49 - 5.91 per kg. As part of the Metlab routines, reagent testing is commonly performed to identify opportunities of process optimization. As part of this program we were able to receive a total of 200kg of free product, which can now be used within the process. ', N'To find opportunities to reduce cost ', N'0', N'01 - Imagens/01 - Antes/9512.jpeg', N'Flocculant reagents used within the Neutralization process costs between $5.49 - 5.91 per kg. As part of the Metlab routines, reagent testing is commonly performed to identify opportunities of process optimization. Typically, this is done with low volume ( >10g) test reagents. ', N'01 - Imagens/02 - Depois/9512.jpeg', N'After discussions with our current floc provider, we were able to receive a 200Kg of floc for field level evaluation at no cost. Allowing us to utilize a small portion for process evaluations and the remainder will be consumed within the operations. ', NULL, N' We were able to achieve a reagent cost savings of $1,254. ', N' Look for opportunities where large volume of samples can be provided for free or at a reduced cost. ', 1254, 3, N'Adequate ventilation at 3935L Crusher', '2026-04-17T00:00:00.000', '2026-04-23T12:11:31.000', N'460605', NULL, NULL);
INSERT INTO #PVC VALUES (9513, N'81035621', N'81003289', N'SUPORTE PARA LIXADEIRA', NULL, N'Others/Outros', N'Atualmente, as lixadeiras ficam armazenadas de forma inadequada, espalhadas pelo chão ou bancadas, com cabos enrolados e sem padronização.
INSERT INTO #PVC VALUES (9514, N'81057208', N'81057208', N'Realocação do Painel Elétrico do Pórtico GD-2312-SA-01', NULL, N'Others/Outros', N'O painel elétrico do pórtico encontra-se atualmente instalado em local inadequado, com acesso restrito e exposição a riscos operacionais. Essa condição dificulta as atividades de manutenção preventiva e corretiva, aumenta o risco de acidentes elétricos para os colaboradores e não atende plenamente aos requisitos de segurança estabelecidos pela NR‑10. Além disso, a localização atual compromete a agilidade no atendimento a falhas e pode impactar diretamente a disponibilidade e a confiabilidade do equipamento.', N'Realocar o painel elétrico do pórtico GD-2312-SA-01, para um local seguro.', N'10178', N'01 - Imagens/01 - Antes/9514.jpeg', N'O painel elétrico do pórtico estava instalado em um local de difícil acesso, o que dificultava a operação e as atividades de manutenção. Para realizar qualquer intervenção, os colaboradores tinham pouco espaço para trabalhar, aumentando o risco de acidentes.
INSERT INTO #PVC VALUES (9515, N'81045351', N'81045351', N'Quadro de gestão de uniformes e epis', NULL, N'Others/Outros', N'Atualmente utilizamos um quadro de Gestão de Estoque através de planilha, que apresenta o controle dos EPIs e uniformes disponíveis, com espaço para saldo e observações. Apesar de ser um material de controle, ainda há dificuldades na atualização frequente das informações e na agilidade para tomada de decisão sobre reposições ou entregas, especialmente quando há alta demanda.', N'Acompanhamento de EPIs e Uniformes, o controle dos EPIs e uniformes disponíveis, com espaço para saldo e observações.', N'10017', N'01 - Imagens/01 - Antes/9515.jpeg', N'Controle de estoque através de planilha.', N'01 - Imagens/02 - Depois/9515.jpeg', N'- Aumento da agilidade na gestão de EPIs e uniformes;
INSERT INTO #PVC VALUES (9516, N'81045351', N'81045351', N'PROGRAMA DE APADRINHAMENTO', NULL, N'Others/Outros', N'Essa iniciativa foi criada com base na necessidade de promover uma integração mais estruturada e acolhedora aos novos colaboradores, por meio do acompanhamento de um padrinho responsável por orientar, apoiar e acompanhar o desenvolvimento durante o período inicial de atividades.', N'Fortalecer o processo de integração e acompanhamento dos colaboradores em treinamento dentro das unidades.', N'10017', N'01 - Imagens/01 - Antes/9516.jpeg', N'Os colaboradores novatos não eram devidamente acompanhados de forma visual nas áreas', N'01 - Imagens/02 - Depois/9516.jpeg', N'Implementar pop de apadrinhamento;
INSERT INTO #PVC VALUES (9517, N'81034722', N'81034722', N'Oportunidades PGU em tempo real', NULL, N'Projects/Projetos', N'Havia uma dificuldade em capturar as oportunidades que tínhamos nas Paradas de Manutenção, a informação era discutida, mas muitas vezes se perdia, e ficávamos com falhas nas lições aprendidas.', N'Garantir informação e estruturar lições aprendidas', N'10081', N'01 - Imagens/01 - Antes/9517.jpeg', N'Havia uma dificuldade em capturar as oportunidades que tínhamos nas Paradas de Manutenção, a informação era discutida, mas muitas vezes se perdia, e ficávamos com falhas nas lições aprendidas.', N'01 - Imagens/02 - Depois/9517.jpeg', N'Criamos um grupo de whatsapp para garantir o registro das informações em tempo real na parada, isso contribuiu para agilidade na informação e garantia de registro do desvio, assim que identificado, o que culminou em finalizar a parada com as lições aprendidas já prontas e registradas.', NULL, N'Finalizamos a parada com os desvios 100% mapeados e com as lições aprendidas prontas.', N'.', 0, NULL, N'resultados e ao aprimorar a atuação preventiva na garantia da qualidade do produto. ', '2026-04-17T00:00:00.000', '2026-04-23T12:56:43.000', N'81034722', NULL, NULL);
INSERT INTO #PVC VALUES (9518, N'81057561', N'480642', N'Alteração na Ligação Elétrica do Compressor Principal', NULL, N'Open Pit/Poço aberto', N'A ligação elétrica permitia que o compressor permanecesse acionado mesmo em modo de locomoção. Isso gerava esforço desnecessário no conjunto motor-compressor, aumentando consumo, desgaste e temperatura.
INSERT INTO #PVC VALUES (9519, N'460594', N'460594', N'Drill Core Library Collection', NULL, N'No Replication/Sem replicação', N'There isn''t a complete compilation of reference materials and hand samples of rock types of Voisey''s Bay.', N'To compile reference materials and hand samples of rock types of Voisey''s Bay.', N'10311', N'01 - Imagens/01 - Antes/9519.jpeg', N'There isn''t a complete compilation of reference materials and hand samples of rock types of Voisey''s Bay.', N'01 - Imagens/02 - Depois/9519.jpeg', N'To kickstart and provide a complete compilation of reference materials and hand samples of rock types of Voisey''s Bay. A Spreadsheet has been created consisting of the rock types with explanations pertinent to each sample.', NULL, N'Yes, the collection has started for the compilation. To be taken from Drill core as the program progresses', N'Hand Samples provided for reference', 0, NULL, N'Foi executada correção estrutural no chassi do implemento, com foco na eliminação dos esforços de torção atuantes e no restabelecimento adequado do sistema de travamento e fixação, em conformidade com as diretrizes e orientações técnicas da Engenharia.', '2026-04-20T00:00:00.000', '2026-04-23T14:51:16.000', N'460594', NULL, NULL);
INSERT INTO #PVC VALUES (9520, N'81038914', N'81038914', N'Eliminação de drenagens indevidas por falta de energia/comunicação na flotação Cleaner – Salobo 3', NULL, N'Open Pit/Poço aberto', N'Em qualquer evento de falta de energia ou perda de comunicação, todas as colunas de flotação Cleaner SLB3 eram automaticamente drenadas.
INSERT INTO #PVC VALUES (9521, N'81057561', N'81057321', N'Acionamento Automático da Bomba de Escova', NULL, N'Open Pit/Poço aberto', N'Antes a manutenção tinha que realizar o acionamento manual da bomba de escova, colocando se no risco de realizar o serviço de forma mais manual.
INSERT INTO #PVC VALUES (9522, N'200959', N'200959', N'Copper Cliff Mine Senior On Call Training & One Note', NULL, N'Underground/Subterrâneo', N'The existing documentation system is disorganized and inefficient. It makes information difficult to locate, update and use effectively and at times lacked the required materials.', N'Provides an easier access to required material during on-call emergency response', N'10238', N'01 - Imagens/01 - Antes/9522.jpeg', N'The previous approach to senior on‑call access for emergency protocols and procedures was unclear and inconsistent. A central binder containing key policies previously existed but had been lost over time. As a result, individuals were required to rely on personal knowledge to locate procedures and dispersed information during emergencies. This approach was disorganized, inefficient, and unreliable, creating unnecessary challenges in quickly retrieving critical documentation when it was most needed.', N'01 - Imagens/02 - Depois/9522.jpeg', N'A Senior On‑Call training presentation was developed along with a centralized OneNote. This OneNote serves as a single source of truth, replacing traditional folders with direct links to online forms and resources hosted on SharePoint. The structured layout and clearly defined categories significantly improve accessibility and reduce the time required to locate critical documents and information during an emergency. Additionally, it enables senior on‑call logs to be captured in one location, enhancing visibility, continuity, and communication regarding on‑site activities.', NULL, N'OneNote allows for on-call information to be accessed more easily. It is also simpler to update files, ensuring the most current and accurate information is always available. ', N'Providing on‑call personnel with fast access to accurate, current information is essential to reducing response times, minimizing risk, and supporting effective decision‑making in emergency situations.', 0, NULL, NULL, '2026-04-01T00:00:00.000', '2026-04-23T15:20:23.000', N'200959', NULL, NULL);
INSERT INTO #PVC VALUES (9523, N'81048517', N'81048517', N'Antecipação do Cronograma De Projeções', NULL, N'Others/Outros', N'Com a antecipação das reuniões mensais de performance do CFO e do COO no calendário global, as RPs dos Diretores passaram a ocorrer em torno do 6º dia útil. Considerando que o fechamento demanda, no mínimo, 3 dias úteis, e que as projeções tinham data de corte até o final do 3º dia útil — sem contemplar ajustes e eventuais atrasos das áreas —, o time passou a dispor de apenas 2 dias úteis para elaboração e validação dos materiais, aumentando significativamente o risco e a pressão sobre os prazos', N'Aumentar o prazo para entregar materiais de consolidação', N'10367', N'01 - Imagens/01 - Antes/9523.jpeg', N'Antes da melhoria, o processo de submissão das projeções mensais apresentava desperdícios relacionados a retrabalho e tempo de espera.
INSERT INTO #PVC VALUES (9524, N'81029873', N'81006344', N'SUPORTE PARA PENDURAR AVENTAL DE COURO', NULL, N'Others/Outros', N'Ao final da atividade de solda, o EPI (avental/blusão de couro) permanece úmido em decorrência da transpiração do colaborador e é acondicionado no interior de um baú ou sobre o próprio equipamento, comprometendo a conservação do EPI e a organização do ambiente de trabalho.', N'Otimizar a organização, o acondicionamento e a conservação dos EPIs no ambiente de trabalho.', N'10245', N'01 - Imagens/01 - Antes/9524.jpeg', N'Ao final da atividade de solda, o EPI (avental/blusão de couro), mesmo apresentando umidade decorrente da transpiração do colaborador, era acondicionado de forma inadequada no interior de um baú, sem passar por um processo de secagem natural. Essa prática aumenta a probabilidade de proliferação de fungos e bactérias, além de reduzir a vida útil do EPI.', N'01 - Imagens/02 - Depois/9524.jpeg', N'Após a definição de um local adequado, foi realizada a instalação de um suporte fixo, permitindo que o EPI permaneça aberto e ventilado, evitando o acondicionamento inadequado e contribuindo para a secagem natural. A solução prolonga a vida útil do equipamento, mantém o ambiente de trabalho organizado e reduz o risco de proliferação de fungos e bactérias.', NULL, N'A meta inicial de melhorar a organização, o acondicionamento e a conservação do EPI foi plenamente atingida. Com a implantação do suporte adequado, o equipamento passou a ser armazenado de forma correta, permitindo ventilação e secagem natural, eliminando o acondicionamento inadequado em baús e reduzindo os riscos de deterioração, bem como a desorganização do ambiente.', N'A correta definição e padronização de locais para o armazenamento de EPIs contribuem para a melhor conservação dos equipamentos, a organização do ambiente de trabalho e a melhoria das condições de segurança.', 0, NULL, NULL, '2026-04-16T00:00:00.000', '2026-04-23T15:32:47.000', N'81029873', NULL, NULL);
INSERT INTO #PVC VALUES (9525, N'200959', N'200595', N'CCM 3935L Crusher Vent System', NULL, N'Underground/Subterrâneo', N'Ventilation within the crusher cavity was ineffective due to airflow following the path of least resistance along the hanging wall and reporting directly to the 3800L long belt. This resulted in uneven air distribution, with ventilation concentrated in certain areas of the cavity while other sections remained poorly ventilated.', N'Disperse the ventilation within the cavity ', N'10238', N'01 - Imagens/01 - Antes/9525.jpeg', N'Ventilation airflow followed the path of least resistance, with the primary airstream traveling along the hanging wall and reporting directly to the 3800L long belt. As a result, airflow became concentrated in specific areas of the crusher cavity, leaving other sections poorly ventilated.', N'01 - Imagens/02 - Depois/9525.jpeg', N'Design airflow originally reporting to 3935L is now captured at the entrance and redistributed throughout the crusher cavity using upgraded auxiliary ventilation systems. The redistributed airflow is then utilized by a secondary auxiliary system installed in the nipping well to effectively ventilate the #3 and #4 surge bin locations.
INSERT INTO #PVC VALUES (9526, N'81043460', N'81043460', N'Harvesting Crane Coupling Repairs', NULL, N'Others/Outros', N'The sacrificial coupling inserts in all 4 bridge motor gearboxes have failed.', N'Suitable replacement plan without further issue to production', N'0', N'01 - Imagens/01 - Antes/9526.jpeg', N'Original blue rubber coupling inserts were all damaged leaving the bridge motors and gear boxes uncoupled, preventing the harvesting crane from moving north or south. The blue pieces missing on all 4 motors.', N'01 - Imagens/02 - Depois/9526.jpeg', N'The team was able to get accurate measurements, design, 3d print and install suitable replacements before causing the nickel tankhouse to go down on power. These pieces from supplier also have a 1 month lead time.', NULL, N'Yes, Great work by all!', N'Replacement in kind isnt always feasable as an option', 8000, 3, N'MAIOR SEGURANÇA AO COLABORADOR AO SOLICITAR AUTORIZAÇÃO PARA TRANSITAR EM LOCAIS COM RESTRIÇÃO DE PESSOAS.', '2026-04-21T00:00:00.000', '2026-04-23T15:52:58.000', N'81043460', NULL, NULL);
INSERT INTO #PVC VALUES (9527, N'81013885', N'81013885', N'VALVULA AUTOMATICA', NULL, N'Others/Outros', N'Drenagem do vaso de pressão realizada por válvula manual tipo esfera.', N'Drenagem realizada de forma automática, sem necessidade de intervenção manual.', N'10362', N'01 - Imagens/01 - Antes/9527.jpeg', N'Drenagem do vaso de pressão realizada por válvula manual tipo esfera.
INSERT INTO #PVC VALUES (9528, N'81054395', N'81054395', N'Orientações - solicitações de materiais no CH Master via nota YE', NULL, N'Open Pit/Poço aberto', N'As solicitações de materiais chegam por diferentes formatos e com níveis variados de informação, sem um fluxo padronizado, gerando retrabalho, pendências frequentes, atrasos no atendimento e dificuldade de priorização das demandas.', N'Padronizar o processo de solicitações de materiais via SAP e CH Master, reduzindo retrabalho, pendências e aumentando a eficiência e previsibilidade dos atendimentos.', N'10075', N'01 - Imagens/01 - Antes/9528.jpeg', N'Antes, o processo de solicitações de materiais não tinha um padrão bem definido. Demandas diferentes eram tratadas da mesma forma, com informações incompletas ou fora do fluxo correto, o que gerava retrabalho, pendências constantes e atrasos no atendimento. Essa situação impactava a eficiência do processo e dificultava a organização e a priorização das demandas.', N'01 - Imagens/02 - Depois/9528.jpeg', N'Solução / Melhoria
INSERT INTO #PVC VALUES (9529, N'81044397', N'81044397', N'Implantação de espelho para verificação de EPI antes do início das atividades', NULL, N'Open Pit/Poço aberto', N'Foi identificado que os colaboradores iniciam suas atividades sem realizar uma verificação prévia dos EPIs, o que pode resultar no uso incorreto ou incompleto dos equipamentos de proteção, aumentando o risco de acidentes e não conformidades com os padrões de segurança.', N'Garantir que 100% dos colaboradores realizem a verificação dos EPIs antes do início das atividades, assegurando conformidade com os padrões de segurança e reduzindo riscos de acidentes.', N'10213', N'01 - Imagens/01 - Antes/9529.jpeg', N'Ausência de padronização na verificação de EPIs antes do início das atividades, resultando em possíveis falhas no uso correto dos equipamentos e aumento de riscos à segurança.', N'01 - Imagens/02 - Depois/9529.jpeg', N'Garantir que 100% dos colaboradores realizem a verificação dos EPIs antes do início das atividades, assegurando conformidade com os padrões de segurança e reduzindo riscos de acidentes.', NULL, N'sim ', N'Garantir que 100% dos colaboradores realizem a verificação dos EPIs antes do início das atividades', 10, 1, N'Garantir acompanhamento contínuo e ativo das notas em atraso, promovendo maior confiabilidade, disciplina e eficiência no processo de gestão da carteira do CMA.', '2026-04-22T00:00:00.000', '2026-04-23T16:07:56.000', N'81044397', NULL, NULL);
INSERT INTO #PVC VALUES (9530, N'542508', N'81033636', N'OTMIZAÇÃO DE INDETIFICAÇÃO DE QUALIDADE DE COMBUSTÍVEL', NULL, N'Others/Outros', N'A identificação do status da qualidade do combustível é realizada por meio da coleta de amostras, que são encaminhadas sequencialmente ao laboratório. Após a obtenção dos resultados das análises laboratoriais, é definido o status da qualidade do produto. Complementarmente, são realizadas inspeções por meio de manômetros, a fim de identificar a necessidade de substituição dos filtros das OPAs, visando a melhoria da qualidade do combustível.  ', N'AGILIDADE NA IDENTIFICAÇÃO DA QUALIDADE DO COMBUSTÍVEL', N'10077', N'01 - Imagens/01 - Antes/9530.jpeg', N'A identificação do status da qualidade do combustível é realizada por meio da coleta de amostras, que são encaminhadas sequencialmente ao laboratório. Após a obtenção dos resultados das análises laboratoriais, é definido o status da qualidade do produto. Complementarmente, são realizadas inspeções por meio de manômetros, a fim de identificar a necessidade de substituição dos filtros das OPAs, visando a melhoria da qualidade do combustível.  ', N'01 - Imagens/02 - Depois/9530.jpeg', N'Foi instalado um analisador de partículas na Rampa‑02 do posto pesado, que atua como uma ferramenta estratégica na gestão de combustíveis, oferecendo os seguintes benefícios técnicos: monitoramento da qualidade do combustível no momento do abastecimento, identificação do status do produto em tempo real e facilitação da prevenção e controle da qualidade do diesel.  ', NULL, N'A questão foi resolvida ao proporcionar maior agilidade na obtenção dos resultados e ao aprimorar a atuação preventiva na garantia da qualidade do produto. ', N'AGILIDADE NA IDENTIFICAÇÃO DA QUALIDADE DO COMBUSTÍVEL', 0, NULL, N'Garantir que a inspeção das guilhotinas da prensa seja realizada de forma segura, padronizada e eficiente, eliminando a necessidade de abertura total da janela de visita e reduzindo a exposição dos operadores a riscos.', '2026-04-22T00:00:00.000', '2026-04-23T16:08:24.000', N'542508', NULL, NULL);
INSERT INTO #PVC VALUES (9531, N'553135', N'516988', N'DISPOSITIVO PARA MÁSCARA DO RADIADOR ', NULL, N'Others/Outros', N'DURANTE A REMOÇÃO E INSTALAÇÃO DO COMPONENTE O RISCO DE ESMAGAMENTO DE MEMBROS ERA MUITO ALTO, POR FALTA DE UM DISPOSITIVO QUE EVITASSE ISSO. ', N'ELIMINAR RISCO DE ESMAGAMENTO', N'10139', N'01 - Imagens/01 - Antes/9531.jpeg', N'DURANTE A REMOÇÃO E INSTALAÇÃO DO COMPONENTE O RISCO DE ESMAGAMENTO DE MEMBROS ERA MUITO ALTO, POR FALTA DE UM DISPOSITIVO QUE EVITASSE ISSO. ', N'01 - Imagens/02 - Depois/9531.jpeg', N'Confeccionado dispositivo para máscara do radiador 
INSERT INTO #PVC VALUES (9532, N'541850', N'541850', N'Fixação Segura do Implemento do Comboio Lubrificador CV54 para Prevenção de Trincas Estruturais', NULL, N'Open Pit/Poço aberto', N'Durante o diagnóstico técnico, foi constatado que o sobrechassi do implemento apresentava ausência de elastômeros em alguns pontos de fixação, bem como desgaste acentuado em outros, comprometendo a interface entre o implemento e o chassi e proporcionado trincas.
INSERT INTO #PVC VALUES (9533, N'81054419', N'81054419', N'Dimensionamento do Parque Reserva de Básculas com Base em método estatístico', NULL, N'Others/Outros', N'O parque reserva de básculas vinha sendo definido com base em critérios históricos e conservadores, sem considerar de forma estruturada:
INSERT INTO #PVC VALUES (9534, N'81048240', N'81048240', N'Boletim VPS', NULL, N'Others/Outros', N'Antes da implementação do Kaizen, as informações consolidadas da Gerência Geral (GG) não possuíam um boletim estruturado. Os dados existiam, porém estavam distribuídos em diferentes fontes e comunicações, o que dificultava a visualização integrada, o acompanhamento periódico e a padronização das informações para apoio à gestão e à tomada de decisão.', N'Boletim da Gerência Geral, contendo informações consolidadas, estruturadas e padronizadas, antes inexistentes nesse formato.', N'10367', N'01 - Imagens/01 - Antes/9534.jpeg', N'Antes da implementação do Kaizen, as informações consolidadas da Gerência Geral (GG) não possuíam um boletim estruturado. Os dados existiam, porém estavam distribuídos em diferentes fontes e comunicações, o que dificultava a visualização integrada, o acompanhamento periódico e a padronização das informações para apoio à gestão e à tomada de decisão.', N'01 - Imagens/02 - Depois/9534.jpeg', N'Como solução, foi desenvolvido e implementado um boletim informativo estruturado, passando a centralizar, organizar e padronizar as principais informações da GG em um único material. O boletim passou a ser o produto oficial para consolidação e divulgação dessas informações, garantindo maior clareza, facilidade de acesso e padronização da comunicação.', NULL, N'Sim, o problema foi resolvido, pois a implantação de um boletim oficial e padronizado centralizou as informações da GG, eliminando a dispersão e melhorando a clareza, organização e acompanhamento pela gestão.', N'Processos sem um produto definido tendem a gerar informações descentralizadas. A definição clara de um boletim como entrega do processo fortalece o fluxo de informação, garante consistência e facilita o acompanhamento pela gestão.', 0, NULL, N'Aumento da confiabilidade operacional do sistema;
INSERT INTO #PVC VALUES (9535, N'81052333', N'81047054', N'Guarda-corpo com Plataforma ', NULL, N'Crusher/Britadeira', N'Atividades em altura realizadas com andaimes demandam:
INSERT INTO #PVC VALUES (9536, N'81052333', N'472940', N'Suporte para máquinas de Solda', NULL, N'Projects/Projetos', N'Máquina de solda no chão, Má organização impactos
INSERT INTO #PVC VALUES (9537, N'81052333', N'81014733', N'instalação de suporte com vários pontos de içamento ', NULL, N'Crusher/Britadeira', N'Antes apenas um ponto de fixação para Talha. Gerando esforço físico, na desmontagem do redutor, risco de prensamento de membros. Sendo necessário em vários momentos, colocar a mão em carga (Fazer balanço/Arraste)', N'distribuição uniforme de esforços, evitar prensamento de membros.', N'10362', N'01 - Imagens/01 - Antes/9537.jpeg', N'Antes apenas um ponto de fixação para Talha. Gerando esforço físico, sedo necessário em vários momentos, colocar a mão em carga, realizar balanço/Arraste, risco de acidentes com mãos e dedos.', N'01 - Imagens/02 - Depois/9537.jpeg', N'A solução facilitou o passo a passo da desmontagem, eliminando a necessidade de contato manual com a carga e permitindo a retirada do componente de forma segura, sem risco de danos ao equipamento ou aos operadores.', NULL, N'sim, a solução otimizou a desmontagem ao eliminar a necessidade de contato manual com a carga, reduzindo riscos aos operadores e prevenindo danos ao equipamento.', N'Diminuição do cenário de risco', 15677, 1, N'Diminuímos consideravelmente a quantidade de falhas nesse conjunto. ', '2026-04-16T00:00:00.000', '2026-04-23T21:57:08.000', N'81052333', NULL, NULL);
INSERT INTO #PVC VALUES (9538, N'502383', N'502648', N'ACESSO AO HIDRANTE', NULL, N'Open Pit/Poço aberto', N'DIFICULDADE DE ACESSAR HIDRANTE DEVIDO SOLO MUITO IRREGULAR E LISO QUANDO CHOVE', N'MINIMIZAR RISCOS DE QUEDA/ TROPEÇÕES/ LESÕES', N'10362', N'01 - Imagens/01 - Antes/9538.jpeg', N'PISO IRREGULAR COM RISCO DE QUEDA DE MESMO NÍVEL, TROPEÇÕES, LESÕES.', N'01 - Imagens/02 - Depois/9538.jpeg', N'FOI FABRICADO E INSTALADO UMA GRADE DE PISO ELIMINANDO/ OU MINIMIZANDO CONDIÇÃO DE RISCO DE ACIDENTE COMO: QUEDA DE MESMO NÍVEL, TROPEÇÕES.', NULL, N'MONTADO GRADE DE PISO MINIMIZAMOS OS RISCOS DE ACIDENTES', N'AMBIENTE DE TRABALHO MAIS SEGURO', 0, NULL, N'PADRONIZAÇÃO DO USO DAS LISTAS DE TAREFAS, VISÃO CONSOLIDADA PARA SUPORTE À TOMADA DE DECISÃO E REDUÇÃO CONTÍNUA DO TEMPO DE PLANEJAMENTO DAS ORDENS DE MANUTENÇÃO.', '2026-04-08T00:00:00.000', '2026-04-24T03:20:01.000', N'502383', NULL, NULL);
INSERT INTO #PVC VALUES (9539, N'502383', N'502383', N'PORTÃO DE ACESSO GALPÃO', NULL, N'Open Pit/Poço aberto', N'ÁREA DE TRÂNSITO DE EQUIPAMENTOS MÓVEIS COM RISCO DE ATROPELAMENTOS', N'ELIMINAR RISCOS DE ACIDENTES POR ATROPELAMENTO', N'10362', N'01 - Imagens/01 - Antes/9539.jpeg', N'ACESSO ABERTO SEM RESTRIÇÃO COM RISCO DE ATROPELAMENTO POR SER ÁREA DE MOVIMENTAÇÃO DE EQUIPAMENTOS MÓVEIS.', N'01 - Imagens/02 - Depois/9539.jpeg', N'FOI FABRICADO E INSTALADO UM PORTÃO DE ACESSO A ÁREA DO GALPÃO RESTRINGINDO O ACESSO A PESSOAS AUTORIZADAS MINIMIZANDO RISCO DE ACIDENTE POR ATROPELAMENTO.', NULL, N'RISCO ALTO DE ACIDENTES COM ATROPELAMENTO/ APÓS INSTALAÇÃO DO PORTÃO DE ACESSO RISCO CONTROLADO.', N'REDUÇÃO DE RISCOS DE ACIDENTE DE TRABALHO', 0, NULL, N'FOI ADQUIRIDO UMA PASTA SANFONA DEVIDAMENTE ETIQUETADA E ALIMENTADA COM TODOS OS DOCUMENTOS PERTINENTES A EXECUÇÃO DAS ATIVIDADES. ', '2026-04-15T00:00:00.000', '2026-04-24T03:34:48.000', N'502383', NULL, NULL);
INSERT INTO #PVC VALUES (9540, N'81037838', N'524037', N'Dreno do TQ-10', NULL, N'Others/Outros', N'O dreno do TQ-10 era curto e o material era projetado diretamente no piso .', N'Eliminar o lançamento de material no piso.', N'10054', N'01 - Imagens/01 - Antes/9540.jpeg', N'O Dreno curto , com lançamento de material diretamente no piso.', N'01 - Imagens/02 - Depois/9540.jpeg', N'Adequação do Dreno com instalação de extensão,garantindo o direcionamento correto do material e eliminando risco de queda.', NULL, N'A meta de eliminar o derramamento de material no piso foi atingida, com o direcionamento correto do dreno do TQ-10.', N'a importância de adequar corretamente o dimensionamento dos drenos para evitar derramamento e risco operacionais.', 0, NULL, N'melhora na fiscalização do banheiro masculino ', '2026-04-19T00:00:00.000', '2026-04-24T04:13:09.000', N'81037838', NULL, NULL);
INSERT INTO #PVC VALUES (9541, N'81054395', N'81054395', N'Reformulação do template de solicitação para materiais', NULL, N'Open Pit/Poço aberto', N'O template anterior era confuso e extenso, solicitava informações desnecessárias e utilizava termos do Klassmatt, não aderentes ao CH Master. Isso gerava erros no preenchimento, retrabalho e aumento no tempo de atendimento. O problema foi identificado por meio da recorrência de solicitações com dados inconsistentes e dúvidas frequentes dos usuários.', N'Tornar as solicitações de criação de código mais claras, objetivas e alinhadas ao padrão atual do CH Master', N'10075', N'01 - Imagens/01 - Antes/9541.jpeg', N'A situação anterior era caracterizada por um template de solicitação de criação de códigos pouco intuitivo, excessivamente detalhado e desalinhado com o processo vigente do CH Master. O formulário solicitava informações que não eram essenciais para o cadastro, utilizava terminologias antigas do Klassmatt e não deixava claro o que era realmente obrigatório. Como consequência, as solicitações chegavam com dados inconsistentes ou incompletos, gerando dúvidas frequentes, retrabalho, atrasos no atendimento e maior esforço tanto para os solicitantes quanto para a área responsável pelo cadastro.', N'01 - Imagens/02 - Depois/9541.jpeg', N'Solução / Melhoria
INSERT INTO #PVC VALUES (9542, N'92000576', N'92000576', N'Implantação de Alerta Automático por E‑mail para Notas em Atraso por Frota com Base no Painel de Gestão de Carteira do CMA', NULL, N'Projects/Projetos', N'As notas abertas relacionadas a laudos e telemetria, geradas a partir do SAP ECC e tratadas no ambiente do CMA, não possuíam um mecanismo automático de alerta para sinalizar atrasos de forma ativa e segmentada. Como consequência, notas em atraso corriam risco de esquecimento, exigiam acompanhamento manual no painel e dependiam de consultas frequentes para identificação, reduzindo a eficiência do acompanhamento pelo PCM, execução, CMA e engenharia.', N'Criar um alerta automático por e‑mail para notas em atraso, segmentado por frota, garantindo que todas as áreas envolvidas sejam notificadas de forma recorrente e direcionada, reduzindo esquecimentos e fortalecendo o acompanhamento da carteira de notas.', N'10015', N'01 - Imagens/01 - Antes/9542.jpeg', N'Antes da melhoria, o acompanhamento das notas em atraso era realizado exclusivamente por meio do Painel de Gestão de Carteira do CMA no Power BI. Embora o painel concentrasse as informações, não havia um alerta ativo que notificasse os responsáveis pelas frotas sobre atrasos específicos. Isso exigia consultas manuais frequentes e aumentava o risco de esquecimento de notas pendentes, principalmente em ambientes com grande volume de registros.', N'01 - Imagens/02 - Depois/9542.jpeg', N'Foi implementado um alerta automático de Notas em Atraso, utilizando como base o Painel de Gestão de Carteira do CMA no Power BI. Os dados, oriundos do SAP ECC, são tratados e consolidados no Power BI. A partir disso, o Power Automate realiza consultas programadas ao dataset do Power BI e envia alertas por e‑mail para os responsáveis de cada frota. Cada grupo recebe apenas as notas referentes à sua frota (ex.: infraestrutura, transporte, etc.), garantindo comunicação direcionada e efetiva. Os e‑mails apresentam informações como TAG, nota, ordem, data de conclusão desejada, descrição e prioridade.', N'https://make.powerautomate.com/environments/Default-7893571b-6c2c-4cef-b4da-7d4b266a0626/flows/shared/07b123bf-b417-4833-b056-3912bddf079c?v3=false', N'SIM – O problema foi resolvido.
INSERT INTO #PVC VALUES (9543, N'92000578', N'81042309', N'Padronização de Inspeção Segura em Equipamento de Prensa', NULL, N'Others/Outros', N'A operação necessitava abrir completamente a janela de visita para verificar as guilhotinas do prensa, expondo os trabalhadores a riscos de prensamento e queda, aumentando a probabilidade de acidentes.', N'Melhoria no Sistema de Acesso para Inspeção de Guilhotinas', N'10229', N'01 - Imagens/01 - Antes/9543.jpeg', N'Para realizar inspeções visuais nas guilhotinas do prensa, era necessário abrir totalmente a janela de visita.
INSERT INTO #PVC VALUES (9544, N'92000576', N'92000576', N'Criação de Aplicativo para Registro, Tratamento e Acompanhamento de Intervenções em Eventos Críticos e Não Críticos de Telemetria Provenientes do VisionLink e Minecare', NULL, N'Projects/Projetos', N'Os eventos de telemetria provenientes do sistema VisionLink, especialmente aqueles classificados como críticos (alto potencial), exigem tratamento técnico imediato, registro das ações realizadas e acompanhamento estruturado. Antes da implantação da solução, não existia uma ferramenta única e padronizada que permitisse gerenciar todo o ciclo desses eventos, desde o registro da intervenção até o acompanhamento e validação, dificultando a rastreabilidade, a gestão do histórico e a governança do processo', N'Implantar um aplicativo dedicado para registrar, tratar e acompanhar eventos de telemetria críticos e não críticos, garantindo padronização dos registros, clareza de responsabilidades, rastreabilidade das intervenções realizadas e suporte à tomada de decisão técnica.', N'10015', N'01 - Imagens/01 - Antes/9544.jpeg', N'Antes da melhoria, os eventos de telemetria não possuíam uma solução centralizada para registro e acompanhamento das intervenções. Os registros eram realizados de forma descentralizada, sem padronização e sem uma visão consolidada dos eventos tratados ou pendentes. Isso dificultava o controle operacional, a análise histórica e a gestão adequada dos eventos conforme seu nível de criticidade.', N'01 - Imagens/02 - Depois/9544.jpeg', N'Foi desenvolvido um aplicativo específico para Intervenções de Telemetria, estruturado para atender diferentes níveis de criticidade dos eventos:
INSERT INTO #PVC VALUES (9545, N'81044674', N'504114', N'Ciclonagem CI-2017-01', NULL, N'No Replication/Sem replicação', N'O equipamento não possuía revestimento adequado, ocasionando obstruções frequentes e vazamentos de material. Essa condição provocava lentidão operacional, atrasos críticos no cronograma de manutenção e redução da eficiência do processo, além de comprometer a tomada de decisão em tempo real.', N'Restabelecer a fluidez e a eficiência do processo por meio da adequação do equipamento, eliminando falhas estruturais e garantindo um processamento ágil e seguro.', N'10174', N'01 - Imagens/01 - Antes/9545.jpeg', N'O equipamento apresentava falhas no fluxo de material, exigindo intervenções manuais constantes. Esse cenário resultava em baixa confiabilidade operacional, atrasos recorrentes e maior exposição dos operadores a riscos de acidentes.', N'01 - Imagens/02 - Depois/9545.jpeg', N'Foi realizada a substituição do ciclone por um novo equipamento com revestimento adequado, eliminando falhas de fluxo e vazamentos. A melhoria restabeleceu os padrões de segurança, aumentou a confiabilidade operacional e trouxe maior agilidade ao processo.', NULL, N'O equipamento apresentava falhas no fluxo de material, exigindo intervenções manuais constantes. Esse cenário resultava em baixa confiabilidade operacional, atrasos recorrentes e maior exposição dos operadores a riscos de acidentes.', N'Intervenções simples e bem direcionadas podem gerar ganhos significativos de desempenho, eliminando falhas recorrentes, reduzindo riscos operacionais e aumentando a eficiência do processo.', 0, NULL, N'Maior controle, rastreabilidade e confiabilidade no uso das ferramentas de preditiva.', '2026-04-14T00:00:00.000', '2026-04-24T11:36:20.000', N'81044674', NULL, NULL);
INSERT INTO #PVC VALUES (9546, N'400428', N'400428', N'Spare  Discharge Grating storage', NULL, N'Concentration/Concentração', N'Did not have a designated laydown area for spare discharge grating inside building', N'Have a clear/labelled area for spare discharge grating', N'10058', N'01 - Imagens/01 - Antes/9546.jpeg', N'Chose a spot inside and conveniently available for storage, but was not clearly labelled', N'01 - Imagens/02 - Depois/9546.jpeg', N'Found area to store. Have signage identifying what and where to store.', NULL, N'Yes. Proper storage inside.', N'proper storage ', 0, NULL, N'Agilidade nas analises de vibração.', '2026-04-23T00:00:00.000', '2026-04-24T11:40:30.000', N'400428', NULL, NULL);
INSERT INTO #PVC VALUES (9547, N'81044674', N'81038934', N'Instalação estratégica de válvulas de bloqueio na tubulação MECAP para aumento da confiabilidade operacional', NULL, N'No Replication/Sem replicação', N'O sistema de tubulação do equipamento CX 2305SA-01 apresentava recorrentes falhas operacionais, caracterizadas principalmente por travamentos e obstruções na linha, decorrentes da ausência de válvulas de bloqueio para controle e isolamento do fluxo.
INSERT INTO #PVC VALUES (9548, N'400428', N'400428', N'Hippo-Hoppo storage', NULL, N'Concentration/Concentração', N'No designated storage for empty hippo-hoppers', N'Clearly identify empty hippo-hoppo storage', N'10058', N'01 - Imagens/01 - Antes/9548.jpeg', N'No identified storage area for empty hippo-hopper storage', N'01 - Imagens/02 - Depois/9548.jpeg', N'Identified storage area and created signage ', NULL, N'Clearly labelled and identified storage area', N'Identified area for storage', 0, NULL, N'grateful workers expressed appreciation for the attention to their safety.', '2026-04-23T00:00:00.000', '2026-04-24T11:58:37.000', N'400428', NULL, NULL);
INSERT INTO #PVC VALUES (9549, N'81044674', N'81038855', N'Substituição da válvula pinch CF-2057-20', NULL, N'No Replication/Sem replicação', N'válvula pinch estourando o mangote com frequência e oxidação dos componentes com risco de  projeção de material contra pessoa 
INSERT INTO #PVC VALUES (9550, N'515697', N'81055398', N'Sensor do Strut ', NULL, N'Others/Outros', N'O sensor do strut da frota DR416i com alto índice de falhas na leitura do sensor de posição travado.', N'Corrigir falhas no sensor do strut travado', N'10150', N'01 - Imagens/01 - Antes/9550.jpeg', N'Condição visual do sensor de travamento do Strut que encontrava apresentando várias falhas indesejadas devido folga entre base e o suporte de escoras de suporte do mastro que apresentou uma folga de 5mm conforme descrição sinalizada.', N'01 - Imagens/02 - Depois/9550.jpeg', N'Houve a necessidade de alteração do sensor indutivo de 12 mm para 18 mm, com o objetivo de aumentar a distância nominal de detecção do sensor instalado no equipamento. Os sensores indutivos de 12 mm originalmente aplicados apresentaram diversas paradas indesejadas, ocasionadas principalmente pela variação do alcance de detecção, que pode oscilar entre 2 mm e 8 mm, dependendo do modelo e do fabricante. O alcance típico desses sensores é de aproximadamente 2 mm, tornando-os sensíveis a variações mecânicas e desalinhamentos. Já os sensores indutivos de 18 mm possuem alcance maior, entre 5 mm e 8 mm, oferecendo maior estabilidade de detecção. Conforme observado na imagem do primeiro anexo, existe uma folga aproximada de 5 mm entre a base e o tirante de fixação, que pode variar durante o posicionamento do mastro, comprometendo a detecção.', NULL, N'Houve a necessidade de alteração do sensor indutivo de 12 mm para 18 mm, com o objetivo de modificar a distância nominal de detecção (alcance) do sensor indutivo instalado no equipamento.
INSERT INTO #PVC VALUES (9551, N'81011654', N'475273', N'BI UTILIZAÇÃO  DAS LISTA DE TAREFAS', NULL, N'Others/Outros', N'NÃO HÁ UMA VISÃO CONSOLIDADA DA UTILIZAÇÃO DAS LISTAS DE TAREFAS, O QUE DIFICULTA A GESTÃO DA NECESSIDADE DE CRIAÇÃO DE NOVAS LISTAS, AS QUAIS, POR SUA VEZ, ELEVAM O TEMPO DE PLANEJAMENTO DAS ORDENS DE MANUTENÇÃO.', N'IMPLEMENTAR A UTILIZAÇÃO EFETIVA E PADRONIZADA DA LISTA DE TAREFAS, GARANTINDO VISIBILIDADE, ORGANIZAÇÃO, PRIORIDADE DAS ATIVIDADES E SUPORTE À TOMADA DE DECISÃO, COM FOCO EM AUMENTAR A EFICIÊNCIA OPERACIONAL E A CONFIABILIDADE DOS DADOS.', N'10279', N'01 - Imagens/01 - Antes/9551.jpeg', N'ANTES  A UTILIZAÇÃO DAS LISTAS DE TAREFAS OCORRIA DE FORMA DESCENTRALIZADA, SEM UMA VISÃO ÚNICA E CONSOLIDADA. A INEXISTÊNCIA DE CRITÉRIOS PADRONIZADOS PARA ANÁLISE E REUTILIZAÇÃO DAS LISTAS GERAVA INSEGURANÇA NO PLANEJAMENTO E LEVAVA À CRIAÇÃO FREQUENTE DE NOVAS LISTAS.
INSERT INTO #PVC VALUES (9552, N'553135', N'81019440', N'BOOK DE DOCUMENTOS', NULL, N'Others/Outros', N'ANTES NÃO HAVIA UM LOCAL ESPECIFICO QUE REUNISSE TODOS OS DOCUMENTOS USADOS EM CAMPO E NA OFICINA PARA REALIZAR AS ATIVIDADES DE CONFIABILIDADE. FOI ADQUIRIDO UMA PASTA SANFONA DEVIDAMENTE ETIQUETADA E ALIMENTADA COM TODOS OS DOCUMENTOS PERTINENTES A EXECUÇÃO DAS ATIVIDADES. ', N'AGILIDADE NO PROCESSO ', N'10139', N'01 - Imagens/01 - Antes/9552.jpeg', N'ANTES NÃO HAVIA UM LOCAL ESPECIFICO QUE REUNISSE TODOS OS DOCUMENTOS USADOS EM CAMPO E NA OFICINA PARA REALIZAR AS ATIVIDADES DE CONFIABILIDADE', N'01 - Imagens/02 - Depois/9552.jpeg', N'FOI ADQUIRIDO UMA PASTA SANFONA DEVIDAMENTE ETIQUETADA E ALIMENTADA COM TODOS OS DOCUMENTOS PERTINENTES A EXECUÇÃO DAS ATIVIDADES. ', NULL, N'FOI ADQUIRIDO UMA PASTA SANFONA DEVIDAMENTE ETIQUETADA E ALIMENTADA COM TODOS OS DOCUMENTOS PERTINENTES A EXECUÇÃO DAS ATIVIDADES. ', N'RECURSOS SIMPLES', 0, NULL, N'Um quadro de marcação mais simplificado e com frações de hora. Assim, basta o requisitante colocar o seu nome no espaço referente ao dia e o horário desejado.
INSERT INTO #PVC VALUES (9553, N'81061781', N'776047', N'PLACA DO BANHEIRO MASCULINO', NULL, N'Projects/Projetos', N'falta de sinalização no banheiro masculino', N'melhora na fiscalização do banheiro masculino ', N'10327', N'01 - Imagens/01 - Antes/9553.jpeg', N'ausência da sinalização no banheiro masculino, podendo gerar uso indevido ou desogarnização', N'01 - Imagens/02 - Depois/9553.jpeg', N'melhor identificação e uma responsabilidade maior dos colaboradores', NULL, N'Sim, visão melhor do ambiente', N'melhor identificação e uma responsabilidade maior dos colaboradores', 0, NULL, N'A solução apresenta potencial de replicação para outras áreas com condição semelhante, reforçando seu caráter sustentável e alinhado aos princípios de melhoria contínua.
INSERT INTO #PVC VALUES (9554, N'81062527', N'81062527', N'Controle de instalação Dynamox ', NULL, N'Others/Outros', N'anteriormente, tinhamos a informação de quais equipamentos tihamos aplicado mais não tinhamos um registro/ controle "automático de aplicação ', N'obter um controle  dos materiais (sensores, cola) utilizados nas instalações ', N'10015', N'01 - Imagens/01 - Antes/9554.jpeg', N'anteriormente, tinha a informação de quais equipamentos foram aplicado os sensores  mais não tínhamos um registro/ controle "automático" da quantidade de material utilizado além de imagens das instalações, as respostas são enviadas em pdf a apartir do preenchimento do forms e tbm são incluidas nas ordens como evidência   ', N'01 - Imagens/02 - Depois/9554.jpeg', N'as respostas chegam via e-mail com um relatório em pdf, sendo possível monitorar o estoque disponível dos materiais utilizados e se necessário gerar suprimentos para reposição, unificação de informações que antes precisavam ser vistas em  vários locais distintos ex: ordem de execução (sap) n° dos dipositivos instalados (plataforma dynamox), material utilizado (as vezes nas ordens, as vezes em uma planilha preenchida  manualmente) ', NULL, N'sim, temos um controle mais preciso tanto de estoque como de informação de instalação', N'controle de utilização de material', 0, NULL, N'freeing up maintenance resources', '2026-03-30T00:00:00.000', '2026-04-24T15:51:37.000', N'81062527', NULL, NULL);
INSERT INTO #PVC VALUES (9555, N'485595', N'485595', N'Bucha cônica para instalação dos ball stud', NULL, N'Others/Outros', N'Sempre que precisávamos usinar os olhais dos ball stud, também tínhamos que fabricar internamente uma bucha cônica. 
INSERT INTO #PVC VALUES (9556, N'81046953', N'92000321', N'PLATAFORMA DE ACESSO AOS VASOS DE AR DA FILTRAGEM', NULL, N'Concentration/Concentração', N'Durante as atividades que necessitam de bloquear os vasos de ar 2551 VA 02 e 2551 VA 01, era necessário a montagem de andaime expondo pessoas a trabalho em altura com risco ergonômico e perda de tempo para o inicio das atividades.', N'ELIMINAR MONTAGEM DE ANDAIMES ', N'10362', N'01 - Imagens/01 - Antes/9556.jpeg', N'Durante as atividades que necessitam de bloquear os vasos de ar 2551 VA 02 e 2551 VA 01, era necessário a montagem de andaime expondo pessoas a trabalho em altura com risco ergonômico e perda de tempo para o inicio das atividades.', N'01 - Imagens/02 - Depois/9556.jpeg', N'Com a fabricação da plataforma de acesso (GM 5494) tivemos um ganho com retirada de pessoas da linha de fogo e ganho no tempo de resposta pra realização das atividades e redução com ganho não necessidade de montagem de andaime para ter acesso as válvulas dos vasos.', NULL, N'SIM-FOI ELIMINADO MONTAGEM DE ANDAIME.', N'olhar atento a segurança', 0, NULL, N'Tivemos melhora de tempo ao facilitar busca devido armazenamento padronizado e visão de estoque.', '2026-04-07T00:00:00.000', '2026-04-24T15:55:38.000', N'81046953', NULL, NULL);
INSERT INTO #PVC VALUES (9557, N'81052635', N'81016620', N'Cadastro de frequências determinísticas para analise de vibração escavadeiras 7495', NULL, N'Others/Outros', N'No momento da analise de vibração não contava com os cadastros das frequências determinísticas de falha para analise de vibração dos componentes monitorados das escavadeiras 7495, demorando um pouco mais para efetuar a analise de vibração completa dos pontos. Foi cadastrado as frequências dos redutores de elevação e redutores de escavação das escavadeiras.', N'Rapidez na analise de vibração', N'10015', N'01 - Imagens/01 - Antes/9557.jpeg', N'NO MOMENTO DA ANALISE DE VIBRAÇÃO NÃO CONTAVA COM OS CADASTROS DAS FREQUÊNCIAS DETERMINÍSTICAS DE FALHA PARA ANALISE DE VIBRAÇÃO DOS COMPONENTES MONITORADOS DAS ESCAVADEIRAS 7495, DEMORANDO UM POUCO MAIS PARA EFETUAR A ANALISE DE VIBRAÇÃO COMPLETA DOS PONTOS. FOI CADASTRADO AS FREQUÊNCIAS DOS REDUTORES DE ELEVAÇÃO E REDUTORES DE ESCAVAÇÃO DAS ESCAVADEIRAS.', N'01 - Imagens/02 - Depois/9557.jpeg', N'FOI CADASTRADO AS FREQUÊNCIAS DETERMINISTICAS DOS REDUTORES DE ELEVAÇÃO E REDUTORES DE ESCAVAÇÃO DAS ESCAVADEIRAS 7495 PARA AGILIZAR O PROCESSO DE ANALISE DE VIBRAÇÃO.', NULL, N'Ganhamos tempo em analise de vibração.', N'Replicar para outras frotas', 0, NULL, N'MAIOR CONFORTO E ESTABILIDADE, A CONCENTRAÇÃO AUMENTA , REFLETINDO EM MELHOR DESEMPENHO E PRECISÃO NAS TAREFAS REALIZADAS.', '2026-04-23T00:00:00.000', '2026-04-24T15:57:30.000', N'81052635', NULL, NULL);
INSERT INTO #PVC VALUES (9558, N'81062527', N'81062527', N'Checklist de Gestão – Equipamentos de Preditiva', NULL, N'Others/Outros', N'Inexistência de um controle padronizado para utilização das ferramentas de preditiva, incluindo condição do equipamento, data de calibração e status de carregamento, comprometendo a rastreabilidade e a confiabilidade das informações.', N'manter a gestão dos nossos equipamentos de monitoramento', N'10015', N'01 - Imagens/01 - Antes/9558.jpeg', N'As informações sobre o uso das ferramentas de preditiva eram verificadas de forma informal, sem registro estruturado, planilha ou sistema que garantisse rastreabilidade', N'01 - Imagens/02 - Depois/9558.jpeg', N'Processo padronizado com registro de condição do equipamento, calibração e status de carregamento via Forms.', NULL, N'Ausência de controle padronizado e rastreável na utilização das ferramentas de preditiva.', N'A ausência de controle padronizado e rastreável compromete a confiabilidade do processo. A implementação de registros digitais simples permite melhor controle, histórico das informações e gestão adequada das ferramentas de preditiva.', 0, NULL, N'META ATINGIDA', '2026-04-06T00:00:00.000', '2026-04-24T16:07:39.000', N'81062527', NULL, NULL);
INSERT INTO #PVC VALUES (9559, N'81029801', N'81016620', N'Cadastro de frequências determinísticas para analise de vibração das pás carregadeiras WE1850. ', NULL, N'Others/Outros', N'NO MOMENTO DA ANALISE DE VIBRAÇÃO NÃO CONTAVA COM OS CADASTROS DAS FREQUÊNCIAS DETERMINÍSTICAS DE FALHA PARA ANALISE DE VIBRAÇÃO DOS COMPONENTES MONITORADOS DAS PÁS CARREGADEIRAS, DEMORANDO UM POUCO MAIS PARA EFETUAR A ANALISE DE VIBRAÇÃO COMPLETA DOS PONTOS. FOI CADASTRADO AS FREQUÊNCIAS DETERMINISTICAS DAS BOMBAS DO PTO.', N'Agilidade nas analises de vibração', N'10015', N'01 - Imagens/01 - Antes/9559.jpeg', N'NO MOMENTO DA ANALISE DE VIBRAÇÃO NÃO CONTAVA COM OS CADASTROS DAS FREQUÊNCIAS DETERMINÍSTICAS DE FALHA PARA ANALISE DE VIBRAÇÃO DOS COMPONENTES MONITORADOS DAS PÁS CARREGADEIRAS WE1850, DEMORANDO UM POUCO MAIS PARA EFETUAR A ANALISE DE VIBRAÇÃO COMPLETA DOS PONTOS. FOI CADASTRADO AS FREQUÊNCIAS DETERMINISTICAS DAS BOMBAS DO PTO.', N'01 - Imagens/02 - Depois/9559.jpeg', N'FOI CADASTRADO AS FREQUÊNCIAS DETERMINISTICAS DE FALHA DAS BOMBAS DO PTO AGILIZANDO AS ANALISES DE VIBRAÇÃO DAS CARREGADIRAS WE1850.', NULL, N'Agilidade para analise de falhas.', N'Replicar para outras frotas', 0, NULL, N'Correia não está danificando durante a operação, está totalmente alinhada no ponto de montagem do suporte.', '2026-04-23T00:00:00.000', '2026-04-24T16:13:33.000', N'81029801', NULL, NULL);
INSERT INTO #PVC VALUES (9560, N'81019448', N'81019448', N'Padronização e Controle Visual das Demandas SAP do Centro de Trabalho SU005', NULL, N'Others/Outros', N'As demandas criadas no SAP para o centro de trabalho SU005 não possuíam um controle sistemático e visual fora do próprio sistema, tornando o acompanhamento reativo, disperso e suscetível a falhas. Podendo resultar em demandas despercebidas, atrasos no tratamento e impactos indiretos para as áreas.', N'Implementar um controle estruturado, visual e padronizado das demandas SAP do centro de trabalho SU005, por meio de uma planilha de gestão, com foco em: rastreabilidade; previsibilidade, priorização e confiabilidade.', N'10015', N'01 - Imagens/01 - Antes/9560.jpeg', N'As demandas (Notas YE) do centro de trabalho SU005 era realizado exclusivamente dentro do SAP, de forma individual e baseada em consultas pontuais ao sistema.', N'01 - Imagens/02 - Depois/9560.jpeg', N'Implantação de uma ferramenta de gestão visual estruturada para controle das Notas YE, CT-SU005, centralizando informações, permitindo priorização, acompanhamento contínuo e redução de riscos de atrasos.', NULL, N'Sim.
INSERT INTO #PVC VALUES (9561, N'81041052', N'81041052', N'Wash Bay Safety Lock and Tag Board', NULL, N'Underground/Subterrâneo', N'Safety tags and locks were not easily accessible for workers in the wash bay at 5160. There was no lockout station located in the bay while every other bay was equipped with their own supply.', N'Easier access to safety equipment for Wash Bay Attendants', N'10117', N'01 - Imagens/01 - Antes/9561.jpeg', N'Having no lock and tag board in the wash bay resulted in workers creating an ad-hoc place for their locks and tags. This was insufficient and not up to Vale standard. Every other bay had a lockout station but the wash bay did not and had to continuously leave the work area for supplies. ', N'01 - Imagens/02 - Depois/9561.jpeg', N'Now standardized with the other bays in the shop, the new lockout station embraces the 5 S''s. The new station shines and installing it where there was none before demonstrates how important access to safety tool is for every worker. It is also easy to check on the availability of lock and tag supplies with a quick glance making this improvement easy to sustain.', NULL, N'yes, locks, scissors, and tags are all available and within easy reach in a neat and tidy lockout station board.', N'safety matters in every corner of the workplace', 0, NULL, N'Melhoria na organização do ambiente', '2026-04-23T00:00:00.000', '2026-04-24T16:31:03.000', N'81041052', NULL, NULL);
INSERT INTO #PVC VALUES (9562, N'81061965', N'81061965', N'Atualização de lista de materiais  pós instalação de kit autônomo – Frota 930E_4', NULL, N'Others/Outros', N'Após a instalação do kit autônomo nos caminhões komatsu série 4, não houve a adequação do kit de mangueiras do gabinete no sistema. Dessa forma, na manutenção de 5000H estava chegando na área o kit de mangueiras antigo que não era mais aplicável na maquina. Além disso, o novo kit apresenta mangueiras adicionais e mudanças de características como comprimentos, disposições e terminais.', N'Realizar a devida atualização de mangueiras do gabinete após a instalação do kit autônomo', N'10015', N'01 - Imagens/01 - Antes/9562.jpeg', N'Após instalar o kit autônomo nos 930E Série 4, o sistema não foi atualizado e manteve o kit de mangueiras antigo. Na manutenção de 5000h, o material enviado para a área era incompatível com a nova configuração.', N'01 - Imagens/02 - Depois/9562.jpeg', N'Após realizar a correspondência das novas mangueiras, o kit de 5000h foi revisado e alinhado à configuração com kit autônomo. O sistema passou a contemplar mangueiras corretas em quantidade, comprimento e terminais, eliminando itens obsoletos, retrabalho e atrasos na manutenção.', NULL, N'A meta inicial era garantir que o kit de mangueiras utilizado na manutenção de 5000h fosse compatível com os caminhões Komatsu Série 4 após a instalação do kit autônomo, eliminando materiais incorretos e retrabalho. Com a correspondência das novas mangueiras e a atualização do sistema, o problema foi totalmente atendido: o kit passou a refletir a configuração real da máquina, reduzindo desperdícios, tempo de parada e aumentando a confiabilidade da manutenção.', N'A principal lição aprendida foi que toda modificação no equipamento, como a instalação do kit autônomo, deve ser acompanhada da correspondência técnica e atualização sistêmica dos componentes. A ausência dessa etapa gera kits incorretos, retrabalho e desperdícios. A comunicação integrada entre engenharia, manutenção e suprimentos é essencial para garantir padronização, eficiência e confiabilidade da manutenção.', 0, NULL, N'Melhoria na organização e segurança ', '2026-04-17T00:00:00.000', '2026-04-24T16:33:53.000', N'81061965', NULL, NULL);
INSERT INTO #PVC VALUES (9564, N'81023633', N'81029875', N'Ponto certo, trabalho seguro ', NULL, N'Others/Outros', N'O ponto de apoio do gabarito estava localizado apenas na parte inferior do martelo, dificultando a movimentação, aumentando o tempo da atividade e gerando risco de contato com estruturas próximas.', N'Adequar ponto de apoio superior para movimentação segura do gabarito, eliminando riscos de interferência com estruturas próximas, melhorando ergonomia e aumentando a eficiência operacional.', N'10220', N'01 - Imagens/01 - Antes/9564.jpeg', N'O equipamento possuía ponto de apoio apenas na parte inferior do martelo, dificultando a movimentação do gabarito durante a atividade. A condição exigia maior curso de içamento, aumentava o tempo de execução e gerava risco de interferência com estruturas próximas.', N'01 - Imagens/02 - Depois/9564.jpeg', N'Com o apoio da equipe de manutenção mecânica, viabilizou-se a confecção e instalação de um olhal superior no martelo, criando ponto de apoio adequado para conexão e movimentação do gabarito. A melhoria proporcionou maior controle operacional, redução do tempo de execução, melhor ergonomia e eliminação do risco de contato com estruturas adjacentes. ', NULL, N'Sim. Com a instalação do olhal superior, a atividade passou a contar com ponto de apoio adequado para movimentação do gabarito, eliminando a condição anterior, reduzindo riscos operacionais e melhorando a execução da tarefa.', N'A criação de ponto de apoio adequado eliminou improvisos, reduziu riscos operacionais e tornou a movimentação do gabarito mais segura e eficiente.', 0, NULL, N'Eliminação dos riscos', '2026-04-08T00:00:00.000', '2026-04-24T17:49:58.000', N'81023633', NULL, NULL);
INSERT INTO #PVC VALUES (9565, N'498554', N'498554', N'GERENCIAMENTO DE COMPONENTES  EM REFORMA', NULL, N'Others/Outros', N'O controle de saída e entrada de componentes para
INSERT INTO #PVC VALUES (9566, N'81045885', N'81045885', N'Quadro de agendamento de reunião simplificado.', NULL, N'Others/Outros', N'A folha para marcação de horários da sala de reuniões do PCM de Componentes não tinha de marcar horários fracionados durante o dia, o que também deixava muito bagunçado quando outras pessoas queriam marcar horários específicos.
INSERT INTO #PVC VALUES (9567, N'81042217', N'551106', N'Implantação de dispositivo de sinalização e absorção de impacto em viga de baixa altura para prevenção de acidentes com pessoas', NULL, N'Others/Outros', N'Foi identificado um ponto em área operacional com viga estrutural em altura abaixo do padrão ergonômico, localizada em rota de circulação de pessoas. Durante atividade rotineira, um colaborador sofreu um impacto na região da cabeça, abaixo do capacete, caracterizando um evento de segurança de baixo impacto, porém com potencial de maior gravidade.
INSERT INTO #PVC VALUES (9568, N'1008438', N'1008438', N'Reinstall Soda Ash Heat Exchanger PSV', NULL, N'Others/Outros', N'Reinstall Soda Ash Heat Exchanger PSV', N'Reinstall Soda Ash Heat Exchanger PSV', N'10277', N'01 - Imagens/01 - Antes/9568.jpeg', N'PSV was recertified by Score but needed to be reinstalled on the soda ash line.', N'01 - Imagens/02 - Depois/9568.jpeg', N'Reinstalled Soda Ash Heat Exchanger PSV, bolt up and torquing completed.  Reducing maintenace resources.', NULL, N'na', N'na', 0, NULL, N'With the shute widened, technicians are no longer having to unclog the sulfate by leaning in over the shute. This also stops a lot of the dust that comes from the sulfate, a carcinogen. ', '2026-04-24T00:00:00.000', '2026-04-24T23:56:23.000', N'1008438', NULL, NULL);
INSERT INTO #PVC VALUES (9569, N'81037838', N'524037', N'Relocação de válvula elimina trabalho em altura', NULL, N'Projects/Projetos', N'Válvula posicionada na parte superior,obrigando o operador a subir na base ou se esticar para abrir/fechar.Risco de queda e postura inadequada.', N'Elimina 100% do risco de queda associado á manobra da válvula através da sua realocação para altura ergonômica, garantindo operação segura ao nível do piso.', N'10054', N'01 - Imagens/01 - Antes/9569.jpeg', N'Válvula posicionada na parte superior,obrigando o operador a subir na base ou se esticar para abrir/fechar.Risco de queda e postura inadequada.', N'01 - Imagens/02 - Depois/9569.jpeg', N'Válvula realocada para altura ergonômica. Operação agora ao nível do piso. Risco de queda eliminado. ', NULL, N'proporcionar postura adequada ao operador durante manobra ,atendendo á NR-17.', N'Equipamento que exigem manobra frequente devem ter seus dispositivos de acionamento ao alcance das mãos.', 0, NULL, NULL, '2026-04-13T00:00:00.000', '2026-04-25T03:45:50.000', N'81037838', NULL, NULL);
INSERT INTO #PVC VALUES (9570, N'81020702', N'486145', N'Suporte extensão 930E', NULL, N'Others/Outros', N'Sem lugar padronizado para armazenar extensões', N'Desenvolver suporte para armazenamento padronizado', N'10140', N'01 - Imagens/01 - Antes/9570.jpeg', N'Não havia um lugar padronizado para armazenar os cabos de extensão que atende a frota 930E.', N'01 - Imagens/02 - Depois/9570.jpeg', N'Utilizando os materiais que temos em área, foi desenvolvido um suporte padronizado com mínimo e máximo para armazenar as extensões 930E.', NULL, N'Sim', N'Melhoria dos nossos processos operacionais ', 0, NULL, NULL, '2026-04-24T00:00:00.000', '2026-04-25T12:36:14.000', N'81020702', NULL, NULL);
INSERT INTO #PVC VALUES (9571, N'81057538', N'81057538', N'ERGONÔMIA IMPLEMENTADA NA PESAGEM DE AMOSTRAS', NULL, N'Others/Outros', N'COLABORADOR FAZIA PESAGEM EM PÉ, COM POSTURA INADEQUADA.', N'PROPOR E IMPLEMENTAR MELHORIAS ERGONÔMICAS', N'10129', N'01 - Imagens/01 - Antes/9571.jpeg', N'DURANTE ATIVIDADE DE PESAGEM TINHAMOS DIFICULDADES DE POR A CADEIRA DEVIDO O ÁRMARIO IMPEDIR , MANTENDO UMA POSTURA QUE PODE GERAR TENSÃO MUSCULAR EXCESSIVA. ESSA POSTURA , SE MANTIDA POR LONGOS PERÍODOS , AUMENTA O RÍSCO DE DORES E LESÕES POR ESFORÇOS REPETITIVO.', N'01 - Imagens/02 - Depois/9571.jpeg', N'COM A RETIRADA DO ÁRMARIO E A IMPLANTAÇÃO DA CADEIRA DURANTE A ATIVIDADE , GANHAMOS POSTURA ERGONOMICA E ELIMINAMOS A POSTURA INCORRETA  DURANTE A PESAGEM DAS AMOSTRAS.', NULL, N'SIM ,A REDUÇÃO DE MOVIMENTOS INADEQUADOS E ESFORÇOS EXCESSIVOS CONTRIBUI PARA UM AMBIENTE DE TRABALHO MAIS SEGURO.', N'POSTURA ERGONOMICA DURANTE ATIVIDADE', 0, NULL, NULL, '2026-04-23T00:00:00.000', '2026-04-25T16:24:40.000', N'81057538', NULL, NULL);
INSERT INTO #PVC VALUES (9572, N'498359', N'81061120', N'PROTEÇÃO DA RAC 07', NULL, N'Others/Outros', N'PROTEÇÃO FORA DO LOCAL ADEQUADO, COM CORROSÃO E ACUMULO DE MATERIAL', N'VOLTAR COM CONDIÇÕES IDEAIS DE SEGURANÇA DO EQUIPAMENTO', N'10362', N'01 - Imagens/01 - Antes/9572.jpeg', N'PROTEÇÃO FORA DO LOCAL ADEQUADO, COM CORROSÃO E ACUMULO DE MATERIAL', N'01 - Imagens/02 - Depois/9572.jpeg', N'FOI REPOSICIONADO A RAC 07 NO SEU LOCAL ADEQUADO, ELIMINADO ACUMULO MATERIAL E RISCOS PRENSAMENTO E CONTATOS COM PARTES MOVEIS, COLOCANDO DE VOLTA A CONDIÇÃO NORMAL DE SEGURANÇA DO EQUIPAMENTO.', NULL, N'META ATINGIDA', N'MELHORAR AMBIENTE DE TRABALHO ', 0, NULL, N'1. Segurança: Piso desobstruído (Zero risco de queda).
INSERT INTO #PVC VALUES (9573, N'81060882', N'81060882', N'SUPORTE AUTO ALINHADOR DE RETORNO EM "V"', NULL, N'Others/Outros', N'Equipamento se encontrava sem suporte auto alinhador de retorno, vindo a desalinhar de forma anormal e causar danos na borda da correia.', N'Alinhar o transportador de correia para não danificar a sua borda ou causar algum rasgo.', N'10362', N'01 - Imagens/01 - Antes/9573.jpeg', N'Equipamento se encontrava desalinhando no módulo 45 , vindo a colidir com a estrutura e danificando a borda da correia.
INSERT INTO #PVC VALUES (9574, N'81052181', N'550548', N'Conexão Inteligente', NULL, N'Others/Outros', N'A chave de fluxo apresentava falhas recorrentes de funcionamento devido ao acúmulo de crosta no sensor, exigindo intervenções frequentes para limpeza.
INSERT INTO #PVC VALUES (9575, N'81022574', N'81055666', N'Confecção de suporte para mangueira na remoagem', NULL, N'Others/Outros', N'Mangueira deixada no chão, com isso contribuía para um ambiente desorganizado, inseguro, diminuindo também o tempo de uso da mangueira', N'organização e padronização do ambiente de trabalho', N'10051', N'01 - Imagens/01 - Antes/9575.jpeg', N'Mangueira deixada no chão,contribuindo para um ambiente desorganizado, inseguro, diminuindo também o tempo de uso da mangueira devido a corrosão e mal uso.', N'01 - Imagens/02 - Depois/9575.jpeg', N'Confeccionado suporte para mangueira, aumentando o tempo de uso, pois a mangueira vai se manter armazenada em local adequado, melhoramos também os aspectos organizacionais do ambiente', NULL, N'Sim, eliminamos o problema e trouxemos bons resultados', N'Organização sempre é bom', 0, NULL, N'1.	Segurança: Piso desobstruído (Zero risco de queda).
INSERT INTO #PVC VALUES (9576, N'81022574', N'81055555', N'Confecção de suporte para mangueira no piso das peneiras', NULL, N'Others/Outros', N'Mangueira deixada no chão,contribuindo para um ambiente desorganizado, inseguro, diminuindo também o tempo de uso da mangueira devido a corrosão e mal uso.', N'Confeccionar suporte para mangueira', N'10051', N'01 - Imagens/01 - Antes/9576.jpeg', N'Mangueira deixada no chão,contribuindo para um ambiente desorganizado, inseguro, diminuindo também o tempo de uso da mangueira devido a corrosão e mal uso.', N'01 - Imagens/02 - Depois/9576.jpeg', N'Foi confeccionado suporte para mangueira, melhorando aspectos organizacionais do ambiente, promovendo um ambiente mais seguro para trabalhar.', NULL, N'O problema foi resolvindo', N'Ambiente mais organizado', 0, NULL, N'SEGURANÇA E ERGONOMIA ', '2026-04-24T00:00:00.000', '2026-04-25T23:05:50.000', N'81022574', NULL, NULL);
INSERT INTO #PVC VALUES (9577, N'81022574', N'81022574', N'Eliminação de Risco no Ponto de Descarte ~de material no piso das Peneiras', NULL, N'Others/Outros', N'O descarte do material era realizado em abertura sem proteção adequada, utilizando tubo rol como forma improvisada de controle do vão.
INSERT INTO #PVC VALUES (9578, N'1010856', N'1010856', N'sample drain hose', NULL, N'Others/Outros', N'had to carry buckets to sump which caused spills', N'avoid carrying buckets of solution to sump', N'0', N'01 - Imagens/01 - Antes/9578.jpeg', N'messy sample bucket area in an awkward position', N'01 - Imagens/02 - Depois/9578.jpeg', N'now that solution drains freely picking up the bucket is no longer required', NULL, N'yes', N'cleanliness, ergonomics', 0, NULL, N'label in place to warn people of possible HCL mist/vapors. ', '2026-04-25T00:00:00.000', '2026-04-26T00:02:32.000', N'1010856', NULL, NULL);
INSERT INTO #PVC VALUES (9579, N'81045257', N'1015402', N'3d Printed copper vacuum vent covers', NULL, N'Refining/Refino', N'Vents were being covered by random objects to preserve vacuum. ', N'Cost savings and preserve equipment ', N'0', N'01 - Imagens/01 - Antes/9579.jpeg', N'The vents were being covered by pieces of square plastic, pieces of wood, etc. ', N'01 - Imagens/02 - Depois/9579.jpeg', N'Printed 3d vent caps help preserve the vacuum and the integrity of the tubes. ', NULL, N'Yes, the problem was solved. The caps stop the vacuum from pulling in airflow and helps preserve the integrity of the vents. ', N'Challenge the design of equipment on site.', 500, 3, N'com a tag de identificação, facilitar a localização do equipamento com tempo mais rápido.', '2026-04-16T00:00:00.000', '2026-04-26T00:58:25.000', N'81045257', NULL, NULL);
INSERT INTO #PVC VALUES (9580, N'81045257', N'1015402', N'3D Printed cobalt cell risers', NULL, N'Refining/Refino', N'Original risers were seizing up and was expensive to replace. ', N'Cost savings', N'0', N'01 - Imagens/01 - Antes/9580.jpeg', N'Original risers were seizing up and was expensive to replace. ', N'01 - Imagens/02 - Depois/9580.jpeg', N'3D Printed a cell riser with coarser threads . ', NULL, N'Yes, the problem was solved, the risers are holding up and it''s much more cost effective. It can be made in house. ', N'Challenge the original design if you think it can be better ', 750, 3, N'Aumento da vida útil do frigobar pela proteção contra umidade, impactos e sujeira provenientes do contato direto com o piso.', '2026-04-10T00:00:00.000', '2026-04-26T01:03:10.000', N'81045257', NULL, NULL);
INSERT INTO #PVC VALUES (9581, N'81045257', N'81023784', N'Widened boric acid shute ', NULL, N'Refining/Refino', N'The current boric acid shute was too small for the nickel sulfate addition, so we had the shute widened to better fit and break up the sulfate. ', N'Make putting in sulfate safer. ', N'0', N'01 - Imagens/01 - Antes/9581.jpeg', N'The current boric acid shute was too small for the nickel sulfate addition and would get clogged, making it harder and unsafer work for operations.', N'01 - Imagens/02 - Depois/9581.jpeg', N'We got the shute widened and installed so the sulfate had an easier time going through and wouldn''t get clogged. ', NULL, N'Yes, the problem was solved. The shute no longer clogs.', N'Challenge the designs of equipment if you think its not working. ', 0, NULL, N'Eliminar a exposição do colaborador durante a limpeza das capelas, garantindo uma atividade mais segura, ergonômica e eficiente, além de melhorar a visualização interna do equipamento.', '2026-04-07T00:00:00.000', '2026-04-26T01:22:52.000', N'81045257', NULL, NULL);
INSERT INTO #PVC VALUES (9582, N'81045257', N'1010302', N'Install a valve on the HCL offload system', NULL, N'Refining/Refino', N'The hcl offload valve for the connection on the truck was found damaged and there was a 1-month lead time on a replacement. ', N'Install a new valve on the HCL offload system', N'0', N'01 - Imagens/01 - Antes/9582.jpeg', N'The hcl offload valve for the connection on the truck was found damaged and there was a 1-month lead time on a replacement. ', N'01 - Imagens/02 - Depois/9582.jpeg', N'Operations first confirmed with engineering if they could use a cpvc valve instead of the old one. Once confirmed, the valve was installed and was able to be connected to the truck .', NULL, N'Yes, the problem was solved, and we can now make a connection onto the truck using the new valve.', N'Challenge the design of equipment if you think it can be better', 1000, 3, N'Com essa modificação, o sistema é previamente pressurizado antes da partida, evitando a entrada de ar na linha e proporcionando uma partida mais suave, além de reduzir esforços no sistema de alimentação e aumentar a confiabilidade operacional', '2026-04-16T00:00:00.000', '2026-04-26T01:28:32.000', N'81045257', NULL, NULL);
INSERT INTO #PVC VALUES (9583, N'81045257', N'1010034', N'Operations repaired the harvesting crane pendant ', NULL, N'Refining/Refino', N'The harvesting crane pendant had the lights gone out and was scheduled to be sent to a 3rd party to repair.', N'Repair the pendant', N'0', N'01 - Imagens/01 - Antes/9583.jpeg', N'The harvesting crane pendant had the lights gone out and was scheduled to be sent to a 3rd party to repair.', N'01 - Imagens/02 - Depois/9583.jpeg', N'Operations were able to fix the pendant and repair the light. ', NULL, N'Yes, the problem was solved, pendant is currently working and being used. ', N'Equipment can be repaired instead of bought new. ', 1000, 3, N'APLICADO CHAPA DE ACORDO COM O DIMENSIONAMENTO DA MESA, GARANTINDO O ESPAÇAMENTO CORRETO ENTRE A MESA DO DHR E O TAMBOR DE MANGUEIRAS, EVITANDO AS QUEBRAS CONSTANTES DOS TENSORES E ELOS DA CORRENTE.', '2026-04-09T00:00:00.000', '2026-04-26T01:34:28.000', N'81045257', NULL, NULL);
INSERT INTO #PVC VALUES (9584, N'81045257', N'1010404', N'Boric acid transfer pump clogged', NULL, N'Refining/Refino', N'The boric acid transfer pump was clogged up with materials. The maintenance team at the time was too busy to look at it. ', N'Repair pump', N'0', N'01 - Imagens/01 - Antes/9584.jpeg', N'The boric acid transfer pump was clogged up with materials. The maintenance team at the time was too busy to look at it. ', N'01 - Imagens/02 - Depois/9584.jpeg', N'Operations took the pump apart and noticed all the material clogging it. They removed the build-up from the pump and fixed it. ', NULL, N'Yes, the problem was solved, and we did not need to purchase new parts. ', N'Make sure equipment is functioning properly ', 3000, 3, N'Less wasted time and proper storage', '2026-04-20T00:00:00.000', '2026-04-26T01:40:29.000', N'81045257', NULL, NULL);
INSERT INTO #PVC VALUES (9585, N'81050420', N'81022580', N'SUPORTE PARA MANGUEIRA', NULL, N'Others/Outros', N' Mangueira solta no piso, gerando risco de tropeço e desgaste do material.', N'Garantir a organização e durabilidade do item.', N'10031', N'01 - Imagens/01 - Antes/9585.jpeg', N' Mangueira solta no piso, gerando risco de tropeço e desgaste do material.', N'01 - Imagens/02 - Depois/9585.jpeg', N' Suporte metálico fabricado e instalado, garantindo a organização e durabilidade do item.', NULL, N'Antes  Mangueira solta no piso, gerando risco e tropeço e desgaste do material, depois.', N'Conservação: Maior vida útil para a mangueira', 0, NULL, N'Abrangência para todos os chutes das prensagem e identificação de risco de queda em estruturas.', '2026-04-08T00:00:00.000', '2026-04-26T02:02:25.000', N'81050420', NULL, NULL);
INSERT INTO #PVC VALUES (9586, N'81045257', N'1015402', N'3D Printed bridge motor coupler inserts. ', NULL, N'Refining/Refino', N'The harvesting crane was unable to move due to the bridge motor coupler inserts disintegrating, and the lead time to get a new part was 3 weeks out. ', N'Replace the old couplers that had disintegrated', N'0', N'01 - Imagens/01 - Antes/9586.jpeg', N'The harvesting crane was unable to move due to the bridge motor coupler inserts disintegrating, and the lead time to get a new part was 3 weeks out. ', N'01 - Imagens/02 - Depois/9586.jpeg', N'The motor coupler inserts were modeled and then 3D printed in house by a technician and inserted into the cranes. The crane has been running on the 3d printed parts since with no issue. ', NULL, N'Yes, the problem was solved. The crane is currently running on the 3D printed pieces. ', N'Challenge the design of equipment if you belive it can be better.', 10, 3, N'Less material will be used for skirting, less time repairing/replacing', '2026-04-20T00:00:00.000', '2026-04-26T02:06:02.000', N'81045257', NULL, NULL);
INSERT INTO #PVC VALUES (9587, N'81050420', N'81032668', N'CANHÃO DE ALTA PRESSÃO PARA LIMPEZA DE PISO', NULL, N'Others/Outros', N' Linha de água inutilizada devido falta de finalização na tubulação , válvula de abertura quebrada , tubulação obstruída', N'realizar limpeza nas canaletas e na baia e desobstruído tubulação ', N'10031', N'01 - Imagens/01 - Antes/9587.jpeg', N'Linha de água inutilizada devido falta de finalização na tubulação , válvula de abertura quebrada , tubulação obstruída.', N'01 - Imagens/02 - Depois/9587.jpeg', N'Foi instalado na linha, uma válvula nova para abertura da água , instalado também um canhão com pressão para realizar limpeza nas canaletas e na baia e desobstruído tubulação.', NULL, N'Resolvido, pois a Linha de água inutilizada devido falta de finalização na tubulação , válvula de abertura quebrada, tubulação obstruída.', N'- Fácil manuseio ; - Melhoria no processo  ; - ⁠Impacto na segurança operacional e na integridade física dos colaboradores', 0, NULL, N'Redução do potencial de acidentes graves ou fatais
INSERT INTO #PVC VALUES (9588, N'81050420', N'81048282', N'SUPORTE PARA MANGUEIRA', NULL, N'Others/Outros', N'Mangueira solta no piso, gerando risco de tropeço e desgaste do material', N'Segurança: Piso desobstruído (Zero risco de queda', N'10031', N'01 - Imagens/01 - Antes/9588.jpeg', N'Mangueira solta no piso, gerando risco de tropeço e desgaste do material.', N'01 - Imagens/02 - Depois/9588.jpeg', N'Suporte metálico fabricado e instalado, garantindo a organização e durabilidade do item.', NULL, N'Suporte metálico fabricado e instalado, garantindo a organização e durabilidade do item.', N'Segurança: Piso desobstruído (Zero risco de queda). 2.	5S: Ambiente limpo e padronizado. 3.	Conservação: Maior vida útil para a mangueira.', 0, NULL, N'More consistent operation within target ranges, faster response to deviations, improved communication across shifts, and overall increased operational efficiency.', '2026-04-25T00:00:00.000', '2026-04-26T02:42:28.000', N'81050420', NULL, NULL);
INSERT INTO #PVC VALUES (9589, N'81050420', N'81043444', N'TAMPA PARA CALHA DE DESCARGA', NULL, N'Others/Outros', N'CALHA DE DESCARGA DO MATERIAL DE LIMPEZA DO PISO DO PENEIRAMENTO SEM PORTA COM RISCO DE QUEDA DE PESSOAS.
INSERT INTO #PVC VALUES (9590, N'81022558', N'81022558', N'BP-2308SA-40', NULL, N'Others/Outros', N'Baia da remoagem sem bomba de poço acumulando material e dificultando acesso.', N'Facilitar limpeza e acesso no local', N'10229', N'01 - Imagens/01 - Antes/9590.jpeg', N'Linha de água inutilizada devido falta de finalização na tubulação e retirada da bomba de poço que seria utilizada para que o material retornasse ao circuito , válvula de abertura quebrada , tubulação obstruída.', N'01 - Imagens/02 - Depois/9590.jpeg', N'Foi instalado na linha, uma válvula nova para abertura da água , instalado também um canhão com pressão para realizar limpeza nas canaletas e na baia e desobstruído tubulação ✅', NULL, N'facilitou a limpeza no local com a instalação do canhão', N'facilitou a limpeza no local com a instalação do canhão', 0, NULL, N'Organização do ambiente.', '2026-04-25T00:00:00.000', '2026-04-26T03:43:57.000', N'81022558', NULL, NULL);
INSERT INTO #PVC VALUES (9591, N'81043762', N'81043762', N'Label Strip feed tank overflow', NULL, N'Refining/Refino', N'CRM action entered to label the strip feed tank overflow in impurities as it may contain HCL mist or vapors. ', N'label a warning on the tank overflow', N'0', N'01 - Imagens/01 - Antes/9591.jpeg', N'there was now label on the strip feed tank overflow in impurities to indicate that HCL mist or vapors may be present. ', N'01 - Imagens/02 - Depois/9591.jpeg', N'label installed to warn people that HCL mist or vapors may be present. ', NULL, N'yes. the label is in place. ', N'ensure proper labels are in place. ', 0, NULL, N'Ganha na produção mantendo em alimentação a linha disponível ', '2026-04-25T00:00:00.000', '2026-04-26T03:55:48.000', N'81043762', NULL, NULL);
INSERT INTO #PVC VALUES (9592, N'81022558', N'81022558', N'BP-2310SA-37', NULL, N'Others/Outros', N'Sem a tag de identificação do medidor de vazão dificulta uma possível inspeção, manutenção no mesmo para pessoas que não conhecem a área', N'Facilitar a visualização do equipamento', N'10229', N'01 - Imagens/01 - Antes/9592.jpeg', N'Instrumento de de indicação de vazão da BP-2310SA-37 sem tag , dificultando sua identificação.', N'01 - Imagens/02 - Depois/9592.jpeg', N'Foi instalada melhoria com tag de identificação para facilitar sua visualização.', NULL, N'com a tag de identificação, facilitar a localização do equipamento com tempo mais rápido.', N'Facil a visualização do equipamento', 0, NULL, N'*A área ficou mais iluminada proporcionado maior segurança operacional, melhor visibilidade para os operadores e suporte para as atividades executadas no local.
INSERT INTO #PVC VALUES (9593, N'81037838', N'524037', N'Confecção de suporte para frigobar. ', NULL, N'Projects/Projetos', N'Frigobar  estava instalado diretamente sobre o piso, gerando risco ergonômico para os colaboradores durante o uso diário e dificultando a limpeza da área sob o equipamento.', N'Reduzir em 100% a necessidade de flexão da coluna para acesso ao frigobar', N'10054', N'01 - Imagens/01 - Antes/9593.jpeg', N' Refrigerador (Frigobar) se encontrava diretamente  no piso, gerando risco ergonômico para os colaboradores durante o uso diário e dificultando a limpeza do local.', N'01 - Imagens/02 - Depois/9593.jpeg', N' Foi instalado um suporte metálico para elevação, do frigobar com altura compatível para uso e fácil acesso para limpeza.', NULL, N' Meta atingida. Risco ergonômico eliminado.', N'Pequenas melhorias com material disponível geram grande impacto na ergonomia e organização da área. Soluções simples, custo zero e de rápida execução devem ser incentivadas.', 0, NULL, N'Confined Space Entry is no longer required to access this valve for the purposes of flow to the Ocean outfall Pipeline', '2026-04-25T00:00:00.000', '2026-04-26T04:33:22.000', N'81037838', NULL, NULL);
INSERT INTO #PVC VALUES (9594, N'81059060', N'506314', N'Melhoria na limpeza das capelas', NULL, N'No Replication/Sem replicação', N'As novas capelas de exaustão não têm um mecanismo que permita abrir bem a porta, o que dificulta bastante a limpeza dos vidros. Por causa disso, a limpeza acaba não sendo tão eficiente e ainda coloca o colaborador em uma posição ruim do ponto de vista ergonômico.
INSERT INTO #PVC VALUES (9595, N'81030117', N'81057321', N'MELHORIA NO SISTEMA DA BOMBA DE ESCORVA PZ22', NULL, N'Others/Outros', N'Anteriormente, a bomba operava apenas de forma manual. Foi instalado um circuito em paralelo, onde a bomba é acionada automaticamente por aproximadamente 10 segundos sempre que o primeiro estágio do equipamento é ligado.
INSERT INTO #PVC VALUES (9596, N'81030117', N'81002626', N'BATENTE DA MESA DO DHR', NULL, N'Others/Outros', N'QUEBRA CONSTANTE NO TENSOR E ELOS DA CORRENTE.', N'GARANTIR PRODUTIVIDADE', N'10324', N'01 - Imagens/01 - Antes/9596.jpeg', N'MESA DO DHR SEM A PROTEÇÃO DOS BATENTES DE COLISÃO COM O TAMBOR DE MANGUEIRAS.', N'01 - Imagens/02 - Depois/9596.jpeg', N'APLICADO CHAPA DE ACORDO COM O DIMENSIONAMENTO DA MESA, GARANTINDO O ESPAÇAMENTO CORRETO ENTRE A MESA DO DHR E O TAMBOR DE MANGUEIRAS, EVITANDO AS QUEBRAS CONSTANTES DOS TENSORES E ELOS DA CORRENTE.', NULL, N'MESA DO DHR SEM A PROTEÇÃO DOS BATENTES DE COLISÃO COM O TAMBOR DE MANGUEIRAS.', N'DESENVOLVIMENTO DAS ATIVIDADES COM SEGURANÇA', 0, NULL, N'Atualização diária garantida da base YE
INSERT INTO #PVC VALUES (9597, N'400428', N'400428', N'Standard Crusher Skirting Storage', NULL, N'Crusher/Britadeira', N'No proper storage for skirting', N'Proper Storage', N'10058', N'01 - Imagens/01 - Antes/9597.jpeg', N'No dedicated spot for storage of spare skirting for Standard Crusher Skirting', N'01 - Imagens/02 - Depois/9597.jpeg', N'Have a clear dedicated spot that is readily available beside the standard crusher.', NULL, N'Yes. Less wasted time and proper storage', N'Proper storage/time management', 0, NULL, N'Redução de Retrabalho
INSERT INTO #PVC VALUES (9598, N'81047036', N'507810', N'Redução do Risco de Queda na Atividade de Agulhamento em Correia Transportadora', NULL, N'Others/Outros', N'Risco de queda com diferença de nível em correia transportadora, podendo causar eventos N1 e N2', N'Eliminar a exposição ao risco crítico de queda de pessoas na correia transportadora durante a atividade de agulhamento, por meio da adoção de solução de engenharia que promova o fechamento permanente do vão existente entre as agulhas do chute de transferência e o andaime de acesso, complementado pela instalação de guarda-corpo, atendendo à hierarquia de controles de risco e garantindo condições seguras, padronizadas e sustentáveis para execução da atividade.', N'10145', N'01 - Imagens/01 - Antes/9598.jpeg', N'exposição ao risco de queda de pessoas na correia transportadora durante a atividade de agulhamento', N'01 - Imagens/02 - Depois/9598.jpeg', N'Fechamento do vão que dá acesso a correia transportadora, eliminando o risco de queda.
INSERT INTO #PVC VALUES (9599, N'400428', N'400428', N'Standard Crusher Bowl Liner', NULL, N'Crusher/Britadeira', N'Liner was too short wearing out skirting prematurely and causing spillage', N'Increase bowl liner to reduce wear and spillage', N'10058', N'01 - Imagens/01 - Antes/9599.jpeg', N'Liner was too short and feed was hitting too high causing premature wear on skirting.', N'01 - Imagens/02 - Depois/9599.jpeg', N'Liner was increased by 6 inches which the feed will hit and not wear out skirting causing premature wear and spillage', NULL, N'Yes. Feed hits line and no spillage', N'Will be less clean up and repairs/replace', 0, NULL, NULL, '2026-04-25T00:00:00.000', '2026-04-26T19:10:51.000', N'400428', NULL, NULL);
INSERT INTO #PVC VALUES (9600, N'81047036', N'471876', N'Sistema de Retenção de Queda no Recebimento de Equipamentos – Laboratório', NULL, N'Others/Outros', N'Risco de queda ao receber equipamentos no segundo andar do prédio do laboratório de salobo. Este problema é significativo devido ao risco de morte ou vida mudada na eminência de uma queda.', N'Eliminar a exposição ao risco crítico de queda de pessoas durante a atividade de recebimento de equipamentos na área do Laboratório de Salobo, por meio da implantação de solução de engenharia com sistema de ancoragem e trava-queda retrátil, garantindo que, em caso de queda, o trabalhador permaneça suspenso, evitando impacto ao solo e prevenindo acidentes graves ou fatais.', N'10145', N'01 - Imagens/01 - Antes/9600.jpeg', N'Durante a atividade de recebimento de equipamentos na área do laboratório de Salobo, os empregados realizavam movimentações próximo a desníveis sem a existência de sistema de ancoragem adequado.
INSERT INTO #PVC VALUES (9601, N'81054319', N'81054319', N'Addition of Anolyte Ratio and CCD Wash Ratio to POL Start-of-Shift PI Vision Display', NULL, N'Refining/Refino', N'Key operating parameters—anolyte ratio and CCD wash ratio—were not readily visible on the POL start-of-shift PI Vision screen. Technicians and area coaches had to navigate DCS or search through emails to find the latest values, which takes more time and effort to confirm operating targets.
INSERT INTO #PVC VALUES (9602, N'1010180', N'1010180', N'Line cleaning scaffold elimination', NULL, N'Refining/Refino', N'Point of work for line cleaning included one area where scaffold would be required at a cost.', N'Cost saving', N'0', N'01 - Imagens/01 - Antes/9602.jpeg', N'Line cleaning required scaffold build for a point of work where line needed to be broken.', N'01 - Imagens/02 - Depois/9602.jpeg', N'Identified another place where line could be broken in and achieve better cleaning that did not require scaffold ', NULL, N'Achieved positive results for less work and cost ', N'Walk down jobs with effeciency in mind ', 4000, 3, N'Evitando paradas superiores a 2horas da usina Salobo I e II.', '2026-04-16T00:00:00.000', '2026-04-27T03:22:37.000', N'1010180', NULL, NULL);
INSERT INTO #PVC VALUES (9603, N'521673', N'521673', N'Carrinho para bombona', NULL, N'No Replication/Sem replicação', N'Antes, as bombonas não possuíam um local fixo para armazenamento, o que gerava desorganização no processo e aumentava o tempo de espera da equipe da usina quando vinha realizar a coleta.', N'Mater organização do ambiente', N'10366', N'01 - Imagens/01 - Antes/9603.jpeg', N'Antes, as bombonas não possuíam um local fixo para armazenamento, o que gerava desorganização no processo e aumentava o tempo de espera da equipe da usina quando vinha realizar a coleta. A falta de padronização dificultava a identificação e localização das bombonas, causando atrasos e impactando a eficiência da operação.', N'01 - Imagens/02 - Depois/9603.jpeg', N'O carrinho fica em local estratégico com as bombonas devidamente identificadas, com o objetivo de facilitar a organização e a coleta pela equipe da usina, garantindo organização do ambiente, segurança e controle no processo.', NULL, N'Sim,  garantindo mais eficiência, segurança e controle no processo.', N'Local organizado aumenta a produtividade.', 0, NULL, N'Definir massas e teores atualizados com novos resultados químicos.', '2026-04-26T00:00:00.000', '2026-04-27T03:27:47.000', N'521673', NULL, NULL);
INSERT INTO #PVC VALUES (9604, N'505062', N'81032592', N'Intertravamento automático Nível Alto H1 silos SI-2005-01', NULL, N'No Replication/Sem replicação', N'Sempre que alguma posição do silo SI-2005-01 atingia o nível H1 mesmo desabilitado, os alimentadores do túnel eram automaticamente intertravados, impossibilitando alimentar a linha e silo disponível', N'quando o silo estiver bloqueado, o valor H1 seja desconsiderado. Dessa forma, mantém-se a lógica de operação apenas entre os silos que estão liberados para operação.', N'10229', N'01 - Imagens/01 - Antes/9604.jpeg', N'Sempre que alguma posição do silo SI-2005-01 atingia o nível H1 mesmo desabilitado, os alimentadores do túnel eram automaticamente intertravados, impossibilitando alimentar a linha e silo disponível. A liberação ocorria apenas quando o nível H1 fosse desabilitado ou quando algum silo baixasse abaixo do setpoint configurado pelo técnico de sala. ', N'01 - Imagens/02 - Depois/9604.jpeg', N'Foi ajustada a condição de operação para que, quando o silo estiver bloqueado, o valor H1 seja desconsiderado. Dessa forma, mantém-se a lógica de operação apenas entre os silos que estão desabilitados para operação.', NULL, N'Sim realizado alteração na logica ', N'silo desativado ba pass a logicas ', 0, NULL, N'result will be reduced wear, increasing longevity of gearbox and the oil within ', '2026-04-03T00:00:00.000', '2026-04-27T04:16:30.000', N'505062', NULL, NULL);
INSERT INTO #PVC VALUES (9605, N'123307', N'513430', N'Pilha Pulmão Iluminada', NULL, N'Others/Outros', N'Foi constatado deficiência na iluminação do pátio mirante, onde existia uma iluminação gerada apenas pela torre de iluminação(xuxinha) e mesmo assim a iluminação ainda não era adequada, o que gerava exposição de riscos para as pessoas que transitavam pela área para realizar inspecção e manutenção , e pelo time de troca de turno dos tratorista que dão apoio na pilha pulmão.', N'Melhorar a iluminação', N'10054', N'01 - Imagens/01 - Antes/9605.jpeg', N'Foi constatado deficiência na iluminação do pátio mirante, onde existia uma iluminação gerada apenas pela torre de iluminação(xuxinha) e mesmo assim a iluminação ainda não era adequada, o que gerava exposição de riscos para as pessoas que transitavam pela área para realizar inspecção e manutenção , e pelo time de troca de turno dos tratorista que dão apoio na pilha pulmão.', N'01 - Imagens/02 - Depois/9605.jpeg', N'Foram instalados refletores reduzindo riscos e eliminando custo gerado pela torre de iluminação. Além da eliminação do custo, a área ficou mais iluminada proporcionado maior segurança operacional, melhor visibilidade para os operadores e suporte para as atividades executadas no local.', NULL, N'Sim, foram instalados refletores e  a área ficou mais iluminada proporcionado maior segurança operacional, melhor visibilidade para os operadores e suporte para as atividades executadas no local.', N'VER e AGIR', 0, NULL, N'Com a redução de paradas do circuito de rebritagem, reduzimos o impacto na produção da usina.', '2026-04-23T00:00:00.000', '2026-04-27T06:30:47.000', N'123307', NULL, NULL);
INSERT INTO #PVC VALUES (9606, N'1008800', N'1008800', N'Actuate Ocean Outfall Manual Valve', NULL, N'Refining/Refino', N'HIRA determined that the lack of quick and easy access to the wet well valve was an issue. If Ocean Outfall went off spec, discharging above requirements of the MMER, this valve would not be able to be closed instantaneously. Therefore an environmental incident would occur.', N'Allow Operations to close valve in a timely manner', N'0', N'01 - Imagens/01 - Antes/9606.jpeg', N'The valve to shut off flow to the ocean outfall pipeline was a manual butterfly valve. It is located in a wet well which requires confined space entry to access and open/close.', N'01 - Imagens/02 - Depois/9606.jpeg', N'Through engineering, planning, and execution, this manual valve was upgraded to an actuated valve, with local operator control as well. The actuator is outside of the wet well, which allows for operator control to be used to actuate the valve as well as the control room.
INSERT INTO #PVC VALUES (9607, N'594051', N'594051', N'Padronização modelo Report de Alerta da Engenharia Mina', NULL, N'Others/Outros', N'Durante o período de divulgação dos relatórios da engenharia, não havia um modelo padronizado para a elaboração e apresentação dos reports, o que dificultava a consistência das informações e a consolidação das análises.', N'Melhorar a comunicação visual com as área.', N'10081', N'01 - Imagens/01 - Antes/9607.jpeg', N'Não tinha um modelo de report. padronizado pela Engenharia de Mina.', N'01 - Imagens/02 - Depois/9607.jpeg', N'Foi padronizado um modelo para a divulgação de alertas e informações da Engenharia, proporcionando maior clareza na comunicação, facilitando a interação entre as áreas e garantindo mensagens objetivas e consistentes.', NULL, N'Melhorar a comunicação visual com as área.', N'Melhorar a comunicação visual com as área.', 0, NULL, N'Eliminamos o risco de aprisionamento, fraturas ou lesões que poderia ser ocasionada acidental por movimentação involuntárias de pessoas.', '2026-04-24T00:00:00.000', '2026-04-27T08:53:04.000', N'594051', NULL, NULL);
INSERT INTO #PVC VALUES (9608, N'1009274', N'1010414', N'Nickel Stripping Booth', NULL, N'Others/Outros', N'Frequent failures and poor performance of the nickel stripping booth reduced system availability, increased costs, and added additional work by not performing well. ', N'Reduce Cost, increase reliability & performance', N'0', N'01 - Imagens/01 - Antes/9608.jpeg', N'Retract brackets were among the highest component failures in the stripping booth. Next to this was the volatile performance issues of the hammer cylinders. No 2 cylinders performed the same, and the retract design was very problematic. ', N'01 - Imagens/02 - Depois/9608.jpeg', N'Adapted a larger cylinder with machined provisions for self- retract. Removal of all retract components (secondary air cylinders, retract brackets, reed switches.', NULL, N'eliminated many moving parts and failure items. Achieved lower reject rates, and higher system performance all while lowering the cost. ', N'Overall successful project!', 100000, 3, N'Com a implementação do lava-olhos portátil no comboio diesel, espera-se reduzir significativamente os riscos à saúde e segurança dos colaboradores em casos de contato com produtos químicos.', '2026-04-24T00:00:00.000', '2026-04-27T09:31:36.000', N'1009274', NULL, NULL);
INSERT INTO #PVC VALUES (9609, N'81040056', N'81040056', N'UTOMAÇÃO DO BOLETIM YE', NULL, N'No Replication/Sem replicação', N'A base de dados YE, extraída do SAP BO, precisava ser acompanhada diariamente para controle de notas em aberto, notas a vencer e notas atrasadas. Antes da automação, esse acompanhamento exigia esforços manuais, dependência de acesso individual à base, atualização não padronizada e comunicação reativa para os times envolvidos.
INSERT INTO #PVC VALUES (9610, N'81040056', N'81040056', N'Gestão de Solicitações - Suprimentos', NULL, N'Others/Outros', N'solicitações  de demandas de suprimentos sem mapeamento correto, falta de centralização do Fluxo
INSERT INTO #PVC VALUES (9611, N'81016184', N'81016184', N'Otimização de Custos com Recurso Interno', NULL, N'Others/Outros', N'Havia a necessidade de utilização de um suporte específico, cujo atendimento estava condicionado à aquisição externa, gerando custo financeiro, dependência de fornecedor e possível tempo de espera para atendimento da demanda.', N'Fabricar internamente um suporte utilizando recursos disponíveis da equipe e da manutenção, evitando a aquisição de suporte externo e gerando redução de custos para a empresa.', N'10230', N'01 - Imagens/01 - Antes/9611.jpeg', N'Antes da implementação da melhoria, a demanda por um suporte específico era atendida exclusivamente por meio de aquisição externa, gerando um alto impacto financeiro, com custo unitário de R$ 5.028,67 por suporte.
INSERT INTO #PVC VALUES (9612, N'92000679', N'92000679', N'FLUXO DE DEVOLUÇÃO DE CASCOS REMAN', NULL, N'Others/Outros', N'Ausência de fluxo de devolução de itens REMAN.', N'Padronização de Processo', N'0', N'01 - Imagens/01 - Antes/9612.jpeg', N'Não existia detalhamento do processo onde as etapas e responsáveis não estavam definidos.', N'01 - Imagens/02 - Depois/9612.jpeg', N'Com a definição por fluxo de trabalho, foram mapeadas todas as etapas e quem são os responsáveis por elas.', NULL, N'SIM. O processo passou a ter dono de acordo com as etapas.', N'Redução de Custos', 500000, 1, N'- Redução significativa do tempo gasto na consolidação e validação mensal dos indicadores;
INSERT INTO #PVC VALUES (9613, N'81048232', N'81048232', N'Automação da Revisão de Apontamentos Diários', NULL, N'Others/Outros', N'A revisão diária dos apontamentos do sistema produtivo para identificar eventos passíveis de unificação era feita 100% manualmente', N'Automatizar Processo', N'10081', N'01 - Imagens/01 - Antes/9613.jpeg', N'A revisão dos apontamentos era totalmente manual e envolvia a análise diária de cerca de 9.600 linhas, com múltiplos filtros, validações linha a linha, conferência de campos técnicos e cálculo manual de intervalos para identificar eventos unificáveis. O processo demandava alto esforço operacional para registrar e solicitar unificações.
INSERT INTO #PVC VALUES (9614, N'66944', N'66944', N'Reconciliação Polígonos Despacho/Liberação ', NULL, N'Projects/Projetos', N'Massas e teores lavrados com valores muito diferente das massas e teores liberados.', N'15', N'10247', N'01 - Imagens/01 - Antes/9614.jpeg', N'Arquivo não sistêmico no BI, comparando a massa liberada e lavrada.', N'01 - Imagens/02 - Depois/9614.jpeg', N'Criado indicador de FMDS semanal com o acompanhamento de massas e teores lavrados, comparando como massas e teores liberados. Criação de plano de ação para corrigir os desvios observados', NULL, N'Sim, gerado acompanhamento para atuar na causa raiz', N'Acompanhamento e ações para melhorar reconciliações de massa e teores lavrados', 0, NULL, N'Pra minimiza os riscos de colisão e diminuir o volume de poeira em frente as tendas', '2026-04-24T00:00:00.000', '2026-04-27T10:59:51.000', N'66944', NULL, NULL);
INSERT INTO #PVC VALUES (9615, N'505203', N'505203', N'Prevenção de Reversão Indevida da TR‑2012‑01 em Silos Parados', NULL, N'Others/Outros', N'O processo apresentava ocorrências recorrentes de elevação de nível nos silos das extremidades, mesmo com a linha parada ou em paradas programadas. A reversão indevida da TR‑2012‑01, quando os alimentadores das extremidades estavam desabilitados, provocava alimentação momentânea do silo, resultando em sobrecarga, paradas operacionais não programadas e perda significativa de produção. Em um dos eventos, foi registrada parada de aproximadamente 2 horas devido à sobrecarga no silo do peneiramento.', N'Evitar paradas por silo alto quando estivermos com linhas sem alimentação', N'10025', N'01 - Imagens/01 - Antes/9615.jpeg', N'Antes da melhoria, o processo apresentava ocorrências recorrentes de elevação de nível nos silos das extremidades, mesmo com a linha parada ou em paradas programadas. A reversão indevida da TR‑2012‑01, quando os alimentadores das extremidades estavam desabilitados, provocava alimentação momentânea do silo, resultando em sobrecarga, paradas operacionais não programadas e perda significativa de produção. Em um dos eventos, foi registrada parada de aproximadamente 2 horas devido à sobrecarga no silo do peneiramento.', N'01 - Imagens/02 - Depois/9615.jpeg', N'Após a implementação da nova lógica de controle associada ao APC, as reversões indevidas da TR‑2012‑01 foram eliminadas, impedindo a alimentação dos silos das extremidades quando os alimentadores estavam parados. Como resultado, o nível dos silos passou a se manter baixo e estável, inclusive durante paradas programadas e corretivas, eliminando as ocorrências de sobrecarga e as paradas operacionais não programadas. Observou-se redução significativa da perda de produção, aumento da estabilidade operacional, maior disponibilidade das Usinas Salobo I e II e melhoria na eficiência da atuação da sala de controle, confirmando a efetividade da solução implementada.', NULL, N'Antes: 
INSERT INTO #PVC VALUES (9616, N'66944', N'66944', N'Reconciliação rápida modelo de blocos quinzenal', NULL, N'Projects/Projetos', N'Falta de acompanhamento quinzenal no impacto de novos resultados químicos no modelo mensal', N'1%', N'10247', N'01 - Imagens/01 - Antes/9616.jpeg', N'A atualização do modelo quinzenal trazia apenas os valores globais antes e depois da atualização dos resultados químicos.', N'01 - Imagens/02 - Depois/9616.jpeg', N'Criadas colunas para comparar diferença nos valores de massa e teores, por qualidade, após atualização de novos resultados químicos.', NULL, N'Visualização rápida do impacto da atualização de teores', N'Coluna de reconciliação permite observa impacto da atualização de teores', 0, NULL, N'Redução da atuação reativa, aumento da aderência ao planejamento integrado M+3, melhoria na previsibilidade de aquisições e reformas de componentes, e aumento da confiabilidade operacional com mitigação de riscos à produção.', '2026-04-24T00:00:00.000', '2026-04-27T11:15:18.000', N'66944', NULL, NULL);
INSERT INTO #PVC VALUES (9617, N'81057857', N'1010414', N'Oil health ', NULL, N'Refining/Refino', N'Gearbox 223-312-PXE-002 had inadequate ability for oil to breath, unable to collect oil sample, and no quick connect for oil changes.  
INSERT INTO #PVC VALUES (9618, N'81033881', N'81033881', N'Adequação do projeto da base de esticamento do tambor de retorno da 2301TC06', NULL, N'No Replication/Sem replicação', N'Paradas frequentes do circuito de rebritagem devido desalinhamento da correia do transportador 2301TC06, causado pela instabilidade das bases dos mancais do tambor de retorno.', N'Reduzir em 70% as paradas por desalinhamento de correia devido falha na posição dos mancais do tambor de retorno do transportador 2301TC06..', N'10081', N'01 - Imagens/01 - Antes/9618.jpeg', N'O desgaste acentuado da rosca do fuso impedia o ajuste correto do alinhamento do tambor, causando o desalinhamento da correia e paradas do circuito de rebritagem, gerando impacto no processo produtivo.', N'01 - Imagens/02 - Depois/9618.jpeg', N'Foi realizado a revisão do projeto das base e alterado a rosca do fuso de ajuste de UNC para trapezoidal, garantindo um melhor ajuste operacional e aumento de vida útil.', NULL, N'Sim.
INSERT INTO #PVC VALUES (9621, N'387677', N'387677', N'install sump drain valves', NULL, N'Concentration/Concentração', N'C32 sump did not have sump drain valves to drain sump, there was holes in the back of the sump that were boarded up and needed to be removed every time the sump had to be drained', N'to ease the draining of sumps', N'10058', N'01 - Imagens/01 - Antes/9621.jpeg', N'sump before, back of sump did not have valves or an easy way to drain sump, these were boarded up and needed to be removed every time it had to be drained.', N'01 - Imagens/02 - Depois/9621.jpeg', N'installed a sump drain valve, and plexie glass piece, to make it easier to drain sump ', NULL, N'yes', N'installing equipment to ease job', 0, NULL, N'Minimização de riscos ambientais decorrentes das atividades com combustíveis, garantindo maior controle operacional e proteção ao meio ambiente.', '2026-04-19T00:00:00.000', '2026-04-27T13:31:39.000', N'387677', NULL, NULL);
INSERT INTO #PVC VALUES (9622, N'512019', N'512019', N'Proteção de vão Aberto na Mesa de Perfuração da PZ 43', NULL, N'No Replication/Sem replicação', N'Após o abaixamento do mastro, permanece um vão exposto no alojamento da trava vertical. A inexistência de dispositivo de proteção (como tampa, grade ou barreira física) nessa abertura gera risco grave de aprisionamento de membros, podendo resultar em torção, fratura ou lesões por atrito/escoriação, especialmente durante movimentação involuntária da trava ou do próprio mastro.', N'Eliminação de Vão aberto', N'10324', N'01 - Imagens/01 - Antes/9622.jpeg', N'Após o abaixamento do mastro, permanece um vão exposto no alojamento da trava vertical. A inexistência de dispositivo de proteção (como tampa, grade ou barreira física) nessa abertura gera risco grave de aprisionamento de membros, podendo resultar em torção, fratura ou lesões por atrito/escoriação, especialmente durante movimentação involuntária de pessoas no local.', N'01 - Imagens/02 - Depois/9622.jpeg', N'Após a instalação da melhoria, quando baixado o mastro o vão aberto pode ser fechado por uma proteção que foi instalada. Com isso eliminamos o risco de aprisionamento, fraturas ou lesões que poderia ser ocasionada acidental por movimentação involuntárias de pessoas.', NULL, N'Problema resolvido.  Vão aberto após abaixamento da torre pode ser fechado com facilidade.', N'Ganhos no quisito segurança', 0, NULL, N'We can use this feed to help us determine what is going on at 1250 L and send people to need to appropriate area.', '2026-04-22T00:00:00.000', '2026-04-27T13:49:40.000', N'512019', NULL, NULL);
INSERT INTO #PVC VALUES (9623, N'121608', N'69856', N'Lava Olhos Portátil', NULL, N'Others/Outros', N' Atualmente nas nossas operações de abastecimentos de equipamentos, há risco de contato acidental com combustíveis, graxas e outros produtos químicos utilizados no processo. Em situações de emergência, a ausência de um equipamento de lavagem ocular próximo pode atrasar o atendimento, aumentando a gravidade de lesões e afastamentos.', N'Redução de Risco, maior agilidade no atendimento e melhoria no processo de  segurança', N'10079', N'01 - Imagens/01 - Antes/9623.jpeg', N'Durante Gemba, foi identificado a ausência de lava-los nos postos móveis, onde em possíveis situações de emergência, a ausência deste equipamento de lavagem ocular próximo pode atrasar o atendimento, aumentando a gravidade de lesões e afastamentos.
INSERT INTO #PVC VALUES (9624, N'301042', N'607496', N'Enclosed Cab Cleaning', NULL, N'Underground/Subterrâneo', N'Occ Health dust monitoring experience higher levels in closed cabbed equipment.', N'Reduce elevated exposure to dust in cabbed equipment', N'10238', N'01 - Imagens/01 - Antes/9624.jpeg', N'The previous vacuum was not sufficient enough to clean the cabbed equipment.', N'01 - Imagens/02 - Depois/9624.jpeg', N'The fuel bays have been upgraded with an industrial vacuum to clean the cabbed equipment.', NULL, N'Less dust in cabbed equipment resulting in better air quality.', N'Proper tool for the job', 0, NULL, N'better visibility and easier to keep free of obstructions', '2026-04-13T00:00:00.000', '2026-04-27T14:14:08.000', N'301042', NULL, NULL);
INSERT INTO #PVC VALUES (9625, N'81030117', N'553136', N'PROTEÇÃO CONTRA QUEDA DE PESSOAS', NULL, N'Others/Outros', N'Parte do piso na mesa de perfuração, estava aberta com exposição potência a queda de pessoas com  nível diferente, com torção de membros e fratura exposta.', N'EVITAR QUEDA DO MESMO NIVEL E NIVEL DIFERENTE.', N'10324', N'01 - Imagens/01 - Antes/9625.jpeg', N'Parte do piso na mesa de perfuração, estava aberta com exposição potência a queda de pessoas com  nível diferente, com torção de membros e fratura exposta.', N'01 - Imagens/02 - Depois/9625.jpeg', N'Foi confeccionado 
INSERT INTO #PVC VALUES (9626, N'1009274', N'1010414', N'Oil Reduction - Nickel Stripping', NULL, N'Refining/Refino', N'an excessive amount of oil was being consumed by the nickel stripping booth. This was leading to a large mess of the machinery and contributing to dirty nickel in the area. ', N'reduce oil consumption while maintaining performance', N'0', N'01 - Imagens/01 - Antes/9626.jpeg', N'excessive oil/ dirt accumulated on controls. We were consuming 1L of oil for every 1000 mandrels stripped. ', N'01 - Imagens/02 - Depois/9626.jpeg', N'New pneumatic setup, away from the equipment. Oil consumption reduced to 1L for every 63,000 mandrels. 98% reduction in oil consumption.', NULL, N'yes, oil consumption was reduced and performance maintained. ', N'Excellent performance while reducing waste', 0, NULL, N'• Aumento da visibilidade operacional em tempo real
INSERT INTO #PVC VALUES (9627, N'81003351', N'81052011', N'Padronização e Automação da Gestão de Indicadores de Aprendizagem', NULL, N'No Replication/Sem replicação', N'Havia dificuldade no acompanhamento das métricas e indicadores da área de Aprendizagem. A ausência dessa visibilidade impactava diretamente a gestão de indicadores como treinamentos obrigatórios, MICT, projetos de liderança, mineração de talentos e portas de entrada. O problema foi identificado durante as rotinas de FMDS e RP.
INSERT INTO #PVC VALUES (9628, N'81029885', N'81029885', N'Dashboard de CMRA : Implantação de Modelo Estruturado para Gestão e Rateio de Recursos Móveis', NULL, N'Projects/Projetos', N'A gestão dos recursos móveis era realizada por meio de controles manuais e descentralizados (Excel e apresentações estáticas), com baixa visibilidade operacional diária e ausência de critério padronizado para análise de utilização, ociosidade e rateio de custos.
INSERT INTO #PVC VALUES (9629, N'81061781', N'523252', N'LOMBADAS EM FRENTE AO PÁTIO MIRANTE', NULL, N'Projects/Projetos', N'EVITAR RISCO DE COLISÃO ', N'Pra minimiza os riscos de colisão e diminuir o volume de poeira em frente as tendas', N'10327', N'01 - Imagens/01 - Antes/9629.jpeg', N'NÃO HAVIA LOMBADAS EM FRENTE AO PÁTIO, ASSIM CAUSANDO MUITA POEIRA', N'01 - Imagens/02 - Depois/9629.jpeg', N'Construção dos redutores de velocidade em frente o pátio mirante 
INSERT INTO #PVC VALUES (9630, N'983254', N'545267', N'Coletor de água do ar condicionado.', NULL, N'Others/Outros', N'Gotejamento de água sobre as vigas da flotação', N'Eliminar gotejamento de água sobre a vida em frente a subestação da moagem', N'10054', N'01 - Imagens/01 - Antes/9630.jpeg', N'Gotejamento de água sobre as estruturas em frente a subestação da moagem.', N'01 - Imagens/02 - Depois/9630.jpeg', N'Recipiente em PVC para coleta de água proveniente dos ar-condicionado que goteja sobre a vida da subestação da moagem', NULL, N'Meta superada, pois, eliminamos o gotejamento e ainda reutilizamos água gerada do condicionador de ar. ', N'Replicação', 0, NULL, N'eliminado risco de contaminação', '2026-04-14T00:00:00.000', '2026-04-27T15:24:20.000', N'983254', NULL, NULL);
INSERT INTO #PVC VALUES (9631, N'542336', N'542336', N'M+3 USINA', NULL, N'Others/Outros', N'AUSÊNCIA DE VIZIBILIDADE DO PLANEJAMENTO ESTRATÉGICO NA USINA', N'PLANEJAMENTO LONGO PRAZO', N'10081', N'01 - Imagens/01 - Antes/9631.jpeg', N'Ausência de rotina estruturada para análise antecipada dos laudos preditivos e integração entre PCM, áreas executantes e Gestão de Componentes.', N'01 - Imagens/02 - Depois/9631.jpeg', N'Implantação do planejamento integrado m+3, suportado por laudos preditivos e governança entre PCM, Engenharia e áreas executantes, proporcionando visibilidade de longo prazo, previsibilidade de recursos, antecipação de aquisições/reformas e aumento da confiabilidade operacional dos ativos.', NULL, N'SIM. O problema foi mitigado com a implantação do planejamento integrado M+3, proporcionando visibilidade antecipada das demandas e reduzindo a atuação reativa. O processo passa a ser contínuo, com evolução conforme maturidade das áreas e qualidade dos dados preditivos.', N'A antecipação baseada em dados preditivos, aliada à integração entre áreas, é fundamental para garantir previsibilidade e reduzir atuações reativas na manutenção. A governança do processo (rotina M+3) é tão importante quanto a ferramenta utilizada.', 0, NULL, N'Reduzimos eventos operacionais e intervenções corretivas, trazendo uma operação mais estável e previsível. Além disso, a mitigação de falhas e paradas não planejadas além de impactar na produção do equipamento, reduz nosso custo de manutenção. Este Kaizen impacta também a segurança de pessoas, pois evitando paradas não planejadas do equipamento, reduzimos a exposição do operador e do time de manutenção ao risco.', '2026-04-23T00:00:00.000', '2026-04-27T15:26:23.000', N'542336', NULL, NULL);
INSERT INTO #PVC VALUES (9632, N'983254', N'983254', N'Redução de risco de batida contra', NULL, N'Others/Outros', N'Risco  de batida contra e perada de tempo da equipe de coleta de resíduos da DIR da operação de Usina.', N'Redução de Risco na area da DIR da moagem', N'10054', N'01 - Imagens/01 - Antes/9632.jpeg', N'Estacionamento do caminhão para coleta de resíduos na DIR da operação de usina sem os trava rodas, com risco de batida contra parede do fundo. Operador desce do caminhão para colocar os trava rodas, gerando perda de tempo na atividade. ', N'01 - Imagens/02 - Depois/9632.jpeg', N'Instalação de trava rodas e batentes fixo na área da DIR da operação de Usina.', NULL, N'Ganho no tempo de coleta e redução do risco de batida contra. ', N'Redução de Riscos, ganha de tempo.', 0, NULL, N'Reduzimos eventos operacionais e intervenções corretivas, trazendo uma operação mais estável e previsível. Além disso, a mitigação de falhas e paradas não planejadas, além de impactar na produção do equipamento, impacta diretamente no custo de manutenção.', '2026-04-22T00:00:00.000', '2026-04-27T15:34:27.000', N'983254', NULL, NULL);
INSERT INTO #PVC VALUES (9633, N'81045248', N'81062684', N'cutter attachment for hose', NULL, N'No Replication/Sem replicação', N'When needing to cut a length of hose for use, you need to locate something to cut it with. To minimize wasting time, we''ve attached a hose cutting tool directly to the hose reel so it is available for use. ', N'make the best use of time ', N'0', N'01 - Imagens/01 - Antes/9633.jpeg', N'hose is available for use', N'01 - Imagens/02 - Depois/9633.jpeg', N'a cutter was attached to the hose reel station so that it is available immediately for cutting hose quickly ', NULL, N'works well for cutting hose quickly ', N'work quickly no time wasted ', 0, NULL, N'MELHORIA NO USO DA TOMADA 220V', '2026-04-26T00:00:00.000', '2026-04-27T15:56:03.000', N'81045248', NULL, NULL);
INSERT INTO #PVC VALUES (9634, N'701383', N'535629', N'Melhoria Preventiva na Gestão de Resíduos', NULL, N'Others/Outros', N'As condições da área de gestão de resíduos eram passíveis de aprimoramento para fortalecer o controle ambiental e a prevenção de riscos.', N'Aperfeiçoar de forma preventiva as condições de gestão e armazenamento de resíduos, reduzindo riscos ambientais e operacionais.', N'10079', N'01 - Imagens/01 - Antes/9634.jpeg', N'A área destinada à disposição da caçamba coletora de resíduos encontrava-se instalada sobre o solo natural, o que restringia as condições mais adequadas para a limpeza, movimentação e recolhimento da caçamba durante as atividades de manuseio e armazenamento de resíduos, especialmente em situações eventuais como queda da caçamba durante o manuseio ou ocorrências durante os procedimentos de limpeza.
INSERT INTO #PVC VALUES (9635, N'606883', N'606883', N'1250 level upper sandfill borehole', NULL, N'Underground/Subterrâneo', N'We currently do not have instant visibility on 1250 level upper sandfill bore hole. We have had spills in the past in this area and had to physically inspect.', N'To gain instant visibility on area', N'10328', N'01 - Imagens/01 - Antes/9635.jpeg', N'We would have issues with the sandfill and would have to send personnel to physically inspect 1250 level to see if there was an issue there that needed to be addressed. Picture is an example of a sandfill leak', N'01 - Imagens/02 - Depois/9635.jpeg', N'Installed 3 cameras in the area as it does go around a corner. Can now pull up instant feed of area to see if there are any issues. Picture is of camera 3', NULL, N'yes problem was solved. We now have a good visual on area', N'Cameras can be important tools to view areas that have potential risks.', 0, NULL, N'melhoria no processo de identificação de componentes eletricos', '2026-04-24T00:00:00.000', '2026-04-27T16:04:56.000', N'606883', NULL, NULL);
INSERT INTO #PVC VALUES (9636, N'607251', N'607251', N'Upgrade type of batteries used in  haualge trucks', NULL, N'Underground/Subterrâneo', N'The current batteries are lead acid type batteries which give off hydrogen gas when charging which is explosive.', N'Eliminate the hazards associated with liquid filled batteries', N'10066', N'01 - Imagens/01 - Antes/9636.jpeg', N'The AD 30 Cat haulage trucks at Totten mine come equipped with lead acid filled batteries. This type of battery gives off hydrogen gas when charging which is explosive.', N'01 - Imagens/02 - Depois/9636.jpeg', N'To eliminate the hazards associated with lead acid batteries, Totten mobile team sourced out AGM (absorbed glass mat) type batteries which do not give off explosive gases. We installed one set in a haulage truck to test fit and check the overall performance of the battery. After testing these batteries for a month or so we have ordered 4 more sets to install in the rest of our truck fleet.', NULL, N'Yes, problem solved. The elimination of the hydrogen gas eliminated the potential explosion hazard.', N'Look for alternative solutions ', 0, NULL, N'Confiança de dados de relatório em BI ', '2026-04-24T00:00:00.000', '2026-04-27T16:12:02.000', N'607251', NULL, NULL);
INSERT INTO #PVC VALUES (9637, N'1010730', N'1010730', N'Safety Shower Visibility Upgrade', NULL, N'Others/Outros', N'Safety Showers and access area on floor were often impeded on upper levels of buildings. Visibility was poor due to lack of colouring and reflectors', N'Make safety showers more visible and identifiable ', N'0', N'01 - Imagens/01 - Antes/9637.jpeg', N'Safety showers on upper decking were not 5s to prevent obstruction or easy visibility on floor (grating) area', N'01 - Imagens/02 - Depois/9637.jpeg', N'Added stripes on floor grating and reflective tape on piping for better visibility in production area.', NULL, N'Much more visiblity and easier designation of access zone to keep clear of obstruction', N'better visibility and designation of area ', 0, NULL, N'uso das tomadas', '2026-04-26T00:00:00.000', '2026-04-27T16:33:37.000', N'1010730', NULL, NULL);
INSERT INTO #PVC VALUES (9638, N'81051676', N'81051676', N'Aumento da estabilidade da vazão do Espessador do Salobo 3', NULL, N'Concentration/Concentração', N'O controle da vazão do underflow do espessador era feito manualmente pelo ajuste da rotação da bomba, exigindo atenção constante do operador. Essa prática aumentava a variabilidade do processo, comprometia a estabilidade do equipamento e elevava o risco de perda de regime operacional, inadequado para um sistema de dinâmica lenta.', N'Reduzir a variabilidade no controle de vazão do espessador contribuindo para a manutenção do regime de operação e perdas metalúrgicas associadas.', N'10306', N'01 - Imagens/01 - Antes/9638.jpeg', N'Anteriormente, a rotação da bomba do under do espessador era manipulada buscando atingir a vazão desejada
INSERT INTO #PVC VALUES (9639, N'81051676', N'81051676', N'Controle de Consumo de Reagentes Online', NULL, N'Concentration/Concentração', N'Ausência de um controle online para o monitoramento do consumo de reagentes das Usinas. Como consequência, o orçamento era frequentemente extrapolado e as ações corretivas só eram desencadeadas após o fechamento do consumo, de forma reativa.', N'Criar um controle de consumo de reagentes online visando adequar consumo ao orçamento 2026 por Usina.', N'10229', N'01 - Imagens/01 - Antes/9639.jpeg', N'Ausência de sistema online e integrado para monitoramento do consumo de reagentes, o que impedia o acompanhamento em tempo real e a gestão proativa de custos, levando a ações apenas reativas.', N'01 - Imagens/02 - Depois/9639.jpeg', N'Foi desenvolvida no PI Vision uma solução de gestão de reagentes com o objetivo de centralizar o
INSERT INTO #PVC VALUES (9640, N'81038384', N'81038384', N'Painel de controle de YE ', NULL, N'Others/Outros', N'Não havia um painel padronizado e confiável para o acompanhamento das notas abertas do tipo YE. ', N'Melhorar a visibilidade do processo', N'10230', N'01 - Imagens/01 - Antes/9640.jpeg', N'Não havia um painel padronizado e confiável para o acompanhamento das notas abertas do tipo YE. o que dificultava a visibilidade consolidada e o monitoramento do status real, resultando em atrasos na tomada de decisão e aumento do tempo de entrega das demandas associadas.', N'01 - Imagens/02 - Depois/9640.jpeg', N'Foi desenvolvido um painel para o acompanhamento integral do processo das notas YE, proporcionando maior visibilidade do tempo em carteira, status atual e etapa do fluxo. O painel possui visualização rápida e padronizada, permitindo a identificação de desvios e a proposição ágil de ações para tratativa e redução do tempo de entrega', NULL, N'Sim.', N'Todo processo precisa ser medido.', 0, NULL, N'Com as placas de identificação agora ficou bem mais claro identificar e solucionar os problemas de maneira mais praticas e com eficiência garantindo a segurança dos executores.', '2026-04-23T00:00:00.000', '2026-04-27T17:36:01.000', N'81038384', NULL, NULL);
INSERT INTO #PVC VALUES (9641, N'521650', N'521650', N'Frascos com tampa roqueável para coleta de amostras dos LG''s', NULL, N'Others/Outros', N'Durante o transporte das amostras dos LG''S (lavadores de gases)  as amostras eram transportadas em bequeres de teflon pesados e sem tampas com isso corríamos o risco de derramamento e respingos.', N'Evitar derramamento e respingos das amostras dos LG''s durante o transporte.', N'10366', N'01 - Imagens/01 - Antes/9641.jpeg', N'Os béqueres de coleta para amostras dos lavadores de gases são de teflon, tornando-o pesado. Não há tampas disponibilizadas para vedá-los durante o transporte, podendo causar derramamentos e respingos principalmente no acesso as escadas no trajeto. 
INSERT INTO #PVC VALUES (9642, N'81050431', N'81058947', N'COLETOR DE  RESIDOS', NULL, N'Others/Outros', N'OS COLETORES SÃO FIXOS ', N'ERGONOMIA', N'10139', N'01 - Imagens/01 - Antes/9642.jpeg', N'era feito de maneira não convencional onde fazíamos  uso excessivo de movimentação. ', N'01 - Imagens/02 - Depois/9642.jpeg', N'criado coletor adaptador para manutenção com rodinhas em aço.', NULL, N'sim', N'melhorias', 0, NULL, NULL, '2026-04-26T00:00:00.000', '2026-04-27T17:58:28.000', N'81050431', NULL, NULL);
INSERT INTO #PVC VALUES (9643, N'81050431', N'81058947', N'dispositivo do sabão', NULL, N'Others/Outros', N'sem suporte adequado foi confeccionado um com uma melhoria', N'segurança', N'10139', N'01 - Imagens/01 - Antes/9643.jpeg', N'antes não tinha suporte correto era fornecido no balde', N'01 - Imagens/02 - Depois/9643.jpeg', N'Foi confeccionado um suporte com melhoria para a distribuição do sabão sem risco de acidente', NULL, N'eliminado risco de contaminação', N'segurança', 0, NULL, N'Os resultados esperados com a implantação do procedimento são a redução do tempo de indisponibilidade das telas, maior agilidade na normalização após falhas ou quedas de energia, diminuição de erros operacionais, padronização das ações, e maior autonomia, garantindo a continuidade das atividades do CMA sem impactos operacionais relevantes.', '2026-04-26T00:00:00.000', '2026-04-27T18:18:32.000', N'81050431', NULL, NULL);
INSERT INTO #PVC VALUES (9644, N'81058081', N'81058081', N'Redução de Riscos Operacionais por Operação Manual nos Britadores Primários', NULL, N'Crusher/Britadeira', N'A operação dos britadores primários permitia comandos e ajustes manuais em condições críticas, fora dos limites definidos pela engenharia. A ausência de barreiras sistêmicas eficazes expunha o ativo a falhas diretas por erro operacional, com riscos à segurança, integridade do equipamento e continuidade operacional.', N'Reduzir o risco operacional de médio para baixo e Reduzir a probabilidade do evento ocorrer de muito provável para muito remoto', N'10293', N'01 - Imagens/01 - Antes/9644.jpeg', N'A operação dos britadores primários permitia intervenções manuais em condições críticas, incluindo ajustes sob carga, partidas e comandos fora do envelope seguro definido pela engenharia.
INSERT INTO #PVC VALUES (9645, N'81058081', N'81058081', N'Redução de Riscos Operacionais por Operação Manual nos Britadores Secundários', NULL, N'Crusher/Britadeira', N'A operação dos britadores secundários permitia ajustes e comandos manuais em condições críticas, extrapolando os limites definidos pela engenharia. A ausência de barreiras sistêmicas eficazes aumentava a exposição a falhas decorrentes de erro operacional, com potenciais impactos à segurança, à integridade dos equipamentos e à continuidade operacional.', N'Reduzir o risco operacional de médio para baixo, atuando na sua probabilidade de ocorrer', N'10293', N'01 - Imagens/01 - Antes/9645.jpeg', N'A operação dos britadores secundários permitia intervenções manuais em condições críticas, fora do envelope seguro definido pela engenharia. A inexistência de barreiras sistêmicas eficazes possibilitava que erros operacionais evoluíssem diretamente para falhas do equipamento, com impactos potenciais à segurança, à integridade do ativo e à estabilidade operacional.', N'01 - Imagens/02 - Depois/9645.jpeg', N'Foram implantadas barreiras lógicas na automação, bloqueando ajustes sob carga e comandos. O sistema passou a ser barreira ao erro humano, protegendo ativos e a segurança operacional', NULL, N'A iniciativa atingiu a meta esperada reduzindo o risco operacional de médio para baixo, reduzindo a probabilidade do risco se concretizar.', N'Controles sistêmicos são mais eficazes que controles dependentes do comportamento humano', 0, NULL, N'Redução do tempo de atividade em 30min.', '2026-04-17T00:00:00.000', '2026-04-27T20:40:45.000', N'81058081', NULL, NULL);
INSERT INTO #PVC VALUES (9646, N'81047846', N'81047846', N'IDENTIFICAÇÃO TOMADA 220V', NULL, N'Others/Outros', N'AUSENCIA DE IDENTIFICAÇÃO DAS TOMADAS 220V DO VESTIARIO DO PATIO METSO ESCAVAÇÃO IMPOSSIBILITANDO O USO CORRETO DA MESMA EM COMPONENTES DE TENSÃO DIFERENTE.', N'OTIMIZAR O USO DAS TOMADAS 220V NA AREA', N'10324', N'01 - Imagens/01 - Antes/9646.jpeg', N'TOMADA SEM IDENTIFICAÇÃO DE SUA TENSÃO NOMINAL PODENDO OCORRER USO INCORRETO DA MESMA EM COMPONENTES DE TENSÃO DIFERENTE.', N'01 - Imagens/02 - Depois/9646.jpeg', N'APLICADO ETIQUETA IDENTIFICADORA NA TOMADA 220V PARA MELHOR USO DA MESMA.', NULL, N'SIM RESOLVIDO', N'IDENTIFICAÇÃO DE COMPONENTES ELETRICOS', 0, NULL, N'Padronização do registro das reuniões com fornecedores, garantindo clareza e uniformidade das informações.
INSERT INTO #PVC VALUES (9647, N'81047846', N'81047846', N'IDENTIFICAÇÃO TOMADA 220V', NULL, N'Others/Outros', N'AUSENCIA DE IDENTIFICAÇÃO DAS TOMADAS 220V PODENDO OCORRER MAL USO DA MESMA EM COMPONENTES COM TENSÃO DIFERENTE.', N'MELHORIA NO USO DAS TOMADAS 220V', N'10324', N'01 - Imagens/01 - Antes/9647.jpeg', N'TOMADA 220V SEM IDENTIFICAÇÃO DE SUA TENSÃO NOMINAL.', N'01 - Imagens/02 - Depois/9647.jpeg', N'APLICADO ETIQUETA IDENTIFICADORA NA TOMADA 220V PARA MELHOR ULTILIZAÇÃO DA MESMA.', NULL, N'SIM FOI RESOLVIDO', N'IDENTIFICAÇÃO DE COMPONENTES ELETRICOS', 0, NULL, N'Melhorar identificação e padronização de 5s da aréa.', '2026-04-25T00:00:00.000', '2026-04-27T21:45:02.000', N'81047846', NULL, NULL);
INSERT INTO #PVC VALUES (9648, N'81047846', N'81047846', N'identificação tomada 220v vestiario', NULL, N'Others/Outros', N'tomada 220v sem identificação de sua tensão nominal podendo ocorrer queima de componentes eletricos de tensão diferente.', N'melhoria no uso das tomadas e evitar uso de componentes eletricos com tensão diferente', N'10324', N'01 - Imagens/01 - Antes/9648.jpeg', N'tomada 220v sem identificação de sua tensão nominal', N'01 - Imagens/02 - Depois/9648.jpeg', N'aplicado etiqueta identificadora de tensão nominal na tomada 220v.', NULL, N'sim foi resolvido', N'identificação de componentes eletricos', 0, NULL, N'Aumento da eficiência na execução das manutenções, com redução de retrabalho e melhor aproveitamento dos recursos.', '2026-04-25T00:00:00.000', '2026-04-27T22:11:59.000', N'81047846', NULL, NULL);
INSERT INTO #PVC VALUES (9649, N'81063756', N'81063756', N'Correção de inconsistências no BI de Controle de RAF MSC e Ações Stratws', NULL, N'No Replication/Sem replicação', N'Foi identificado que o relatório de BI referente ao Controle de RAF MSC e Ações Stratws, um dos mais utilizados pela gerência, vinha gerando interpretações equivocadas. O problema na página "Açoes Stratws" estava relacionado, principalmente, a um filtro que não aplicava os critérios corretamente, além de uma inconsistência entre os visuais: enquanto o gráfico de barras indicava um determinado número de ações atribuídas a um responsável, a tabela apresentada na parte inferior exibia um valor diferente.', N'Corrigir de inconsistências no BI de Controle de RAF MSC e Ações Stratws', N'10015', N'01 - Imagens/01 - Antes/9649.jpeg', N'1. Filtro referente aos responsáveis pelas ações não funcionando adequadamente.
INSERT INTO #PVC VALUES (9650, N'81047846', N'81047846', N'identificação da tomada 220v', NULL, N'Others/Outros', N'ausencia de informação sobre as tensões nominais das tomadas do patio metso', N'melhoria na identificação da tensão nominal das tomada 220v do patio metso', N'10324', N'01 - Imagens/01 - Antes/9650.jpeg', N'tomada 220v do vestiario do patio metso sem informação sobre sua tensão nominal', N'01 - Imagens/02 - Depois/9650.jpeg', N'aplicado etiqueta identificadora na tomada 220v para melhor visualização e ultilização da mesma.', NULL, N'sim foi resolvido', N'identificação de componentes eletricos', 0, NULL, N'Melhorar maturidade de 5s da aréa Tagueando os ativos.', '2026-04-24T00:00:00.000', '2026-04-27T22:51:19.000', N'81047846', NULL, NULL);
INSERT INTO #PVC VALUES (9651, N'81047846', N'81047846', N'identificação de tomada eletrica', NULL, N'Others/Outros', N'tomada elétrica sem identificação de sua tensão', N'uso correto da mesma', N'10324', N'01 - Imagens/01 - Antes/9651.jpeg', N'ausência de identificação da tensão da tomada elétrica.', N'01 - Imagens/02 - Depois/9651.jpeg', N'aplicado etiqueta identificando tensão da tomada para melhor visualização e utilização da mesma.', NULL, N'sim foi resolvido', N'identificação de tensão da tomada eletrica', 0, NULL, N'Redução do risco de indisponibilidade operacional, aumento da confiabilidade da frota e maior previsibilidade no suprimento de materiais críticos.
INSERT INTO #PVC VALUES (9652, N'87000324', N'87000320', N'Partial Optimization of Lighting on the 1st Floor of the Office', NULL, N'Others/Outros', N'Increased energy consumption and costs due to unnecessary lighting', N'Energy and cost savings', N'10217', N'01 - Imagens/01 - Antes/9652.jpeg', N'Some unnecessary lights were on.', N'01 - Imagens/02 - Depois/9652.jpeg', N'Lighting has been optimized.', NULL, N'There was no gap,', N'Optimization', 0, NULL, N'Melhorar a identificação dos acionamentos da correia 2101TC02', '2026-03-05T00:00:00.000', '2026-04-27T23:53:54.000', N'87000324', NULL, NULL);
INSERT INTO #PVC VALUES (9653, N'537635', N'537635', N'Quadro de Estratégia e Metas', 3, N'Others/Outros', N'Anteriormente, o quadro de pendências estava desorganizado, o que acabava dificultando a separação e o gerenciamento eficiente dessas pendências.', N'Ver e Agir', N'10245', N'01 - Imagens/01 - Antes/9653.jpeg', N'Anteriormente, o quadro de pendências estava desorganizado, o que acabava dificultando a separação e o gerenciamento eficiente dessas pendências. O maior desafio estava na falta de distinção clara entre as pendências corretivas e preventivas, o que levava a misturas de tarefas com prioridades diferentes. Além disso, muitas pendências, tanto preventivas quanto corretivas, eram tratadas de forma similar, sem levar em consideração a urgência ou o caráter de manutenção preventiva que muitas delas demandam.', N'01 - Imagens/02 - Depois/9653.jpeg', N'Solução Implementada:
INSERT INTO #PVC VALUES (9654, N'537635', N'537635', N'Visão e  Estratégica no Pátio do Mirante. ', NULL, N'Projects/Projetos', N'Antes  o local não possuía iluminação adequada, o que tornava difícil a operação dos equipamentos de forma segura. A solução envolveu a montagem de uma infraestrutura completa de iluminação, visando atender a todas as necessidades do local.', N'Melhores condições da Área ', N'10245', N'01 - Imagens/01 - Antes/9654.jpeg', N'Antes da instalação, o local não possuía iluminação adequada, o que tornava difícil a operação dos equipamentos de forma segura. A solução envolveu a montagem de uma infraestrutura completa de iluminação, visando atender a todas as necessidades do local.
INSERT INTO #PVC VALUES (9655, N'81046149', N'81040359', N'Escada de acesso Seguro', NULL, N'Others/Outros', N'Descrição do problema: Escada de acesso à área operacional apresenta condições inadequadas de uso, como instabilidade, ausência de corrimão, degraus danificados ou inclinação incorreta, aumentando o risco de acidentes.', N'Manter ambiente mas seguro ', N'10362', N'01 - Imagens/01 - Antes/9655.jpeg', N'Descrição do problema: Escada de acesso à área operacional apresenta condições inadequadas de uso, como instabilidade, ausência de corrimão, degraus danificados ou inclinação incorreta, aumentando o risco de acidentes.', N'01 - Imagens/02 - Depois/9655.jpeg', N'Adequar a escada conforme normas de segurança (inclinação, largura e resistência)
INSERT INTO #PVC VALUES (9656, N'81050872', N'81050872', N'Passo a Passo para Inicialização e Conexão das Telas do CMA', NULL, N'Others/Outros', N'Indisponibilidade e instabilidade das telas do CMA, principalmente após quedas de energia, causada por perda de conexão, tela azul, equipamentos desligados ou mau contato nos cabos, o que dificultava a visualização das informações e atrasava a normalização do sistema por falta de um fluxo padronizado de ação.', N'Garantir a inicialização correta, conexão, login e exibição das apresentações padrão em todas as telas do CMA, assegurando o funcionamento normal do sistema após quedas de energia ou falhas de comunicação.', N'10178', N'01 - Imagens/01 - Antes/9656.jpeg', N'Indisponibilidade e instabilidade das telas do CMA, principalmente após quedas de energia, causada por perda de conexão, tela azul, equipamentos desligados ou mau contato nos cabos, o que dificultava a visualização das informações e atrasava a normalização do sistema por falta de um fluxo padronizado de ação.', N'01 - Imagens/02 - Depois/9656.jpeg', N'Com a melhoria, o processo passará a ser padronizado, claro e intuitivo, permitindo a rápida identificação e correção, reduzindo o tempo de indisponibilidade das telas, possibilitando que qualquer pessoa consiga restabelecer o funcionamento completo de forma ágil e eficiente.', NULL, N'
INSERT INTO #PVC VALUES (9657, N'524052', N'524052', N'Relatório de Perfil de Falhas de Motor', NULL, N'Others/Outros', N'Não tínhamos um perfil de perdas específico para o componente, apenas para a frota. Com isso não olhavamos o motor mas apenas o caminhão de forma mais macro', N'avaliação detalhada do motor diesel', N'10254', N'01 - Imagens/01 - Antes/9657.jpeg', N'Não tínhamos um relatório de perfil de perdas específico do motor diesel, as análises eram de forma mais macro, olhando os sistemas do equipamento.', N'01 - Imagens/02 - Depois/9657.jpeg', N'Foi criado um relatório de perfil de perdas de motores para avaliação que reune dados de análise de óleo, relatório de falhas e consumo diesel, para melhorar a avaliação do motor diesel.', NULL, N'sim, foi melhorada a condição de avaliação inicial para um novo patamar de estudos', N'possibilidade de ir mais a fundo nos problemas', 0, NULL, N'Definição do efetivo adequado à demanda real, aumentando a confiabilidade do dimensionamento e a eficiência na execução das atividades.', '2026-04-27T00:00:00.000', '2026-04-28T09:59:34.000', N'524052', NULL, NULL);
INSERT INTO #PVC VALUES (9658, N'81040813', N'81040813', N'Dispositivo aplicado as Retomadoras de Minério', NULL, N'Others/Outros', N'Atualmente para atividade preventiva de virada de caçamba não existia dispositivo adequado para uso no passo da retirada do tirante , sendo necessário o tempo de 2 horas para execução da atividade, além do tempo de exposição dos colaboradores na área restrita.', N'Redução de tempo na execução da atividade de virada de caçamba e exposição a área restrita ao time.', N'10170', N'01 - Imagens/01 - Antes/9658.jpeg', N'Atividade preventiva de virada de caçamba não existia dispositivo adequado para uso no passo da retirada do tirante , sendo necessário tempo de 2 horas para execução da atividade, e de exposição dos colaboradores na área restrita.', N'01 - Imagens/02 - Depois/9658.jpeg', N'Foi fabricado dispositivo para uso no processo de retirada do tirante da caçamba minizando o tempo de atividade em 30min.
INSERT INTO #PVC VALUES (9659, N'81005746', N'81005746', N'Padronização da Ata de Reunião em Excel para Gestão de Fornecedores', NULL, N'Others/Outros', N'Atualmente, o registro das reuniões com fornecedores é realizado por meio de planilhas Excel sem um padrão definido de estrutura e preenchimento. Essa falta de padronização dificulta o acompanhamento das ações acordadas, o controle de prazos e responsáveis, bem como a rastreabilidade das informações discutidas em reunião. Como consequência, há perda de visibilidade sobre os compromissos assumidos, atrasos no retorno de orçamentos, retrabalho nas análises e impacto negativo na gestão das Ordens de Manutenção, comprometendo a eficiência do processo e a tomada de decisão.', N'Melhorar a padronização e controle das ATA de Reunião.', N'10230', N'01 - Imagens/01 - Antes/9659.jpeg', N'As atas de reunião com fornecedores eram registradas em planilhas Excel sem padronização de layout e conteúdo. As informações variavam de acordo com o responsável pelo preenchimento, não havendo campos obrigatórios para ações, prazos, responsáveis e status. Isso dificultava o acompanhamento dos compromissos firmados em reunião, gerava perda de rastreabilidade, retrabalho no controle das Ordens de Manutenção e baixa visibilidade dos pontos críticos, como atrasos de orçamento e desvios de prazo.', N'01 - Imagens/02 - Depois/9659.jpeg', N'Foi implantado um modelo padronizado de Ata de Reunião em Excel, contendo campos estruturados para identificação do fornecedor, participantes, indicadores principais, registro de ações com responsável, prazo, prioridade e status. A planilha permite melhor controle visual, acompanhamento sistemático das ações acordadas e histórico das reuniões. Com isso, houve aumento da rastreabilidade, melhoria na comunicação entre as áreas e fornecedores, redução de retrabalho e maior eficiência na gestão das Ordens de Manutenção.', NULL, N'Meta Inicial / Problema:
INSERT INTO #PVC VALUES (9660, N'81049566', N'502163', N'Identificando ', NULL, N'Refining/Refino', N'Ausência de identificação nas colunas de flotação .', N'Identificar todas colunas de flotação do site', N'10362', N'01 - Imagens/01 - Antes/9660.jpeg', N'Ausência de identificação nas colunas de flotação 28, 29, 30.', N'01 - Imagens/02 - Depois/9660.jpeg', N'Identificado TAGS padronizado nas colunas de flotação .', NULL, N'Colunas com boa identificação conforme padrão .', N'Melhoria na maturidade de 5s', 0, NULL, NULL, '2026-04-27T00:00:00.000', '2026-04-28T11:02:48.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (9661, N'81061965', N'81061965', N'Estabelecimento de fóruns de revisão de planos de manutenção na área – Frotas CAT e KOMATSU', NULL, N'Crusher/Britadeira', N'Ausência de acompanhamento técnico contínuo e integrado nos planos de manutenção das frotas CAT e KOMATSU, resultando em falhas nos planos, baixa integração entre áreas e impactos na qualidade, produtividade e custos.', N'Ausência de acompanhamento técnico contínuo e integrado nos planos de manutenção das frotas CAT e KOMATSU, resultando em falhas nos planos, baixa integração entre áreas e impactos na qualidade, produtividade e custos.', N'10015', N'01 - Imagens/01 - Antes/9661.jpeg', N'Os planos de manutenção não possuíam acompanhamento técnico contínuo, com baixa integração entre as áreas e identificação de melhorias ocorrendo apenas via abertura de notas', N'01 - Imagens/02 - Depois/9661.jpeg', N'Implantados fóruns semanais de revisão dos planos de manutenção, com maior integração entre as áreas, identificação antecipada de melhorias e aumento da qualidade dos planos e da eficiência da execução.', NULL, N'A implantação dos fóruns semanais atendeu à meta estabelecida, eliminando a falta de acompanhamento técnico e melhorando a integração entre as áreas, resultando em maior qualidade dos planos de manutenção, melhor produtividade na execução e identificação antecipada de oportunidades de melhoria.', N'A criação de rotinas estruturadas de revisão e a integração frequente entre as áreas permitem identificar melhorias antecipadamente, aumentar a qualidade dos planos de manutenção e melhorar a eficiência da execução.', 0, NULL, N'Melhor fluxo e eficiência na sucção de óleo, eliminação de obstruções e dificuldades operacionais, mais segurança e padronização no processo, melhoria da produtividade e qualidade do serviço executado.
INSERT INTO #PVC VALUES (9662, N'81061781', N'523252', N'Sinalização dos cabos da tenda de perfuratriz', NULL, N'Projects/Projetos', N'falta identificação e padronização dos cabos', N'melhorar a identificação e padronização dos cabos', N'10327', N'01 - Imagens/01 - Antes/9662.jpeg', N'Os cabos da tenda de perfuratriz estavam sem identificação visual padronizada, dificultando a localização, organização e inspeção.', N'01 - Imagens/02 - Depois/9662.jpeg', N'Foi realizada a sinalização e padronização dos cabos, facilitando a identificação, organização e manuseio, proporcionando mais agilidade, segurança e eficiência no processo.', NULL, N'Melhoria na organização e identificação dos cabos, redução do tempo de localização e inspeção, aumento da segurança operacional e maior eficiência no processo de perfuração', N'A padronização visual é essencial para melhorar a organização do ambiente de trabalho', 0, NULL, N'reduzido o tempo total para fazer o envio é 00:01:55 min, essa demanda não era realizada antes', '2026-04-27T00:00:00.000', '2026-04-28T11:20:27.000', N'81061781', NULL, NULL);
INSERT INTO #PVC VALUES (9663, N'81049566', N'502163', N'Caixas padronizadas', NULL, N'Refining/Refino', N'Ausência de identificação padronizada na caixa 02 DA FLOTAÇÃO.', N'Identificar a caixa 02 da flotação ', N'10362', N'01 - Imagens/01 - Antes/9663.jpeg', N'Ausência de TAG na caixa da flotação 2351 CX 02 ', N'01 - Imagens/02 - Depois/9663.jpeg', N'Identificado e tageado conforme padrão a caixa 2351CX02', NULL, N'Identificado conforme padrão Caixa 2351CX 02', N'Melhoria no 5s', 0, NULL, N'Definição clara do quantitativo de efetivo necessário, com suporte técnico para defesa do orçamento e inclusão da manutenção de pneus.', '2026-04-27T00:00:00.000', '2026-04-28T11:20:45.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (9664, N'81061965', N'81061965', N'Definição de Estoque de Rodas/Aros – Frotas Komatsu 830E e 930E', NULL, N'Others/Outros', N'Os itens de roda/aro das frotas Komatsu, apesar de possuírem política formal de estoques, não se enquadram nos critérios de itens estocáveis por apresentarem baixa recorrência de falhas e histórico de consumo não representativo, permanecendo sem parâmetros de estoque definidos, mesmo possuindo alto lead time e impacto operacional.', N'Definir níveis adequados de estoque de rodas/aros com base em metodologia estatística, garantindo disponibilidade operacional mesmo para itens não estocáveis.', N'10015', N'01 - Imagens/01 - Antes/9664.jpeg', N'Itens classificados como não estocáveis, sem definição de estoque mínimo, ideal ou máximo, com reposição reativa e risco associado ao alto lead time do fornecedor. Na Figura temos a falha de uma roda por trinca, na ocorrência não havia item em estoque para a troca.', N'01 - Imagens/02 - Depois/9664.jpeg', N'Aplicação da metodologia estatística de distribuição de Poisson para dimensionamento do estoque de segurança, considerando vida útil, frota atual e futura e lead time, mesmo com baixo histórico de falhas.', NULL, N'A aplicação da metodologia estatística de Poisson atendeu à meta proposta ao permitir a definição de níveis de estoque para itens não estocáveis, superando a limitação do baixo histórico de consumo e mitigando os riscos operacionais associados ao alto lead time e ao impacto desses componentes na disponibilidade das frotas.', N'Itens de baixa recorrência, mas alto impacto e lead time elevado, exigem abordagens estatísticas específicas para garantir a confiabilidade operacional.', 0, NULL, N'Ganho de produtividade', '2026-04-27T00:00:00.000', '2026-04-28T11:38:12.000', N'81061965', NULL, NULL);
INSERT INTO #PVC VALUES (9665, N'81049566', N'502163', N'Acionamentos 2101TC02', NULL, N'Crusher/Britadeira', N'Ausência de TAG para identificação dos acionamentos da 2101TC02', N'padronizar e elevar maturidade da área', N'10362', N'01 - Imagens/01 - Antes/9665.jpeg', N'Ausência de TAGS nos motores/redutores de Acionamento do 2101TC02 .', N'01 - Imagens/02 - Depois/9665.jpeg', N'Identificado e Tageado os acionamentos da correia 2101TC02. ', NULL, N'Realizado padronização dos Acionamentos da 2101TC02. ', N'melhoria na condição de 5s', 0, NULL, N'Com a implementação do grupo de cadeia de ajuda, espera-se:
INSERT INTO #PVC VALUES (9666, N'81027090', N'81016005', N'Amortecedor de choque- peça unica', NULL, N'Projects/Projetos', N'Com o amortecedor desmontado em partes, o tempo de montagem torna-se excessivamente elevado. Além disso, há problemas relacionados ao torque durante o uso, especialmente devido à influência da temperatura na remoção do top sub.', N'Segurança e tempo de manutenção', N'10015', N'01 - Imagens/01 - Antes/9666.jpeg', N'Com o amortecedor dividido em partes, o tempo de montagem é muito alto. Também há dificuldades no torque durante o uso, agravadas pela temperatura, o que dificulta a retirada do top sub e o surgimento de trincas.', N'01 - Imagens/02 - Depois/9666.jpeg', N'A integração do amortecedor e do choque em uma única peça reduzirá significativamente o tempo de montagem na máquina. Essa solução elimina a necessidade de torque no top sub, pois haverá apenas um componente, além de evitar o aquecimento necessário para a retirada do top sub.', NULL, N'Diminuir o tempo de montagem do conjunto e eliminar riscos operacionais associados ao torque e ao aquecimento, aumentando a segurança dos operadores e a eficiência do processo.', N'Segurança e simplificação do processo.', 0, NULL, N'Operational activities are no longer delayed ', '2026-03-10T00:00:00.000', '2026-04-28T11:58:03.000', N'81027090', NULL, NULL);
INSERT INTO #PVC VALUES (9667, N'81047036', N'81047661', N'Melhoria de acesso em área de mata', NULL, N'Others/Outros', N'Era um problema de acesso, pois no local existe condições perigosas podendo levar a quedas devido a aclives e declives acentuados.
INSERT INTO #PVC VALUES (9668, N'81049566', N'502163', N'2351CX04', NULL, N'Refining/Refino', N'Ausência de TAG padronizado na 2351CX04 DA FLOTAÇÃO', N'IDENTIFICAR CX04 CONFORME PADRÃO ', N'10362', N'01 - Imagens/01 - Antes/9668.jpeg', N'Ausência de TAG na 2351 CX 04', N'01 - Imagens/02 - Depois/9668.jpeg', N'Realizado TAG conforme padrão na 2351 CX 04', NULL, N'Concluído identificação da caixa 04.', N'melhorar maturidade 52', 0, NULL, N'Ongoing 5S initiative improves site conditions. ', '2026-04-27T00:00:00.000', '2026-04-28T12:51:05.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (9669, N'515697', N'515697', N'Coxins Painel elétrico XPC320', NULL, N'No Replication/Sem replicação', N'Durante o processo de perfuração o equipamento gera muita vibração e nesse painel está com muita vibração vindo a ocasionar falhas nos circuitos elétrico e cartões do PLC.', N'Diminuir/elimanr falhar no sistema elétrico ocasionado pela vibração', N'10150', N'01 - Imagens/01 - Antes/9669.jpeg', N'Devido o excesso de vibração da coluna de perfuração o painel elétrico vibrava fazendo com que os componentes elétricos folgassem vindo a causar falhas e até mesmo danificar algums peças como cartões do PLC.', N'01 - Imagens/02 - Depois/9669.jpeg', N'Foi instalado coxins na fixação dos painéis elétricos diminuindo consideravelmente a vibração reduzindo falhas  no sistema elétrico.
INSERT INTO #PVC VALUES (9670, N'81053475', N'81053475', N'Análise e Dimensionamento de Mão de Obra da Frazen', NULL, N'Open Pit/Poço aberto', N'O dimensionamento de mão de obra da Frazen era realizado pela própria contratada, sem validação técnica das demandas reais das atividades.', N'Analisar as demandas reais de atividades e dimensionar corretamente o efetivo necessário, garantindo aderência operacional e otimização de recursos.', N'10015', N'01 - Imagens/01 - Antes/9670.jpeg', N'O dimensionamento do efetivo era realizado exclusivamente pela Frazen, sem análise crítica das atividades, volumes de demanda ou validação pela área técnica.', N'01 - Imagens/02 - Depois/9670.jpeg', N'Dimensionamento revisado com base na análise das demandas reais de atividades, resultando em definição técnica do efetivo necessário, bem como a identificação da necessidade de ajuste do HH dos planos.', NULL, N'Foi realizada a análise detalhada das demandas de atividades, comparando volume, frequência e capacidade produtiva, permitindo o dimensionamento técnico do efetivo necessário.
INSERT INTO #PVC VALUES (9671, N'512018', N'512018', N'Proteção para acoplamento de bombas', NULL, N'Projects/Projetos', N'AS proteções atuais não estão de acordo com a norma NR13, oferecem risco de acidente com parte móveis.', N'garantir a segurança do operador', N'10015', N'01 - Imagens/01 - Antes/9671.jpeg', N'A proteção atual não está de acordo com a NR13, oferecendo risco de acidente com partes móveis, prensamento de mãos e dedos.', N'01 - Imagens/02 - Depois/9671.jpeg', N'Elaborado projeto conforme NR13, protegendo as partes móveis do equipamento, bem como, melhorando a visibilidade do acoplamento quando este estiver em funcionamento.', NULL, N'Elaborado projeto conforme NR13, protegendo as partes móveis do equipamento, bem como, melhorando a visibilidade do acoplamento quando este estiver em funcionamento.', N'Inspeção constante em equipamentos de partes giratórias', 0, NULL, N'Reduz tempo de espera do operador e elimina retrabalho do planejador ao buscar dados do ativo.', '2026-04-08T00:00:00.000', '2026-04-28T13:39:36.000', N'512018', NULL, NULL);
INSERT INTO #PVC VALUES (9672, N'81033256', N'607419', N'7 Shaft Shop Refresh', 3, N'Underground/Subterrâneo', N'Current conditions at the 7 Shaft shop did not support consistent execution of required on‑site equipment servicing and maintenance', N'Organize and set up 7 Shaft shop ', N'10070', N'01 - Imagens/01 - Antes/9672.jpeg', N'Unorganized Area, not set up  for performing equipment Maintenance and services.', N'01 - Imagens/02 - Depois/9672.jpeg', N'The area was cleaned, organized, and configured to support efficient equipment Maintenance activities.', NULL, N'The shop is now organized and properly set up, enabling Three Shaft equipment maintenance activities to be completed on site, delivering significant cost savings. ', N'The shop is now organized and properly set up, enabling three Shaft equipment maintenance activities to be completed on site and delivering significant cost savings.', 2000000, 3, N'Fabricar um local seguro para estacionamento da ponte rolante.', '2026-03-31T00:00:00.000', '2026-04-28T14:07:15.000', N'81033256', NULL, NULL);
INSERT INTO #PVC VALUES (9673, N'81023776', N'81023776', N'Acid bund pumpout', 1, N'No Replication/Sem replicação', N'214 Acid bund drain was blocked with debris causing the bund to continue filling with stormwater. ', N'Have an empty bund to troubleshoot the blocked drain', N'0', N'01 - Imagens/01 - Antes/9673.jpeg', N'Acid Bund continuously filling with rainwater with no way to drain, usually requires clean harbors resources to vacuum the water out to clean the acid bund drain screen.', N'01 - Imagens/02 - Depois/9673.jpeg', N'Sump pumps utilized to effectively drain the acid bund to the lift station in order to access screen of acid pump drain, resulting in cost savings and not needing to have clean harbors for approximately 5 days worth of resources to drain the bund.', NULL, N'Yes the Sump pumps were utilized to effectively drain the acid bund to the lift station in order to access screen of acid pump drain, resulting in cost savings and not needing to have clean harbors for approximately 5 days worth of resources to drain the bund.', N'Sumps can effectively be used instead of clean harbors resources', 15000, 3, N'Satisfação da equipe de execução, qualidade na montagem do sensor', '2026-04-27T00:00:00.000', '2026-04-28T14:21:04.000', N'81023776', NULL, NULL);
INSERT INTO #PVC VALUES (9674, N'81034398', N'81046992', N'Melhoria no Sistema de Sucção de Óleo', 1, N'Others/Outros', N'A mangueira utilizada para sucção de óleo possuía um material improvisado em sua extremidade, ocasionando restrição no fluxo.', N'Garantir maior eficiência e segurança no processo de sucção de óleo', N'10139', N'01 - Imagens/01 - Antes/9674.jpeg', N'A mangueira utilizada para sucção de óleo possuía um material improvisado em sua extremidade, ocasionando restrição no fluxo, risco de obstrução e baixa eficiência durante o processo de sucção. Além disso, a condição inadequada do dispositivo poderia gerar desperdício de tempo e dificuldade operacional.', N'01 - Imagens/02 - Depois/9674.jpeg', N'Foi realizada a substituição da extremidade improvisada da mangueira de sucção por um sistema adequado e mais eficiente, proporcionando melhor passagem do óleo e eliminando riscos de obstrução. A melhoria aumentou a eficiência do processo de sucção, trouxe mais confiabilidade para a atividade e garantiu melhores condições de operação e segurança para os colaboradores.', NULL, N'Sim, Após a melhoria realizada, o sistema passou a operar de forma mais eficiente, sem obstruções e com melhor desempenho na sucção do óleo. O problema identificado foi resolvido.', N'A padronização dos equipamentos reduz retrabalho e melhora a segurança durante as atividades', 0, NULL, N'Redução do risco dos colaboradores nas atividades de desobstrução dos amostradores.', '2026-04-11T00:00:00.000', '2026-04-28T14:35:04.000', N'81034398', NULL, NULL);
INSERT INTO #PVC VALUES (9675, N'81030250', N'81030250', N'Envio Automático Relatório IMOS', 1, N'Others/Outros', N'Necessidade de envio da carteira por responsabilidades de execução, programação, aprovisionamento, planejamento, e PGU, consolidando o relatório por idade da demanda, priorização em criticidade e segurança, e evolução.', N'Garantir que os processos estejam informados das demandas em aberto na carteira', N'10178', N'01 - Imagens/01 - Antes/9675.jpeg', N'Não havia o envio por e-mail da carteira antes dessa consolidação', N'01 - Imagens/02 - Depois/9675.jpeg', N'Foi realizada a consolidação das bases de ordem em aberto D e D-1, responsabilidades por etapa e a separação das parcelas de cada processo, resultando no envio de 6 e-mails que chegam em pelo menos 152 pessoas e grupos de e-mail', NULL, N'Sim, o email contem informações pertinentes as demandas abertas em carteira', N'Centralizar as informações das demandas em um único canal melhora o controle e a visibilidade da carteira.', 0, NULL, N'Redução expressiva do tempo de consulta, eliminação de tarefas manuais repetitivas, melhor visibilidade sobre os pacotes de manutenção e aumento da eficiência e assertividade nas decisões da engenharia de estratégia.', '2026-01-30T00:00:00.000', '2026-04-28T14:37:24.000', N'81030250', NULL, NULL);
INSERT INTO #PVC VALUES (9676, N'81053475', N'81053475', N'Análise de Demanda e Dimensionamento de Efetivo da Frota de Leves', NULL, N'Open Pit/Poço aberto', N'A frota de leves não possuía estudo técnico de dimensionamento de mão de obra, dificultando a definição do efetivo necessário e a defesa do orçamento.', N'Avaliar a demanda de trabalho da frota de leves e definir tecnicamente o efetivo necessário para execução das manutenções, incluindo pneus.', N'10015', N'01 - Imagens/01 - Antes/9676.jpeg', N'Não existia estudo de demanda de trabalho nem dimensionamento de efetivo para a frota de leves e manutenção de pneus.', N'01 - Imagens/02 - Depois/9676.jpeg', N'Dimensionamento realizado com base na demanda real, horas dos planos sistemáticos e definição do efetivo necessário.', NULL, N'Foi realizado um estudo detalhado da frota, avaliando a demanda de trabalho, as horas dos planos sistemáticos e calculando o efetivo necessário para manutenção geral e de pneus.', N'O dimensionamento técnico baseado em dados é fundamental para embasar decisões, garantir recursos adequados e fortalecer a defesa orçamentária.', 0, NULL, N'Redução significativa do tempo gasto em consultas, eliminação de navegação manual na IA07, melhor visibilidade sobre os materiais cadastrados e aumento da eficiência e assertividade na tomada de decisão da engenharia de estratégia de manutenção.', '2026-04-06T00:00:00.000', '2026-04-28T14:43:10.000', N'81053475', NULL, NULL);
INSERT INTO #PVC VALUES (9677, N'92000679', N'92000679', N'Assistente de Criação', 1, N'No Replication/Sem replicação', N'Criação manual de revisões no sistema SAP.', N'Reduzir Tempo de Processo', N'10234', N'01 - Imagens/01 - Antes/9677.jpeg', N'Anteriormente, a criação de revisão do caderno semanal de materiais eram criadas uma a uma.', N'01 - Imagens/02 - Depois/9677.jpeg', N'Automação para criação de revisões de caderno. 52 semanas criadas em menos de 60 segundos, reduzindo a chance de erros humanos, movimentos repetitivos e desperdício de tempo.', NULL, N'SIM, automatização de processo.', N'Ganho de tempo', 0, NULL, N'Garantir a segurança do colaborador quando em inspeção no equipamento, evitando o contato com partes móveis', '2026-04-27T00:00:00.000', '2026-04-28T14:45:36.000', N'92000679', NULL, NULL);
INSERT INTO #PVC VALUES (9678, N'81051255', N'81051255', N'Agilidade na Localização de Materiais no Armazém', 1, N'Others/Outros', N'Na operação 24 horas do armazém, ocorre frequentemente a dificuldade de localizar materiais solicitados fora do horário comercial. Os atendentes, em diversas situações, não conseguem identificar ou encontrar os itens necessários, o que gera atrasos no atendimento, aumenta o tempo de espera das áreas demandantes e compromete a eficiência da operação. A ausência de um processo de comunicação ágil e padronizado entre supervisores e gestores dificulta a resolução imediata desses casos, resultando em desperdício de tempo e impacto negativo na continuidade das atividades.', N'Garantir a rápida localização de materiais no armazém durante a operação 24h, reduzindo o tempo de espera e evitando falhas no atendimento.', N'10178', N'01 - Imagens/01 - Antes/9678.jpeg', N'Na operação 24 horas do armazém, os atendentes frequentemente não conseguem localizar determinados materiais solicitados fora do horário comercial. Essa dificuldade gera atrasos no atendimento, aumenta o tempo de espera das áreas demandantes e compromete a eficiência da operação. A falta de um canal de comunicação ágil e estruturado entre supervisores e gestores impede a rápida resolução desses casos, ocasionando desperdício de tempo e impacto negativo na continuidade das atividades.', N'01 - Imagens/02 - Depois/9678.jpeg', N'Antes da criação do grupo, a operação 24 horas do armazém sofria com dificuldades na localização de materiais fora do horário comercial, gerando atrasos e desperdícios. Depois da implementação do grupo de cadeia de ajuda no WhatsApp, os atendentes passaram a contar com suporte imediato de gestores e supervisores, conseguindo identificar rapidamente vários componentes e tornando a operação mais ágil, confiável e eficiente.', NULL, N'Comparando com a meta inicial e a declaração de problemas, o objetivo era reduzir atrasos e desperdícios na localização de materiais fora do horário comercial, garantindo maior agilidade e eficiência. O problema estava na dificuldade dos atendentes em encontrar componentes e na falta de comunicação ágil. Com o grupo de cadeia de ajuda, esses pontos foram superados: os materiais passaram a ser identificados rapidamente, os atrasos diminuíram e a comunicação tornou-se eficiente, atendendo plenamente à meta definida.', N'Comunicação ágil é essencial: ter um canal direto entre supervisores e gestores reduziu falhas e acelerou a resolução de problemas.', 0, NULL, N'Após a padronização do 5S, a meta estabelecida foi atendida. Os documentos passaram a ser armazenados exclusivamente em locais definidos e identificados, eliminando a permanência de materiais avulsos sobre as mesas. Observou-se melhoria significativa na organização do ambiente de trabalho, maior eficiência na localização de documentos e reforço da rastreabilidade do processo, alinhando a prática aos requisitos do ', '2026-04-08T00:00:00.000', '2026-04-28T14:53:01.000', N'81051255', NULL, NULL);
INSERT INTO #PVC VALUES (9679, N'81033256', N'607492', N'Increased Fuel Tank capacity at 3 shaft ', 1, N'Underground/Subterrâneo', N'The existing 9,000 L fuel tank was consistently depleted by the end of each weekend, resulting in production delays due to unplanned travel to 9 Shaft for re-fueling.', N'Reduce weekend refueling delays ', N'10118', N'01 - Imagens/01 - Antes/9679.jpeg', N'9,000 Liters fuel tank would empty every weekend and only filled up once emptied. ', N'01 - Imagens/02 - Depois/9679.jpeg', N'27,000 liters fuel tank, telemetry on the tank with Near North Fuels to fill up as required.', NULL, N'The increased fuel capacity has reduced operational delays', N'Having proper infrastructure can make crews more productive.', 0, NULL, NULL, '2026-04-02T00:00:00.000', '2026-04-28T14:59:12.000', N'81033256', NULL, NULL);
INSERT INTO #PVC VALUES (9680, N'81053475', N'81053475', N'Priorização Estratégica de Estudos de LCC com Base em Critérios Técnicos', NULL, N'Open Pit/Poço aberto', N'Não havia estudos de LCC  e não possuíam critérios definidos de priorização, dificultando a definição de foco e cronograma para elaboração dos LCC dos equipamentos de mina.', N'Criar uma matriz de priorização para definir, de forma técnica e estruturada, o cronograma de elaboração dos estudos de LCC dos equipamentos de mina.', N'10015', N'01 - Imagens/01 - Antes/9680.jpeg', N'Ausência de um método estruturado para priorizar os estudos de LCC, com execução baseada em demandas pontuais e sem critério comparativo entre os ativos.', N'01 - Imagens/02 - Depois/9680.jpeg', N'Matriz de priorização definida, utilizando critérios técnicos para direcionar o cronograma de elaboração dos estudos de LCC.', NULL, N'Foi desenvolvido um modelo de priorização considerando parâmetros como quantidade de estudos, relevância, maturidade, impacto, vida útil e quantidade de ativos, resultando na criação de uma matriz para definição do cronograma de LCC.', N'A aplicação de critérios objetivos melhora a tomada de decisão, aumenta a transparência e orienta o uso eficiente dos recursos técnicos.', 0, NULL, N'Less time wasted walking back and forth to the annex to pick up booklets.', '2026-03-20T00:00:00.000', '2026-04-28T15:04:28.000', N'81053475', NULL, NULL);
INSERT INTO #PVC VALUES (9681, N'81031229', N'81031229', N'Manual Chainfall Hoist Organization', 3, N'Refining/Refino', N'Our Chain falls were hung on a storage wall without the length of chain labeled on the hoist. We would grab the Chain falls and would have no idea what length of lifting chain we were dealing with. Very annoying.', N'Make our tool selection easier.', N'10193', N'01 - Imagens/01 - Antes/9681.jpeg', N'Previously, we had Chain Falls hanging there and it was difficult to identify how much lifting chain was coiled up in the bucket. We usually prefer to use different chain lengths depending on the application. We spent time handling chain and this was time wasted.', N'01 - Imagens/02 - Depois/9681.jpeg', N'We took out each Chain fall, measured the chain lengths and labeled the units with their respective lengths. We are now done wasting time messing around with chain handling to figure out which chain fall to select for a job.', NULL, N'Worked exactly as forecasted', N'Labeling is key for product identification', 0, NULL, N'Easy access to WHMIS labels.', '2026-04-15T00:00:00.000', '2026-04-28T15:12:50.000', N'81031229', NULL, NULL);
INSERT INTO #PVC VALUES (9682, N'607847', N'607847', N'RBB Remote blasting box antenna', 1, N'Underground/Subterrâneo', N'We were having problems with connection issues with our RBB''s remote blasting boxes, these boxes communicate to the surface blasting box through the radio leaky feed system', N'Get better signal for Blasting box', N'10176', N'01 - Imagens/01 - Antes/9682.jpeg', N'RBB Antenna was to long and was giving us communication issues with the leaky feed radio system.  ', N'01 - Imagens/02 - Depois/9682.jpeg', N'The antenna was shortened to achieve the desired frequency.  Orica-supplied antennas are designed to be cut to specific lengths to accommodate different frequency requirements.', NULL, N'Problem was solved', N'Have better communication with venders ', 0, NULL, N'Easy to understand bed level inside the 3RT.', '2026-04-28T00:00:00.000', '2026-04-28T15:49:16.000', N'607847', NULL, NULL);
INSERT INTO #PVC VALUES (9683, N'81030250', N'81030250', N'Planilha de ferias', 1, N'Others/Outros', N'Com frequência, mais de 4 ou 5 pessoas estavam de férias simultâneamente, o que acarretava em uma drástica diminuição do time em alguns períodos do ano', N'Controlar quantidade de pessoas de férias', N'10178', N'01 - Imagens/01 - Antes/9683.jpeg', N'Sem controle prévio', N'01 - Imagens/02 - Depois/9683.jpeg', N'Foi criada uma planilha dinâmica onde são registradas as intenções de férias em suas 3 parcelas, a planilha limita o quantitativo de pessoas com férias para o mesmo dia.', NULL, N'A quantidade de pessoas de férias simultaneamente foram devidamente controladas com a solução implementada', N'Processo bem controlado gera mais resultado', 0, NULL, NULL, '2026-04-27T00:00:00.000', '2026-04-28T15:59:28.000', N'81030250', NULL, NULL);
INSERT INTO #PVC VALUES (9684, N'81006670', N'81037072', N'Identificação da PEMT – Melhoria no Controle de Abastecimento', 1, N'Others/Outros', N'A PEMT não possuía tag de identificação.', N'Reduz tempo de espera do operador e elimina retrabalho do planejador ao buscar dados do ativo.', N'10144', N'01 - Imagens/01 - Antes/9684.jpeg', N'A PEMT não possuía tag de identificação. A ausência do tag dificultava a liberação e o registro correto da OM de abastecimento de combustível, gerando atrasos e risco de erro no apontamento.', N'01 - Imagens/02 - Depois/9684.jpeg', N'Foi confeccionado e fixado um tag de identificação no equipamento, padronizando conforme demais ativos da frota.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal#', N'Foco em eliminar atividades que não agregam valor (tempo, materiais, movimentação).', N'Com a identificação visível, a abertura da OM para abastecimento e outras atividades de manutenção ficou mais ágil e assertiva', 0, NULL, N'Decline in Copper Cliff Mine TRIF
INSERT INTO #PVC VALUES (9685, N'81049566', N'502163', N'Ponte segura', NULL, N'Refining/Refino', N'Ausência de proteção para o estacionamento ( garagem) da ponte rolante  2301-PR-01 
INSERT INTO #PVC VALUES (9686, N'496890', N'496890', N'Bucha de Sensor ', 1, N'Others/Outros', N'O sensor de velocidade da balança SCHENCK, não existia ponto de fixação fazendo com que fosse fixado de qualquer forma, sem garantia de qualidade, dificultando a montagem e a eficiência do sensor ', N'Otimizar tempo e melhorar qualidade na montagem do sensor da balança SCHENCK.', N'10184', N'01 - Imagens/01 - Antes/9686.jpeg', N'Os sensores adquiridos para a balança SCHENCK, não existia ponto de fixação no redutor, causando dificuldade para fixação do mesmo.', N'01 - Imagens/02 - Depois/9686.jpeg', N'Foi projetado e fabricado uma bucha de fixação com rosca, com passagem com interferência, com isso o sensor fixa na bucha com interferência, e a bucha é roscada no redutor garantindo precisão e melhor fixação, tudo prático e rápido.', NULL, N'Antes não tinha um padrão para montagem do sensor, pois a equipe ultilizavam improviso para fixar o sensor de qualquer maneira, hoje, o executante da atividade, somente fixa o sensor na bucha e monta a bucha roscada, fazendo os ajuste de proximidade.', N'Soluções vindo de dentro da empresa a custo zero', 0, NULL, N'Espera-se redução do lead time no processo de RAF e Garantias, com maior visibilidade e controle das etapas, permitindo acompanhamento em tempo real, priorização adequada das demandas, identificação rápida de desvios e tomada de decisão mais assertiva.', '2026-04-07T00:00:00.000', '2026-04-28T21:03:22.000', N'496890', NULL, NULL);
INSERT INTO #PVC VALUES (9687, N'81033873', N'81033873', N'Aumento da Disponibilidade Física dos Amostradores Metalúrgicos de Salobo 1 e 2', 1, N'Others/Outros', N'Constantes e diárias obstruções dos amostradores metalúrgicos Salobo 1 e 2. Impactando a disponibilidade física e a representatividade das amostras. ', N'Aumento DF para 90%', N'10306', N'01 - Imagens/01 - Antes/9687.jpeg', N'Constantes e diárias obstruções nos amostradores metalúrgicos devido material fora da especificação. Essa obstrução deixava o amostrador parado sendo necessário a utilização do PSI, causando uma menor representatividade nos resultados do teor de alimentação.  ', N'01 - Imagens/02 - Depois/9687.jpeg', N'Devido as constantes obstruções dos amostradores metalúrgicos devido material fora da especificação foi realizada uma avaliação em campo. Nessa avaliação e conforme os cálculos de diâmetro mínimo do amostrador para o novo diâmetro das partículas, aumentamos o diâmetro do amostrador primário de 2,5" para 4" (GM-5567).  
INSERT INTO #PVC VALUES (9688, N'517013', N'517013', N'Automatização da Consulta de Pacotes de Manutenção para Geração de Ordens', 1, N'Open Pit/Poço aberto', N'A consulta sobre quais pacotes de manutenção estavam marcados para envio às ordens exigia navegação manual nas listas de tarefas do SAP, tornando o processo lento, trabalhoso e pouco eficiente para a engenharia de estratégia de manutenção.', N'Disponibilizar de forma rápida, estruturada e automatizada a informação sobre o status dos pacotes de manutenção nas listas de tarefas, facilitando a tomada de decisão e melhorias no processo de planejamento.', N'10015', N'01 - Imagens/01 - Antes/9688.jpeg', N'Para identificar quais pacotes de manutenção estavam marcados para geração de ordens, os engenheiros de estratégia precisavam acessar a transação IA07 no SAP e abrir lista por lista, analisando operação por operação para verificar manualmente quais pacotes estavam sinalizados. Esse processo era extremamente demorado, repetitivo e trabalhoso, dificultava a visão consolidada da informação e consumia grande parte do tempo da equipe, que poderia estar focada em análises estratégicas e melhorias no processo de manutenção.', N'01 - Imagens/02 - Depois/9688.jpeg', N'Foi criada uma consulta no SAP HANA com extração automatizada da base de dados, permitindo a atualização automática do relatório. Além disso, foi desenvolvida uma página específica que apresenta de forma estruturada, clara e inteligente como cada pacote está marcado nas listas de tarefas do SAP. A solução centralizou a informação em um único local, possibilitou acesso rápido e confiável aos dados e apoiou diretamente a tomada de decisão e a melhoria contínua dos processos de planos e listas de tarefas.', NULL, N'O problema foi resolvido por meio da criação de uma consulta customizada no SAP HANA, integrada a um relatório com atualização automática, além do desenvolvimento de uma página específica para visualização estruturada dos pacotes de manutenção.', N'A automação da extração de dados e a consolidação das informações em relatórios analíticos aumentam significativamente a eficiência da engenharia e a qualidade das decisões.', 0, NULL, N'Maior previsibilidade e controle da DF necessária para os dias finais do mês, permitindo direcionamento das ações de manutenção e aumento da probabilidade de fechamento mensal acima da meta planejada.', '2026-04-20T00:00:00.000', '2026-04-28T22:44:43.000', N'517013', NULL, NULL);
INSERT INTO #PVC VALUES (9689, N'517013', N'517013', N'Automatização da Consulta de Materiais por Operação nas Listas de Tarefas do SAP', 1, N'Open Pit/Poço aberto', N'A verificação dos materiais (peças) cadastrados em cada operação das listas de tarefas exigia uma navegação manual no SAP, tornando o processo lento, trabalhoso e ineficiente para a engenharia de estratégia de manutenção.', N'Disponibilizar de forma rápida, estruturada e automatizada a informação dos materiais cadastrados por operação nas listas de tarefas, facilitando a tomada de decisão e melhorias nos planos de manutenção.', N'10015', N'01 - Imagens/01 - Antes/9689.jpeg', N'Para identificar quais materiais (peças) estavam cadastrados em cada operação das listas de tarefas, os engenheiros de estratégia de manutenção precisavam acessar a transação IA07 no SAP e abrir lista por lista, analisando operação por operação manualmente. Esse processo era demorado, repetitivo e trabalhoso, dificultava a visão consolidada das informações, consumia tempo excessivo da equipe e limitava outras atividades estratégicas relacionadas à melhoria dos planos e listas de tarefas.', N'01 - Imagens/02 - Depois/9689.jpeg', N'Foi criada uma consulta no SAP HANA com extração automatizada da base de dados, possibilitando atualização automática do relatório. Além disso, foi desenvolvida uma página específica que apresenta, de forma estruturada e inteligente, os materiais cadastrados em cada operação das listas de tarefas no SAP. A solução centralizou a informação em um único local, permitiu acesso rápido e confiável aos dados e apoiou a tomada de decisão e melhorias contínuas no processo de planos e listas de tarefas.', NULL, N'O problema foi resolvido por meio da criação de uma consulta customizada no SAP HANA, integrada a um relatório com atualização automática, além do desenvolvimento de uma página específica para visualização estruturada dos materiais por operação nas listas de tarefas.', N'A automação da extração de dados técnicos e a consolidação das informações em relatórios analíticos aumentam significativamente a eficiência da engenharia e a qualidade das decisões.', 0, NULL, N'Com isso, eliminou-se o uso de soluções improvisadas, aumentando a segurança da equipe e a confiabilidade da atividade.', '2026-04-20T00:00:00.000', '2026-04-28T23:03:09.000', N'517013', NULL, NULL);
INSERT INTO #PVC VALUES (9690, N'512018', N'512018', N'Proteção para acoplamento de bomba', 2, N'Projects/Projetos', N'A proteção atual não atende completamente a NR 13', N'Garantir a segurança do colaborador', N'10015', N'01 - Imagens/01 - Antes/9690.jpeg', N'A proteção atual não atende completamente a NR 13, oferecendo risco de acidente com parte rotativas.', N'01 - Imagens/02 - Depois/9690.jpeg', N'Elaborado projeto conforme norma NR13, protegendo partes móveis do equipamento, e proporcionando inspeção visual com segurança.', NULL, N'Elaborado projeto conforme norma NR13, protegendo partes móveis do equipamento, e proporcionando inspeção visual com segurança, garantido a proteção do colaborador no momento da inspeção sensitiva/preditiva', N'Criteriosidade em inspeção de equipamentos', 0, NULL, N'ganhamos tempo por evitar os retrabalhos nas lavagens e melhoramos a qualidade das nossas amostras evitando a contaminação.', '2026-04-09T00:00:00.000', '2026-04-28T23:48:11.000', N'512018', NULL, NULL);
INSERT INTO #PVC VALUES (9691, N'549066', N'549066', N'Padronização do local para armazenar documentos da operação Niquel', 3, N'No Replication/Sem replicação', N'Anteriormente, não havia definição formal de local ou método para gestão dos documentos físicos, resultando em sua permanência de forma avulsa sobre as mesas de trabalho até posterior arquivamento ou descarte. Essa condição caracterizava falha no controle documental, contribuindo para a desorganização do ambiente, risco de extravio de informações e comprometimento da rastreabilidade dos processos, em desacordo com os princípios de padronização, organização e controle previstos nos sistemas de gestão da qualidade.', N'Meta manter o ambiente organizado e o objetivo e facilitar o processo. ', N'10108', N'01 - Imagens/01 - Antes/9691.jpeg', N'Antes os documentos não tinha local definido, ficando avulso por cima das mesas ate alguém recolher e arquivar ou descartar. Poluindo o cenário e dificultando a rastreabilidade do processo.  ', N'01 - Imagens/02 - Depois/9691.jpeg', N'Após a implementação e padronização do 5S, com ênfase no Senso de Organização (Seiton), foi definido local específico e identificado para o recebimento e acondicionamento dos documentos físicos. Essa padronização eliminou a permanência de documentos avulsos sobre as mesas de trabalho, promovendo a organização do ambiente, melhoria da rastreabilidade do processo, redução do risco de extravio de informações e maior conformidade com os requisitos do sistema de gestão da qualidade relativos ao controle da informação documentada.', N'https://apps.powerapps.com', N'Declaração do problema:
INSERT INTO #PVC VALUES (9692, N'81046149', N'81046149', N'PORTIOLA DOS SENSOR ', NULL, N'Open Pit/Poço aberto', N'PORTIOLA DO SENSOR DO LSH DO CHUTE DE VALIMENTAÇÃO DA 2301TC02
INSERT INTO #PVC VALUES (9693, N'81036746', N'81036746', N'New SLAM booklet storage in Sat Lab', 3, N'Others/Outros', N'No easy access to new slam booklets in the building for workers. Technicians have to walk back to annex to get booklet.', N'Easy access to slam booklets', N'10045', N'01 - Imagens/01 - Antes/9693.jpeg', N'Workers had to leave the work area to go to the annex to get slam booklets. ', N'01 - Imagens/02 - Depois/9693.jpeg', N'Booklets can be stored in the sat lab and picked up easily while workers are in the field.', NULL, N'The problem was solved. ', N'Easy access to required items can same time.', 0, NULL, N'Redução do tempo aguardando aprovação das ordens.', '2026-04-28T00:00:00.000', '2026-04-29T05:00:24.000', N'81036746', NULL, NULL);
INSERT INTO #PVC VALUES (9694, N'81036746', N'81036746', N'WHMIS label storage', 3, N'Others/Outros', N'WHMIS labels currently only stored in the main lab, making it difficult to replace worn out labels or add labels to new sample containers while in work area. ', N'Easy access to WHMIS labels for sample containers', N'10045', N'01 - Imagens/01 - Antes/9694.jpeg', N'Workers would have to walk to main lab to get labels for sample bottles and other containers causing unneeded trips and time wastage.', N'01 - Imagens/02 - Depois/9694.jpeg', N'WHMIS labels are easily accessible in the sat lab for workers use.', NULL, N'The problem was solved.', N'Easy access to needed material caused less time waste.', 0, NULL, N'Redução do tempo de parada dos equipamentos associado à indisponibilidade de radiadores, contribuindo para maior produtividade operacional e menor esforço reativo das equipes de manutenção.', '2026-04-28T00:00:00.000', '2026-04-29T05:11:30.000', N'81036746', NULL, NULL);
INSERT INTO #PVC VALUES (9695, N'87000312', N'87000318', N'Installed sight glass at the Burner port of the No 3 RT.', 1, N'Refining/Refino', N'It was difficult to see inside the No.3 RT.', N'Make it possible to visualize the inside of the 3RT.', N'0', N'01 - Imagens/01 - Antes/9695.jpeg', N'While No 3 RT is operation, It was difficult to see the bed level inside the RT.', N'01 - Imagens/02 - Depois/9695.jpeg', N'Thanks to install sight glass, bed level of the No3 RT can be checked during operation.', NULL, N'Yes, we could achieve the target as we thought.', N'Asset ', 0, NULL, N'GARANTIR PADRÃO ÚNICO DE EXECUÇÃO PARA A SUBSTITUIÇÃO DO CILINDRO COM INCLUSÃO DA LÂMINA 854K, REDUZINDO TEMPO DE PARADA, RISCOS OPERACIONAIS E VARIABILIDADE DO PROCESSO.', '2026-04-27T00:00:00.000', '2026-04-29T05:36:33.000', N'87000312', NULL, NULL);
INSERT INTO #PVC VALUES (9696, N'87000312', N'87000318', N'Acid-resistant mortar was installed between the steel shell and the fire-resistant castable at the top of the 3RT.', 1, N'Refining/Refino', N'Top shell of the 3RT sometime has had corrosion.', N'Prevent corrosion at the top shell of the 3RT', N'0', N'01 - Imagens/01 - Antes/9696.jpeg', N'Top shell of the 3RT sometime has had corrosion. because, shell was made from mild steel.', N'01 - Imagens/02 - Depois/9696.jpeg', N'Thanks to install acid resistant mortar at the top shell of the No3 RT can be kept good condition for a long time.', NULL, N'Yes, we could achieve the target as we thought.', N'Asset ', 100000000, NULL, N'Redução de tempo de execução da atividade ', '2026-04-28T00:00:00.000', '2026-04-29T05:44:09.000', N'87000312', NULL, NULL);
INSERT INTO #PVC VALUES (9697, N'200959', N'81021520', N'Copper Cliff Mine Safety Recognition Program', NULL, N'Underground/Subterrâneo', N'CCM was experiencing a high number of recordable workplace injuries, as reflected from overall total recordable injury Frequency (TRIF) value for the complex. The elevated TRIF at CCM highlights improvements required for site safety performance and the need for better injury prevention efforts.', N'Reduce the TRIF number at Copper Cliff Mine', N'10238', N'01 - Imagens/01 - Antes/9697.jpeg', N'Before the safety recognition program was introduced, CCM recorded a Total Recordable Injury Frequency (TRIF) >15. This level was considered unacceptable and highlighted improvements were required in the effectiveness of the safety controls in place.
INSERT INTO #PVC VALUES (9698, N'521673', N'81047013', N'Suporte para béquer', 2, N'No Replication/Sem replicação', N'Antes, os béqueres ficavam armazenados no armário e, para retirá‑los, era necessário se abaixar repetidas vezes.', N'Otimizar a ergonomia', N'10366', N'01 - Imagens/01 - Antes/9698.jpeg', N'Antes, os béqueres ficavam armazenados no armário e, para retirá‑los, era necessário se abaixar repetidas vezes. Essa postura inadequada gerava esforço físico desnecessário e desconforto ergonômico, além de demandar mais tempo para pegar todos os béqueres que seriam utilizados, tornando a atividade menos prática e eficiente.', N'01 - Imagens/02 - Depois/9698.jpeg', N'Atualmente, os béqueres passaram a ser armazenados em uma caixa organizadora, proporcionando um acondicionamento mais adequado para a análise. Essa mudança trouxe melhorias significativas do ponto de vista ergonômico, pois elimina a necessidade de se abaixar repetidas vezes, reduzindo o esforço físico e o risco de desconfortos posturais. Além disso, a nova forma de armazenamento permite retirar todos os béqueres de uma só vez, otimizando o tempo de preparação, aumentando a produtividade e contribuindo para um ambiente de trabalho mais seguro e organizado.', NULL, N'Sim, a nova forma de armazenamento permite retirar todos os béqueres de uma só vez, otimizando o tempo de preparação, aumentando a produtividade e contribuindo para um ambiente de trabalho mais seguro e organizado.', N'minimização de risco ergonômico ', 0, NULL, N'ELIMINAÇÃO DAS OCORRÊNCIAS RELACIONADAS À CAUSA RAIZ
INSERT INTO #PVC VALUES (9699, N'81038384', N'81038384', N'Painel de controle de Raf´s e Garantias', NULL, N'Others/Outros', N'Não havia controle com visibilidade das etapas do processo.', N'visibilidade', N'10230', N'01 - Imagens/01 - Antes/9699.jpeg', N'O processo de acompanhamento das notas de RAF e Garantias apresentava falhas de controle e visibilidade. Não existia um controle estruturado que permitia visualizar de forma clara e consolidada as etapas do processo, o status real e o tempo em carteira de cada nota. Essa condição dificulta o acompanhamento adequado, a priorização das demandas e a identificação de desvios, resultando em atrasos na tomada de decisão e impacto negativo no lead time de entrega das notas de RAF e Garantias. 
INSERT INTO #PVC VALUES (9700, N'81016184', N'539074', N'Save de Matéria Prima', NULL, N'Others/Outros', N'Eixo de tambores que são substituído somente
INSERT INTO #PVC VALUES (9701, N'92000157', N'92000157', N'Relatório de DF de Recuperação', 1, N'Others/Outros', N'Ausência de um controle específico que traduzisse a necessidade futura de DF em ações claras e acompanháveis.', N'Criar um acompanhamento da DF de recuperação, permitindo visibilidade das necessidades de execução nos próximos dias e direcionamento das ações para garantir o atingimento da meta mensal.', N'10279', N'01 - Imagens/01 - Antes/9701.jpeg', N'A DF era analisada apenas de forma consolidada, sem visão clara da disponibilidade necessária para recuperação nos dias restantes do mês, dificultando o direcionamento das ações.', N'01 - Imagens/02 - Depois/9701.jpeg', N'Passou-se a acompanhar a DF de recuperação diariamente, com visão antecipada da necessidade de execução, permitindo atuação direcionada e maior previsibilidade no fechamento mensal do indicador. Além disso, foi desenvolvido uma projeção de fechamento para o mes com os dados da DF diarizada e Planejada para o restante do mês.', NULL, N'A falta de visibilidade da DF necessária para recuperação foi solucionada com o acompanhamento estruturado, atendendo à meta de apoiar o fechamento mensal acima do planejado.', N'Antecipar a necessidade de DF permite atuação proativa.', 0, NULL, N'EXECUÇÃO DA ATIVIDADE DE FORMA PADRONIZADA, SEGURA E CONTROLADA', '2026-04-20T00:00:00.000', '2026-04-29T13:12:58.000', N'92000157', NULL, NULL);
INSERT INTO #PVC VALUES (9702, N'512019', N'81050243', N'Confeccionado cavalete para cavaletar traseira da roc d65', NULL, N'Others/Outros', N'Para algumas atividades de manutenção em máquinas de pequeno diâmetro, é necessário cavaletear a parte traseira do equipamento. Anteriormente, não contávamos com cavaletes adequados para essa operação.  ', N'Segurança dos colaboradores', N'10324', N'01 - Imagens/01 - Antes/9702.jpeg', N'Para algumas atividades de manutenção em máquinas de pequeno diâmetro, é necessário cavaletear a parte traseira do equipamento. Anteriormente, não contávamos com cavaletes adequados para essa operação.  ', N'01 - Imagens/02 - Depois/9702.jpeg', N'Foi desenvolvido um projeto de cavalete específico, acompanhado de memorial de cálculo e dimensionamento adequado, garantindo que o cavaleteamento seja realizado de forma correta e segura.', NULL, N'Com isso, eliminou-se o uso de soluções improvisadas, aumentando a segurança da equipe e a confiabilidade da atividade.', N'melhores condiçoes seguras', 0, NULL, N'Ergonomia', '2026-04-10T00:00:00.000', '2026-04-29T13:24:19.000', N'512019', NULL, NULL);
INSERT INTO #PVC VALUES (9703, N'81033364', N'81033364', N'ILUMINAÇÃO PIAS VIA UMIDA', 1, N'No Replication/Sem replicação', N'Falta de iluminação adequada devido a instalação dos tubos de exaustão que ficaram na frente da lâmpada.', N'iluminação adequada para realização da atividade.', N'10366', N'01 - Imagens/01 - Antes/9703.jpeg', N'Com a instalação das novas exaustão e pias na via úmida percebemos que a iluminação que tínhamos na sala anteriormente  ficou prejudicada devido aos tubos ficarem na frente da iluminação dificultando assim uma boa visualização na hora da lavagem de vidraria. Diante desta situação foi visto que muitas vidrarias estavam sendo limpas incorretamente gerando assim um retrabalho e possivelmente a contaminação de algumas amostras.', N'01 - Imagens/02 - Depois/9703.jpeg', N'Foi solicitado junto a equipe de montagem a instalação de lâmpadas dentro das capelas de exaustão, trazendo assim uma boa visualização  das vidrarias no processo de lavagem evitando contaminação e trazendo mais segurança aos colaboradores durante essa atividade.', NULL, N'Com a nova iluminação ganhamos tempo na lavagem de vidrarias, evitamos retrabalhos e percebemos que havia riscos invisíveis que antes não conseguíamos enxergar de imediato com o pedaços de vidros nas pias e até mesmo no chão. A boa iluminação trouxe segurança para a sala.', N'Precisamos sempre buscar a melhor condição para a realização das nossas atividades de rotina.', 0, NULL, N'Padronização do óleo hidráulico para o Hydra XP 100, assegurando atendimento pleno aos requisitos de viscosidade e faixa de temperatura de operação de 60º dos equipamentos Sandvik DR416i, Epiroc PV351D e FlexROC D60/D65.
INSERT INTO #PVC VALUES (9704, N'487516', N'487516', N'Dimensionamento garantia operacional de componentes usando confiabilidade', 1, N'Projects/Projetos', N'Inexistência de metodologia para dimensionamento do número de componentes reservas. A elaboração do orçamento de componentes para atendimento às corretivas baseava somente no histórico de corretivas do ano anterior. A confiabilidade dos componentes não era considerada.', N'Melhorar acertividade do orçamento de manutenção da mina de 2027 para componentes reservas.', N'10008', N'01 - Imagens/01 - Antes/9704.jpeg', N'Inexistência de metodologia para dimensionamento do número de componentes reservas. A elaboração do orçamento de componentes para atendimento às corretivas baseava somente no histórico de corretivas do ano anterior. A confiabilidade dos componentes não era considerada. Desta forma, a assertividade quanto ao número de falhas esperadas era baixa, levando a erros no orçamento da manutenção.', N'01 - Imagens/02 - Depois/9704.jpeg', N'Foi elaborado o levantamento histórico no SAP das falhas de cada componente com suas respectivas vidas. Considerado também os componentes em operação atualmente. Realizada análise da confiabilidade, cálculo do número de falhas esperadas e posteriormente determinado o número de componentes reservas através da Distribuição de Poisson com base no nível de confiança desejado.', NULL, N'SIM.
INSERT INTO #PVC VALUES (9705, N'501925', N'501925', N'Haste de Instalação Segura', 2, N'Others/Outros', N'Antes era necessário solicitar montagem de andaime para acessar pontos de instalação de sensores de vibração nos moinhos verticais.', N'eliminar necessidade de andaime para instalação de sensores nos redutores dos moinhos verticais', N'10178', N'01 - Imagens/01 - Antes/9705.jpeg', N'Antes era necessário solicitar montagem de andaime para acessar pontos de instalação de sensores de vibração nos moinhos verticais. Demandando tempo maior para a execução da atividade, além dos riscos relacionados ao acesso por andaime.', N'01 - Imagens/02 - Depois/9705.jpeg', N'Foi realizada a aquisição de uma haste com garra para alcance dos pontos que necessitam montagede  andaime para acesso.', NULL, N'Eliminação do risco relacionado ao acesso por andaime', N'melhoria na segurança ao acessar equipamento.', 0, NULL, N'5S', '2026-04-28T00:00:00.000', '2026-04-29T13:46:55.000', N'501925', NULL, NULL);
INSERT INTO #PVC VALUES (9706, N'92000157', N'92000157', N'Relatório de Ordens Aguardando Aprovação', 1, N'Others/Outros', N'Ausência de um controle padronizado e visível das ordens de manutenção aguardando aprovação, resultando em atrasos na liberação das ordens, impacto nos processos seguintes', N'Criar um relatório para monitoramento das ordens aguardando aprovação, garantindo visibilidade, priorização e atuação proativa sobre os atrasos.', N'10279', N'01 - Imagens/01 - Antes/9706.jpeg', N'O acompanhamento era feito de forma dispersa pelo SAP, resultando em atrasos na aprovação das ordens e impactos nos processos seguintes.', N'01 - Imagens/02 - Depois/9706.jpeg', N'Foi implantado um relatório que permite acompanhamento ativo, priorização das ordens e atuação proativa sobre os atrasos.', NULL, N'A meta inicial foi atendida com a implantação do relatório, que passou a permitir acompanhamento e atuação proativa sobre as ordens, reduzindo perdas nos processos seguintes', N'Falta de visibilidade gera atrasos no processo de aprovação.', 0, NULL, N'Redução do desgaste da gaxeta
INSERT INTO #PVC VALUES (9707, N'81028405', N'81028405', N'Parque reserva radiadores', 1, N'No Replication/Sem replicação', N'Atualmente não existe um critério técnico definido para o dimensionamento do parque reserva mínimo de radiadores. As decisões de estoque são tomadas sem histórico consolidado de falhas, tempo de reposição ou criticidade do componente, o que gera risco tanto de indisponibilidade por falta de material quanto de excesso de capital imobilizado.', N'Estabelecer critério técnico para o dimensionamento do parque reserva mínimo de radiadores.', N'10015', N'01 - Imagens/01 - Antes/9707.jpeg', N'O parque reserva de radiadores não possui critério técnico definido. O dimensionamento é realizado sem padronização, sem histórico de falhas consolidado e sem consideração do tempo de reposição, resultando em decisões baseadas na percepção e maior risco de indisponibilidade operacional ou excesso de estoque', N'01 - Imagens/02 - Depois/9707.jpeg', N'O parque reserva mínimo de radiadores passa a ser definido com base em critério técnico padronizado, considerando histórico de falhas, criticidade do componente e tempo de reposição, proporcionando maior previsibilidade operacional e melhor equilíbrio do estoque.', NULL, N'A meta inicial de eliminar a ausência de critério técnico para o parque reserva de radiadores foi atendida. O processo evoluiu de decisões baseadas em percepção para um modelo padronizado, orientado por confiabilidade, tempo de reposição e risco operacional, com impactos positivos esperados na produtividade e no tempo de resposta da manutenção.', N'Padronizar critérios elimina decisões reativas, reduz riscos de parada e cria base para melhorias contínuas na gestão de sobressalentes.', 0, NULL, N'Redução de Custo:  
INSERT INTO #PVC VALUES (9708, N'81011654', N'81011654', N'LISTA TAREFAS - SUBST CIL INCL LÂMINA 854K', 1, N'Others/Outros', N'A SUBSTITUIÇÃO DO CILINDRO COM INCLUSÃO DA LÂMINA 854K APRESENTA DIFICULDADES NO PLANEJAMENTO E EXECUÇÃO DAS ATIVIDADES, DEVIDO À AUSÊNCIA DE UMA LISTA PADRONIZADA DE TAREFAS, GERANDO RETRABALHO, AUMENTO DO TEMPO DE PARADA DO EQUIPAMENTO E RISCOS OPERACIONAIS.', N'PADRONIZAR E IMPLEMENTAR UMA LISTA DE TAREFAS PARA A SUBSTITUIÇÃO DO CILINDRO COM INCLUSÃO DA LÂMINA 854K, VISANDO REDUZIR O TEMPO DE EXECUÇÃO, AUMENTAR A SEGURANÇA OPERACIONAL E MELHORAR A EFICIÊNCIA DO PLANEJAMENTO DA MANUTENÇÃO.', N'10279', N'01 - Imagens/01 - Antes/9708.jpeg', N'Antes da implementação do Kaizen, a atividade de substituição do cilindro com inclusão da lâmina 854K era executada sem uma lista de tarefas padronizada. As etapas do serviço variavam conforme a equipe envolvida, gerando falhas de comunicação entre planejamento, manutenção e operação.
INSERT INTO #PVC VALUES (9709, N'81050579', N'81006658', N'Abastecimento do comando final ', 1, N'Projects/Projetos', N' Durante o abastecimento de óleo lubrificante dos comandos finais das Escavadeira hidráulica 374F havia um grande derramamento causando assim desperdício e risco de contaminação do solo', N'Redução de desperdício, Redução  de tempo na atividade ', N'10144', N'01 - Imagens/01 - Antes/9709.jpeg', N' Durante o abastecimento de óleo lubrificante dos comandos finais das Escavadeira hidráulica 374F havia um grande derramamento, causando assim desperdício e risco de contaminação do solo.', N'01 - Imagens/02 - Depois/9709.jpeg', N'Foi confeccionado um dispositivo para auxiliar no abastecimento. Eliminando assim o desperdício de óleo e risco de contaminação do solo.', NULL, N'SIM', N'SENTIMENTO DE DONO ', 0, NULL, N'Ganhos Obtidos:  
INSERT INTO #PVC VALUES (9710, N'81013885', N'511655', N'REVITALIZAÇÃO DO SUPORTE DAS BOMBAS', 1, N'Others/Outros', N'Foi identificada a necessidade de intervenção no suporte das bombas devido ao desgaste estrutural e à corrosão avançada da estrutura metálica.', N' Conservação da estrutura.', N'10362', N'01 - Imagens/01 - Antes/9710.jpeg', N'Foi identificada a necessidade de intervenção no suporte das bombas devido ao desgaste estrutural e à corrosão avançada da estrutura metálica, ocasionados pela exposição contínua às intempéries e às condições operacionais da área. As condições observadas comprometiam a integridade do suporte e poderiam impactar na segurança e confiabilidade operacional do equipamento.', N'01 - Imagens/02 - Depois/9710.jpeg', N'Foi realizada a revitalização da pintura do suporte das bombas, com tratamento da superfície e aplicação de pintura industrial, restabelecendo a proteção contra corrosão e melhorando as condições de conservação da estrutura.', NULL, N'Foi realizada a revitalização da pintura do suporte das bombas, com tratamento da superfície e aplicação de pintura industrial.', N' Conservação da estrutura.', 0, NULL, N' Ganhos Obtidos:  
INSERT INTO #PVC VALUES (9711, N'81011654', N'81011654', N'LISTA DE TAREFAS  SUBST CIL ELEVA LÂMINA D11T D10T D9T  ', 2, N'Others/Outros', N'A SUBSTITUIÇÃO DO CILINDRO DE ELEVAÇÃO DA LÂMINA DO EQUIPAMENTO D11T D10 É REALIZADA SEM UMA LISTA DE TAREFAS PADRONIZADA, GERANDO VARIAÇÃO NA EXECUÇÃO, FALHAS DE PLANEJAMENTO, AUMENTO DO TEMPO DE PARADA, RETRABALHOS E RISCOS À SEGURANÇA OPERACIONAL, DEVIDO À DEPENDÊNCIA DO CONHECIMENTO INDIVIDUAL DAS EQUIPES.', N'DESENVOLVER E IMPLEMENTAR UMA LISTA DE TAREFAS PADRONIZADA PARA A SUBSTITUIÇÃO DO CILINDRO DE ELEVAÇÃO DA LÂMINA DO D11T D10, VISANDO REDUZIR O TEMPO DE EXECUÇÃO, AUMENTAR A SEGURANÇA, MELHORAR O PLANEJAMENTO DA MANUTENÇÃO E GARANTIR PADRÃO ÚNICO DE EXECUÇÃO.', N'10279', N'01 - Imagens/01 - Antes/9711.jpeg', N'Antes da implementação do Kaizen, a substituição do cilindro de elevação da lâmina do equipamento D11T D10 era executada sem uma lista de tarefas estruturada e padronizada. As atividades eram planejadas de forma genérica, com variação na sequência operacional, ausência de detalhamento de recursos, tempos e requisitos de segurança.
INSERT INTO #PVC VALUES (9712, N'81011654', N'81011654', N'LISTA TAREFAS  SUBST CILINDRO ELEVAÇÃO DO RIPPER  D11', NULL, N'Others/Outros', N'A SUBSTITUIÇÃO DO CILINDRO DE ELEVAÇÃO DO RIPPER É REALIZADA SEM UMA LISTA PADRONIZADA DE TAREFAS, RESULTANDO EM VARIAÇÕES NA EXECUÇÃO, RISCOS À SEGURANÇA, REPROCESSOS, AUMENTO DO TEMPO DE INTERVENÇÃO E POSSÍVEIS FALHAS NO RETORNO À OPERAÇÃO.', N'GARANTIR CONFORMIDADE TÉCNICA E QUALIDADE NA EXECUÇÃO', N'10279', N'01 - Imagens/01 - Antes/9712.jpeg', N'A SUBSTITUIÇÃO DO CILINDRO DE ELEVAÇÃO DO RIPPER ERA REALIZADA SEM UMA LISTA PADRONIZADA DE TAREFAS E SEM REFERÊNCIA AO NÚMERO DO PRO, FICANDO DEPENDENTE DA EXPERIÊNCIA INDIVIDUAL DA EQUIPE EXECUTANTE.
INSERT INTO #PVC VALUES (9713, N'81021983', N'81021983', N'MELHORIA DE DP', 1, N'No Replication/Sem replicação', N'O DP-0520-04 vinha apresentando falhas recorrentes de modulação, devido a erro de posição.
INSERT INTO #PVC VALUES (9714, N'81011654', N'81011654', N'LISTA TAREFAS SUBST  LÂMINA –D9T, D10T, D11T/R E 854K', NULL, N'Others/Outros', N'A SUBSTITUIÇÃO DE LÂMINAS NOS TRATORES D9T, D10T E D11T ERA REALIZADA SEM UMA LISTA PADRONIZADA DE TAREFAS E SEM VINCULAÇÃO AO NÚMERO DO PRO, RESULTANDO EM VARIAÇÕES NA EXECUÇÃO, FALTA DE RASTREABILIDADE, AUMENTO DO TEMPO DE INTERVENÇÃO, RETRABALHOS E RISCOS À SEGURANÇA OPERACIONAL.
INSERT INTO #PVC VALUES (9715, N'544566', N'544566', N'RELOCAÇÃO PAINEL DETECTOR DE METAL', 2, N'No Replication/Sem replicação', N'Local de dificil acesso para realizar atividades de manutenção, inspeção e calibração do detector de metal', N'melhorar Ergonomia do local da atividade ', N'0', N'01 - Imagens/01 - Antes/9715.jpeg', N'Painel do detetctor de metal se encontra em local de dificl acesso , devido haver projeção de material . Só é possivel acessar ao painel subindo todas as escadas do prédio e passarela do transportador TR2104SA-01', N'01 - Imagens/02 - Depois/9715.jpeg', N'Painel relocado para o outro lado do transportador sendo assim o usuário do pianel não irá mais dar a volta pelo prédio para acessá-lo', NULL, N'Redução do risco de projeção de material e melhora na ergonomia da atividade.', N'segurança é o foco', 0, NULL, N'1. Segurança - VIDA EM PRIMEIRO LUGAR
INSERT INTO #PVC VALUES (9716, N'989707', N'989707', N'Padronização óleo Hidráulico Frota Perfuratriz Grande Diâmetro e Pequeno Diâmetro', 1, N'Others/Outros', N'Padronização', N'Padronização óleo das frotas Perfuratriz Mina Sossego', N'10081', N'01 - Imagens/01 - Antes/9716.jpeg', N'Era utilizado óleo Hydra XP 32 e óleo Hydra XP 68 nas perfuratrizes de grande e pequeno diâmetro.', N'01 - Imagens/02 - Depois/9716.jpeg', N'Após a padronização inicial, foi identificada melhoria na performance dos equipamentos com a utilização do óleo hidráulico Hydra XP 68. No entanto, ao avançar na análise técnica visando à padronização dos óleos hidráulicos, considerando os parâmetros de viscosidade e temperatura de operação, concluiu-se que o óleo Hydra XP 100 atende integralmente os requisitos operacionais dos equipamentos Sandvik DR416i, Epiroc PV351D e FlexROC D60/D65.', NULL, N'Declaração do Problema (Situação Inicial)
INSERT INTO #PVC VALUES (9717, N'81050579', N'81013220', N'Suporte para maquina de soldagem ', 1, N'Projects/Projetos', N'O equipamento de soldagem apresentava limitações de mobilidade, dificultando seu deslocamento entre diferentes áreas de manutenção. ', N'Facilidade na desmobilização ', N'10144', N'01 - Imagens/01 - Antes/9717.jpeg', N'O equipamento de soldagem apresentava limitações de mobilidade, dificultando seu deslocamento entre diferentes áreas de manutenção. ', N'01 - Imagens/02 - Depois/9717.jpeg', N'Foi desenvolvido e confeccionado um dispositivo de suporte para equipamento de soldagem, visando otimizar a mobilidade e permitir o deslocamento do mesmo para diferentes postos de trabalho', NULL, N'Sim', N'Sentimento de dono ', 0, NULL, N'Using up to date certified equipment', '2026-04-01T00:00:00.000', '2026-04-29T16:57:13.000', N'81050579', NULL, NULL);
INSERT INTO #PVC VALUES (9718, N'983254', N'983254', N'Identificação do prédio da filtragem', NULL, N'Others/Outros', N'Falta de padronização de 5S na identificação do prédio da filtragem.', N'Adequação a identificação da identificação do prédio da filtragem.', N'10054', N'01 - Imagens/01 - Antes/9718.jpeg', N'Identificação do prédio da filtragem com placa desatualizada não adequada as boas práticas de 5S da área.', N'01 - Imagens/02 - Depois/9718.jpeg', N'Adequação da identificação do prédio da filtragem adequando as boas práticas de 5S da área.', NULL, N'Elevação de maturidade de 5S da área da filtragem.', N'Melhoria de S5', 0, NULL, N'MAIS VISIBILIDADE DAS POLIAS E CORREIAS DE ACIONAMNETO.', '2026-04-16T00:00:00.000', '2026-04-29T17:11:31.000', N'983254', NULL, NULL);
INSERT INTO #PVC VALUES (9719, N'525172', N'81054503', N' Implementação de Proteção de Gaxeta', 2, N'Others/Outros', N'Aumentar a confiabilidade operacional e a segurança do equipamento por meio da implementação de uma proteção de gaxeta, eliminando o acesso facilitado a partes móveis, reduzindo desgaste e vazamentos, e minimizando manutenções corretivas.', N'Aumentar a confiabilidade operacional e a segurança do equipamento por meio da implementação de uma proteção de gaxeta, eliminando o acesso facilitado a partes móveis, reduzindo o desgaste prematuro e os vazamentos', N'10229', N'01 - Imagens/01 - Antes/9719.jpeg', N'A gaxeta do equipamento operava sem proteção adequada, permanecendo exposta ao contato direto com polpa, respingos de material e acúmulo de sujeira.', N'01 - Imagens/02 - Depois/9719.jpeg', N'Com a proteção instalada, a gaxeta passou a operar em ambiente mais protegido, com menor exposição a contaminantes e eliminação do acesso direto às partes móveis.', NULL, N'Foi desenvolvida e instalada uma proteção física na região da gaxeta, confeccionada com material resistente e ajustada ao conjunto do equipamento. A proteção atua como barreira contra polpa, impurezas e respingos do processo, além de impedir o contato direto com partes móveis', N'A ausência de proteção adequada em componentes críticos, como a gaxeta, impacta diretamente na confiabilidade e na segurança do equipamento.', 0, NULL, N'com a implantação desse cartão ele fica no crachá da operação então facilita o acesso e conseguimos ter o controle dos registros feitos na nossa área e garantir segurança da equipe ', '2026-04-24T00:00:00.000', '2026-04-29T17:24:27.000', N'525172', NULL, NULL);
INSERT INTO #PVC VALUES (9720, N'81006670', N'81037072', N'Vedação das Flanges', 2, N'Others/Outros', N'Necessidade de lixar a superfície da flange para remover resíduos de material.
INSERT INTO #PVC VALUES (9721, N'81007243', N'81003514', N'Revestimento na Lamina MA', 1, N'Others/Outros', N'Desgaste da lamina devido atrito com o material', N'Proteção da lamina da motoniveladora', N'10139', N'01 - Imagens/01 - Antes/9721.jpeg', N'Desgaste da lamina devido atrito direto  com material .', N'01 - Imagens/02 - Depois/9721.jpeg', N'Feito reforço para garantir a durabilidade da lamina', NULL, N'Sim', N'Custo evitado', 1, 3, N'Fácil acesso e agilidade na realização das inspeções ', '2026-04-22T00:00:00.000', '2026-04-29T18:27:54.000', N'81007243', NULL, NULL);
INSERT INTO #PVC VALUES (9722, N'81006670', N'81037072', N'Suporte para Fixação do Bastão de Acionamento da Válvula do Canhão', 1, N'No Replication/Sem replicação', N'Desorganização, risco de dano ao componente e dificuldade de acesso durante a operação.', N'Cria local definido para o item, facilitando inspeções e checklists operacionais.', N'10144', N'01 - Imagens/01 - Antes/9722.jpeg', N'O bastão de abertura da válvula do canhão permanecia solto dentro da cabine, sem local apropriado para armazenamento. Isso gerava desorganização, risco de dano ao componente e dificuldade de acesso durante a operação.
INSERT INTO #PVC VALUES (9723, N'81006670', N'81037072', N'Otimização do Suporte do Joystick – Cabine de Operação  ', 1, N'Others/Outros', N'Suporte original do joystick era superdimensionado', N'Eliminar componentes desnecessários e liberar espaço na cabine ', N'10144', N'01 - Imagens/01 - Antes/9723.jpeg', N'O suporte original do joystick era superdimensionado, ocupava espaço excessivo na cabine e dificultava a ergonomia e o manuseio durante a operação.', N'01 - Imagens/02 - Depois/9723.jpeg', N'Foi confeccionado novo suporte simplificado, exclusivo para o joystick. O novo modelo eliminou componentes desnecessários, liberou espaço na cabine e melhorou a posição de trabalho do operador.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal#', N'Focam na triangulação entre engenharia, gestão e comportamento humano, utilizando cases reais para prevenir acidentes. A adoção de boas práticas, treinamentos contínuos e comunicação ativa é essencial para fortalecer a cultura de segurança e reduzir riscos operacionais', N' Identificação e controle imediato de riscos no ambiente de trabalho.', 0, NULL, N'Estabilidade da taxa e diminuição do número de paradas por baixa rotação.', '2026-04-28T00:00:00.000', '2026-04-29T18:39:08.000', N'81006670', NULL, NULL);
INSERT INTO #PVC VALUES (9724, N'81050431', N'81058947', N'PONTO DE INDENTIFICAÇAO DE MÁQUINAS ', NULL, N'Others/Outros', N'As máquinas eram organizadas e so tinha indentificao  no piso ', N'Visibilidade ', N'10139', N'01 - Imagens/01 - Antes/9724.jpeg', N'Antes a identificação era só no solo', N'01 - Imagens/02 - Depois/9724.jpeg', N'Foi criado uma placa estilo outdoor para facilitar a visualização ', NULL, N'Sim', N'Melhoria ', 0, NULL, N'Agora temos um controle maior e podemos identificar qualquer desvio antes do material chegar até ao armazém ', '2026-04-26T00:00:00.000', '2026-04-29T19:56:27.000', N'81050431', NULL, NULL);
INSERT INTO #PVC VALUES (9725, N'723908', N'723908', N'Acoplamento do mangote com engate rápido de abastecimento de Óleo da Máquina PZ-23', 2, N'Others/Outros', N'Dificuldade para realizar o abastecimento dos óleo
INSERT INTO #PVC VALUES (9726, N'81047456', N'486275', N'COMBOIO CV 59', 1, N'Others/Outros', N'Dificuldade no atendimento de abastecimento de óleos nas frotas de perfuratrizes, devido à distribuição inadequada dos óleos nos tanques.', N'Otimizar a configuração dos tanques, garantindo mais agilidade e eficiência no abastecimento.', N'10139', N'01 - Imagens/01 - Antes/9726.jpeg', N'Dificuldade no atendimento de abastecimento de óleos nas frotas de perfuratrizes, devido à distribuição inadequada dos óleos nos tanques.', N'01 - Imagens/02 - Depois/9726.jpeg', N'Otimizar a configuração dos tanques, garantindo mais agilidade e eficiência no abastecimento.
INSERT INTO #PVC VALUES (9727, N'81057254', N'81057254', N'Eliminação de Vazamentos e Aumento da Confiabilidade dos Contra‑Eixos por Reengenharia do Sistema de Vedação', 1, N'Crusher/Britadeira', N'Vazamentos crônicos de óleo lubrificante nos contra‑eixos dos britadores primários, causados por falhas recorrentes de vedação, resultando em alto consumo de óleo, aumento de HMC e exposição ao risco operacional.', N'Eliminar 100% das intervenções diárias de reabastecimento manual e não aquecer o contra‑eixos em 45 dias', N'10293', N'01 - Imagens/01 - Antes/9727.jpeg', N'Contra‑eixos operando com óleo ISO VG 220 (PAO) e vedação NBR de lábio simples, exigindo abastecimento manual 2x/dia, com consumo mensal de ~1.260 litros de óleo, custo de R$ 78,5 mil/mês e 24,07 h de HMC em 2026 devido a vazamentos recorrentes', N'01 - Imagens/02 - Depois/9727.jpeg', N'Alternativa disruptiva, com a aplicação de vedação Viton de lábio duplo, lubrificado com graxa semifluida (NLGI 00), buscando aumentar a contenção do lubrificante dentro do ativo.
