INSERT INTO #PVC VALUES (9729, N'502383', N'602789', N'SUPORTE PARA FERRAMENTAS', 1, N'Open Pit/Poço aberto', N'FERRAMENTAS JOGADAS NO CHÃO EM LUGAR INADEQUADO', N'GUARDADR FERRAMENTAS EM LOCAL APROPRIADO', N'0', N'01 - Imagens/01 - Antes/9729.jpeg', N'FERRAMENTAS ARMAZENADAS DE FORMA INCORRETA FIXADAS COM ABRAÇADEIRAS DE PLÁSTICO E NO GUARDA-CORPO.', N'01 - Imagens/02 - Depois/9729.jpeg', N'FOI FABRICADO E INSTALADO SUPORTE PARA ARMAZENAMENTO CORRETO DAS FERRAMENTAS.', NULL, N'FERRAMENTAS ARMAZENADAS CONFORME REGIMENTO DE 5`S DA EMPRESA', N'MELHOR AMBIENTE DE TRABALHO', 0, NULL, N'Houve ganho direto de produtividade, decorrente da maior disponibilidade operacional do sistema, redução de paradas não programadas e maior continuidade do processo produtivo.', '2026-04-25T00:00:00.000', '2026-04-30T04:16:44.000', N'502383', NULL, NULL);
INSERT INTO #PVC VALUES (9730, N'1007278', N'1007278', N'Fuel Offload replacement hose', 2, N'Others/Outros', N'Current fuel offload hose was expired and required to be replaced with up to date inspected hose', N'Maintain inspected equipment', N'0', N'01 - Imagens/01 - Antes/9730.jpeg', N'Current fuel offload hose was overdue on inspection and required replacement', N'01 - Imagens/02 - Depois/9730.jpeg', N'New fuel offload was ordered with up-to-date inspection and installed by Utilities', NULL, N'Out of date hose removed and new one installed that has up to date inspection', N'Maintain equipment cert on equipment', 0, NULL, N'Movimentação automática do spout do moinho de bolas 2', '2026-04-25T00:00:00.000', '2026-04-30T04:24:17.000', N'1007278', NULL, NULL);
INSERT INTO #PVC VALUES (9731, N'502383', N'502383', N'JANELA DE INSPEÇÃO', 1, N'Open Pit/Poço aberto', N'DIFICULDADE EM INSPECIONAR ACIONAMENTO DA BR 02 DEVIDO PROTEÇÃO DAS POLIAS.', N'MELHORAR VISIBILIDADE AO INSPECIONAR ACIONAMENTO', N'0', N'01 - Imagens/01 - Antes/9731.jpeg', N'FALTA DE VISIBILIDADE AO INSPECIONAR POLIAS E CORREIAS DO ACIONAMENTO DO BR 02 DEVIDO PROTEÇÃO.', N'01 - Imagens/02 - Depois/9731.jpeg', N'FOI FABRICADO E INSTALADO JANELA DE VISITA DE INSPEÇÃO MELHORANDO DIAGNÓSTICOS MAIS PRECISOS SOBRE DESGASTES DE CORREIAS E MELHORANDO VISIBILIDADE NA INSPEÇÃO DO MESMO.', NULL, N'INSPEÇÕES MAIS PRECISAS E DETALHADAS.', N'INSPEÇÃO MAIS PRECISA', 0, NULL, N'Melhora nos parâmetros de vibração do rolamento, indicando maior vida util', '2026-04-27T00:00:00.000', '2026-04-30T04:26:25.000', N'502383', NULL, NULL);
INSERT INTO #PVC VALUES (9732, N'81030963', N'81038507', N'Cartão direito de Recusa ', 1, N'Others/Outros', N'Para realizar o direito de recusa é necessário preencher um formulário no SISPAV. Pensando na facilidade, criamos um cartão com QR Code para parar a atividade em condição insegura', N'facilitar o acesso em caso de Direito de recusa', N'10079', N'01 - Imagens/01 - Antes/9732.jpeg', N'Para realizar o direito de recusa é necessário preencher um formulário no SISPAV. Pensando na facilidade, criamos um cartão com QR Code para parar a atividade em condição insegura', N'01 - Imagens/02 - Depois/9732.jpeg', N'Para exercer o direito de recusa, criamos um cartão com QR Code que dá autonomia ao operador para parar a atividade e acessar o formulário do SISPAV de forma prática, rápida e com registro.', NULL, N'Antes o processo era muito difícil de acesso por que na hora da atividade nem sempre os operadores tem o acesso rápido ao formulário', N'Com melhorias simples elevamos a qualidade do nosso processo e garantimos a segurança ', 0, NULL, N'A intervenção recuperou a eficiência da agitação do concentrado de cobre, proporcionando melhor homogeneização do meio, maior estabilidade operacional do equipamento e desempenho otimizado do processo de flotação.', '2026-04-23T00:00:00.000', '2026-04-30T09:10:39.000', N'81030963', NULL, NULL);
INSERT INTO #PVC VALUES (9733, N'124132', N'124132', N'New LED lighting installed in sound enclosure 10 kg line', 2, N'Refining/Refino', N'The lighting was poor in the sound enclosure of the 10 kg line.', N'Better lighting', N'#N/A', N'01 - Imagens/01 - Antes/9733.jpeg', N'We had old lighting in the sound enclosure with some not working at the 10 kg line.', N'01 - Imagens/02 - Depois/9733.jpeg', N'Electrical installed new LED lighting in the sound enclosure at the 10 kg line. ', NULL, N'Better lighting ', N'Better lighting', 0, NULL, N'Como resultado, as atividades de manutenção tornaram-se mais seguras, eficientes e produtivas, reduzindo riscos ocupacionais e aumentando a confiabilidade operacional.', '2026-04-06T00:00:00.000', '2026-04-30T09:26:55.000', N'124132', NULL, NULL);
INSERT INTO #PVC VALUES (9734, N'81030963', N'81047196', N'Ferramentas Norteando Segurança ( Cartão com Qr code)', 1, N'Others/Outros', N'Foi criado um projeto chamado norteando segurança onde todo o efetivo precisa fazer auditorias semanais nos postos equipamento afim de eliminar riscos na nossa operações temos 6 ferramentas forms onde podemos registrar as inspeções criamos um cartão para anexar esses Qrcodes', N'deixar todas as ferramentas de inspeção que foram criadas de fácíl acesso para todo o efetivo armazém ', N'10079', N'01 - Imagens/01 - Antes/9734.jpeg', N'Foi criado um projeto chamado norteando segurança onde todo o efetivo precisa fazer auditorias semanais nos postos equipamento afim de eliminar riscos na nossa operações temos 6 ferramentas forms onde podemos registrar as inspeções criamos um cartão para anexar esses Qrcodes', N'01 - Imagens/02 - Depois/9734.jpeg', N'Foi criado o projeto Norteando a Segurança, no qual todo o efetivo realiza auditorias semanais nos postos e equipamentos. As inspeções são registradas em 6 Forms, acessados por QR Codes em um cartão', NULL, N'Antes tínhamos que preencher  em link agora podemos acessar direto no celular apenas scaneando o qrcode ', N'Melhorias simples impactam a segurança dos nossos processos ', 0, NULL, N'Redução de tempo para leitura e interpretação de dados e tendências da qualidade de água industrial da Usina Salobo.', '2026-04-23T00:00:00.000', '2026-04-30T09:29:37.000', N'81030963', NULL, NULL);
INSERT INTO #PVC VALUES (9735, N'124132', N'124132', N'Replacing old moldy fridge', 2, N'Refining/Refino', N'We had an old fridge that was very dirty and had some mold in it.', N'Replacing old fridge', N'#N/A', N'01 - Imagens/01 - Antes/9735.jpeg', N'We had an old fridge that was very dirty and had mold in it.', N'01 - Imagens/02 - Depois/9735.jpeg', N'We purchased a new fridge for the employee''s lunchroom.', NULL, N'New fridge will be maintained/cleaned on a weekly basis.', N'New fridge ', 0, NULL, N'Como resultado, houve aumento da confiabilidade operacional, redução de paradas não programadas e maior segurança para as equipes envolvidas.', '2026-04-27T00:00:00.000', '2026-04-30T09:33:21.000', N'124132', NULL, NULL);
INSERT INTO #PVC VALUES (9736, N'81011163', N'81062557', N'OTIMIZAÇÃO DO COMPARTILHAMENTO DE TORQUE NA TCLD', 1, N'Others/Outros', N'Desbalanceamento de corrente dos motores da TCLD e níveis elevados de corrente.', N'Equalizar a corrente entre os motores; reduzir o nivel medio de corrente; aumentar a estabilidade operacional; possibilitar ganho de taxa horária com segurança', N'10081', N'01 - Imagens/01 - Antes/9736.jpeg', N'Os motores da TCLD operavam com distribuição de carga não totalmente equilibrada, o sistema é acionado por inversores ABB modelo ACS880, responsáveis pelo controle de velocidade e compartilhamento de torque entre motores, nesse cenário temos:
INSERT INTO #PVC VALUES (9737, N'81030963', N'81055853', N'Controle de componentes reformados ', 1, N'Others/Outros', N'Todos os componentes reformados e preservados chegavam sem termos visibilidade consolidada do material.', N'Eliminar vários controles em planilhas paralelas ', N'10079', N'01 - Imagens/01 - Antes/9737.jpeg', N'Todos os componentes reformados e preservados chegavam sem termos visibilidade consolidada do material.', N'01 - Imagens/02 - Depois/9737.jpeg', N'Os componentes reformados e preservados não possuíam visibilidade consolidada. Diante disso, surgiu a iniciativa de criar um BI para controle e acompanhamento nos FMDS.', NULL, N'Antes nosso processo era sem padrão desorganizado e com vários controles paralelos ', N'Com um BI simples temos uma visão geral do material que vamos receber e se estão vindo nas condições adequadas', 0, NULL, N'Facilidade e confiabilidade no preenchimento das informações de bloqueio', '2026-04-29T00:00:00.000', '2026-04-30T09:52:48.000', N'81030963', NULL, NULL);
INSERT INTO #PVC VALUES (9738, N'81056249', N'81056448', N'Proteção do Motor M5 do soprador (BR-2001-01) contra queda de água', 2, N'Projects/Projetos', N'Após a realocação do motor M5 do soprador BB-2001, foi identificada a incidência de queda direta de água sobre o motor e a caixa de ligação elétrica.
INSERT INTO #PVC VALUES (9739, N'81023633', N'81023633', N'Do descontrole à excelência: Transformação da Gestão de Bloqueios ', 3, N'Others/Outros', N'Os dispositivos de bloqueio não possuíam padronização visual nem organização por área, dificultando a identificação e controle durante as atividades.', N'Organizar e padronizar os dispositivos de bloqueio, visando a identificação rápida, melhoria na gestão visual e aumento da segurança operacional', N'10064', N'01 - Imagens/01 - Antes/9739.jpeg', N'Cenário de desorganização e ausência de padronização na disposição dos dispositivos de bloqueio, com baixa visibilidade e controle. A condição gerava perda de tempo na localização, fragilidade na rastreabilidade e aumento da exposição a riscos operacionais.', N'01 - Imagens/02 - Depois/9739.jpeg', N'Transformação do cenário por meio da implantação de gestão visual, com padronização e segregação dos dispositivos de bloqueio por área e processo. O resultado foi um ambiente organizado, com alto nível de controle, rastreabilidade e agilidade, elevando o padrão de segurança e eficiência operacional.', NULL, N'O problema foi resolvido, pois a organização e padronização eliminaram a dificuldade de identificação e melhoraram o controle dos bloqueios ', N'A padronização visual e organização dos recursos facilitam o controle operacional e reduzem falhas no processo.,', 0, NULL, N'Improved Quality ', '2026-04-29T00:00:00.000', '2026-04-30T11:25:05.000', N'81023633', NULL, NULL);
INSERT INTO #PVC VALUES (9740, N'81046953', N'81055527', N'Implantação de Portão de Controle de acesso', 2, N'Others/Outros', N'A área do piso superior apresentava acesso livre sem qualquer tipo de bloqueio físico, mesmo sendo uma região próxima aos equipamentos e com potencial de atividades operacionais e de manutenção. Essa condição permitia a circulação indevida de pessoas, durante içamentos de carga e atividades críticas.', N'Reduzir circulação de pessoas na área, elevando o nível de segurança.', N'10362', N'01 - Imagens/01 - Antes/9740.jpeg', N'A área do piso superior apresentava acesso livre sem qualquer tipo de bloqueio físico, mesmo sendo uma região próxima aos equipamentos e com potencial de atividades operacionais e de manutenção. Essa condição permitia a circulação indevida de pessoas, durante içamentos de carga e atividades críticas.', N'01 - Imagens/02 - Depois/9740.jpeg', N'Foi implementado um portão metálico com identificação visual padronizada, promovendo o bloqueio físico controlado do acesso à área. A adequação elevou significativamente o nível de segurança operacional, mitigando a exposição a riscos de acidentes e assegurando maior controle de acesso a pessoas não autorizadas. Adicionalmente, a melhoria contribuiu para a organização e disciplinamento do fluxo de pessoas, fortalecendo as práticas de prevenção, conformidade com os requisitos de segurança e a integridade das operações no ambiente de filtragem.', NULL, N'Sim, houve redução da circulação de pessoas não autorizadas na área com a implantação do portão metálico.', N'Olhar atento a oportunidades de melhoria da segurança do local de trabalho.', 0, NULL, N'Antes o equipamento permanecia inoperante por cerca de 15 minutos para abastecimento após a melhoria equipamento vai continuar em operação no modo perfuração aumentando a produtividade e com segurança', '2026-04-15T00:00:00.000', '2026-04-30T11:50:33.000', N'81046953', NULL, NULL);
INSERT INTO #PVC VALUES (9741, N'839373', N'839373', N'Tanque do castelinho', 1, N'Concentration/Concentração', N'Tanque com volume abaixo do necessário para os novos parâmetros de processo', N'Aumentar o volume de material (água de processo) no tanque', N'10362', N'01 - Imagens/01 - Antes/9741.jpeg', N'Tanque em estado de corrosão e com volume limitado para a nova demanda de ROP da moagem', N'01 - Imagens/02 - Depois/9741.jpeg', N'Novo tanque do castelinho com 23% de volume util', NULL, N'Meta atingida', N'As demandas de ROP precisam acompanhar as adequações nas instalações', 0, NULL, N' Outro fator positivo é que agora teremos menos tempo de exposição do colaborar frente as telas.', '2026-04-17T00:00:00.000', '2026-04-30T11:58:56.000', N'839373', NULL, NULL);
INSERT INTO #PVC VALUES (9742, N'516091', N'81040392', N'Tanque de inox do DT-02 flotação', 1, N'Concentration/Concentração', N'O tanque anteriormente instalado, fabricado em aço, encontrava-se em avançado estado de desgaste, apresentando degradação estrutural acentuada e comprometimento de sua integridade ao longo do tempo. Essa condição resultava em baixa confiabilidade operacional, elevada frequência de manutenções corretivas e maior probabilidade de falhas, impactando negativamente a disponibilidade do equipamento, a segurança da equipe e a estabilidade do processo.', N'Redução de paradas corretivas no Tanque', N'10362', N'01 - Imagens/01 - Antes/9742.jpeg', N'O tanque anteriormente instalado, fabricado em aço, encontrava-se em avançado estado de desgaste, apresentando degradação estrutural acentuada e comprometimento de sua integridade ao longo do tempo. Essa condição resultava em baixa confiabilidade operacional, elevada frequência de manutenções corretivas e maior probabilidade de falhas, impactando negativamente a disponibilidade do equipamento, a segurança da equipe e a estabilidade do processo.', N'01 - Imagens/02 - Depois/9742.jpeg', N'Com a instalação do novo tanque em aço inoxidável, foi alcançado um aumento significativo da vida útil do equipamento, associado à expressiva redução das manutenções recorrentes. Essa melhoria elevou o nível de segurança da equipe, ao minimizar a necessidade de intervenções operacionais no equipamento, reduzindo a exposição dos colaboradores a riscos. Como resultado, houve também ganho direto de produtividade, decorrente da maior disponibilidade operacional do sistema, redução de paradas não programadas e maior continuidade do processo produtivo.', NULL, N'Sim, Houve redução de paradas corretivas no Tanque com a substituição do material.', N'A intervenção reforça a importância de revisar padrões técnicos e incorporar melhorias como prática contínua, prevenindo reincidência de problemas semelhantes.', 0, NULL, N'Se ganha em tempo e produtividade após a mudança sistêmica.', '2025-11-12T00:00:00.000', '2026-04-30T12:06:37.000', N'516091', NULL, NULL);
INSERT INTO #PVC VALUES (9743, N'839373', N'839373', N'Movimentação Spout bolas 2', NULL, N'Concentration/Concentração', N'Movimentação manual do spout do moinho de bolas 2', N'Automatizar a movimentação do spout do moinho de bolas 2', N'10362', N'01 - Imagens/01 - Antes/9743.jpeg', N'Spout do moinho de bolas 2 sem o motor hidráulico para movimentação', N'01 - Imagens/02 - Depois/9743.jpeg', N'Spout do moinho de bolas 2 com o motor hidráulico instalado', NULL, N'Problema resolvido. A movimentação do spout que demanda 6 hs de atividade, agora pode ser feira em 2,42 min', N'É possível fazer diferente ', 0, NULL, N'Eliminar condições que impacta no processo e gerem desvios de parâmetros de controle .', '2026-04-17T00:00:00.000', '2026-04-30T12:10:42.000', N'839373', NULL, NULL);
INSERT INTO #PVC VALUES (9744, N'839373', N'839373', N'Rolamento dupla carreira de esfera soprador', NULL, N'Concentration/Concentração', N'Os rolamentos (6320 C3) usados anteriormente geravam falha na gaiola o que ocasionava a troca frequente dos mesmos ( a cada quinze dias)', N'Eliminar as falhas nas gaiolas dos rolamentos (6320 C3) usados anteriormente', N'10362', N'01 - Imagens/01 - Antes/9744.jpeg', N'Rolamento (6320 C3) usado anteriormente nos sopradores', N'01 - Imagens/02 - Depois/9744.jpeg', N'Novo rolamento (21320E) aplicado no soprador (2351 VT 01R). Rolamento mais robusto e com maior capacidade de carga radial e axial', NULL, N'Problema resolvido', N'Podemos melhor os processos e eliminar condições não desejadas', 0, NULL, N'Eliminar condições que impacta no 
INSERT INTO #PVC VALUES (9745, N'81007328', N'81007328', N'Substituição do rotor do agitador da 2351CF15.', 1, N'Concentration/Concentração', N'A Célula de Flotação 2351CF15 apresentava elevado nível de degradação no rotor do agitador, com desgaste significativo das pás, o que comprometia a eficiência da agitação do concentrado de cobre durante a operação. Essa condição resultava em desempenho operacional insatisfatório do equipamento, afetando negativamente a estabilidade e a eficiência do processo de flotação.', N'Melhorar a condição de operação do equipamento', N'10362', N'01 - Imagens/01 - Antes/9745.jpeg', N'A Célula de Flotação 2351CF15 apresentava elevado nível de degradação no rotor do agitador, com desgaste significativo das pás, o que comprometia a eficiência da agitação do concentrado de cobre durante a operação. Essa condição resultava em desempenho operacional insatisfatório do equipamento, afetando negativamente a estabilidade e a eficiência do processo de flotação.', N'01 - Imagens/02 - Depois/9745.jpeg', N'Foi realizada a substituição do rotor do agitador da Célula de Flotação 15, restabelecendo suas condições normais de operação. A intervenção recuperou a eficiência da agitação do concentrado de cobre, proporcionando melhor homogeneização do meio, maior estabilidade operacional do equipamento e desempenho otimizado do processo de flotação.', NULL, N'Sim, Houve melhoria na condição de operação do equipamento.', N'Confiabilidade do equipamento reflete na produtividade: Equipamentos em boas condições garantem melhor desempenho do processo e menor risco de paradas.', 0, NULL, N'Eliminar condições de sujidade e aspecto do ambiente ', '2026-04-14T00:00:00.000', '2026-04-30T12:38:35.000', N'81007328', NULL, NULL);
INSERT INTO #PVC VALUES (9746, N'516091', N'81047018', N'Acesso para o AM14 da Flotação', 2, N'Others/Outros', N'Anteriormente, o acesso era realizado por meio de andaime, exigindo a utilização obrigatória de cinturão de segurança, com impacto negativo na ergonomia da atividade. Essa condição apresentava elevado risco de queda em altura, além de dificultar a mobilidade do colaborador e o manuseio adequado das ferramentas, comprometendo a eficiência e a segurança das atividades de manutenção', N'Eliminar o trabalho em altura e melhorar a ergonomia dos trabalhadores', N'10362', N'01 - Imagens/01 - Antes/9746.jpeg', N'Anteriormente, o acesso era realizado por meio de andaime, exigindo a utilização obrigatória de cinturão de segurança, com impacto negativo na ergonomia da atividade. Essa condição apresentava elevado risco de queda em altura, além de dificultar a mobilidade do colaborador e o manuseio adequado das ferramentas, comprometendo a eficiência e a segurança das atividades de manutenção', N'01 - Imagens/02 - Depois/9746.jpeg', N'Com a implantação do novo acesso por meio de plataforma fixa, foi eliminada a necessidade de trabalho em altura anteriormente realizado com andaime. Essa melhoria proporcionou um avanço significativo nas condições de segurança, reduzindo o risco de queda. Além disso, houve uma melhora na ergonomia da atividade, permitindo postura adequada, maior estabilidade e facilidade no manuseio de ferramentas. Como resultado, as atividades de manutenção tornaram-se mais seguras, eficientes e produtivas, reduzindo riscos ocupacionais e aumentando a confiabilidade operacional.', NULL, N'Sim, conseguimos eliminar o trabalho em altura e melhorar a ergonomia dos trabalhadores.', N'Melhorias ergonômicas impactam diretamente a produtividade e a qualidade da manutenção, permitindo melhor postura, estabilidade e manuseio seguro das ferramentas.', 0, NULL, N'Redução  dos acionamentos do suprimentos referente as regularizações de pagamento ao fornecedor.', '2025-07-28T00:00:00.000', '2026-04-30T12:49:27.000', N'516091', NULL, NULL);
INSERT INTO #PVC VALUES (9747, N'81021009', N'81021009', N'Melhoria da Gestão de Informações e Monitoramento das Tendências da Qualidade da Água na Usina Salobo', 1, N'Others/Outros', N'Geração de múltiplos relatórios em Excel, cuja análise demanda de 2 a 3 horas, com informações não consolidadas, dificultando a interpretação e a identificação de tendências de melhoria ou deterioração da qualidade da água.', N'Aprimorar a leitura e o entendimento dos parâmetros de controle da água industrial nas torres de refrigeração das usinas Salobo.', N'10293', N'01 - Imagens/01 - Antes/9747.jpeg', N'Quantidade elevada de relatórios, tornando necessária a recorrência a dados passados para análise de tendências e dificultando o entendimento e a decisão quanto ao tratamento da água.', N'01 - Imagens/02 - Depois/9747.jpeg', N'Melhor visualização das tendências da qualidade da água por meio de painéis de BI, permitindo a rápida compreensão dos parâmetros de controle facilitando a tomada de decisão para a aplicação do tratamento mais adequado.', NULL, N'A interpretação dos dados passou a ser mais simples e direta, viabilizando a análise rápida das tendências de qualidade da água industrial de maneira individualizada por torre', N'Dados consolidados em uma ferramenta de gestão são essenciais para decisões mais assertivas e para o gerenciamento eficaz de todo o processo.', 0, NULL, N'Antes da implementação do Kaizen, não existia um padrão para cadastro do local de instalação /Equipamento.', '2026-04-29T00:00:00.000', '2026-04-30T13:21:38.000', N'81021009', NULL, NULL);
INSERT INTO #PVC VALUES (9748, N'516091', N'81040443', N'Novo tanque do castelinho do espeçador', 1, N'Others/Outros', N'O tanque anterior, fabricado em aço, possuía capacidade de 14.000 litros e apresentava baixa durabilidade, o que acarretava a necessidade de manutenções frequentes e recorrentes. Além disso, sua capacidade limitada impactava diretamente a operação, restringindo o volume de armazenamento e resultando em menor eficiência produtiva em função das paradas e reabastecimentos mais frequentes.', N'Mais capacidade e menos paradas operacionais.', N'10362', N'01 - Imagens/01 - Antes/9748.jpeg', N'O tanque anterior, fabricado em aço, possuía capacidade de 14.000 litros e apresentava baixa durabilidade, o que acarretava a necessidade de manutenções frequentes e recorrentes. Além disso, sua capacidade limitada impactava diretamente a operação, restringindo o volume de armazenamento e resultando em menor eficiência produtiva em função das paradas e reabastecimentos mais frequentes.', N'01 - Imagens/02 - Depois/9748.jpeg', N'Foi realizada a substituição do tanque de aço com capacidade de 14.000 litros por um novo tanque com capacidade de 25.000 litros. Essa atualização representou um aumento significativo na capacidade de armazenamento, ampliando a autonomia operacional do sistema.
INSERT INTO #PVC VALUES (9749, N'527706', N'527706', N'Implantação do Painel de Monitoramento de Gastos no Depósito ROD1', 1, N'No Replication/Sem replicação', N'Antes da iniciativa, não existia um painel consolidado de controle e acompanhamento das aquisições do depósito ROD1, o que limitava a visibilidade dos gastos e dificultava a demonstração do volume de trabalho executado pela Gestão de Componentes.', N'Prover visibilidade estruturada do cenário de consumo e gastos do depósito ROD1, apoiando a tomada de decisão e o acompanhamento das aquisições realizadas pela Gestão de Componentes.', N'10008', N'01 - Imagens/01 - Antes/9749.jpeg', N'Não havia painel de monitoramento e divulgação do trabalho realizado. ', N'01 - Imagens/02 - Depois/9749.jpeg', N'Consolidação das bases de dados do SAP, desenvolvimento do painel em Power BI e divulgação do painel e respectivo link para todos os líderes e partes interessadas, garantindo acesso à informação e visibilidade dos gastos do depósito ROD1. gastos de Mina e Usina. destino de atendimento das aquisições, se é projeto ou cobertura de parque de sobressalentes. os valores empenhados e já executados inserido saldo no depósito', N'https://app.powerbi.com/groups/51ef6e99-b755-4578-9e47-9f64c4f04f10/reports/47bb9a8f-0a8f-496b-84ab-b7cc6c9fa6a5/866d899938dda51506eb?experience=power-bi', N'N/A', N'Divulgar os trabalhos realizados pela coordenação', 0, NULL, N'Better condition monitoring, allowing for earlier detection of equipment faults. Less downtime. Planned work vs. YEMs or urgent work.', '2026-04-15T00:00:00.000', '2026-04-30T13:48:59.000', N'527706', NULL, NULL);
INSERT INTO #PVC VALUES (9750, N'81030250', N'81030250', N'Consolidação e Report de pendências no CCB', 1, N'Others/Outros', N'Demora excessiva na consolidação das informações assim como dificuldade na rastreabilidade das informações de bloqueio consolidadas', N'Fazer o processo de consolidação dos bloqueios de forma dinâmica e precisa', N'10178', N'01 - Imagens/01 - Antes/9750.jpeg', N'O processo era realizado em Word, todas as informações de datas, status e equipamentos precisavam ser realizados manualmente e repetidamente', N'01 - Imagens/02 - Depois/9750.jpeg', N'Agora existe uma padronização de equipamentos status, equipes e datas que reduzem o tempo de preenchimento e auxiliam na rastreabilidade e confiabilidade das informações', NULL, N'Sim,  o processo tem melhor consolidação dos bloqueios de forma dinâmica e precisa', N'Padronização traz muita produtividade', 0, NULL, N'ensuring proper parts are in stock to achieve the best results', '2026-04-13T00:00:00.000', '2026-04-30T14:05:14.000', N'81030250', NULL, NULL);
INSERT INTO #PVC VALUES (9751, N'81022869', N'200279', N'Garson Legacy Rock Pile Cost Optimization', 1, N'Others/Outros', N'Currently, Dams Buttressing Project is utilizing Garson Mine Legacy Rock Pile as material to support the project. At times, the material being sent did not meet the specifications the project needed and therefore required further cleaning. The contractor providing the material had an existing rate of $12.90/Ton to fully clean the material; however, this would increase the current $/Ton by $4.45/Ton.', N'Cost Avoidance', N'10238', N'01 - Imagens/01 - Antes/9751.jpeg', N'The contractor was proposing there existing rate of $12.90/Ton to fully clean the material; however, this would increase the current $/Ton ($8.45/Ton) by $4.45/Ton.', N'01 - Imagens/02 - Depois/9751.jpeg', N'By fully understanding the projects team desired material specification, the team determined that the intensive cleaning originally proposed by the contractor was not needed, and instead adding an excavator to sort through the material (~$1/Ton) was satisfactory.', NULL, N'Yes and the results are being captured under P15.', N'Evaluate alternatives to ensure the best value is being realized', 360000, 3, N'was able to do all the work in house without Contracting out. ', '2026-04-01T00:00:00.000', '2026-04-30T14:07:17.000', N'81022869', NULL, NULL);
INSERT INTO #PVC VALUES (9752, N'460346', N'1013323', N'Water Addition Ratio', NULL, N'Refining/Refino', N'CRT''s are forgetting to adjust water with flowrates in CoSX', N'Automate the process', N'10107', N'01 - Imagens/01 - Antes/9752.jpeg', N'CRT''s are forgetting to adjust water with flowrates in CoSX.  ', N'01 - Imagens/02 - Depois/9752.jpeg', N'We have this running now in Cascade and is working as it should.
INSERT INTO #PVC VALUES (9753, N'81030117', N'81057321', N'MELHORIA NO SISTEMA DE INTER-TRAVAMENTO', 1, N'Others/Outros', N'Antes o equipamento permanecia inoperante por cerca de 15 minutos para abastecimento após a melhoria equipamento vai continuar em operação no modo perfuração aumentando a produtividade e com segurança', N'Maior segurança', N'10324', N'01 - Imagens/01 - Antes/9753.jpeg', N'Antes da implementação dessa melhoria, o equipamento permanecia inoperante por aproximadamente 15 minutos para a realização do abastecimento de água. Após a modificação, o equipamento não necessita mais ser paralisado, podendo continuar operando em modo de perfuração, o que resulta em ganho de produtividade, mantendo a segurança da equipe envolvida na atividade de abastecimento.', N'01 - Imagens/02 - Depois/9753.jpeg', N'Foi implementada na PZ37 uma melhoria no sistema de intertravamento dos movimentos das patolas e das esteiras durante o modo de abastecimento do reservatório de água.
INSERT INTO #PVC VALUES (9754, N'81037412', N'81050795', N'DEVOLUTIVA DE INSPEÇÃO ESTRUTURAL SEMI-AUTOMÁTICA', 1, N'Others/Outros', N'O TEMPO GASTO COM DEVOLUTIVA (RELATÓRIO) DAS INSPEÇÕES DE INTEGRIDADE ESTRUTURAL ACABA FAZENDO COM QUE A CONCLUSÃO DAS OMS DEMOREM MAIS TEMPO QUE O ESPERADO. COM A AUTOMATIZAÇÃO DE PARTE DO DOCUMENTO, O TEMPO IRÁ SER REDUZIDO CONSIDERAVELMENTE ALÉM DE GERAR UMA PADRONIZAÇÃO ENTRE AS ENTREGAS E TAMBÉM EVITAR ERROS NO MOMENTO DE DEFINIÇÃO DAS CLASSES DOS ATIVOS. ', N'DIMINIUIÇÃO DO TEMPO DE TRATATIVA DOS DADOS APÓS A INSPEÇÃO EM CAMPO', N'10317', N'01 - Imagens/01 - Antes/9754.jpeg', N'O TEMPO GASTO COM DEVOLUTIVA (RELATÓRIO) DAS INSPEÇÕES DE INTEGRIDADE ESTRUTURAL ACABA FAZENDO COM QUE A CONCLUSÃO DAS OMS DEMOREM MAIS TEMPO QUE O ESPERADO. ', N'01 - Imagens/02 - Depois/9754.jpeg', N'COM A AUTOMATIZAÇÃO DE PARTE DO DOCUMENTO, O TEMPO IRÁ SER REDUZIDO CONSIDERAVELMENTE ALÉM DE GERAR UMA PADRONIZAÇÃO ENTRE AS ENTREGAS E TAMBÉM EVITAR ERROS NO MOMENTO DE DEFINIÇÃO DAS CLASSES DOS ATIVOS. ', NULL, N'Sim, a economia de tempo irá gerar resultados satisfatórios em relação ao tempo de entrega e qualidade do documento final.', N'Documentos com padronização diminuem o tempo de execução, evitam erros no processo e tornam a entrega mais limpa e assertiva.', 0, NULL, NULL, '2026-04-28T00:00:00.000', '2026-04-30T14:37:38.000', N'81037412', NULL, NULL);
INSERT INTO #PVC VALUES (9755, N'27185', N'27185', N'Otimização de tempo na parametrização de métricas espectrais', NULL, N'No Replication/Sem replicação', N'As linhas de alertas no sistema dynamox não se atualizam automaticamente após usar a ferramenta de alertas IA na aba de Métricas Espectrais ou no modo manual.
INSERT INTO #PVC VALUES (9756, N'541142', N'498011', N'Separador de contaminantes tanque de recirculo 2351 MO 01 ', 1, N'Others/Outros', N'Ausência de ponto de captura de contaminantes no tanque de recirculo do MO 01.', N'Reduzir impactos e perdas no processo produtivo', N'10209', N'01 - Imagens/01 - Antes/9756.jpeg', N'Ausência de ponto de captura de contaminantes no tanque de recirculo do MO 01.', N'01 - Imagens/02 - Depois/9756.jpeg', N'Instalado coletor de contaminantes removível, afim de segregar material em suspensão que tenha potencial de contaminar o concentrado na fase de liberação de partículas ( remoagem )   ', NULL, N'Instalado coletor de contaminantes removível, afim de segregar material em suspensão que tenha potencial de contaminar o concentrado na fase de liberação de partículas ( remoagem ) ', N'Perdas / Impacto produtivo / 5S', 0, NULL, N'Transparência e previsibilidade na execução do AIP, com 90% de aderência ao Budget Capex 2026, permitindo gestão proativa de desvios, disciplina de capital e melhor decisão da Diretoria e Comitês.', '2026-04-29T00:00:00.000', '2026-04-30T15:29:57.000', N'541142', NULL, NULL);
