INSERT INTO #PVC VALUES (9911, N'524896', N'543016', N'Padronização de Armazenamento de Baterias', 1, N'Others/Outros', N'Atualmente, as baterias são armazenadas de forma inadequada, sem padronização e proteção adequada, aumentando o risco de danos, perda, desgaste prematuro e falhas operacionais, além de comprometer a organização do ambiente.', N'Padronizar e garantir o armazenamento seguro das baterias, eliminando riscos de danos, perdas e exposição inadequada, aumentando a organização e a confiabilidade operacional.', N'0', N'01 - Imagens/01 - Antes/9911.jpeg', N'As baterias eram armazenadas de forma dispersa e sem proteção adequada, sem identificação padronizada e expostas a impactos, sujeira e umidade. Essa condição dificultava o controle, aumentava o risco de danos e reduzia a confiabilidade no uso operacional.', N'01 - Imagens/02 - Depois/9911.jpeg', N'Foi desenvolvido e implementado um porta baterias com estrutura resistente, ventilação adequada e identificação visual, garantindo armazenamento organizado e protegido. O acesso foi restrito somente aos técnicos, assegurando maior controle, rastreabilidade e uso adequado das baterias.
INSERT INTO #PVC VALUES (9912, N'81046197', N'81046197', N'Ajuste mangueira freio TCLD tambor de retorno', 1, N'Others/Outros', N'A mangueira do freio se encontrava em uma condição insegura . ', N'eliminar risco da área', N'10362', N'01 - Imagens/01 - Antes/9912.jpeg', N'mangueira exposta de forma insegura na área , podendo gerar danos e parando o processo de frenagem da correia ', N'01 - Imagens/02 - Depois/9912.jpeg', N'fabricado bandejamento e instalada as mangueiras do freio de forma organizada e segura ', NULL, N'O problema foi resolvido', N'Olhar de critico para segurança dos colaboradores e ativos', 0, NULL, N'FOI REALIZADO A FABRICAÇÃO E INSTALAÇÃO DE PROTEÇÃO TIPO RAC7, PROTEGENDO PARTES ROTATIVAS EXPOSTA, ELIMINANDO CONDIÇÃO INSEGURA.', '2026-05-06T00:00:00.000', '2026-05-07T15:37:27.000', N'81046197', NULL, NULL);
