INSERT INTO #PVC VALUES (9957, N'81013118', N'81013118', N'DCS printer table', 3, N'No Replication/Sem replicação', N'DCS printer desk was cluttered ', N'declutter', N'0', N'01 - Imagens/01 - Antes/9957.jpeg', N'DCS desk was cluttered', N'01 - Imagens/02 - Depois/9957.jpeg', N'cleaned up the desk. 5s''D area for hole punch', NULL, N'yes ', N'n/a', 0, NULL, N'Procedimento padrão replicável; Maior eficiência no tempo investido para a realização da atividade; Independência e flexibilidade na manipulação, conversão e análise dos dados.', '2026-05-10T00:00:00.000', '2026-05-11T04:17:29.000', N'81013118', NULL, NULL);
INSERT INTO #PVC VALUES (9958, N'1010776', N'1010776', N'SLN UF helper hose', 1, N'Refining/Refino', N'When SLN UF density increases the UF pump is unable to transfer enough solution', N'Increase flow', N'0', N'01 - Imagens/01 - Antes/9958.jpeg', N'When SLN UF density increases the UF pump is unable to transfer enough solution causing THK upset', N'01 - Imagens/02 - Depois/9958.jpeg', N'able to quickly transfer the THK to the UF tank and not have to reprocess the solution ', NULL, N'YES', N'NA', 0, NULL, N'Beter organization. Easy access.', '2026-05-10T00:00:00.000', '2026-05-11T05:35:24.000', N'1010776', NULL, NULL);
INSERT INTO #PVC VALUES (9959, N'1010776', N'1010776', N'Installing sump into sump hole', 2, N'Others/Outros', N'Sump was on top of grating and not able to pump the bund empty', N'able to clear the area of excess water', N'0', N'01 - Imagens/01 - Antes/9959.jpeg', N'Sump was installed on the bund floor', N'01 - Imagens/02 - Depois/9959.jpeg', N'installed scaffolding around grating and removed a section to install sump in to the sump pit', NULL, N'Yes', N'NA', 0, NULL, NULL, '2026-05-10T00:00:00.000', '2026-05-11T05:39:29.000', N'1010776', NULL, NULL);
INSERT INTO #PVC VALUES (9960, N'81054395', N'81054395', N'Padronização do Estoque Ideal via Aplicativo ', 1, N'Open Pit/Poço aberto', N'A definição de estoque ideal era realizada manualmente, com critérios variando.
INSERT INTO #PVC VALUES (9961, N'81042631', N'81042631', N'Avaliação Mensal de  Contratos', 1, N'Others/Outros', N'O processo de coleta e análise de avaliações apresentava diversas limitações. As respostas eram registradas em formulários simples e armazenadas em planilhas, exigindo exportação manual para tratamento dos dados. ', N'Melhorar eficiência operacional, reduzir retrabalho e centralizar dados', N'10067', N'01 - Imagens/01 - Antes/9961.jpeg', N'As avaliações eram registradas em formulários básicos, e as respostas ficavam armazenadas em planilhas, exigindo exportação manual para análise. Esse modelo tornava o processo lento, suscetível a erros e pouco integrado com outros sistemas. A geração de relatórios dependia de consolidação manual, aumentando o retrabalho e dificultando o acompanhamento em tempo real.', N'01 - Imagens/02 - Depois/9961.jpeg', N'Com a migração para o Power Apps, o processo ganhou automação e centralização. Os dados são integrados diretamente ao BI, permitindo atualização imediata e relatórios dinâmicos. Fluxos automatizados reduzem tarefas repetitivas e erros manuais. ', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/2748bf75-941d-4e3d-bad1-4b26a943264f?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&hint=2fc48325-5c24-4966-917a-29d1dcd277c9&sourcetime=1774446891026&source=portal', N'No cenário inicial, as avaliações eram coletadas em formulários simples e armazenadas em planilhas, o que exigia exportação manual para análise. Esse processo era lento, sujeito a erros e pouco integrado com outros sistemas. A geração de relatórios dependia de consolidação manual, aumentando o retrabalho e dificultando o acompanhamento em tempo real.
INSERT INTO #PVC VALUES (9962, N'200795', N'607262', N'Skip Measuring Box Discharge Liners', 1, N'No Replication/Sem replicação', N'Discharge chute angle was too steep, and the size of the discharge opening was too large.  Resulting in spillage.  ', N'More controlled load with less spillage due to lower velocity', N'10238', N'01 - Imagens/01 - Antes/9962.jpeg', N'Discharge chute angle was too steep, and the size of the discharge opening was too large.  Resulting in spillage.  ', N'01 - Imagens/02 - Depois/9962.jpeg', N'Replaced liners and extended discharge lip.  Resulted in a more controlled load with less spillage due to lower velocity.', NULL, N'Problem was solved.', N'Should have had better QAQC with last installation', 0, NULL, N'Redução significativa dos riscos ergonômicos, eliminando a necessidade de execução de atividades diretamente no solo.
INSERT INTO #PVC VALUES (9963, N'81048597', N'81026411', N'Acesso Oeste Sequeirinho', 1, N'Others/Outros', N'Devido à mancha de inundação proveniente do estudo de ruptura hipotética da Barragem do Sossego se propagar até à Cava Sequeirinho, tornou-se necessário o controle de acesso à área de lavra da Mina do Sossego (Requisito Legal). Todo profissional que precisa acessar a área passou a ser obrigado a realizar o treinamento do PAEBM e registrar sua entrada e sua saída na portaria da Mina. Como consequência, tornou-se indispensável a adoção de um processo de controle de acesso rigoroso e estruturado. Outro ponto a se considerar foi a ampliação da área e processos a serem considerados no PAEBM como a ACO (Avaliação de Conformidade e Operacionalidade do PAEBM), sinalização, sirenes, etc.​', N'A execução do Projeto “Acesso Oeste Sequeirinho” possibilita a remoção da ZAS da Cava Sequeirinho, eliminando a exposição de trabalhadores à mancha de inundação da Barragem do Sossego, alinhado, assim, com as recomendações do GISTM (Global Industry Standard on Tailings Management) ao se reduzir as consequências de um hipotético rompimento da Barragem a um nível tão baixo quanto razoavelmente praticável (ALARP - As Low As Reasonably Practicable). Além de se alinhar aos Valores da Empresa “A vida em 1º lugar”.​', N'10363', N'01 - Imagens/01 - Antes/9963.jpeg', N'Devido à mancha de inundação proveniente do estudo de ruptura hipotética da Barragem do Sossego se propagar até à Cava Sequeirinho, tornou-se necessário o controle de acesso à área de lavra da Mina do Sossego (Requisito Legal). Todo profissional que precisa acessar a área passou a ser obrigado a realizar o treinamento do PAEBM e registrar sua entrada e sua saída na portaria da Mina. Como consequência, tornou-se indispensável a adoção de um processo de controle de acesso rigoroso e estruturado. Outro ponto a se considerar foi a ampliação da área e processos a serem considerados no PAEBM como a ACO (Avaliação de Conformidade e Operacionalidade do PAEBM), sinalização, sirenes, etc.​', N'01 - Imagens/02 - Depois/9963.jpeg', N'A execução do Projeto “Acesso Oeste Sequeirinho” possibilita a remoção da ZAS da Cava Sequeirinho, eliminando a exposição de trabalhadores à mancha de inundação da Barragem do Sossego, alinhado, assim, com as recomendações do GISTM (Global Industry Standard on Tailings Management) ao se reduzir as consequências de um hipotético rompimento da Barragem a um nível tão baixo quanto razoavelmente praticável (ALARP - As Low As Reasonably Practicable). Além de se alinhar aos Valores da Empresa “A vida em 1º lugar”.​', NULL, N'Sim. A estrutura cumpre com a função de bloquear a propagação da mancha de inundação da Barragem do Sossego na área de lavra da Mina do Sossego.', N'A análise de determinado risco pode resultar em ações de melhorias como: redução da exposição de pessoas aos riscos, bem como melhoria na performance do processo e redução de custos operacionais.', 0, NULL, N'
INSERT INTO #PVC VALUES (9964, N'81043217', N'81059046', N'Aumento da confiabilidade do transportador 6013TR03 com substituição do revestimento do tambor motriz', NULL, N'Others/Outros', N'Constantes paradas do transportador 6013TR03 devido a falhas de subvelocidade, impactando a disponibilidade do equipamento e o fluxo operacional.
INSERT INTO #PVC VALUES (9965, N'543029', N'543029', N'IDENTIFICAÇÃO TANQUE DIESEL', 1, N'Others/Outros', N'Alto risco de complemento errado entre o Óleo diesel e óleo hidraulico.', N'Eliminação risco de complemento de Óleo errado', N'10081', N'01 - Imagens/01 - Antes/9965.jpeg', N'Não havia uma indicação clara de qual tanque está direcionado para o Óleo diesel.', N'01 - Imagens/02 - Depois/9965.jpeg', N'Fabricado um placa de identificação que deixa claro e objetivo qual óleo vai neste compartimento. ', NULL, N'A única indicação de qual óleo vai neste compartimento poderia ser confundida caso ela esteja com acumulo de poeira. ', N'eliminação da possibilidade de erro', 0, NULL, N'Melhoria significativa na identificação do alerta vermelho por meio da sinalização visual e sonora, aumentando a percepção de risco na área operacional. Redução de falhas de comunicação, reforço da segurança dos colaboradores, maior confiabilidade operacional e padronização da sinalização conforme requisitos de Saúde e Segurança.', '2026-05-09T00:00:00.000', '2026-05-11T14:47:07.000', N'543029', NULL, NULL);
INSERT INTO #PVC VALUES (9966, N'81043217', N'81043217', N'Melhoria na confiabilidade do sensor de subvelocidade do 6013TR03', 1, N'Others/Outros', N'Ocorrência de paradas recorrentes do transportador 6013TR03 provocadas por falhas de leitura do sensor de subvelocidade, impactando negativamente a disponibilidade do equipamento e a continuidade do fluxo operacional.
INSERT INTO #PVC VALUES (9967, N'81043217', N'471480', N'Aumento das dimensões do atuador do sensor de subvelocidade do 6013TR03', 1, N'Others/Outros', N'Constantes paradas do transportador 6013TR03 devido a falhas de subvelocidade, impactando a disponibilidade do equipamento e o fluxo operacional.
INSERT INTO #PVC VALUES (9968, N'496696', N'496696', N'Padronização e automação do relatório de turno — Gestão de Materiais PCM Corretiva', 1, N'Open Pit/Poço aberto', N'O relatório de turno da Gestão de Materiais (PCM Corretiva) tinha baixa visibilidade para as áreas: KPIs misturavam operação e tratativas, gerando inconsistências. Faltavam indicadores de envelhecimento, taxa de atendimento e frotas críticas. Visual fora do padrão VBM e identificação de NF manual, reduzindo confiabilidade e apoio à decisão.', N'Estruturar um relatório de turno automatizado com indicadores claros (taxa de atendimento do turno, taxa geral, aging por faixa de dias), separação entre dados operacionais e tratativas, alertas de volume por frota, detecção automática de NF, e identidade visual alinhada ao padrão Vale Base Metals — eliminando retrabalho manual e aumentando a confiabilidade da informação para as áreas solicitantes.', N'10023', N'01 - Imagens/01 - Antes/9968.jpeg', N'O relatório de turno misturava dados operacionais com tratativas em um único total, gerando números inconsistentes. Não havia taxa de atendimento, análise de envelhecimento dos itens em aberto, nem sinalização de frotas com alto volume de solicitações em corretiva. A identificação de NF era manual e os status não tinham definição explícita no relatório. A paleta visual não seguia o padrão Vale Base Metals.
INSERT INTO #PVC VALUES (9969, N'81020702', N'502854', N'Caderno material de Kamban', 1, N'Others/Outros', N'Demora de tempo ao encontrar materiais de kamban para o bip.', N'Desenvolver caderno dos materias de kamban para facilitar busca.', N'10140', N'01 - Imagens/01 - Antes/9969.jpeg', N'O bip para solicitar material de kamban era necessário realizar uma impressão individual de cada peça para localizar.', N'01 - Imagens/02 - Depois/9969.jpeg', N'Criamos um caderno para inserir todos os materiais que solicitamos frequentemente, tendo melhora na qualidade e no controle de tempo.', NULL, N'Sim', N'Melhorar até nas pequenas atividades.', 0, NULL, N'Centralização das informações, eliminação de inconsistências entre frotas, maior confiabilidade dos dados, melhoria da rastreabilidade e ganho significativo na agilidade das análises e decisões do PCM.', '2026-05-05T00:00:00.000', '2026-05-11T18:30:12.000', N'81020702', NULL, NULL);
INSERT INTO #PVC VALUES (9970, N'81026411', N'81026411', N'Procedimento para análise de dados de Estações Totais Robóticas (Instrumentação de Deformação)', 1, N'Others/Outros', N'Para o manuseio e análise dos dados medidos e fornecidos pela ETR (Estação Total Robótica) utilizava-se a plataforma desenvolvida pela fabricante da ETR. Esta plataforma não possui uma interface amigável (didática e de fácil manuseio) e nem sempre o usuário possui as habilitações necessárias para algumas edições e input’s.', N'Independência na manipulação de dados e análises de instrumentação de monitoramento, com a criação de um padrão que garanta uma verificação mais visual e intuitiva dos dados.', N'10363', N'01 - Imagens/01 - Antes/9970.jpeg', N'Para o manuseio e análise dos dados medidos e fornecidos pela ETR (Estação Total Robótica) utilizava-se a plataforma desenvolvida pela fabricante da ETR. Esta plataforma não possui uma interface amigável (didática e de fácil manuseio) e nem sempre o usuário possui as habilitações necessárias para algumas edições e input’s.', N'01 - Imagens/02 - Depois/9970.jpeg', N'Criação de Procedimento para a análise de dados de Estações Totais Robóticas (Instrumentação de Deformação) com a utilização de planilha Excel padronizada. O Excel é uma plataforma bem difundida e de linguagem amigável. Com a utilização de software aberto a edições e outros input’s necessários para uma avaliação mais intuitiva, ganha-se tempo e flexibilidade neste processo de conversão de dados em conclusões e verificações de performance.', NULL, N'Sim, procedimento simples e objetivo criado possibilitando a obtenção dos resultados desejados.', N'A criação de um procedimento padrão para a análise da instrumentação de monitoramento permitiu uma maior eficiência no tempo investido para a atividade e uma maior garantia de uma análise mais adequada e intuitiva.', 0, NULL, N'Bearings will last longer which will reduce equipment failure and downtime.', '2026-05-10T00:00:00.000', '2026-05-11T19:49:03.000', N'81026411', NULL, NULL);
INSERT INTO #PVC VALUES (9971, N'388278', N'388278', N'Proper storage area for chute liners.', 3, N'Concentration/Concentração', N'Repaired or spare chute liners were previously stored on the grinding floor anywhere or in a tough congested space in the mill storage area.', N'Easy access and one close location to the fine ore bins.', N'10058', N'01 - Imagens/01 - Antes/9971.jpeg', N'Trays were stored on the grinding floor causing tripping hazards. It was difficult to be aware of the inventory. By placing them in a corner in the heavily congested storage did not work.', N'01 - Imagens/02 - Depois/9971.jpeg', N'Easy central location in a better storage area.', NULL, N'This is a better centralized area and easy to inventory. ', N'Organization.', 0, NULL, N'o conjunto fica rígido, sem balançar.', '2026-05-10T00:00:00.000', '2026-05-12T00:07:45.000', N'388278', NULL, NULL);
INSERT INTO #PVC VALUES (9972, N'81004794', N'81004794', N'Waste Removal From RSA ', 1, N'Others/Outros', N'Hardtop waste containers were temporarily emptied into a sealed area at our RSA to free up containers needed for production, due to limited container inventory. This accumulated waste now requires removal.', N'Waste removal ', N'0', N'01 - Imagens/01 - Antes/9972.jpeg', N'The waste that was previously dumped now needs to be removed. However, there are currently no available waste containers to facilitate its removal.', N'01 - Imagens/02 - Depois/9972.jpeg', N'I collaborated with our waste management contractor, Clean Harbors, and proposed the use of semi dump/end‑dump units to remove the accumulated waste directly from the site and transport it to disposal. This approach also resulted in a cost savings, as these units can accommodate significantly more waste compared to the standard method of shipping two containers per truck. Utilizing two semi dump units generated an estimated savings of $30,000 while preserving our container inventory.', NULL, N'YEs', N'Look for other options ', 30000, 3, N'Facilitar acesso através da rampa
INSERT INTO #PVC VALUES (9973, N'81053928', N'81053928', N'CPL Reactor Moat Seal', 1, N'Refining/Refino', N'moat seal valve not labeled.', N'Label the valve so techs know what it is for.', N'10283', N'01 - Imagens/01 - Antes/9973.jpeg', N'Moat seal valve not labeled.', N'01 - Imagens/02 - Depois/9973.jpeg', N'Labeled the valve so techs know which valve to use when we have to turn it off or on.', NULL, N'Yes it was solved, now techs know which valve to operate without hesitation.', N'Location of moat seal valve.', 0, NULL, N'A falta de gestão do fluxo de recebimento causa inúmeros prejuízos para a Vale.', '2026-05-11T00:00:00.000', '2026-05-12T02:41:24.000', N'81053928', NULL, NULL);
INSERT INTO #PVC VALUES (9974, N'1010414', N'1010414', N'Port Process Cameras Upgrade', 1, N'Refining/Refino', N'Port area has limited cameras, only 1 was found working. Control room operator has no visibility creating a risk to the business.', N'Update cameras and provide control room operator visibility ', N'0', N'01 - Imagens/01 - Antes/9974.jpeg', N'Only one camera was working in the area creating limited visibility for the control room operator', N'01 - Imagens/02 - Depois/9974.jpeg', N'All critical required cameras were replaced and configured in the control room giving visibility to the operator', NULL, N'Yes. Goal was to provide sufficient camera coverage for the area reducing risk to the business', N'n/a', 0, NULL, N'Reformar a peça', '2026-05-12T00:00:00.000', '2026-05-12T07:42:05.000', N'1010414', NULL, NULL);
INSERT INTO #PVC VALUES (9975, N'81022762', N'81020892', N'Dispositivo ergonômico e seguro para acesso à parte inferior da esteira mecânica durante manutenções', 2, N'Others/Outros', N'ausência de um dispositivo apropriado que possibilitasse o acesso ergonômico e seguro à parte inferior do equipamento durante as atividades de manutenção. ', N'Melhorar as condições ergonômicas e de segurança nas atividades de manutenção realizadas sob a esteira mecânica, proporcionando melhor postura de trabalho, maior visibilidade e mobilidade, além de garantir que as intervenções sejam executadas de forma controlada, padronizada e conforme os requisitos das normas internas de segurança e ergonomia.', N'10144', N'01 - Imagens/01 - Antes/9975.jpeg', N'As atividades de manutenção na parte inferior dos equipamentos eram realizadas diretamente no chão, sem dispositivo de apoio adequado. Essa condição gerava problemas de segurança, riscos ergonômicos, baixo conforto ao trabalhador, dificuldade de acesso aos componentes, falta de padronização do método de trabalho, além de impactos negativos na produtividade, limpeza e conformidade com normas internas.
INSERT INTO #PVC VALUES (9976, N'81057208', N'81057208', N'Padronização da Troca de Tomada da Máquina de Solda', 1, N'Others/Outros', N'O processo de troca de tomada das máquinas de solda não possui padronização, resultando em retrabalho, aumento do tempo de manutenção, risco de falhas elétricas e संभावel exposição dos colaboradores a riscos de acidentes.', N'Eliminar riscos de falha elétrica e acidentes durante o processo, garantindo padronização e segurança na execução.', N'10178', N'01 - Imagens/01 - Antes/9976.jpeg', N'
INSERT INTO #PVC VALUES (9977, N'81022762', N'543499', N'Proteção da bomba d’água contra intempéries para aumento da confiabilidade operacional', 1, N'Others/Outros', N'exposição direta da bomba d’água à chuva, sem qualquer proteção física. A falha foi identificada por meio de análise de recorrência das quebras e observação em campo, constatando que os danos ocorriam após episódios de chuva.', N'Proteger a bomba d’água contra exposição às condições climáticas, visando aumentar sua vida útil, reduzir falhas recorrentes, evitar interrupções no fornecimento de água e diminuir custos de manutenção e reposição de componentes.', N'#N/A', N'01 - Imagens/01 - Antes/9977.jpeg', N'A bomba d’água responsável pelo abastecimento dos banheiros ficava exposta diretamente às intempéries, principalmente à chuva. Essa condição causava infiltração de água, resultando na queima de componentes internos, perda frequente de funcionalidade da bomba e transtornos operacionais, como falta de água para higiene pessoal e uso dos sanitários.', N'01 - Imagens/02 - Depois/9977.jpeg', N'Foi fabricado e instalado um habitáculo de proteção para a bomba d’água, protegendo o equipamento contra chuva e demais intempéries. Após a implementação da melhoria, não houve mais queima de componentes internos nem falhas no funcionamento da bomba. Como impactos positivos, observou-se aumento da confiabilidade do sistema, eliminação de interrupções no fornecimento de água, melhoria nas condições de uso dos banheiros e redução de custos com manutenção.', NULL, N'Sim. A solução atendeu plenamente à meta inicial, eliminando a causa das falhas recorrentes. Desde a instalação da proteção, a bomba não apresentou novas ocorrências, garantindo operação contínua e confiável.', N'Equipamentos expostos às intempéries têm sua vida útil significativamente reduzida e maior probabilidade de falhas recorrentes. A análise de falhas repetitivas associada à observação em campo é essencial para identificação correta da causa raiz. Soluções simples e de baixo custo, como proteções físicas adequadas, podem gerar alto impacto em confiabilidade e redução de custos. A proteção preventiva dos ativos evita manutenções corretivas, retrabalho e interrupções operacionais. Melhorias voltadas à confiabilidade dos ativos contribuem diretamente para a continuidade dos serviços e bem-estar dos usuários finais.', 0, NULL, N'Automatização do cálculo da Curva S, redução de erros, maior confiabilidade dos resultados, eliminação de retrabalho manual e ganho de tempo no controle dos cenários de risco.', '2026-04-30T00:00:00.000', '2026-05-12T10:13:57.000', N'81022762', NULL, NULL);
INSERT INTO #PVC VALUES (9978, N'81022762', N'543499', N'Implantação de sinalização luminosa vermelha para reforço da segurança operacional', 2, N'Others/Outros', N'ausência de sinalização visual associada ao alerta sonoro, não atendendo plenamente às boas práticas de segurança. A identificação da causa ocorreu por observação em campo e análise das condições operacionais da área.', N'Melhorar a identificação do alerta vermelho na área operacional, reforçando a comunicação visual e sonora, com foco na prevenção de acidentes e aumento da segurança ocupacional.', N'10144', N'01 - Imagens/01 - Antes/9978.jpeg', N'Anteriormente, a sinalização de alerta era realizada apenas por meio de aviso sonoro. Essa condição limitava a percepção do alerta, especialmente em ambientes com ruído elevado, podendo comprometer a comunicação operacional e aumentar os riscos de exposição dos colaboradores a situações perigosas.', N'01 - Imagens/02 - Depois/9978.jpeg', N'Foi realizada a instalação de sinalização luminosa vermelha, associada ao alerta sonoro, além da implantação de placa de identificação visual para fácil entendimento operacional. A melhoria aumentou a visibilidade do status de alerta da área, reduziu riscos operacionais, fortaleceu a comunicação visual e reforçou a segurança dos colaboradores.
INSERT INTO #PVC VALUES (9979, N'517013', N'517013', N'Automação da Simulação de Monte Carlo para Orçamento de DF', 1, N'Open Pit/Poço aberto', N'O processo de simulação de Monte Carlo para estimar horas de manutenção corretiva e condicional no orçamento de DF era realizado de forma manual, utilizando softwares de confiabilidade e diversas planilhas Excel pesadas, tornando o processo lento, trabalhoso e sujeito a erros.', N'Automatizar a simulação de Monte Carlo para tornar o processo mais ágil, padronizado e confiável, permitindo análises rápidas e replicáveis.', N'10015', N'01 - Imagens/01 - Antes/9979.jpeg', N'A simulação de Monte Carlo era feita manualmente, com necessidade de inserir dados um a um em softwares de confiabilidade e posteriormente consolidar os resultados em diversas planilhas Excel com múltiplas abas. As planilhas eram grandes, pesadas e lentas, tornando o processo demorado, trabalhoso e com alto risco de erros, além de dificultar análises em maior escala.', N'01 - Imagens/02 - Depois/9979.jpeg', N'Foi desenvolvida uma pasta de trabalho em Excel com macros VBA que permite, a partir da inserção dos dados, realizar automaticamente o teste de aderência às principais distribuições estatísticas (Weibull-2P, Exponencial, Lognormal e Normal), selecionar a melhor distribuição com base em critérios robustos e executar a simulação de Monte Carlo. A solução possibilita análises em lote de vários modelos com um único clique, garantindo padronização, rapidez e confiabilidade nos resultados.', NULL, N'Foi desenvolvida uma planilha em Excel com macros VBA que automatiza o teste de aderência estatística (MLE, LogLik, AIC, BIC) e a simulação de Monte Carlo (10.000 cenários), além de permitir análise em lote por modelo.', N'Automatizar análises estatísticas e simulações complexas aumenta significativamente a eficiência, padronização e qualidade dos resultados.', 0, NULL, N'Antes levava em torno de 20 minutos na busca de uma determinada amostra, agora em 5 minutos a amostra é encontrada e disponibilizada. ', '2026-05-11T00:00:00.000', '2026-05-12T10:44:39.000', N'517013', NULL, NULL);
INSERT INTO #PVC VALUES (9980, N'81022762', N'81046657', N'Implantação de caminho seguro sinalizado para travessia na área de manutenção', 2, N'Others/Outros', N' inexistência de uma solução estrutural definitiva para o caminho seguro que suportasse a circulação de pessoas e equipamentos auxiliares. ', N'Garantir a segurança na travessia de pessoas na área de manutenção por meio da implantação de um caminho seguro resistente, bem definido e identificado, permitindo também a passagem de equipamentos auxiliares sem danificar a estrutura.', N'10144', N'01 - Imagens/01 - Antes/9980.jpeg', N'Antes da implementação da melhoria definitiva, foram realizadas diversas tentativas para manter um caminho seguro na área de manutenção. Inicialmente, foi utilizada lona de borracha, porém essa solução se mostrava ineficaz, pois a lona enrolava com o tráfego, perdendo a função de sinalização e segurança.
INSERT INTO #PVC VALUES (9981, N'517013', N'517013', N'Padronização e Automatização do Planejamento de DF de Curto e Médio prazo - PCM', 1, N'Open Pit/Poço aberto', N'A elaboração do planejamento de disponibilidade física (DF) no PCM era realizada por meio de múltiplas planilhas com diversas abas, dificultando a consolidação e aumentando o risco de erros e sem padronização.', N'Padronizar e automatizar o processo de planejamento de DF, garantindo confiabilidade, rastreabilidade e facilidade de consolidação das informações.', N'10015', N'01 - Imagens/01 - Antes/9981.jpeg', N'O planejamento de disponibilidade física (DF) era elaborado utilizando diversas planilhas com múltiplas abas, variando entre as frotas. Esse formato tornava o processo difícil de consolidar, com alto risco de erros em fórmulas e referências, além de falta de padronização entre os arquivos. O processo era demorado, trabalhoso e limitava a rastreabilidade e a confiabilidade das informações.', N'01 - Imagens/02 - Depois/9981.jpeg', N'Foi criada uma pasta de trabalho em Excel padronizada por frota, contendo uma única tabela estruturada com todos os dias e meses necessários para o planejamento diário de DF. A solução permite atualização dinâmica sem risco de quebra de código, utilizando Power Query para modelagem dos dados e geração automática de tabelas com os resultados de DF conforme o padrão PNR-000012. Todas as frotas passaram a utilizar o mesmo modelo, garantindo padronização, confiabilidade, rastreabilidade e auditabilidade das informações.', NULL, N'Foi desenvolvida uma estrutura única em Excel por frota, com base de dados consolidada e modelagem via Power Query, eliminando fórmulas dispersas e garantindo cálculos automáticos de DF conforme o padrão corporativo (PNR-000012).', N'A padronização e centralização de dados em estruturas únicas, aliadas à automação, são fundamentais para garantir confiabilidade e escalabilidade nos processos de planejamento.', 0, NULL, N'Redução mínima de 5% ao mês nas emissões de CO₂, automatização de 100% dos indicadores ambientais,
INSERT INTO #PVC VALUES (9982, N'517013', N'517013', N'Implantação de Dashboard Integrado de Planejamento de DF de Curto e Médio em Power BI - PCM Mina', 1, N'Open Pit/Poço aberto', N'O planejamento de disponibilidade física (DF) no PCM era descentralizado em múltiplas planilhas, sem padronização e sem uma visão consolidada das informações.', N'Centralizar e padronizar as informações de planejamento de DF em um único ambiente analítico, garantindo confiabilidade, rastreabilidade e suporte à tomada de decisão.', N'10015', N'01 - Imagens/01 - Antes/9982.jpeg', N'O planejamento de DF era realizado por meio de diversas planilhas com múltiplas abas, variando entre as frotas. Esse modelo era suscetível a erros de fórmulas e referências, dificultava a consolidação das informações e tornava o processo demorado e trabalhoso. Além disso, não existia um local único para concentração dos dados, cada frota possuía seu próprio report e não havia um dashboard padronizado, comprometendo a visibilidade, a rastreabilidade e a confiabilidade das análises.', N'01 - Imagens/02 - Depois/9982.jpeg', N'Foi desenvolvido um dashboard inteligente em Power BI que consolida todas as informações do planejamento de curto e médio prazo do PCM de mina, englobando os processos de M+1, M+3 e M+12. A solução centraliza os dados em um único ambiente, apresentando indicadores como DF, horas de manutenção, quantidade de equipamentos e data/hora da última atualização por processo e frota. O modelo segue o cálculo de DF conforme o padrão PNR-000012, garantindo confiabilidade, padronização, rastreabilidade e auditabilidade das informações, além de facilitar a tomada de decisão.', NULL, N'Foi desenvolvido um dashboard em Power BI integrando dados de diferentes fontes de planejamento, com modelagem estruturada e padronização dos cálculos de DF conforme o PNR-000012.', N'A centralização das informações em dashboards analíticos é essencial para garantir governança, confiabilidade e agilidade na tomada de decisão.', 0, NULL, N'Improved chemical offloading accuracy through clear, standardized visual verification, reducing the risk of incorrect unloading, strengthening safety compliance, and minimizing reliance on human behaviour.', '2026-05-11T00:00:00.000', '2026-05-12T12:38:29.000', N'517013', NULL, NULL);
INSERT INTO #PVC VALUES (9983, N'81048127', N'81048127', N'Fittings', 1, N'Refining/Refino', N'Installing automatic greasers has been a issue in some places due to height restrictions', N'Make things better', N'0', N'01 - Imagens/01 - Antes/9983.jpeg', N'When trying to install auto lubers on equipment we have come across areas where we can''t fit the auto luber due to height restriction and fitting usage.', N'01 - Imagens/02 - Depois/9983.jpeg', N'I found a 1 piece fitting which reduced the use of multiple fittings which allows us to use the auto luber in tight areas where we can''t always get to when equipment is running. Less fittings and looks better.', NULL, N'Yes, bearings are getting grease as needed where as in past if ops couldn''t shut down the equipment it got missed until the next available opportunity.', N'equipment will last longer', 0, NULL, N'reduced tripping hazards in the area', '2026-05-11T00:00:00.000', '2026-05-12T12:39:44.000', N'81048127', NULL, NULL);
INSERT INTO #PVC VALUES (9984, N'81024026', N'81023756', N'Base do elimination/EGR PZ35', 1, N'Others/Outros', N'O sistema de elimination/EGR fica preso só por 2 ou 3 parafusos no bloco. Com o motor trabalhando, ele balança igual vara verde. Essa trepidação quebra flange, espana rosca e racha solda com o tempo.', N'o conjunto fica rígido, sem balançar.', N'0', N'01 - Imagens/01 - Antes/9984.jpeg', N'O sistema de elimination/EGR fica preso só por 2 ou 3 parafusos no bloco. Com o motor trabalhando, ele balança igual vara verde. Essa trepidação quebra flange, espana rosca e racha solda com o tempo.', N'01 - Imagens/02 - Depois/9984.jpeg', N'O calço amarelo vira um "terceiro apoio". Ele abraça o sistema e distribui a vibração pra uma área maior do bloco. A borracha por trás absorve o que sobrar. Resultado: o conjunto fica rígido, sem balançar.', NULL, N'SIM', N'Inovação', 0, NULL, NULL, '2026-04-27T00:00:00.000', '2026-05-12T12:43:30.000', N'81024026', NULL, NULL);
INSERT INTO #PVC VALUES (9985, N'81030198', N'520914', N'Rampa de acesso à caldeiraria ', 3, N'No Replication/Sem replicação', N'Dificuldade em acessar caldeiraria com carrinho
INSERT INTO #PVC VALUES (9986, N'92000679', N'92000679', N'Painel Executivo PCM - V360', 1, N'Others/Outros', N'Falta de controle e previsibilidade sobre os processos e os valores financeiros, o que leva diretamente a atrasos, retrabalho e risco financeiro.', N'Oferecer uma visão consolidada e gerencial do status financeiro e operacional dos chamados.', N'10023', N'01 - Imagens/01 - Antes/9986.jpeg', N'A visualização é pouco intuitiva dentro da plataforma. Concentrando um alto volume de informações. ', N'01 - Imagens/02 - Depois/9986.jpeg', N'Dashboard autoexplicativo; Facilidade para aplicação de filtros; Maior agilidade para tomada de decisão;', N'https://app.powerbi.com/groups/me/reports/035d441d-e7a5-4935-83e5-517e9488227a/7b301e8fd3ca9961da2d?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi&clientSideAuth=0', N'Sim. Passa a existir a gestão executiva do fluxo de recebimento fiscal do V360.', N'Gestão do fluxo do recebimento fiscal', 79000000, 1, N'Espera-se alcançar maior controle e eficiência na gestão dos exames ocupacionais, com redução significativa dos casos em atraso e melhor planejamento dos exames a vencer (30 e 60 dias).
INSERT INTO #PVC VALUES (9987, N'81024026', N'81024026', N'Recuperação da Chave Fork ', 3, N'Others/Outros', N'Peça iria para sulcada por desgaste
INSERT INTO #PVC VALUES (9988, N'81024689', N'81024689', N'Gray Water & Fresh Water Tanks', 1, N'Others/Outros', N'Lunch rooms did not have a proper disposal for Lunch Room waste water or a supply of fresh water.', N'To avoid waste water disposal and wildlife interactions', N'10289', N'01 - Imagens/01 - Antes/9988.jpeg', N'No where to dispose of and contain waste water from Lunch rooms or a supply of fresh water for cleaning.', N'01 - Imagens/02 - Depois/9988.jpeg', N'Installed a gray water and fresh water tank. Both tanks are plumbed into the 3 lunch rooms in to sinks. ', NULL, N'Yes', N'This will remove wildlife attractants and make the lunch rooms more sanitary', 0, NULL, N'Melhoria no controle financeiro e de prazos dos contratos, com aumento da visibilidade, redução de riscos e expectativa de maior execução e eficiência na gestão.', '2026-05-11T00:00:00.000', '2026-05-12T14:31:36.000', N'81024689', NULL, NULL);
INSERT INTO #PVC VALUES (9989, N'81022747', N'81006480', N'Sistema de abastecimento  de engate rápido', 1, N'Others/Outros', N'TINHA QUE REMOVE A TAMPA DO RESERVATÓRIO COM ISSO CONTAMINADA O ÓLEO E O SISTEMA DO EQUIPAMENTO.', N'MELHORIA', N'10144', N'01 - Imagens/01 - Antes/9989.jpeg', N'PARA  REALIZAR O ABASTECIMENTO DO RESERVATÓRIO HIDRÁULICO ÓLEO SAE30  TINHA QUE REMOVE A TAMPA DO RESERVATÓRIO COM ISSO CONTAMINADA O ÓLEO E O SISTEMA DO EQUIPAMENTO.', N'01 - Imagens/02 - Depois/9989.jpeg', N'FOI REALIZADO UMA MELHORIA  COM ENGATE 3/4 NO ABASTECIMENTO DO RESERVATÓRIO HIDRÁULICO ÓLEO SAE30  E EVITANDO A CONTAMINAÇÃO DO ÓLEO  E DO SISTEMA DO EQUIPAMENTO', NULL, N'FOI REALIZADO UMA MELHORIA  COM ENGATE 3/4 NO ABASTECIMENTO DO RESERVATÓRIO HIDRÁULICO ÓLEO SAE30  E EVITANDO A CONTAMINAÇÃO DO ÓLEO', N'Sentimento de dono', 0, NULL, N'Aumento da DF e MTBF', '2026-05-11T00:00:00.000', '2026-05-12T14:43:02.000', N'81022747', NULL, NULL);
INSERT INTO #PVC VALUES (9990, N'517013', N'517013', N'Automatização da Curva S do Controle de Cenários de Redução de Risco', 1, N'Open Pit/Poço aberto', N'O controle do avanço da Curva S dos cenários de redução de risco era realizado manualmente por projeto, dificultando manutenção, atualização e confiabilidade dos resultados.', N'Automatizar o cálculo do avanço dos cenários e a geração da Curva S, garantindo confiabilidade, padronização e redução de esforço manual.', N'10015', N'01 - Imagens/01 - Antes/9990.jpeg', N'A lógica de cálculo do avanço da Curva S era realizada manualmente por projeto, com dependência de fórmulas inseridas individualmente. Esse processo dificultava atualizações, aumentava o risco de perda de referência das fórmulas e gerava possibilidade de inconsistências nos resultados e no gráfico da Curva S. Além disso, demandava tempo elevado para manutenção e ajustes do controle.', N'01 - Imagens/02 - Depois/9990.jpeg', N'Foi implementada uma lógica automatizada com uso de fórmulas avançadas no Excel, permitindo o cálculo automático dos avanços dos cenários de redução de risco. A solução possibilita atualização dinâmica e segura do gráfico de Curva S, garantindo maior confiabilidade, padronização e eliminando a necessidade de ajustes manuais recorrentes.', N'https://app.powerbi.com/groups/me/apps/c960d030-8e40-47d7-b172-2287cfbb548d/reports/ae89b32c-cf36-4994-8f88-9cdc4f0d8cca/312950aec92b96a7fa79?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi&clientSideAuth=0', N'Foi desenvolvida uma lógica em Excel utilizando fórmulas avançadas para cálculo automático dos avanços, com estrutura que permite atualização dinâmica e integração direta com o gráfico de Curva S.', N'Automatizar lógicas de cálculo recorrentes reduz riscos operacionais, aumenta a confiabilidade dos resultados e melhora significativamente a eficiência do processo.', 0, NULL, N'AGORA TEMOS CONTROLE DE QUEM ESTÁ UTILIZANDO A ILHA.', '2026-05-11T00:00:00.000', '2026-05-12T15:03:37.000', N'517013', NULL, NULL);
INSERT INTO #PVC VALUES (9991, N'517013', N'517013', N'Refatoração e Inteligência Analítica no Dashboard de Cenários de Risco', 1, N'Open Pit/Poço aberto', N'O relatório em Power BI apresentava limitações na análise dos projetos de redução de risco, sem direcionamento claro para atuação em desvios e com baixa maturidade analítica.', N'Aprimorar o relatório com lógica analítica avançada, melhor modelagem de dados e visual que facilite a identificação de desvios e tomada de decisão.', N'10015', N'01 - Imagens/01 - Antes/9991.jpeg', N'O relatório em Power BI apresentava oportunidades de melhoria, não possuindo direcionamento claro para atuação em caso de desvios no avanço dos projetos. A modelagem de dados era limitada, sem uso adequado de Power Query e com ausência de medidas inteligentes em DAX. Além disso, a visualização dificultava a rápida identificação de problemas, reduzindo a efetividade do dashboard como ferramenta de gestão.', N'01 - Imagens/02 - Depois/9991.jpeg', N'O relatório foi completamente refatorado, com melhoria da modelagem de dados via Power Query, criação de medidas avançadas em DAX e redesign da interface visual. O novo dashboard apresenta layout moderno, com rápida identificação de desvios e suporte direto ao direcionamento das ações. Foi implementada Curva S totalmente automatizada e lógica inteligente para exibição dinâmica por projeto conforme filtros aplicados, elevando o nível analítico e a eficiência na tomada de decisão.', NULL, N'O relatório foi reconstruído utilizando modelagem estruturada em Power Query, desenvolvimento de medidas DAX avançadas e redesign visual orientado à análise de desvios, incluindo lógica dinâmica para Curva S e contexto por projeto.', N'Dashboards só geram valor quando combinam boa modelagem de dados, cálculos robustos e visual orientado à decisão.', 0, NULL, N'.', '2026-05-11T00:00:00.000', '2026-05-12T15:14:08.000', N'517013', NULL, NULL);
INSERT INTO #PVC VALUES (9992, N'81029891', N'81029891', N'Otimização do arquivo de amostras Medio Prazo', 3, N'No Replication/Sem replicação', N'A demora na localização das amostras impactando diretamente o tempo de espera para a execução e a a tratativa das mesmas.', N'Reduzir tempo de procura das amostras', N'10365', N'01 - Imagens/01 - Antes/9992.jpeg', N'As amostras eram armazenadas em caixas sem identificação padronizada, o que ocasionava ineficiência no processo de localização e rastreabilidade dos registros de furo. Essa condição impactava significativamente as demandas de rotina, aumentando o tempo de busca devido à verificação recorrente de caixas incorretas e, consequentemente, elevando o tempo de resposta operacional.', N'01 - Imagens/02 - Depois/9992.jpeg', N'Foi implementado, em cada caixa de armazenamento, um sistema de identificação visual contendo o registro do furo e a numeração completa das amostras armazenadas. Essa padronização assegurou maior assertividade e rastreabilidade no processo de localização, reduzindo o tempo de busca e eliminando a necessidade de verificação de caixas incorretas.', NULL, N'Sim, a rastreabilidade e tempo na busca pelas amostras ', N'Processos sem identificação padronizada tendem a gerar ineficiências', 0, NULL, N'Padronizar local de armazenamento organizado dos cintos ', '2026-05-11T00:00:00.000', '2026-05-12T15:41:25.000', N'81029891', NULL, NULL);
INSERT INTO #PVC VALUES (9993, N'81054815', N'549542', N'Implementação de Porta Vigia', 2, N'Concentration/Concentração', N'Atualmente, o posto das cabines das balanças de FeNi (granulado e finos) possui acesso por meio de porta comum, a qual não oferece controle adequado de entrada e saída de pessoas. Essa condição possibilita o acesso não autorizado às cabines, comprometendo a segurança patrimonial, a integridade dos colaboradores e a confiabilidade do processo de pesagem. A ausência de um sistema de controle mais eficaz expõe o posto a riscos operacionais, interferências indevidas nas atividades das balanças e ao não atendimento pleno das normas internas de segurança.', N'Substituir a porta comum por uma porta vigia no posto das cabines das balanças de FeNi (granulado e finos), com o objetivo de melhorar o controle de acesso, aumentar a segurança dos colaboradores e evitar interferências indevidas no processo de pesagem.', N'10233', N'01 - Imagens/01 - Antes/9993.jpeg', N'O posto das cabines das balanças de FeNi (granulado e finos) utilizava uma porta comum, sem controle adequado de acesso. Isso permitia a entrada de pessoas não autorizadas, gerando riscos à segurança dos colaboradores e possíveis interferências no processo de pesagem. Além disso, a situação não atendia plenamente às normas internas de segurança.', N'01 - Imagens/02 - Depois/9993.jpeg', N'Substituição da porta comum por porta vigia no posto das cabines das balanças de FeNi (granulado e finos), garantindo melhor controle de acesso e maior segurança no local.
INSERT INTO #PVC VALUES (9994, N'81042246', N'81042246', N'Dashboard inteligente  para acompanhamento de redução de CO2', 1, N'Others/Outros', N'Atualmente o acompanhamento das emissões de CO₂ da operação é realizado de forma descentralizada e com baixa visibilidade gerencial, dificultando:
INSERT INTO #PVC VALUES (9995, N'81034859', N'81034859', N'Bulk Chemical Delivery Labels', 2, N'Others/Outros', N'In our chemical delivery process, the warehouse previously provided drivers with a colour‑coded tag indicating the designated offloading area, along with a small map showing the unloading location. Each offloading area was clearly identified with a matching coloured sign that specified the chemical bund. Drivers could then confirm they were in the correct location by ensuring their tag matched the signage in the offloading area. However, the tag cards were rarely returned, and over time warehouse technicians became complacent and stopped issuing them altogether.', N'To ensure chemical deliveries are offloaded in the correct designated area by providing drivers with clear, visual confirmation of the correct unloading location.', N'0', N'01 - Imagens/01 - Antes/9995.jpeg', N'In our chemical delivery process, the warehouse previously provided drivers with a colour‑coded tag indicating the designated offloading area, along with a small map showing the unloading location. Each offloading area was clearly identified with a matching coloured sign that specified the chemical bund. Drivers could then confirm they were in the correct location by ensuring their tag matched the signage in the offloading area. However, the tag cards were rarely returned, and over time warehouse technicians became complacent and stopped issuing them altogether.', N'01 - Imagens/02 - Depois/9995.jpeg', N'New stick‑on labels were created for each building with a chemical offloading area. The labels include the chemical name, associated pictogram, NFPA rating, building name and number, and date/signature fields for both the warehouse technician and control room verification. Once the warehouse check is completed and confirmed with the control room, the correct label is attached to the driver’s paperwork to match the signage at the offloading location. This also serves as a visual confirmation for the technician that the driver is in the correct area. After offloading is complete, the technician signs the paperwork, which is then returned to the warehouse for receipt. This process eliminates the need for colour‑coded tags and removes the risk of tags not being returned or reused.
INSERT INTO #PVC VALUES (9996, N'81039890', N'81039890', N'AC Discharge lines insulation storage area', 3, N'No Replication/Sem replicação', N'no designated area to keep AC discharge insulation blankets while they are not on the discharge lines ', N'5S ', N'10283', N'01 - Imagens/01 - Antes/9996.jpeg', N'insulation blankets for the AC discharge lines were not stored neatly they were strewn around the areas in and around the discharge lines', N'01 - Imagens/02 - Depois/9996.jpeg', N'created storage boxes to house the insulation blankets on the AC flash vessel decks to keep the space tidy and the blankets in one spot', NULL, N'yes the initial problem was solved the blankets were no longer just laying about on the AC flash vessel deck', N'keep the space tidy ', 0, NULL, N'A proactive, standardized process that ensures timely reporting and fuel ordering, eliminating stockouts and preventing operational disruptions.', '2026-05-04T00:00:00.000', '2026-05-13T05:00:39.000', N'81039890', NULL, NULL);
INSERT INTO #PVC VALUES (9997, N'460522', N'460522', N'ISO 450001 and Responsible Care Integration', 2, N'Others/Outros', N'Responsible Care certification was not integrated into ISO45001 certification work scope. 
INSERT INTO #PVC VALUES (9998, N'81044881', N'81044881', N'TOMADA PARA TESTE DE FERRAMENTA ', 1, N'Projects/Projetos', N'ANTES AS FERRAMENTAS SAIR PRA AREA SEM SER TESTADAS, NISSO NO RETORNO ALGUMAS VOLTAVAM DENIFICADAS, SÓ NO PROXIMO USO QUE QUANDO O COLABRADOR NO MOMENTO DE USO ERA VERFICADO O DEFEITO.', N'EVITAR QUE AS FERRAMENTAS SAIAM E RETORNAM DANIFICADAS', N'10139', N'01 - Imagens/01 - Antes/9998.jpeg', N'No empréstimo de esmerilhadeiras e outras ferramentas com plugue elétrico, não havia um meio de verificar se o equipamento estava funcionando corretamente. Em alguns casos, apenas na devolução o colaborador informava que a ferramenta apresentava defeito.', N'01 - Imagens/02 - Depois/9998.jpeg', N'Foi instalada uma tomada para teste das ferramentas antes do empréstimo. Com isso, a funcionalidade do equipamento é conferida no ato da entrega, garantindo que a ferramenta esteja em condições adequadas de uso.', NULL, N'SIM', N'EVITAR QUE AS FERRAMENTAS SAIAM E RETORNAM DANIFICADAS', 0, NULL, N'Garantido a troca dos redutores com maior necessidade, Laudo e realizado projeção de troca para gestão produção e Custo.', '2026-05-01T00:00:00.000', '2026-05-13T10:38:58.000', N'81044881', NULL, NULL);
INSERT INTO #PVC VALUES (9999, N'81061565', N'81061565', N'Melhoria na gestão de exames ocupacionais e redução de pendências', 2, N'No Replication/Sem replicação', N'Atualmente, a gestão de exames ocupacionais apresenta pendências significativas, com registros de exames atrasados e grande volume de exames próximos ao vencimento (30 e 60 dias), impactando o controle preventivo e a conformidade dos processos da área de medicina ocupacional.', N'Reduzir a quantidade de exames atrasados e a vencer, aumentando a aderência ao cumprimento dos prazos e garantindo maior controle da saúde ocupacional dos colaboradores.', N'10189', N'01 - Imagens/01 - Antes/9999.jpeg', N'Atualmente, observa-se um elevado volume de exames ocupacionais com pendências, sendo:
INSERT INTO #PVC VALUES (10000, N'81044881', N'81044881', N'SUPORTE DE CARTÃO DE BLOGUEIO', 1, N'Projects/Projetos', N'DESORGANIZAÇÃO DOS CARTÃOS NA BANCADA', N'ORGANIZAÇÃO DOS CARTÃO DE BLOGUEIO', N'10139', N'01 - Imagens/01 - Antes/10000.jpeg', N'COM O NOVO MODELO DE CARTÃO DE BLOGUEIO QUE SÃO MENORES E NÃO TINHA SUPORTE.', N'01 - Imagens/02 - Depois/10000.jpeg', N'AGORA ESTÁ ORGANIZADO SEM POLUIÇÃO NAS BANCADAS.', NULL, N'ORGANIZAÇÃO DOS CARTÃO DE BLOGUEIO', N'ORGANIZÇÃO', 0, NULL, N'Maior controle no transporte', '2026-05-01T00:00:00.000', '2026-05-13T11:17:17.000', N'81044881', NULL, NULL);
INSERT INTO #PVC VALUES (10001, N'81002441', N'81061565', N'Melhoria na gestão e controle de contratos de fornecedores', 1, N'Others/Outros', N'Atualmente, observa-se dificuldade no controle integrado dos contratos de fornecedores, especialmente na relação entre valores contratados e executados, além da gestão de prazos e acompanhamento de vencimentos.
INSERT INTO #PVC VALUES (10002, N'81000072', N'81000072', N'Melhoria no sistema de Injeção de Agua', 1, N'Others/Outros', N'Devido a proximidade da válvula check de retenção de água na sucção da bomba, a coluna d''agua retida não é o suficiente para a eficiência da bomba na partida, ocorrendo falhas na injeção de água durante a perfuração.', N'Redução de falhas e aumento de disponibilidade física e MTBF', N'10164', N'01 - Imagens/01 - Antes/10002.jpeg', N'Devido a proximidade da válvula check de retenção de água na sucção da bomba, a coluna d''agua retida não é o suficiente para a eficiência da bomba na partida, ocorrendo falhas na injeção de água durante a perfuração.', N'01 - Imagens/02 - Depois/10002.jpeg', N'Foi instalado o filtro tela e válvula check na parte inferior lateral do tanque, tendo uma mangueira de aproximadamente 2 metros mantendo a coluna d''agua retida até a entrada da sucção da bomba ', NULL, N'Tivemos ganho na redução de falhas recorrentes do sistema de injeção de água. ', N'Redução nos indices de corretivas', 0, NULL, N'ORGANIZAÇÃO', '2026-05-12T00:00:00.000', '2026-05-13T12:14:21.000', N'81000072', NULL, NULL);
INSERT INTO #PVC VALUES (10003, N'81044881', N'81044881', N'CONTROLE DE USO DA ILHA', 1, N'Projects/Projetos', N'ANTES NO FINAL DO DIA TINHA ALGUNS COLABORADOR QUE NÃO ENTRAGAVA AS FICHAS DA ILHA.', N'MANTER O CONTROLE DE USO DA ILHA DE LUBRIFICABTES', N'10139', N'01 - Imagens/01 - Antes/10003.jpeg', N'ANTES NO FINAL DO DIA TINHA ALGUNS COLABORADOR QUE NÃO ENTRAGAVA AS FICHAS DA ILHA.', N'01 - Imagens/02 - Depois/10003.jpeg', N'AGORA NA ENTREGA DA FICHA E ANOTADO O NOME, MATRICULA, O EQUIPAMENTO E O NOME DO OLEO QUE VAI SER USADO.', NULL, N'SIM, CONTROLE E ORGANIZAÇÃO', N'CONTROLE E ORGANIZAÇÃO', 0, NULL, N'Foco na agilidade que a identificação traz para o processo.
INSERT INTO #PVC VALUES (10004, N'81047115', N'81051917', N'recipiente de descarte de contaminados', 3, N'Others/Outros', N'Vinha correndo um problema grave em relação ao descarte dos materiais contaminados não recicláveis proveniente da área, e o mesmo ocorria no momento do descarte. ', N'Organização, maximização de tempo e segurança ', N'10362', N'01 - Imagens/01 - Antes/10004.jpeg', N'Dificuldade no descarte dos materiais contaminados proveniente da área, recipiente inadequado para o armazenamento ', N'01 - Imagens/02 - Depois/10004.jpeg', N'Foi feito a substituição do recipiente que armazenava os contaminados proveniente da área por um mais adequado, ganhando tempo ergonomia, e praticidade', NULL, N'Sim, ficou nítido a identificação', N'Senso de organização', 0, NULL, N'Monitoramento visual contínuo do nível e da qualidade do óleo, possibilitando identificação rápida de anomalias e tomada de decisão mais ágil', '2026-05-11T00:00:00.000', '2026-05-13T12:41:21.000', N'81047115', NULL, NULL);
INSERT INTO #PVC VALUES (10005, N'549714', N'549714', N'Suporte Para Cinto de Segurança ', 3, N'No Replication/Sem replicação', N'Antes os cintos ficavam espalhados, sem local específico para guarda-lo. ', N'Guardar de forma organizada os cintos de segurança', N'0', N'01 - Imagens/01 - Antes/10005.jpeg', N'Ausência de um local específico para armazenamento dos cintos de segurança.', N'01 - Imagens/02 - Depois/10005.jpeg', N'Suporte específico para guardar os cintos de segurança, colocando em prática o 5S e organização. ', NULL, N'SIM. ', N'Boa prática do 5S', 0, NULL, N'Easier to find inventory in the cabinet', '2026-04-06T00:00:00.000', '2026-05-13T12:45:56.000', N'549714', NULL, NULL);
INSERT INTO #PVC VALUES (10006, N'81034629', N'482820', N'Suporte Escorredor de Filtros', 3, N'Others/Outros', N'Ausência de um suporte onde os filtros ficassem suspensos escorrendo.', N'Facilitar o escorrimento do fluído do filtro de maneira prática e segura ', N'0', N'01 - Imagens/01 - Antes/10006.jpeg', N'Ausência de um suporte onde os filtros ficassem suspensos escorrendo.', N'01 - Imagens/02 - Depois/10006.jpeg', N'Realizado a confecção de um suporte para escorrer o fluido do filtro de forma prática e segura. ', NULL, N'Sim ', N'5s', 0, NULL, N'Both pumps able to be flushed without moving flush points', '2026-04-29T00:00:00.000', '2026-05-13T12:57:32.000', N'81034629', NULL, NULL);
INSERT INTO #PVC VALUES (10007, N'81034859', N'81034859', N'Chemical Offloading Signs', 2, N'Others/Outros', N'Two required chemical offloading area signs are missing from designated locations—one in the boiler fuel offloading area and one in the Soda Ash offloading area. The absence of proper signage creates a risk of improper identification, potential safety hazards, and non-compliance with standard operating procedures during chemical handling and offloading activities.', N'Ensure all chemical offloading areas are clearly identified', N'0', N'01 - Imagens/01 - Antes/10007.jpeg', N'Two required chemical offloading area signs are missing from designated locations—one in the boiler fuel offloading area and one in the Soda Ash offloading area. The absence of proper signage creates a risk of improper identification, potential safety hazards, and non-compliance with standard operating procedures during chemical handling and offloading activities.', N'01 - Imagens/02 - Depois/10007.jpeg', N'New Signage has been created and installed for both the Boiler Fuel and Soda Ash offloading areas. The new signs are colour-matched to the corresponding chemical Identification labels.
INSERT INTO #PVC VALUES (10008, N'517429', N'517429', N'Otimização do Processo de Classificação de Paradas Via Seca no GPV', 1, N'Others/Outros', N' Anteriormente, durante a classificação de paradas no sistema, os usuários tinham acesso a todas as TAGs de equipamentos, independentemente do subprocesso analisado. Isso resultava em:
INSERT INTO #PVC VALUES (10009, N'81034859', N'81034859', N'Fuel Dip Communications', NULL, N'Others/Outros', N'We experienced several incidents where gasoline/diesel ran out. Although daily tank dips were being completed, the readings were not communicated to supervisors, so fuel was not ordered when levels became low.
INSERT INTO #PVC VALUES (10010, N'128215', N'128215', N'5s identificação', 3, N'No Replication/Sem replicação', N'Dificuldade em identifica local   
INSERT INTO #PVC VALUES (10011, N'539074', N'539074', N'Painel de Gestão de Redutores Vertimil', 1, N'Others/Outros', N'Ausência de visão de histórico de troca e projeção de troca de redutores Vertimil.', N'Possibilitar visão de projeção de troca para priorização', N'10230', N'01 - Imagens/01 - Antes/10011.jpeg', N'Painel anterior não possibilitava a visão de histórico, apresentando somente a visão do momento.', N'01 - Imagens/02 - Depois/10011.jpeg', N'Implementado Painel com visão de dados histórico e projeção de troca.', NULL, N'Sim, O problema foi resolvido.', N'Quem não não gerência', 0, NULL, N'Underground equipment operator will have the knowledge needed to understand the expectations of the inspections.', '2026-05-13T00:00:00.000', '2026-05-13T15:39:15.000', N'539074', NULL, NULL);
INSERT INTO #PVC VALUES (10012, N'81040307', N'81040307', N'Automated Risk Newsletter powered by AI‑Enabled Portfolio Insights for Decision Support', 1, N'Projects/Projetos', N'Prior to this initiative, a standardized risk framework had been implemented across Ontario Surface Projects, enabling consistent data collection and improved structure.
INSERT INTO #PVC VALUES (10013, N'514353', N'514353', N'MELHORIA NO TRANSPORTE DE PEDRA DE MÁRMORE', 1, N'Others/Outros', N'O transporte das pedras de mármore era realizado manualmente pelos colaboradores, exigindo grande esforço físico e contato direto com a peça durante o levantamento e deslocamento.', N'Melhoria no transporte', N'10017', N'01 - Imagens/01 - Antes/10013.jpeg', N'O transporte das pedras de mármore era realizado manualmente pelos colaboradores, exigindo grande esforço físico e contato direto com a peça durante o levantamento e deslocamento.', N'01 - Imagens/02 - Depois/10013.jpeg', N'Implantado suporte para movimentação de pedra de mármore, proporcionando melhor pegada, apoio, tato e estabilidade no levantamento e transporte, reduzindo esforço e riscos operacionais.', NULL, N'Maior controle no transporte;
INSERT INTO #PVC VALUES (10014, N'514353', N'514353', N'MELHORIA NA ORGANIZAÇÃO DE MATERIAIS', 3, N'Others/Outros', N'Os materiais de pintura e ferramentas eram armazenados em malões, dificultando a organização, identificação e controle dos itens no container.', N'Melhor organização dos materiais.', N'#N/A', N'01 - Imagens/01 - Antes/10014.jpeg', N'Os materiais de pintura e ferramentas eram armazenados em malões, dificultando a organização, identificação e controle dos itens no container.', N'01 - Imagens/02 - Depois/10014.jpeg', N'Realizado 5S no container com reaproveitamento de caixas de broca pintadas e identificadas para organização dos materiais de hidráulica, pintura, carpintaria e pedreiro.', NULL, N'Melhor organização dos materiais;
INSERT INTO #PVC VALUES (10015, N'81044881', N'81044881', N'SUPORTE DE CARTÃO DE TRANSFERÊNCIA', 1, N'Projects/Projetos', N'DESORGANIZAÇÃO NAS BANCADAS', N'ORGANIZAÇÃO', N'10139', N'01 - Imagens/01 - Antes/10015.jpeg', N'NÃO TINHA SUPORTE PARA ORGANIZAR OS CARTÕES NA BANCADA.', N'01 - Imagens/02 - Depois/10015.jpeg', N'AGORA ESTÁ ORGANIZADO E DISPONIVEL PARA OS COLABORADORES UTILIZAR.', NULL, N'SIM', N'ORGANIZAÇÃO', 0, NULL, N'falha na comunicação e com relatório melhorou a informação.', '2026-05-12T00:00:00.000', '2026-05-13T16:33:48.000', N'81044881', NULL, NULL);
INSERT INTO #PVC VALUES (10016, N'81060882', N'81060882', N'ID Equipamento 2301TC06', 2, N'Others/Outros', N'Falta de identificação no equipamento, não ficando claro seu tag durante as atividades.', N'Foco em aumentar o nível de identificação', N'10362', N'01 - Imagens/01 - Antes/10016.jpeg', N'Equipamento sem a identificação de forma clara.', N'01 - Imagens/02 - Depois/10016.jpeg', N'Realizada a identificação do equipamento para contribuir na segurança e produtividade.', NULL, N'Deixar os dados do equipamento claros e visíveis para todos.', N'Padronização da comunicação visual é necessária.', 0, NULL, N'A implementação de gestão visual nos roteiros de manutenção traz ganhos diretos para o planejamento, execução e segurança das atividades. Entre os principais benefícios, destacam-se:
INSERT INTO #PVC VALUES (10017, N'81038842', N'81038842', N'Implantação de Visor de Nível de Óleo', 1, N'Others/Outros', N'O problema foi encontrado durante uma atividade de lubrificação de rotina . ', N'A atuação proativa da manutenção contribui diretamente para a redução de falhas e aumento da disponibilidade dos ativos', N'10031', N'01 - Imagens/01 - Antes/10017.jpeg', N'O reservatório AL-2010-01 não possuía visor de nível de óleo, dificultando a verificação da quantidade e condição do lubrificante. A inspeção dependia de métodos não visuais, aumentando o risco de operação com nível inadequado e falhas no equipamento.', N'01 - Imagens/02 - Depois/10017.jpeg', N'Instalação de visor de nível tipo luneta na linha do reservatório, permitindo inspeção visual direta do nível e condição do óleo', NULL, N'Sim, Melhoria na eficiência das inspeções onde não conseguiria visualizar o nível de óleo ', N'O monitoramento visual contínuo facilita a tomada de decisão rápida e evita falhas por lubrificação inadequada', 0, NULL, NULL, '2026-05-11T00:00:00.000', '2026-05-13T23:16:12.000', N'81038842', NULL, NULL);
INSERT INTO #PVC VALUES (10018, N'81053928', N'81053928', N'paint shelf organization', 3, N'Projects/Projetos', N'all different colors of paint just stacked in the cabinet , making it very hard to find the proper color for a job without having to shift everything around.', N'Make colors easier to identify.', N'10283', N'01 - Imagens/01 - Antes/10018.jpeg', N'Trying to find proper color of paint, and how many are in the cabinet without having to shift every bucket .', N'01 - Imagens/02 - Depois/10018.jpeg', N'Shelves are labeled now so proper color and the amount of that color we have are easier to find and keep track of the paint inventory in the cabinet.', NULL, N'yes the problem was solved as we now only have to read shelf label to see if its the right color and the amount', N'Inventory Control', 0, NULL, N'A ausência dessa diferenciação limitava a transparência e a clareza da análise de performance, dificultava o direcionamento das decisões e a priorização de ações, além de aumentar o risco de decisões baseadas apenas em médias globais.
INSERT INTO #PVC VALUES (10019, N'1008463', N'1008463', N'Filter wash flush point', 3, N'No Replication/Sem replicação', N'Pump suctions plugging off and causing tank levels to be high. Only one flush point between two pumps', N'Able to flush both pumps easily', N'10112', N'01 - Imagens/01 - Antes/10019.jpeg', N'Only one flush point available', N'01 - Imagens/02 - Depois/10019.jpeg', N'Second flush point made', NULL, N'Goal was completed', N'Have point pre made', 0, NULL, N'Increased visibility of tripping hazard.', '2026-05-13T00:00:00.000', '2026-05-14T04:14:16.000', N'1008463', NULL, NULL);
INSERT INTO #PVC VALUES (10020, N'1008463', N'460565', N'Sump Pump', 3, N'Others/Outros', N'Outdoor sump pump wasn''t working', N'Able to pump out the bund easily', N'10112', N'01 - Imagens/01 - Antes/10020.jpeg', N'Sump pump wasn''t working', N'01 - Imagens/02 - Depois/10020.jpeg', N'New sump was put together and placed in the bund', NULL, N'Yes, the new pump allowed the sump to be easily pumped out', N'Inspect outside equipment', 0, NULL, N'Redução estimada de até R$ 7.200,00 por ano com a eliminação de custos de manutenção corretiva dos cantos das paredes. A melhoria foi realizada com o reaproveitamento de correia de tambor de retorno, evitando descarte e garantindo proteção contra impactos. A solução aumentou a durabilidade da estrutura, reduziu retrabalho e contribuiu para ganhos financeiros e ambientais.
INSERT INTO #PVC VALUES (10021, N'496444', N'496444', N'ESQUEMA ELETRICO FISICO', 1, N'No Replication/Sem replicação', N'Não havia esquema impresso disponível na área. O colaborador tinha que ficar olhando pelo celular . ', N'Melhorar condiçao de trabalho na area', N'10140', N'01 - Imagens/01 - Antes/10021.jpeg', N'Não havia esquema impresso ,de forma física disponível na área. O colaborador tinha que ficar olhando pelo celular . ', N'01 - Imagens/02 - Depois/10021.jpeg', N'Foi criado um esquema elétrico de forma impressa e encadernada de forma física . Afim de melhorar e agilizar nos diagnósticos elétricos da frota komatsu.', NULL, N'Não havia esquema impresso ,de forma física disponível na área. O colaborador tinha que ficar olhando pelo celular . ', N'Sempre melhorar a condiçao de trabalho', 0, NULL, N'To make scaffold knee bangers are more visible.', '2026-05-13T00:00:00.000', '2026-05-14T05:18:36.000', N'496444', NULL, NULL);
INSERT INTO #PVC VALUES (10022, N'496444', N'496444', N'Melhoria no terminal da shutoff', 1, N'Others/Outros', N'Dificuldade na remoçao dos terminais e dificuldade para medir a resistencia do componente', N'FACILITAR NA REMOCAO DO CABO SEM DANIFICAR O TERMINAL', N'10140', N'01 - Imagens/01 - Antes/10022.jpeg', N'Dificuldade na remoção dos terminais e dificuldade para medir a resistência do componente no local . ', N'01 - Imagens/02 - Depois/10022.jpeg', N'Ganha de tempo na realização da tarefa. Diminuição de quebra do terminal na remoção do conector do ECM.
INSERT INTO #PVC VALUES (10023, N'81033365', N'81048451', N'Suporte para capacete/Mochila', 1, N'Others/Outros', N'ausência de local adequado', N'melhoria continua', N'10139', N'01 - Imagens/01 - Antes/10023.jpeg', N'FOI IDENTIFICADO QUE ESTAVAM COLOCANDO CAPACETES E MOCHILAS EM LOCAL INADEQUADO.', N'01 - Imagens/02 - Depois/10023.jpeg', N'FOI REALIZADO A FABRICAÇÃO DE SUPORTE PARA GUARDAR OS CAPACETES E MOCHILA DE FORMA ORGANIZADA E SEGURA.', NULL, N'AUSENCIA DE LOCAL ADEQUADO E REALIZADO UM LOCAL ADEQUADO', N'MELHORIA CONTINUA', 0, NULL, N'N', '2026-05-05T00:00:00.000', '2026-05-14T08:58:11.000', N'81033365', NULL, NULL);
INSERT INTO #PVC VALUES (10024, N'81033358', N'81033358', N'Visual Fire Suppression Inspection PowerPoint', 1, N'Underground/Subterrâneo', N'Underground equipment operators are unsure as to what they are to look for and inspect during a 1 month visual Fire Suppression inspection.', N'Provide clarity and information', N'10238', N'01 - Imagens/01 - Antes/10024.jpeg', N'Underground equipment operators are unsure as to what they are to look for and inspect during a 1 month visual Fire Suppression inspection.', N'01 - Imagens/02 - Depois/10024.jpeg', N'A detailed PowerPoint presentation has been assembled to provide clarity and required information to ensure underground equipment operators are successful in completing required inspections.', NULL, N'The PowerPoint should definitely prove to be successful in providing the required information needed to complete the inspections as well as provide a better understand of expectations.', N'Providing additional information aids in success and understanding', 0, NULL, N'Esse projeto vai ser replicado para outra estrutura geotécnica que serão construída futuramente em ONP.', '2026-05-13T00:00:00.000', '2026-05-14T09:03:05.000', N'81033358', NULL, NULL);
INSERT INTO #PVC VALUES (10025, N'523293', N'523293', N'Redução do Tempo na Classificação de OMs com Necessidade de Desligamento.', NULL, N'Others/Outros', N'Atualmente, a classificação de OMs que envolvem desligamento demanda análise criteriosa de múltiplos fatores, como criticidade do equipamento, tipo de intervenção, riscos envolvidos e necessidade de integração com outras áreas (operação mina e usina). Em muitos casos, esse processo é realizado de forma manual, o que contribui para atrasos na tomada de decisão e aumento no tempo de resposta.', N'Reduzir o tempo de 10min para 1min', N'10023', N'01 - Imagens/01 - Antes/10025.jpeg', N'Atualmente, a classificação de OMs que envolvem desligamento demanda análise criteriosa de múltiplos fatores, como criticidade do equipamento, tipo de intervenção, riscos envolvidos e necessidade de integração com outras áreas (operação mina e uisna). Em muitos casos, esse processo é realizado de forma manual, o que contribui para atrasos na tomada de decisão e aumento no tempo de resposta.', N'01 - Imagens/02 - Depois/10025.jpeg', N'Foi criada a segmentação em três categorias dentro do grupo de planejamento no sistema SAP para classificação de necessidade de desligamento: 100 – Desligamento Geral, 110 – Desligamento Parcial e 120 – Sem Desligamento.
INSERT INTO #PVC VALUES (10026, N'523293', N'523293', N'Implementação de gestão visual no card único de aviso de desligamento.', 1, N'Others/Outros', N'O envio de dois cards de informe de desligamentos representa um problema de comunicação e padronização dentro do processo de planejamento e execução de manutenções. Essa duplicidade pode gerar diferentes tipos de impactos negativos na rotina operacional.
INSERT INTO #PVC VALUES (10027, N'81033365', N'81048572', N'Proteção de Solda', 1, N'Projects/Projetos', N'ausência de roldanas para facilitar a movimentação.', N'processo de melhoria', N'10139', N'01 - Imagens/01 - Antes/10027.jpeg', N'FOI IDENTIFICADO AUSENCIA DE ROLDANAS NA PROTEÇÃO DE SOLDA, DIFICULTANDO O MANUSEIO E MOVIMENTAÇÃO, PODENDO CAUSAR ACIDENTE.', N'01 - Imagens/02 - Depois/10027.jpeg', N'FOI COLOCADO ROLDANAS NA PROTEÇÃO DE SOLDA PARA FACILITAR O MANUSEIO E MOVIMENTAÇÃO COM SEGURANÇA.', NULL, N'DIFICULDADE NA MOVIMENTAÇÃO.', N'MELHORIA CONTINUA', 0, NULL, N'Isolamento do ponto de contato com espuma protetora, preservando a integridade da mangueira de LED e mantendo a funcionalidade do sinalizador.
INSERT INTO #PVC VALUES (10028, N'81033365', N'81048451', N'Relatório diário de pneus', 1, N'Others/Outros', N'ausência de informação de pneus na troca de turno.', N'processo de melhoria', N'10139', N'01 - Imagens/01 - Antes/10028.jpeg', N'Foi identificado que na passagem dos turnos não havia informado a quantidade de pneus que estava disponível na manutenção de pneu, com isso, havia impacto na manutenção por falta de informação.', N'01 - Imagens/02 - Depois/10028.jpeg', N'Foi criado um relatório diário de pneus para facilitar a informação na passem do turno e eliminando o impacto na manutenção.', NULL, N'falha na comunicação e com relatório melhorou a informação.', N'processo de melhoria', 0, NULL, NULL, '2026-05-12T00:00:00.000', '2026-05-14T12:27:17.000', N'81033365', NULL, NULL);
INSERT INTO #PVC VALUES (10029, N'523293', N'523293', N'Implementação de gestão visual de roteiro de atividade de manutenção em Redes e Linhas', 1, N'Others/Outros', N'Ausência de sequenciamento lógico das atividades, onde as etapas não seguem uma ordem bem definida. Isso aumenta a probabilidade de execução incorreta, como a realização de tarefas fora de sequência, podendo comprometer o resultado final da intervenção.
INSERT INTO #PVC VALUES (10030, N'1009733', N'1009733', N'Adjust valve tuning', 1, N'Refining/Refino', N'Aqueous level control valve for S2 in copper needed to be tuned. The circuit was swinging causing instability in the circuit. ', N'Make the aqueous level in S2 copper more stable. ', N'0', N'01 - Imagens/01 - Antes/10030.jpeg', N'Aqueous level control valve for S2 in copper needed to be tuned. The circuit was swinging causing instability in the circuit. ', N'01 - Imagens/02 - Depois/10030.jpeg', N'DCS along with the CRT tuned the valve allowing the CRT greater control over the aqueous level in S2 in copper thus making the circuit more stable.', NULL, N'not that the circuit is stable we no longer loose product solution to the waste tank and it don''t need to be re-processed back in Neutralization. ', N'S2 was unstable causing circuit upsets. ', 50000, 3, N'......', '2026-05-13T00:00:00.000', '2026-05-14T12:48:56.000', N'1009733', NULL, NULL);
INSERT INTO #PVC VALUES (10031, N'81042135', N'81042135', N'Acompanhamento painel indicadores Infraestrutura', 1, N'No Replication/Sem replicação', N'Os indicadores de performance para  frota de infraestrutura estavam agrupados (infra pneus + infra esteira), ocultando alguma perda em uma das frotas.', N'Gestão dos indicadores para frota de infra pneus e infra esteira', N'10015', N'01 - Imagens/01 - Antes/10031.jpeg', N'Os indicadores de performance para frota de infra estrutura estavam agrupados (infra pneus e infra esteira).', N'01 - Imagens/02 - Depois/10031.jpeg', N'Os indicadores de performance da frota de infraestrutura eram analisados de forma consolidada, o que reduzia a visibilidade sobre o desempenho específico das subfrotas. Esse modelo podia ocultar desvios relevantes, especialmente nas frotas de esteiras e pneus. O acompanhamento adotado não contemplava a segregação dos dados por tipo de frota, concentrando a análise em uma visão única e agregada da infraestrutura.
INSERT INTO #PVC VALUES (10032, N'1014906', N'1014906', N'High Visibility Piping', 2, N'Others/Outros', N'The squeeze water and wash water lines both protrude from the scaffold deck that surrounds each WLN Filter Press creating a tripping hazard.', N'Make tripping hazards more visible and reduce risk.', N'0', N'01 - Imagens/01 - Antes/10032.jpeg', N'Wash Water and Squeeze Water Line both protrude from WLN Filter Press scaffold deck creating tripping hazard.
INSERT INTO #PVC VALUES (10033, N'81042078', N'81042078', N'AUMENTO DA VIDA ÚTIL DA INFRAESTRUTURA POR PROTEÇÃO DE CANTOS EM ÁREAS DE CIRCULAÇÃO', 1, N'Others/Outros', N'Durante a movimentação e posicionamento dos carrinhos de amostras nas entradas das salas do laboratório, observou-se o impacto frequente nos cantos das paredes. Essa condição ocasionava desgaste da estrutura, descascamento da pintura e necessidade recorrente de manutenção corretiva. Além disso, o contato direto comprometia o padrão visual do ambiente e gerava retrabalho para a equipe. Esse cenário resultava em aumento de custos operacionais e redução da vida útil da infraestrutura, além de impactar negativamente na organização e nos padrões de 5S do laboratório.
INSERT INTO #PVC VALUES (10034, N'1014906', N'1014906', N'High Visibility Scaffold Knee Bangers', 2, N'Others/Outros', N'On the scaffold deck that surrounds the WLN Filter Presses multiple scaffold supports protrude through the deck and in the middle of the walkway at knee height, out of the line of site creating are knee bangers.', N'Make knee bangers more visible.', N'0', N'01 - Imagens/01 - Antes/10034.jpeg', N'Scaffold support protrudes from scaffold deck at knee height creating knee bangers on all four WLN Filter Presses.', N'01 - Imagens/02 - Depois/10034.jpeg', N'High visibility paint applied to scaffold knee bangers to make it more visible.', NULL, N'Yes, scaffold knee bangers are more visible.', N'Reduce Safety risks when possible.', 0, NULL, N'Melhor previsibilidade para estimar consumo de água de arandela. Reputacional - Garantir que o produto final atende às características de venda esperadas', '2026-05-13T00:00:00.000', '2026-05-14T13:55:30.000', N'1014906', NULL, NULL);
INSERT INTO #PVC VALUES (10035, N'81002005', N'81002005', N'Suporte para sacar rolamento do comando D9', 1, N'Others/Outros', N'Dificuldade para sacar o rolamento do eixo do comando final.', N'Sacar rolamento do eixo do comando final', N'10303', N'01 - Imagens/01 - Antes/10035.jpeg', N' Bem antes a  equipe tinha a maior dificuldade de sacar o rolamento do eixo do comando devido a interferência, na maioria das vezes era preciso cortar os rolamentos do eixo.  ', N'01 - Imagens/02 - Depois/10035.jpeg', N'  Com a ajuda do suporte e a barra roscada, conseguimos colocar o cilindro hidráulico e facilitou na retirada dos rolamentos do eixo, e ganhamos em segurança na atividade, eliminamos o risco de pensamento das mãos e dedos, ganhamos na postura ergonômica e tempo da atividade.  ', NULL, N'Ganhamos tempo na atividade, custo zero e ergonomia.', N'Com a melhoria eliminamos o risco de pensamento das mãos ', 100, 1, NULL, '2026-05-01T00:00:00.000', '2026-05-14T14:06:42.000', N'81002005', NULL, NULL);
INSERT INTO #PVC VALUES (10036, N'81046197', N'81046197', N'Instalação bebedouro', 3, N'Others/Outros', N'área sem bebedouro', N'saude e segurança', N'10362', N'01 - Imagens/01 - Antes/10036.jpeg', N'área não tinha bebedouro', N'01 - Imagens/02 - Depois/10036.jpeg', N'área com bebedouro', NULL, N'N', N'N', 0, NULL, N'Travado o componente, impossibilitando deslizamento longitudinal do comando sobre o suporte durante uma frenagem e movimentação.', '2026-05-13T00:00:00.000', '2026-05-14T14:16:38.000', N'81046197', NULL, NULL);
INSERT INTO #PVC VALUES (10037, N'81023630', N'81023630', N'Implantação de Marcos Geodésicos no DP02.', 1, N'Projects/Projetos', N'Para a realização da demarcação das coordenadas da construção do dique DP02, seria necessário transportar as coordenadas a partir de um marco geodésico referenciado SIRGAS 2000, localizado na estrutura DP04, a aproximadamente 3.000 metros da área da obra.', N'Reduzir o tempo de execução, esforço operacional e risco de imprecisão das coordenadas.', N'10171', N'01 - Imagens/01 - Antes/10037.jpeg', N'Para a realização da demarcação das coordenadas da construção do dique DP02, seria necessário transportar com GPS RTK as coordenadas a partir do marco geodésico referenciado SIRGAS 2000 localizado na estrutura DP04 a aproximadamente 3.000 metros da área da obra. Essa condição implicaria aumento do tempo de execução e imprecisão nas coordenadas.​', N'01 - Imagens/02 - Depois/10037.jpeg', N'Foi realizada a implantação e o rastreio de dois marcos geodésicos referenciados ao sistema SIRGAS 2000 no polígono do DP02 pela equipe de Geoprocessamento, proporcionando ganho operacional.
INSERT INTO #PVC VALUES (10038, N'81042135', N'81042135', N'Acompanhamento das cartas de serviço/service magazine para fornecedor SOTREQ', 1, N'Projects/Projetos', N'Ausência de gestão estruturada das Cartas de Serviço/Service Magazine para o fornecedor SOTREQ.', N'Implantar modelo estruturado de gestão das Cartas de Serviço (Service Magazine) junto ao fornecedor SOTREQ, garantindo controle, priorização e rastreabilidade das recomendações técnicas.', N'10015', N'01 - Imagens/01 - Antes/10038.jpeg', N'Ausência de gestão estruturada das Cartas de Serviço/Service Magazine para o fornecedor SOTREQ.', N'01 - Imagens/02 - Depois/10038.jpeg', N'Foi implantado modelo estruturado de gestão das Cartas de Serviço (Service Magazine) junto ao fornecedor SOTREQ, garantindo controle, priorização e rastreabilidade das recomendações técnicas.', NULL, N'Sim, foi padronizado e criado uma planilha para acompanhamento das cartas de serviço junto ao fornecedor.', N'Melhor gestão das cartas de serviço/service magazine', 0, NULL, N'Garantir controle efetivo dos laudos de preditiva, rastreabilidade das ações, acompanhamento dos prazos e maior previsibilidade para programação das intervenções de manutenção.
INSERT INTO #PVC VALUES (10039, N'515032', N'515032', N'Suporte de mochilas', 3, N'Others/Outros', N'Mochilas colocadas em local inadequado gerando uma desorganização  ', N'Organização da área  ', N'10362', N'01 - Imagens/01 - Antes/10039.jpeg', N'Mochilas armazenadas em local inadequado, gerando desorganização no ambiente de trabalho.', N'01 - Imagens/02 - Depois/10039.jpeg', N'Instalação de suportes para armazenamento adequado das mochilas, promovendo maior organização e melhoria no ambiente de trabalho.', NULL, N'Sim ', N'Pequenas melhorias estruturais, como a instalação de suportes, contribuem significativamente para a organização e qualidade do ambiente de trabalho.', 0, NULL, NULL, '2026-05-11T00:00:00.000', '2026-05-14T14:34:05.000', N'515032', NULL, NULL);
INSERT INTO #PVC VALUES (10040, N'81026411', N'81026411', N'PROTEÇÃO DA BANDEIROLA DA CAMIONETE', 1, N'Others/Outros', N'O atrito constante entre mosquetão metálico e a bandeirola da camionete gera desgaste na fita de LED, levando ao rompimento dos fios internos e causando falha da sinalização e risco de choque elétrico. Camionete fica impossibilitada de acessar a Mina.', N'Proteger a bandeirola da camionete, evitando seu dano e  impedimento de acesso à Mina. Aumentar a Disponibilidade Física da CAmionete.', N'10363', N'01 - Imagens/01 - Antes/10040.jpeg', N'O atrito constante entre mosquetão metálico e a bandeirola da camionete gera desgaste na fita de LED, levando ao rompimento dos fios internos e causando falha da sinalização e risco de choque elétrico. Camionete fica impossibilitada de acessar a Mina. Perda de Disponibilidade Física da camionete.', N'01 - Imagens/02 - Depois/10040.jpeg', N'Isolamento do ponto de contato com espuma protetora, preservando a integridade da mangueira de LED e mantendo a funcionalidade do sinalizador. Aumento da disponibilidade física da camionete.', NULL, N'Sim, prevenção de dano à bandeirola e aumento da disponibilidade física da camionete.', N'Necessidade de análise de causas de eventos para a prevenção de eventos futuros.', 0, NULL, N'Após a implementação do controle, foram obtidos ganhos significativos, tais como:
INSERT INTO #PVC VALUES (10041, N'81033358', N'81033358', N'X-Lift Truck Cost savings', 1, N'Underground/Subterrâneo', N'High cost of damage to unit unreasonable using new OEM parts due to age of unit.', N'Cost saving', N'10238', N'01 - Imagens/01 - Antes/10041.jpeg', N'High cost of damage to unit unreasonable using new OEM parts due to age of unit. Several parts are now obsolete making maintaining the unit an issue.', N'01 - Imagens/02 - Depois/10041.jpeg', N'Using newer parts and components saved from a previous decommissioning of a like unit, many high costs were able to be eliminated and saved. Saved approximately $15,000.', NULL, N'Using good components salvaged from a decommissioned unit instead of purchasing a new component from the OEM cut costs.', N'Retrieval of salvageable good components and parts cuts cost and down time.', 15000, 3, N'A solução atende aos princípios de melhoria contínua e apresenta potencial de replicação para outras semelhantes. áreas com condições.', '2026-05-15T00:00:00.000', '2026-05-14T14:51:44.000', N'81033358', NULL, NULL);
INSERT INTO #PVC VALUES (10042, N'81013885', N'81013885', N'Suporte para transporte de radiadores', 2, N'Others/Outros', N'Anteriormente os radiadores eram transportados de forma manual sem condições de ser transportados com empilhadeira.', N'Fabricar suporte para transportar radiadores', N'10362', N'01 - Imagens/01 - Antes/10042.jpeg', N'Anteriormente os radiadores não possuíam suporte para transporte, tendo que ser transportados de forma manual.', N'01 - Imagens/02 - Depois/10042.jpeg', N'Após a fabricação do suporte agora é possível realizar o transporte com empilhadeira e paleteira.', NULL, N'Sim', N'Sempre bom ver as dificuldades da área para criação de dispositivos que melhoram e facilitem o dia a dia na manutenção.', 0, NULL, N'The pump system also was more efficient way as it was pumping the sand in a more uniform way.', '2026-05-13T00:00:00.000', '2026-05-14T14:58:37.000', N'81013885', NULL, NULL);
INSERT INTO #PVC VALUES (10043, N'515032', N'81015664', N'Suporte para armazenamento de caixa de eletrodo de solda ', 3, N'Others/Outros', N'Caixa armazenado de forma inadequado gerando desorganização no ambiente de trabalho  ', N'Organiza o ambiente de trabalho ', N'10362', N'01 - Imagens/01 - Antes/10043.jpeg', N'Armazenamento inadequado de caixa, causando desorganização no ambiente de trabalho.', N'01 - Imagens/02 - Depois/10043.jpeg', N'Confecção e instalação de base para armazenamento adequado das caixas, proporcionando melhor organização da área.', NULL, N'Sim', N'A ausência de um local adequado para armazenamento de materiais contribui diretamente para a desorganização do ambiente de trabalho, sendo essencial definir e implementar soluções apropriadas para acondicionamento.', 0, NULL, N'Melhorar o acesso à caixa de acessórios de amarração do caminhão prancha, proporcionando apoio adequado para os pés, maior estabilidade e mais segurança durante a atividade.', '2026-05-12T00:00:00.000', '2026-05-14T15:07:25.000', N'515032', NULL, NULL);
INSERT INTO #PVC VALUES (10044, N'81018181', N'81046944', N'bomba de transferência de óleo ', 3, N'Others/Outros', N'antes o abastecimento dos tambores erra feita de forma manual ou com ajuda de caminhão munck  tornando a atividade morosa e expondo os colaboradores ao içamento de carga.', N'redução de tempo', N'10362', N'01 - Imagens/01 - Antes/10044.jpeg', N'antes o abastecimento dos tambores erra feita de forma manual ou com ajuda de caminhão munck  tornando a atividade morosa e expondo os colaboradores ao içamento de carga.', N'01 - Imagens/02 - Depois/10044.jpeg', N'Foi instalado uma bomba propulsora fixa no equipamento agilizando as atividades e eliminando a utilização de caminhão munck e o içamento de carga tornando a atividade mais segura e retirando os colaboradores da linha de fogo ', NULL, N'foram alcançadas ', N'melhoria continua ', 0, NULL, N'Padronização do trabalho, redução de atividades manuais e mais foco do time na segurança do controle de acesso.
INSERT INTO #PVC VALUES (10045, N'549569', N'549569', N'Arquivamento das amostras de bica de vazamento', 2, N'Others/Outros', N'As amostras de bica de vazamento de metal, após serem analisadas, eram arquivadas por um período de 30 dias dentro de gavetas. No entanto, devido ao desgaste dos armários e ao peso das amostras, as gavetas frequentemente se desprendiam ao serem abastecidas com novas amostras. Essa situação gerava risco de prensamento das mãos e dedos dos operadores e dificultava a identificação das amostras, já que, ao caírem, perdiam a sequência organizada.', N'Eliminação do risco de prensamento', N'10233', N'01 - Imagens/01 - Antes/10045.jpeg', N'As amostras de bica de vazamento de metal, após serem analisadas, eram arquivadas por um período de 30 dias dentro de gavetas. No entanto, devido ao desgaste dos armários e ao peso das amostras, as gavetas frequentemente se desprendiam ao serem abastecidas com novas amostras. Essa situação gerava risco de prensamento das mãos e dedos dos operadores e dificultava a identificação das amostras, já que, ao caírem, perdiam a sequência organizada.', N'01 - Imagens/02 - Depois/10045.jpeg', N'As amostras de bica de vazamento de metal passaram a ser armazenadas em um sistema de estantes com proteção frontal transparente, organizadas de forma alinhada e identificada. A nova estrutura é adequada ao peso das amostras, proporcionando maior estabilidade, segurança e facilidade de visualização. Com isso, foram eliminados os riscos de queda de gavetas, prensamento de mãos e desorganização, garantindo um ambiente mais seguro e eficiente.', NULL, N'Sim. Conseguimos eliminar o risco de prensamento, e ainda conseguimos deixar a área mais organizada.', N'NA', 0, NULL, N'Existiam dois freezers de gelo sem identificação clara.
INSERT INTO #PVC VALUES (10046, N'81018181', N'81018181', N'pintura e revitalização', 3, N'Others/Outros', N'antes não tínhamos um local dedicado para equipamentos de combate a incêndio. ', N'revitalização ', N'10362', N'01 - Imagens/01 - Antes/10046.jpeg', N'antes não tínhamos um local dedicado para equipamentos de combate a incêndio. ', N'01 - Imagens/02 - Depois/10046.jpeg', N'Foi criado um local destinado as equipamentos a combate a incêndio facilitando a utilização dos equipamentos em casa de sinistros e criando um ponto de referencia para os colaboradores.', NULL, N'meta alcançada ', N'melhoria do ambiente', 0, NULL, N'for all workers to be able to reach valves', '2026-05-12T00:00:00.000', '2026-05-14T15:17:36.000', N'81018181', NULL, NULL);
INSERT INTO #PVC VALUES (10047, N'66944', N'66944', N'Mapa de acompanhamento de U semanal', 1, N'Concentration/Concentração', N'Equipe de Controle de Qualidade do produto não tinha visão prévia dos teores de U previstos na alimentação semanal', N'Melhorar previsibilidade de teores de U no concentrado final da Usina', N'10247', N'01 - Imagens/01 - Antes/10047.jpeg', N'Apresentação de Geometalurgia da programação semanal de alimentação trazia apenas o mapa com os teores de Magnésio.', N'01 - Imagens/02 - Depois/10047.jpeg', N'Foi inserido mapa com os polígonos do plano mensal de lavra, modelo de blocos com teores de U e destacados, semanalmente, os polígonos que estão previstos na alimentação da Britagem primária. Deste modo a equipe de Controle de Qualidade do produto pode ter uma visão mais realista dos teores esperados na alimentação e concentrado final.', NULL, N'SIM/ Equipe de Controle de Qualidade do produto pode estimar os teores de U do produto final com base no mapa de teores de U e polígonos previstos para alimentação', N'Disseminar o conhecimento para melhorar a previsibilidade  do U no Concentrado final', 0, NULL, NULL, '2026-05-14T00:00:00.000', '2026-05-14T15:25:05.000', N'66944', NULL, NULL);
INSERT INTO #PVC VALUES (10048, N'81033139', N'81033139', N'BI de movimentação de pneus', 1, N'Others/Outros', N'Sem nenhuma controle disponível', N'Aumentar a eficiência na gestão de pneus através da visualização e análise da  geração versus consumo de estoque por frota, com o objetivo de identificar  gaps, reduzir estoque excedente e melhorar a aderência orçamentária.', N'10015', N'01 - Imagens/01 - Antes/10048.jpeg', N'Sem controle', N'01 - Imagens/02 - Depois/10048.jpeg', N'A implementação do Power BI 
INSERT INTO #PVC VALUES (10049, N'987537', N'473420', N'TRAVAMENTO DO COMANDO FINAL 793 NO SUPORTE.', 2, N'Others/Outros', N'Deslizamento longitudinal do comando sobre o suporte durante uma frenagem.
INSERT INTO #PVC VALUES (10050, N'471876', N'471876', N'DIFICULDADE EM RECEBER GASES', 1, N'Others/Outros', N'Dificuldade em receber gases devido isolamentos da obra', N'facilitar recebimento', N'10366', N'01 - Imagens/01 - Antes/10050.jpeg', N'Este Ano estamos com os mais diversos Projetos em execução, isolamentos, Maquinas nas passagens, caminhos seguros isolados, vindo a ter dificuldade em operações rotineiras, gerando desconfortos, atrasos, uma delas é o recebimento de gases, produto essencial para a rotina do Laboratório.', N'01 - Imagens/02 - Depois/10050.jpeg', N'Procuramos alternativas e conversamos tanto com a nossa equipe, quanto a equipe que faz a entrega do Produto e chegamos a um local especifico, porém um detalhe atrapalhava, pedaço de um Guarda corpo, foi retirado se oferecer risco e ficou melhor o recebimento, mais rápido e mais perto da Baia de gases, evitando os isolamentos e possíveis batida contra, resolvendo o problema.', NULL, N'resolvido', N'que em equipe pensando junto,, a solução aparece.', 0, NULL, NULL, '2026-05-11T00:00:00.000', '2026-05-14T15:48:20.000', N'471876', NULL, NULL);
INSERT INTO #PVC VALUES (10051, N'542336', N'542336', N'CONTROLE DE LAUDOS', 1, N'Others/Outros', N'FALTA DE CONTROLE E VIZIBILIDADE', N'CONTROLE ', N'10081', N'01 - Imagens/01 - Antes/10051.jpeg', N'Não havia um controle estruturado dos laudos de preditiva, o que dificultava a rastreabilidade das anomalias identificadas, a definição de responsáveis, o acompanhamento dos prazos e a tomada de decisão sobre as ações necessárias. As tratativas ocorriam de forma pontual, sem padronização, aumentando o risco de pendências sem plano de ação definido.
INSERT INTO #PVC VALUES (10052, N'134296', N'81006744', N'Protetor do assolho da carroceria caminhão Munck ', 1, N'Others/Outros', N'Desgaste prematuro no assolho do caminhão, sendo necessário reparo no assoalho para restabelecer condição normal .
INSERT INTO #PVC VALUES (10053, N'532866', N'532866', N'Controle de Processos por contratos de Comodatos', 1, N'Others/Outros', N'Anteriormente, o processo de controle de itens em comodato não possuía um sistema estruturado de gestão.
INSERT INTO #PVC VALUES (10054, N'81042217', N'81042217', N'Implantação de iluminação fixa para inspeção segura de shute de transferência em espaço restrito', 2, N'Others/Outros', N'A inspeção do shut de transferência era realizada em um local sem iluminação adequada, com espaço restrito, exigindo que o inspetor acessasse o ponto agachado. A baixa visibilidade dificultava a avaliação do equipamento e aumentava o risco de impacto da cabeça em estruturas superiores, situação  recorrente durante a atividade, mitigada apenas pelo uso de EPI.', N'Eliminar a condição de risco associada à inspeção do shut de transferência em ambiente com iluminação insuficiente. Melhorar a visibilidade e ergonomia durante a atividade de inspeção, principalmente no período noturno. Reduzir o risco de impacto da cabeça em estruturas superiores em espaço restrito. Garantir melhores condições de trabalho, aumentando a eficiência da inspeção e a segurança do colaborador.', N'10294', N'01 - Imagens/01 - Antes/10054.jpeg', N'O local apresenta ausência de iluminação fixa no ponto de 
INSERT INTO #PVC VALUES (10055, N'606883', N'608562', N'Sand media install HDS plant filter', 2, N'Others/Outros', N'When replacing sand media in water filter at HDS plant ', N'To fill the filter at HDS plant with a more safe and effective method', N'10328', N'01 - Imagens/01 - Antes/10055.jpeg', N'When replacing the sand media in the large filter assemblies, employees originally needed to bring the sand media bag by bag to top of scaffolding and dump into filter housing. This proved to be time consuming and posed MSD injury potentials', N'01 - Imagens/02 - Depois/10055.jpeg', N'Pump system was designed and fabricated to pump the sand with water as a "slurry" into the top of the filter housing. This reduced the handling of sandbags from bringing them to the top of the scaffold and being poured in one by one, to pouring into the pump bin with water and pumping in. EE''s only needed to bring up discharge hose to top of filter housing and secure and attend to ensure proper amount of media was installed', NULL, N'The goal was achieved as the handling of the sand media was reduced to ground level, reducing ergonomic factors of bringing up to top of scaffold and pour into filter housing 1 bag at a time into a small opening', N'Able to find a different method of filling filter with sand media media', 0, NULL, N'GANHO DE PRODUTIVIDADE.', '2026-05-13T00:00:00.000', '2026-05-15T07:14:35.000', N'606883', NULL, NULL);
INSERT INTO #PVC VALUES (10056, N'543301', N'543301', N'Instalação de plataforma de apoio para acesso seguro em caminhão', 2, N'Others/Outros', N'Durante o acesso à caixa de correntes do caminhão prancha, foi observado que os colaboradores não dispõem de um local adequado para apoio dos pés durante a retirada e o armazenamento das correntes.
INSERT INTO #PVC VALUES (10057, N'81051666', N'81012634', N'SISTEMA IOT – CONTROLE DE ACESSO À AREAS DE ZAS', 1, N'Others/Outros', N'O controle de acesso à área de ZAS na Guarita da Barragem do Sossego era realizado de forma manual, com registro em papel/prancheta e validação do treinamento PAEBM por meio de passaporte físico. Esse método gerava risco de falhas de checagem, baixa rastreabilidade, possibilidade de inconsistências no registro e maior tempo de atendimento, aumentando a exposição de pessoas e veículos no ponto de controle.
INSERT INTO #PVC VALUES (10058, N'81035706', N'81035706', N'IDENTIFICAÇÃO DOS FREEZES E CHECK DE LIMPEZA SEMANAL', 3, N'Others/Outros', N'Freezers sem identificação
INSERT INTO #PVC VALUES (10059, N'1015684', N'1010297', N'Concentrate feed bin air valves scaffolding', 1, N'Refining/Refino', N'The new air valves on the concentrate feed bin are to high for most technicians to each even from a 3 step ladder.', N'Have a scaffold platform built to make the valves accessible for all workers', N'0', N'01 - Imagens/01 - Antes/10059.jpeg', N'Workers would have to use a step stool to reach valves, most workers still could not reach and have to call for another worker to come help them.', N'01 - Imagens/02 - Depois/10059.jpeg', N'Had a scaffold built to safely access valves for workers.', NULL, N'problem has been resolved, valves can now be accessed by everyone', N'Having proper workstation setup makes completing job safe and easy. ', 0, NULL, N'ergonomia pois a váLvula ficava muito alto, tendo que utilizar um tubo a=para movimentar a válvula', '2026-05-14T00:00:00.000', '2026-05-15T15:00:30.000', N'1015684', NULL, NULL);
INSERT INTO #PVC VALUES (10060, N'472940', N'472940', N' Dispositivo para troca de rodanas (rolos), elos da corrente (link) e sapatas.', 2, N'Crusher/Britadeira', N'“O processo que utilizava talha apresentava baixa eficiência e alto risco devido à falta de controle de alinhamento e força. Processo lento muito retrabalho', N'Otimização dos Processos e diminuição do cenário de risco', N'10362', N'01 - Imagens/01 - Antes/10060.jpeg', N' utilizava talha apresentava baixa eficiência e alto risco devido à falta de controle de alinhamento e força. Colaboradores em linha de fogo, demora no serviço, tentativa de alinhar, corrente sob tensão.', N'01 - Imagens/02 - Depois/10060.jpeg', N'Atividade planejada e padronizada, sem cabo tensionado da talha sem pancada excessiva, com a implementação de dispositivo adequado, houve melhoria em segurança, Forca controlada e menos retrabalho.', NULL, N'sim, Padronização no processo, redução esforço físico, ganhos em tempo e produtividade e diminuição de retrabalho, mais segurança, e menos custo.
INSERT INTO #PVC VALUES (10061, N'134296', N'81006744', N'Proteção do assoalho da carroceria caminhão Munck ', 1, N'Others/Outros', N'Desgaste prematuro do assoalho da carroceria, 
INSERT INTO #PVC VALUES (10062, N'81046149', N'81040359', N'Suporte de mangueiras ', 1, N'Others/Outros', N'Mangueira armazenada sem suporte adequado, permanecendo no piso ou enrolada de forma incorreta, ocasionando riscos de danos ao equipamento, obstrução da área, desgaste prematuro e possibilidade de tropeços e quase acidentes no ambiente de trabalho.', N'Manter ambiente de trabalho limpo e organizado.', N'10362', N'01 - Imagens/01 - Antes/10062.jpeg', N'Mangueira armazenada sem suporte adequado, permanecendo no piso ou enrolada de forma incorreta, ocasionando riscos de danos ao equipamento, obstrução da área, desgaste prematuro e possibilidade de tropeços e quase acidentes no ambiente de trabalho.', N'01 - Imagens/02 - Depois/10062.jpeg', N'Realizado fabricação e instalação de suporte para mangueira na área operacional, proporcionando melhor organização do ambiente, armazenamento adequado do material, redução de riscos de tropeços e aumento da segurança e eficiência das atividades operacionais.', NULL, N'A implantação do suporte para mangueira na área operacional demonstrou a importância da organização e adequação do ambiente de trabalho para prevenção de riscos. A melhoria proporcionou maior segurança aos executantes, conservação do material, redução de possíveis quase acidentes e melhor eficiência nas atividades operacionais.', N'A implantação do suporte para mangueira na área operacional demonstrou a importância da organização e adequação do ambiente de trabalho para prevenção de riscos. ', 5, 1, N'To be able to bleed water hose of pressure', '2026-05-09T00:00:00.000', '2026-05-16T04:13:36.000', N'81046149', NULL, NULL);
INSERT INTO #PVC VALUES (10063, N'81046149', N'81040359', N'Acesso seguro', 1, N'Others/Outros', N'Escada de acesso com degraus danificados, apresentando condições inadequadas de uso, com risco de escorregamento, tropeço e queda dos colaboradores durante o acesso à área operacional.', N'Eliminar os riscos de acidentes relacionados à utilização da escada com degraus danificados, garantindo condições seguras de acesso à área operacional.', N'10362', N'01 - Imagens/01 - Antes/10063.jpeg', N'Escada de acesso com degraus danificados, apresentando condições inadequadas de uso, com risco de escorregamento, tropeço e queda dos colaboradores durante o acesso à área operacional.', N'01 - Imagens/02 - Depois/10063.jpeg', N'A identificação e correção dos degraus danificados da escada reforçaram a importância das inspeções preventivas nas estruturas de acesso da área operacional. A adequação da escada contribuiu para a redução de riscos de quedas, aumento da segurança dos colaboradores e melhoria das condições de trabalho e circulação no ambiente operacional.', NULL, N'Realizar a recuperação ou substituição dos degraus danificados da escada, proporcionando maior segurança, estabilidade, confiabilidade e melhoria nas condições de trabalho dos colaboradores.', N'A identificação e correção dos degraus danificados da escada reforçaram a importância das inspeções preventivas nas estruturas de acesso da área operacional.', 10, 1, N'meta atingida', '2026-05-04T00:00:00.000', '2026-05-16T04:35:46.000', N'81046149', NULL, NULL);
INSERT INTO #PVC VALUES (10064, N'81046149', N'81046149', N'Proteção de canaletas ', 2, N'Others/Outros', N'Canaleta com proteção danificada ou ausente, deixando partes expostas na área operacional, ocasionando risco de tropeços, quedas, danos aos cabos/equipamentos e comprometimento da segurança no ambiente de trabalho.', N'Eliminar os riscos gerados pela canaleta com proteção danificada ou ausente, garantindo segurança e organização na área operacional. Objetivo', N'10362', N'01 - Imagens/01 - Antes/10064.jpeg', N'Canaleta com proteção danificada ou ausente, deixando partes expostas na área operacional, ocasionando risco de tropeços, quedas, danos aos cabos/equipamentos e comprometimento da segurança no ambiente de trabalho.', N'01 - Imagens/02 - Depois/10064.jpeg', N'Realizar adequar instalação da proteção da canaleta para prevenir riscos de acidentes, melhorar as condições de segurança e garantir a integridade dos colaboradores durante a execução das atividades.', NULL, N'Foi realizada a adequação da proteção da canaleta, eliminando a condição insegura e garantindo maior segurança na área operacional.', N'A inspeção preventiva e a correção imediata de proteções danificadas contribuem para a redução de riscos, promovendo um ambiente de trabalho mais seguro e organizado.', 10, 1, N'Tivemos ganho no tempo da  realizaçao da atividade. 
INSERT INTO #PVC VALUES (10065, N'81046149', N'81040359', N'Armazenamento de componentes ', 3, N'Others/Outros', N'Materiais para armazenamento de componentes encontravam-se sem local adequado, causando desorganização na área, dificuldade de acesso e risco de danos aos componentes e acidentes operacionais.', N'A criação de locais específicos para armazenamento melhora o controle dos materiais, otimiza o ambiente de trabalho e aumenta a segurança operacional.', N'10362', N'01 - Imagens/01 - Antes/10065.jpeg', N'Materiais para armazenamento de componentes encontravam-se sem local adequado, causando desorganização na área, dificuldade de acesso e risco de danos aos componentes e acidentes operacionais.', N'01 - Imagens/02 - Depois/10065.jpeg', N'Foi realizada a fabricação e instalação de um local adequado para armazenamento dos componentes, proporcionando melhor organização, segurança e preservação dos materiais na área operacional.', NULL, N'A adequação do local de armazenamento reduziu riscos de danos aos componentes, melhorou o acesso aos materiais e contribuiu para a organização e eficiência das atividades', N'A criação de locais específicos para armazenamento melhora o controle dos materiais, otimiza o ambiente de trabalho e aumenta a segurança operacional.', 10, 1, NULL, '2026-05-08T00:00:00.000', '2026-05-16T05:20:14.000', N'81046149', NULL, NULL);
INSERT INTO #PVC VALUES (10066, N'460383', N'460383', N'Easier to access Daily Comp bottles', 1, N'Others/Outros', N'Daily Comp bottles have been kept on a raised, center portion of a double sided bench.  They were often obstructed by other objects and difficult to reach, especially for people with shoulder issues.', N'Have daily comp bottles stored in an easy to access area', N'#N/A', N'01 - Imagens/01 - Antes/10066.jpeg', N'Daily Comp bottles have been kept on a raised, center portion of a double sided bench.  They were often obstructed by other objects and difficult to reach, especially for people with shoulder issues.', N'01 - Imagens/02 - Depois/10066.jpeg', N'The bottles were moved to a cart where Weekly comp bottles are left to dry.  The cart was labelled and identified as the new storage area for Daily and Weekly comp bottles.  There was also a location identified and labeled as the storage space for the cart.', NULL, N'Yes', N'Store frequently used items in easy to access locations', 0, NULL, NULL, '2026-05-15T00:00:00.000', '2026-05-16T16:05:05.000', N'460383', NULL, NULL);
INSERT INTO #PVC VALUES (10067, N'533543', N'81032592', N' Pré-seleção  no grupo de retomada de alimentação.', NULL, N'No Replication/Sem replicação', N' Atualmente, não temos um alarme na tela principal da Estocagem Secundária indicando que o 
(ou) alimentador (es) do túnel (AL-2301SA-01 / 02 / 03 e 04.), não está habilitado em modo Set 
INSERT INTO #PVC VALUES (10068, N'533543', N'81032592', N'MODO REVESTIMENTO NOVO', NULL, N'No Replication/Sem replicação', N'MODO REVESTIMENTO NOVO HABILITADO DO BR-2005-02 COM MARGEM DE CHEGAR A 75% DE VELOCIDADE DO AL-2005-02 PODENDO OCORRER RISCO DE PARADA DO EQUIPAMENTO', N'MINIMIZAR PARADA DO EQUIPAMENTO POR SOBRECARGA', N'0', N'01 - Imagens/01 - Antes/10068.jpeg', N'AL-2005-02 eleva a rotação até 75% de velocidade com modo revestimento novo do BR-2005-02, Risco de parada da máquina por sobrecarga.', N'01 - Imagens/02 - Depois/10068.jpeg', N'REALIZADO AJUSTE DE ROTAÇÃO DO AL-2005-02 QUANDO ESTIVER MODO REVESTIMENTO NOVO HABILITADO NO BR-2005-02, DE 75% PARA 65% CONDIÇÃO REALIZADA DIRETAMENTE NA LOGICA EVITANDO PARADA DO EQUIPAMENTO. ', NULL, N'GANHO EM PRODUTIVIDADE E PARADA DE EQUIPAMENTO POR SOBRECARGA ', N'MELHORIA E PRODUTIVIDADE ', 0, NULL, N'Tivemos ganho em segurança ao minimizar possíveis danos nos equipamentos e facilitando limpeza.', '2026-05-16T00:00:00.000', '2026-05-16T16:52:32.000', N'533543', NULL, NULL);
INSERT INTO #PVC VALUES (10069, N'81056157', N'81056157', N'Inclusão de um Guarda-Corpo Móvel ao AL 623-01', 2, N'Refining/Refino', N'Risco de queda de altura nas manutenções pertinentes ao Al 623-01', N'eliminação do risco de queda ; otmização de manutenções', N'10170', N'01 - Imagens/01 - Antes/10069.jpeg', N'Para manutençoes AL 623-01era necessário montagem de andaime e maior tempo de intervenção', N'01 - Imagens/02 - Depois/10069.jpeg', N'Projetado guarda corpo móvel garantindo segurança ,ergonomia ,otimização de tempo e redução de custo. Eliminando assim, a condição insegura do local. Também foi realizada a GM de número 5986, de acordo a mudança do projeto.', NULL, N'Sim, foi eliminado o risco de queda .', N'Aumento da percepção de risco, garantia de segurança', 15000, 1, N'A melhoria contribui para uma identificação mais rápida do equipamento pelos colaboradores, reforçando as condições de segurança e atendimento emergencial no ambiente de trabalho.', '2026-03-29T00:00:00.000', '2026-05-16T17:55:48.000', N'81056157', NULL, NULL);
INSERT INTO #PVC VALUES (10070, N'81024716', N'81024716', N'Engate rápido dreno e abastecimento cabeça rotativo PZ45', 2, N'Others/Outros', N'Tinha dificuldade de abastecimento e dreno de óleo cabeça rotativa ', N'facilitar acesso', N'10150', N'01 - Imagens/01 - Antes/10070.jpeg', N'Cabeça rotativa com taps para extração para dreno e abastecimento de óleo, dificultando acesso na PZ45.', N'01 - Imagens/02 - Depois/10070.jpeg', N'Aplicado engate rápido afim de facilitar acesso ao drenar e abastecer óleo na cabeça rotativa PZ45', NULL, N'Antes no formato original, teria que extrair taps para acesso bico da mangueira de abastecimento ocasionado  derramamento de óleo e esforço repetitivo mão de obra humana. Ganhamos eliminando condições de exposição humana no manuseio na aplicação de engate rápido facilitando no abastecimento com comboio de hidraulico. ', N'Menos exposição humana durante manuseio', 10, 1, N'ZERO EXPOSIÇÃO , AGILIDADE E QUALIDADE NA AMOSTRA.', '2026-05-13T00:00:00.000', '2026-05-16T18:11:17.000', N'81024716', NULL, NULL);
INSERT INTO #PVC VALUES (10071, N'520044', N'520044', N'Frasco reserva para solução de Ácido Nítrico 3%', 1, N'Others/Outros', N'Na análise de ICP-MS é utilizado a solução de Ácido Nítrico 3%, onde a mesma se consome e acaba muito rápido na etapa de leitura, é necessário fazer varias vezes a solução durante o turno.', N'otimizar o tempo na etapa de confecção de soluções', N'10206', N'01 - Imagens/01 - Antes/10071.jpeg', N'Na análise de ICP-MS é utilizado a solução de Ácido Nítrico 3%, onde a mesma se consome e acaba muito rápido na etapa de leitura, é necessário fazer varias vezes a solução durante o turno.', N'01 - Imagens/02 - Depois/10071.jpeg', N'Foi disponibilizado um frasco reserva para solução de Ácido Nítrico, onde reduziu a pausas para confecção, na etapa de preparação agora podemos fazer 4 litros de solução de uma vez só, reduzindo tempo nessa etapa.', NULL, N'Foi alcançado o objetivo de reduzir tempo e melhorar o processo de confecção', N'Através da melhoria podemos melhorar nossa etapas.', 0, NULL, N'Maintaining integrity and Improving Workability', '2026-05-15T00:00:00.000', '2026-05-16T19:08:27.000', N'520044', NULL, NULL);
INSERT INTO #PVC VALUES (10072, N'81022566', N'81033840', N'´VALVULA PARA COLETAGEM DE AMOSTRAS', 1, N'Others/Outros', N'Dificuldade para coleta da amostras na filtragem, necessário 2 pessoas, uma para ligar a válvula e outra para segurar a mangueira. Antes tínhamos que usar um tubo pois a válvula era muito alta', N'ERGONOMIA E AGILIDADE', N'10343', N'01 - Imagens/01 - Antes/10072.jpeg', N'Dificuldade para coleta da amostras na filtragem, necessário 2 pessoas, uma para ligar a válvula e outra para segurar a mangueira. Antes tínhamos que usar um tubo pois a válvula era muito alta', N'01 - Imagens/02 - Depois/10072.jpeg', N'Fabricado mangueira e instalado válvula em posição estratégica para facilitar a coleta agora apenas com uma pessoa', NULL, N'sim, pois reduziu de duas pessoas para a coleta agora apenas uma ja resolve', N'VER E AGIR', 0, NULL, N'This activity has been reduced 3 minutes a time.', '2026-05-16T00:00:00.000', '2026-05-17T04:58:24.000', N'81022566', NULL, NULL);
INSERT INTO #PVC VALUES (10073, N'87000312', N'87000381', N'Make it easier to use hot water around the 1st floor pit', 1, N'Refining/Refino', N'There were no pipes providing immediate hot water around the 1F pit, so we had to wait a long time for hot water to come on.', N'Make it easier to use hot water around the 1st floor pit', N'0', N'01 - Imagens/01 - Antes/10073.jpeg', N'There were no pipes providing immediate hot water around the 1F pit, so we had to wait a long time for hot water to come on.', N'01 - Imagens/02 - Depois/10073.jpeg', N'New nozzles have been installed in the hot water pipes flowing around the 1F pit. This allows for the use of hot water without any waiting time.', NULL, N'Yes, we could achieve the target as we thought.', N'Asset ', 0, NULL, NULL, '2026-05-14T00:00:00.000', '2026-05-17T06:27:05.000', N'87000312', NULL, NULL);
INSERT INTO #PVC VALUES (10074, N'81007243', N'81048616', N'Correção de Iluminação nas atividades  externas na oficina', 1, N'Others/Outros', N'A insuficiência de iluminação na área de manutenção de equipamentos compromete a visibilidade dos colaboradores, dificultando a identificação de componentes, pontos de intervenção e potenciais riscos.  A baixa iluminação representa um fator crítico de risco, especialmente em atividades noturnas, podendo impactar diretamente na segurança dos colaboradores e na confiabilidade dos serviços executados.', N'Melhor a iluminação das atividades', N'10139', N'01 - Imagens/01 - Antes/10074.jpeg', N'A insuficiência de iluminação na área de manutenção de equipamentos compromete a visibilidade dos colaboradores, dificultando a identificação de componentes, pontos de intervenção e potenciais riscos.  A baixa iluminação representa um fator crítico de risco, especialmente em atividades noturnas, podendo impactar diretamente na segurança dos colaboradores e na confiabilidade dos serviços executados.', N'01 - Imagens/02 - Depois/10074.jpeg', N'Como ação de melhoria contínua, foi confeccionada e disponibilizada uma luminária móvel para utilização nas áreas externas à oficina, com o objetivo de proporcionar melhores condições de iluminação, aumentando a segurança e a qualidade das atividades executadas pela equipe de manutenção. 
INSERT INTO #PVC VALUES (10075, N'1015684', N'1015684', N'Water hose shut off valve', 1, N'Refining/Refino', N'The utility station outside the 212 annex door has a T on it and one of the water hoses has no way to bleed the pressure off.', N'Install a valve to be able to bleed pressure off the hose so it is not left charged all the time', N'0', N'01 - Imagens/01 - Antes/10075.jpeg', N'The utility station outside the 212-annex door has a T on it and one of the water hoses has no way to bleed the pressure off. This led to the water hose being charged at all times.', N'01 - Imagens/02 - Depois/10075.jpeg', N'Added a ball valve at the utility station to allow the water hose to be tuned off and then pressure bled off when not in use.', NULL, N'Yes, the ball valve now allows water to be bled off from the hose when not in use.', N'Proper materials in place to ensure water hose can be bled off properly', 0, NULL, N'Hooking up the plates without over reaching', '2026-05-16T00:00:00.000', '2026-05-17T09:25:21.000', N'1015684', NULL, NULL);
INSERT INTO #PVC VALUES (10076, N'498359', N'81061120', N'JANELA DE VISITA DO TROMMEL DO MOINHO', 2, N'Others/Outros', N'JANELA DE VISTA SOLTOU DEVIDO A CORROSÃO DA SOLDA, CAUSANDO RISCO DE QUEDA DE NIVEL DIFERENTE DE PESSOAS.', N'ELIMINAR RISCO DE QUEDA', N'10362', N'01 - Imagens/01 - Antes/10076.jpeg', N'JANELA DE VISTA SOLTOU DEVIDO A CORROSÃO DA SOLDA, CAUSANDO RISCO DE QUEDA DE NIVEL DIFERENTE DE PESSOAS.', N'01 - Imagens/02 - Depois/10076.jpeg', N'Foi feito o reparo com solda, eliminado o risco de queda de nivel diferente de pessoas e voltado com a proteção do equipamento. ', NULL, N'meta atingida', N'eliminar riscos da area', 0, NULL, N'Better ergonomics hooking up the press', '2026-05-07T00:00:00.000', '2026-05-17T15:10:15.000', N'498359', NULL, NULL);
INSERT INTO #PVC VALUES (10077, N'486351', N'500808', N'DESTALONADOR DE ANEL CONICO', 2, N'Others/Outros', N'Para destalonar o pneu se fazia uso da maquina pc17 forçando o anel conico junto com o pneu que estava montado no equipamento, para fazer a remoçao do anel conico.', N'Eliminar uso da maquina ou cilindro para remover o componente.', N'10140', N'01 - Imagens/01 - Antes/10077.jpeg', N'Para se fazer a remoçao do anel conico tinhamos que força a pc17 contra o pneu instalado no equipamento, afim de destalonar e remover os componetes, ou remover o pneu montado virar a parte contraria e destalonar com a poio de cilindro hidraulico.', N'01 - Imagens/02 - Depois/10077.jpeg', N'Criado dispotivo para remoçao do anel conico sem uso da tire handler.', NULL, N'SIM', N'SEGURANÇA E QUALIDADE', 0, NULL, N'Better house keeping and knowing where the equipment is', '2026-05-12T00:00:00.000', '2026-05-17T16:03:35.000', N'486351', NULL, NULL);
