INSERT INTO #PVC VALUES (10259, N'525172', N'81054838', N'Substituição das grades de piso da canaleta', 2, N'Others/Outros', N'As grades metálicas da canaleta localizadas ao lado do sump SLB I e II encontravam-se amassadas, deformadas e com desníveis ao longo de sua extensão.
INSERT INTO #PVC VALUES (10260, N'525172', N'81028887', N'Substituição das grades de piso da canaleta', 2, N'Others/Outros', N'As grades metálicas da canaleta localizadas ao lado da BP-2017-40 encontravam-se amassadas, deformadas e com desníveis ao longo de sua extensão.', N'Superfície uniforme, alinhada e sem deformações; Melhor estabilidade para circulação de pessoas; Área mais organizada e adequada às condições operacionais.', N'10229', N'01 - Imagens/01 - Antes/10260.jpeg', N'Essa condição gerava riscos significativos de segurança como possibilidade de tropeços e quedas durante circulação na área, torção de tornozelo e acidentes pessoais', N'01 - Imagens/02 - Depois/10260.jpeg', N'Com a substituição, a canaleta passou a apresentar superfície uniforme, alinhada e sem deformações, melhor estabilidade para circulação de pessoas', NULL, N'Antes, as grades danificadas geravam alto risco de queda e acidentes.
