INSERT INTO #PVC VALUES (10360, N'553135', N'521213', N'CONTROLE DE FPS - FROTA', 1, N'Others/Outros', N'ÁREA NÃO POSSUI CONTOLE E NEM IDENTIFICAÇÃO DE PN E CÓDIGO SAP. AUSENCIA DE IDENTIFICAÇÃO PARA APLICAÇÃO ', N'TORNAR O PROCESSO DE CONTROLE E APLICAÇÃO ÁGIL E CONFIÁVEL ', N'10139', N'01 - Imagens/01 - Antes/10360.jpeg', N'ÁREA NÃO POSSUI CONTOLE E NEM IDENTIFICAÇÃO DE PN E CÓDIGO SAP. AUSENCIA DE IDENTIFICAÇÃO PARA APLICAÇÃO.', N'01 - Imagens/02 - Depois/10360.jpeg', N'CRIADO CONTROLE COM PN''s, CÓDIGOS SAP, FACILITANDO A IDENTIFICAÇÃO E EVITANDO RETRABALHO. CONFIABILIDADE NA AQUISIÇÃO E APLICAÇÃO DAS BORDAS. ', NULL, N'CRIADO CONTROLE COM PN''s, CÓDIGOS SAP, FACILITANDO A IDENTIFICAÇÃO E EVITANDO RETRABALHO. CONFIABILIDADE NA AQUISIÇÃO E APLICAÇÃO DAS BORDAS. ', N'CONTROLE E CONFIABILIDADE ', 0, NULL, NULL, '2026-05-22T00:00:00.000', '2026-05-29T09:12:31.000', N'553135', NULL, NULL);
INSERT INTO #PVC VALUES (10361, N'553135', N'530384', N'SALA DE APOIO - R&I', 3, N'Others/Outros', N'EQUIPE DE MANUTENÇÃO R&I NÃO POSSUI UMA SALA DE APOIO ONDE PUDESSE CONCENTRAR OS INSUMOS BÁSICOS PARA REALIZAR AS ATIVIDADES DA ÁREA DE UMA FORMA RÁPIDA E ORGANIZADA. ', N'DEIXAR A MANUTENÇÃO MAIS AGIL E SEGURANÇA', N'10139', N'01 - Imagens/01 - Antes/10361.jpeg', N'EQUIPE DE MANUTENÇÃO R&I NÃO POSSUI UMA SALA DE APOIO ONDE PUDESSE CONCENTRAR OS INSUMOS BÁSICOS PARA REALIZAR AS ATIVIDADES DA ÁREA DE UMA FORMA RÁPIDA E ORGANIZADA. ', N'01 - Imagens/02 - Depois/10361.jpeg', N'CRIADA UMA SALA DE SUPORTE, ORGANIZADA E DE FÁCIL ACESSO, FACILITANDO A REALIZAÇÃO DAS ATIVIDADES E DEIXANDO A ÁREA MAIS LIMPA, ORGANIZADA E SEGURA. 
INSERT INTO #PVC VALUES (10362, N'553135', N'81019440', N'PAINEL DE CONTROLE E GESTÃO - CONFIABILIDADE', 1, N'Others/Outros', N'AUSENCIA DE UM LOCAL ESTRUTURADO ONDE A EQUIPE PUDESSE ACOMPANHAR DE PERTO DISPONIBILIDADE FISICA E A GESTÃO DE CARTEIRA/SAP', N'LEVAR A INFORMAÇÃO DE FORMA SIMPLES, RÁPIDA E ACERTIVA PARA EQUIPE', N'10139', N'01 - Imagens/01 - Antes/10362.jpeg', N'AUSENCIA DE UM LOCAL ESTRUTURADO ONDE A EQUIPE PUDESSE ACOMPANHAR DE PERTO DISPONIBILIDADE FISICA E A GESTÃO DE CARTEIRA/SAP', N'01 - Imagens/02 - Depois/10362.jpeg', N'CRIADO UM PAINEL DE ACOMPANHAMENTO DE DISPONIBILIDADE FISICA E GESTÃO DE CARTEIRA, DENTRO DO BOX FICANDO DE ACESSO RÁPIDO PARA OS EMPREGADOS. LEVANDO CONFIABILIDADE PARA O PROCESSO. ', NULL, N'CRIADO UM PAINEL DE ACOMPANHAMENTO DE DISPONIBILIDADE FISICA E GESTÃO DE CARTEIRA, DENTRO DO BOX FICANDO DE ACESSO RÁPIDO PARA OS EMPREGADOS. LEVANDO CONFIABILIDADE PARA O PROCESSO. ', N'ORGANIZAÇÃO E AGILIDADE ', 0, NULL, N'Depois da melhoria, o processo de trabalho com o pipa foi realizado com mas segurança, evitando acidentes.', '2026-05-26T00:00:00.000', '2026-05-29T09:47:08.000', N'553135', NULL, NULL);
INSERT INTO #PVC VALUES (10363, N'388959', N'541883', N'Realização de adequação de chassis báscula 785/793 para remoção de pino de cilindro– Caldeiraria', 1, N'Others/Outros', N'corte no chassis das básculas para retirada de pinos do cilindro de elevação', N'Proteger o Chassis das básculas de possíveis trincas', N'#N/A', N'01 - Imagens/01 - Antes/10363.jpeg', N'Furo no chassis de básculas para passagem do pino do cilindro de elevação', N'01 - Imagens/02 - Depois/10363.jpeg', N'tudo instalado reforçando a estrutura e evitando trincas no chassis.', NULL, N'Reforço na estrutura evitando trinca no chassis ', N'Melhorar a avaliação de intervenção em estruturas', 0, NULL, N'Redução de Custo (Savings): Diminuição de despesas operacionais diretas, como gastos com mão de obra para controle manual ou desperdício de energia.
INSERT INTO #PVC VALUES (10364, N'425934', N'425934', N'Controle das chaves dos armários (ferramentas manual)', 3, N'Others/Outros', N'Durante a rotina diária das atividades da oficina, os armários de ferramentas manuais são abertos no início do turno e deveriam ser fechados ao final do expediente. No entanto, não estava acontecendo como previsto.', N'Evitar Vulnerabilidade de ferramentas manuais.', N'10303', N'01 - Imagens/01 - Antes/10364.jpeg', N'Após o expediente, os armários ficavam esquecidos abertos, o que deixava nossas ferramentas manuais vulneráveis a perdas (ferramentas de alto custo).', N'01 - Imagens/02 - Depois/10364.jpeg', N'Foi criado um procedimento para o controle do claviculário, no qual são registradas as informações do colaborador responsável pela retirada das chaves no início do expediente.
INSERT INTO #PVC VALUES (10365, N'81006689', N'81006689', N'Sinalização de movimentação', NULL, N'Others/Outros', N'área de movimentação de equipamento sem sinalização de alerta para pedestres.', N'Alertar pessoas que estão acessando a área sobre movimentação de empilhadeira', N'10233', N'01 - Imagens/01 - Antes/10365.jpeg', N'Área de movimentação de equipamento sem sinalização de alerta para pedestres.', N'01 - Imagens/02 - Depois/10365.jpeg', N'Implementação de placa de sinalização de movimentação de equipamento na área.', NULL, N'sim, foi realizado implementação de placa de sinalização de movimentação de equipamento na área, alertando pessoas que estão acessando a área para redobrar atenção.', N'Manter a atenção ao acessar área com movimentação de equipamentos', 0, NULL, N'REDUÇÃO DO TEMPO DE LOCALIZAÇÃO DE INFORMAÇÕES
INSERT INTO #PVC VALUES (10366, N'81059325', N'81059325', N'Indicador de Aderência as rotinas de D-1 das frotas', 1, N'Others/Outros', N'Ausência de indicador que medisse e acompanhasse a aderência de steakholders críticos nas rotinas de D-1 das Frotas. 
INSERT INTO #PVC VALUES (10367, N'81053501', N'81053501', N'Report D-1 semanal da programação', 1, N'Others/Outros', N'Dificuldade de acompanhamento da apropriação diária das ordens em execução', N'Acompanhamento da programação semanal diário', N'10279', N'01 - Imagens/01 - Antes/10367.jpeg', N'Não existia acompanhamento D-1 da programação semanal ', N'01 - Imagens/02 - Depois/10367.jpeg', N'Foi criado um dashboard do D-1 das atividades programadas semanalmente para acompanhamento diário para execução', NULL, N'Com a criação do D-1, passamos a ter maior visibilidade e controle sobre as atividades planejadas e executadas. Esse acompanhamento diário permite comparar o que foi programado com o que de fato foi realizado, além de monitorar a execução e o cumprimento da programação semanal. Dessa forma, é possível identificar desvios com mais rapidez, apoiar a tomada de decisão e promover ajustes contínuos, contribuindo para maior eficiência e assertividade no planejamento', N'Com a criação do D-1, passamos a ter maior visibilidade e controle sobre as atividades planejadas e executadas.', 0, NULL, N'Atualização do documento PRO-046994', '2026-05-28T00:00:00.000', '2026-05-29T10:58:58.000', N'81053501', NULL, NULL);
INSERT INTO #PVC VALUES (10368, N'547527', N'547527', N' Planilha de Controle de Projeção das Preventivas de 250h', 1, N'No Replication/Sem replicação', N'não existia uma ferramenta estruturada que permitisse a visualização antecipada das demandas, o que dificultava o planejamento das intervenções e a gestão eficiente dos recursos.', N'Com o objetivo de aprimorar o planejamento e controle das manutenções preventivas de 250 horas, foi desenvolvida e implementada uma planilha de acompanhamento de projeção. Anteriormente, não existia uma ferramenta estruturada que permitisse a visualização antecipada das demandas, o que dificultava o planejamento das intervenções e a gestão eficiente dos recursos.', N'10324', N'01 - Imagens/01 - Antes/10368.jpeg', N'Com o objetivo de aprimorar o planejamento e controle das manutenções preventivas de 250 horas, foi desenvolvida e implementada uma planilha de acompanhamento de projeção. Anteriormente, não existia uma ferramenta estruturada que permitisse a visualização antecipada das demandas, o que dificultava o planejamento das intervenções e a gestão eficiente dos recursos.
INSERT INTO #PVC VALUES (10369, N'81023633', N'125450', N'LOTO à Vista: Matriz Simplificada', 1, N'Others/Outros', N'Ao transformar esta planilha textual numa matriz visual (como fez), o processo torna-se muito mais seguro, pois o operador vê a foto real exata da válvula ou disjuntor que precisa de bloquear, eliminando margens para erros.', N'Criar uma matriz de bloqueio 100% visual para eliminar erros de interpretação e reduzir o tempo de execução do procedimento.', N'10064', N'01 - Imagens/01 - Antes/10369.jpeg', N'A interpretação das ordens de bloqueio dependia exclusivamente de uma matriz textual em planilha, um formato complexo que demandava tempo extra dos operadores e elevava o risco de falhas na identificação visual dos equipamentos em campo.', N'01 - Imagens/02 - Depois/10369.jpeg', N'Desenvolvemos uma matriz de bloqueio visual para facilitar a identificação dos equipamentos e itens a serem bloqueados em cada atividade. Esta ferramenta não substitui a matriz oficial, mas atua como um suporte para sua interpretação. As versões impressas já estão disponíveis nos Centros de Controle de Bloqueio (CCBs) das Britagens I, II e III.', NULL, N'O desenvolvimento da matriz visual alcançou o objetivo proposto. 
INSERT INTO #PVC VALUES (10370, N'81037109', N'81037109', N'Base de Controle de Status – PREP', 1, N'Others/Outros', N'A ausência de um controle automatizado e padronizado das ordens em status PREP dificulta o acompanhamento, priorização das demandas e análise das pendências, tornando o processo mais suscetível a erros e retrabalho.
INSERT INTO #PVC VALUES (10371, N'140178', N'989707', N'Aumento da confiabilidade das perfuratrizes através da implementação de filtragem avançada no diesel (Filtros eletrostáticos DRY83 e DRY12)', 1, N'No Replication/Sem replicação', N'As perfuratrizes da operação vêm apresentando baixa confiabilidade e perda de desempenho devido à obstrução prematura dos filtros de diesel, com vida útil média de aproximadamente 100 horas, abaixo do previsto de 250 horas.
INSERT INTO #PVC VALUES (10372, N'81015967', N'81015967', N'Monitoramento online das Subestações SLB ', 2, N'Crusher/Britadeira', N'A rede Profibus da planta apresenta falhas
INSERT INTO #PVC VALUES (10373, N'81009130', N'81009130', N'CT - Centro de treinamento RAC01 NR35', 2, N'Others/Outros', N'A unidade Operacional não possui um centro de treinamento específico para NR35 -RAC01 para atender a prática e teórica em trabalho em altura. Dessa forma, os treinamentos obrigatórios relacionados NR35 são realizados por meio de empresa especializadas. ', N'Qualificar/treinar ', N'10184', N'01 - Imagens/01 - Antes/10373.jpeg', N'A Unidade operacional Onça Puma não possui centro de treinamento próprio destinado as capacitações práticas e teóricas destinados a NR35 e RAC01 - Trabalho em Altura. A ausência de um centro de treinamento próprio evidencia uma oportunidade de melhoria para o fortalecimento da culta de segurança, desenvolvimento técnico das equipes e ampliação das práticas preventivas relacionadas às atividades e 5S na área operacional. ', N'01 - Imagens/02 - Depois/10373.jpeg', N'O fortalecimento da gestão de segurança nas atividades de altura, propões a implantação de um centro de treinamento NR35 na unidade operacional destinado a prática e teórico dos colaboradores próprios e contratados. O espaço poderá contemplar estruturas simuladas de trabalho em altura, sistemas de ancoragem, linha de vida, escadas e comportamento dos colaboradores em área operacional. ', NULL, N'Com a implantação do Centro de treinamento NR35 transforma uma fragilidade operacional em uma oportunidade estratégica de desenvolvimento, prevenção e excelência em segurança, promovendo maior confiabilidade nas operações. ', N'Contexto de estudos e aplicação', 25, 1, N'Visualização instantânea, facilitando a tomada de decisão, otimização de tempo e uma visão ampla do processo  ', '2026-05-20T00:00:00.000', '2026-05-29T11:42:18.000', N'81009130', NULL, NULL);
INSERT INTO #PVC VALUES (10374, N'478997', N'478997', N'Sequenciamento de equipamentos a partir da priorização semanal.', 1, N'Others/Outros', N'Falta representação gráfica do comportamento de parada, liberação e sequenciamento na semana dos equipamentos projetados/programados no S+2', N'Maior clareza à equipe de programação e execução referente ao cenário dos equipamentos na semana programada', N'10023', N'01 - Imagens/01 - Antes/10374.jpeg', N'Representação de entrada e saída dos equipamentos por tabela.', N'01 - Imagens/02 - Depois/10374.jpeg', N'Representação gráfica do sequenciamento dos equipamentos com base do tempo de hora/máquina.', NULL, N'Sim. Execução aprovou durante reunião de programação.', N'Organização', 0, NULL, N'FOI CONFECCIONADO PELA EQUIPE UM SUPORTE PARA O RADIADOR UTILIZANDO RECURSOS DA ÁREA COM BAIXO CUSTO. E ELIMINANDO OS RISCOS ', '2026-05-28T00:00:00.000', '2026-05-29T11:56:42.000', N'478997', NULL, NULL);
INSERT INTO #PVC VALUES (10375, N'81022747', N'26518', N'MELHORIA NA MANGUEIRA DO CAMINHÃO PIPA', 1, N'Others/Outros', N'devido a fixação da mangueira com abraçadeira estava sacando com pressão da água.', N'mudança na fixação.', N'10144', N'01 - Imagens/01 - Antes/10375.jpeg', N'Mangueira do caminhão pipa SM. 31.devido a fixação da mangueira com abraçadeira estava sacando com pressão da água. ', N'01 - Imagens/02 - Depois/10375.jpeg', N'Foi feito mudança na fixação.', NULL, N'Antes a fixação estava soltando com a pressão da agua, após a melhoria começou a ter mas segurança durante o processo', N'Segurança', 0, NULL, N'Assertividade na utilização dos fluidos corretos durante o início do ciclo de vida do ativo. ', '2026-05-25T00:00:00.000', '2026-05-29T12:12:40.000', N'81022747', NULL, NULL);
INSERT INTO #PVC VALUES (10376, N'550466', N'92000156', N'Automação do Sump Ácido', 1, N'Others/Outros', N'O sump da calha ácida tem como função receber e concentrar os efluentes com pH ácido provenientes do dique PN06, realizando o bombeamento desse fluido para a Cava Pista, onde ocorre sua diluição. O eventual transbordamento do sump pode causar impactos ambientais significativos, com risco de contaminação dos rios Sossego e Parauapebas.
INSERT INTO #PVC VALUES (10377, N'81006209', N'81026227', N'Implementação de curvas em PEAD nas baterias da ciclonagem', 1, N'Concentration/Concentração', N'Constantes vazamentos nas baterias da ciclonagem devido ao desgaste excessivo ', N'Aumentar a vida útil das curvas e aumentar a confiabilidade operacional', N'10031', N'01 - Imagens/01 - Antes/10377.jpeg', N'Constantes vazamentos nas baterias da ciclonagem devido ao desgaste excessivo ', N'01 - Imagens/02 - Depois/10377.jpeg', N'Curvas em PEAD implementadas', NULL, N'Curvas mangote com revestimento em PEAD garantem maior confiabilidade e melhor manutenibilidade ', N'Aumento de vida útil e melhor manutenibilidade ', 0, NULL, N'CONFECCIONADA PLACA ORIENTATIVA PARA ACESSO AO EQUIPAMENTO. ORIENTAÇÃO E SEGURANÇA PARA OS EMPREGADOS ', '2026-05-28T00:00:00.000', '2026-05-29T12:45:52.000', N'81006209', NULL, NULL);
